@dataclass
class InSARParameters:
    """Parameters for InSAR/MT-SAR processing"""
    satellite: str  # Sentinel-1, ALOS-2, etc.
    wavelength: float  # Radar wavelength in cm
    incidence_angle: float  # degrees
    heading_angle: float  # degrees
    temporal_baseline: int  # days
    spatial_baseline: float  # meters
    coherence_threshold: float  # 0-1
    unwrapping_method: str  # snaphu, icu, etc.
    atmospheric_model: str  # gacos, era5, etc.

@dataclass
class GPSStationData:
    """GPS station data structure"""
    station_id: str
    location: Tuple[float, float, float]  # lat, lon, elevation
    time_series: Dict[str, np.ndarray]  # east, north, up components
    uncertainties: Dict[str, np.ndarray]  # measurement uncertainties
    processing_method: str
    reference_frame: str
    monument_type: str

@dataclass
class TiltStrainData:
    """Tilt and strain measurement data"""
    instrument_id: str
    instrument_type: str  # tiltmeter, strainmeter
    location: Tuple[float, float, float]
    measurements: Dict[str, np.ndarray]  # tilt_x, tilt_y, strain_xx, etc.
    sampling_rate: float  # Hz
    calibration_data: Dict[str, Any]
    environmental_corrections: Dict[str, np.ndarray]

