    async def _compute_comprehensive_pinn_losses(self, pinn_model, X_tensor, predictions, training_data, stage_config, weights, parameters):
        """Compute comprehensive physics-informed losses"""
        device = X_tensor.device
        losses = {}
        
        # Data loss - MSE with observed atmospheric patterns
        if len(training_data['atmospheric_delays']) > 0:
            target_delays = torch.FloatTensor(training_data['atmospheric_delays']).to(device)
            quality_weights = torch.FloatTensor(training_data['quality_weights']).to(device)
            
            # Weighted MSE loss
            data_residuals = (predictions.squeeze() - target_delays) ** 2
            losses['data_loss'] = weights['data'] * torch.mean(quality_weights * data_residuals)
        else:
            losses['data_loss'] = torch.tensor(0.0, device=device)
        
        # Physics loss - Atmospheric physics constraints
        physics_loss_components = await self._compute_physics_loss_components(
            pinn_model, X_tensor, predictions, training_data, parameters
        )
        losses['physics_loss'] = weights['physics'] * sum(physics_loss_components.values())
        
        # Boundary condition loss
        boundary_loss = await self._compute_boundary_condition_loss(
            pinn_model, X_tensor, predictions, parameters
        )
        losses['boundary_loss'] = weights['boundary'] * boundary_loss
        
        # Conservation law loss (mass conservation for atmospheric flow)
        conservation_loss = await self._compute_conservation_loss(
            pinn_model, X_tensor, predictions, parameters
        )
        losses['conservation_loss'] = weights['conservation'] * conservation_loss
        
        # Temporal consistency loss
        temporal_loss = await self._compute_temporal_consistency_loss(
            pinn_model, X_tensor, predictions, training_data, parameters
        )
        losses['temporal_consistency_loss'] = weights['temporal_consistency'] * temporal_loss
        
        # Spatial smoothness loss
        spatial_loss = await self._compute_spatial_smoothness_loss(
            predictions, X_tensor, parameters
        )
        losses['spatial_smoothness_loss'] = weights['spatial_smoothness'] * spatial_loss
        
        return losses
    
    async def _compute_physics_loss_components(self, pinn_model, X_tensor, predictions, training_data, parameters):
        """Compute detailed physics loss components"""
        device = X_tensor.device
        physics_losses = {}
        
        # Hydrostatic equilibrium loss
        if X_tensor.requires_grad:
            # Compute pressure gradient
            pressure_grad = torch.autograd.grad(
                predictions.sum(), X_tensor, 
                create_graph=True, retain_graph=True
            )[0]
            
            # Hydrostatic equilibrium: dp/dz = -ρg
            # Assuming atmospheric density ρ ≈ 1.225 kg/m³, g = 9.81 m/s²
            expected_gradient = -1.225 * 9.81
            hydrostatic_residual = pressure_grad[:, 2] - expected_gradient  # z-component
            physics_losses['hydrostatic'] = torch.mean(hydrostatic_residual ** 2)
        else:
            physics_losses['hydrostatic'] = torch.tensor(0.0, device=device)
        
        # Atmospheric stratification loss (temperature lapse rate)
        if len(training_data['meteorological_features']) > 0:
            meteo_features = torch.FloatTensor(training_data['meteorological_features']).to(device)
            temperature_data = meteo_features[:, 0]  # First feature is temperature
            
            # Standard atmospheric lapse rate: -6.5 K/km
            expected_lapse_rate = -0.0065  # K/m
            if len(temperature_data) > 1:
                temp_gradient = torch.gradient(temperature_data)[0]
                lapse_rate_residual = temp_gradient - expected_lapse_rate
                physics_losses['lapse_rate'] = torch.mean(lapse_rate_residual ** 2)
            else:
                physics_losses['lapse_rate'] = torch.tensor(0.0, device=device)
        else:
            physics_losses['lapse_rate'] = torch.tensor(0.0, device=device)
        
        # Atmospheric refractivity physics
        # Refractivity N = 77.6 * P/T + 373256 * e/T²
        if len(training_data['physics_constraints']) > 0:
            pressure_data = torch.FloatTensor(training_data['physics_constraints']).to(device)
            temperature_data = torch.FloatTensor(training_data['meteorological_features'])[:, 0].to(device)
            
            # Advanced atmospheric refractivity with multi-layer modeling
            refractivity_loss = await self._compute_advanced_refractivity_loss(
                predictions, pressure_data, temperature_data, humidity_data
            )
            physics_losses['refractivity'] = refractivity_loss
        else:
            physics_losses['refractivity'] = torch.tensor(0.0, device=device)
        
        return physics_losses
    
    async def _compute_boundary_condition_loss(self, pinn_model, X_tensor, predictions, parameters):
        """Compute boundary condition loss for atmospheric model"""
        device = X_tensor.device
        
        # Identify boundary points (edges of spatial domain)
        spatial_coords = X_tensor[:, :3]  # Assuming first 3 features are spatial coordinates
        
        # Find boundary points (normalized coordinates near ±1)
        boundary_mask = (
            (torch.abs(spatial_coords[:, 0]) > 0.9) |  # x boundaries
            (torch.abs(spatial_coords[:, 1]) > 0.9) |  # y boundaries
            (torch.abs(spatial_coords[:, 2]) > 0.9)    # z boundaries
        )
        
        if torch.sum(boundary_mask) > 0:
            boundary_predictions = predictions[boundary_mask]
            
            # Atmospheric boundary conditions: smooth transition to zero at domain edges
            boundary_target = torch.zeros_like(boundary_predictions)
            boundary_loss = F.mse_loss(boundary_predictions, boundary_target)
        else:
            boundary_loss = torch.tensor(0.0, device=device)
        
        return boundary_loss
    
    async def _compute_conservation_loss(self, pinn_model, X_tensor, predictions, parameters):
        """Compute conservation law loss (mass conservation)"""
        device = X_tensor.device
        
        if not X_tensor.requires_grad:
            return torch.tensor(0.0, device=device)
        
        # Compute divergence of atmospheric flow
        # ∇ · (ρv) = 0 for mass conservation
        try:
            # Compute gradients of predictions
            grad_outputs = torch.ones_like(predictions)
            gradients = torch.autograd.grad(
                outputs=predictions,
                inputs=X_tensor,
                grad_outputs=grad_outputs,
                create_graph=True,
                retain_graph=True,
                only_inputs=True
            )[0]
            
            # Divergence (sum of spatial derivatives)
            divergence = gradients[:, 0] + gradients[:, 1] + gradients[:, 2]  # ∂/∂x + ∂/∂y + ∂/∂z
            
            # Conservation loss: divergence should be close to zero
            conservation_loss = torch.mean(divergence ** 2)
            
        except Exception as e:
            logger.warning(f"Conservation loss computation failed: {e}")
            conservation_loss = torch.tensor(0.0, device=device)
        
        return conservation_loss
    
    async def _compute_temporal_consistency_loss(self, pinn_model, X_tensor, predictions, training_data, parameters):
        """Compute temporal consistency loss"""
        device = X_tensor.device
        
        if len(training_data['temporal_features']) == 0:
            return torch.tensor(0.0, device=device)
        
        temporal_features = torch.FloatTensor(training_data['temporal_features']).to(device)
        
        # Temporal smoothness: atmospheric changes should be gradual
        if len(predictions) > 1:
            temporal_diff = torch.diff(predictions.squeeze())
            temporal_consistency_loss = torch.mean(temporal_diff ** 2)
        else:
            temporal_consistency_loss = torch.tensor(0.0, device=device)
        
        return temporal_consistency_loss
    
    async def _compute_spatial_smoothness_loss(self, predictions, X_tensor, parameters):
        """Compute spatial smoothness loss"""
        device = X_tensor.device
        
        if not X_tensor.requires_grad:
            return torch.tensor(0.0, device=device)
        
        try:
            # Compute second derivatives (Laplacian) for smoothness
            grad_outputs = torch.ones_like(predictions)
            first_grad = torch.autograd.grad(
                outputs=predictions,
                inputs=X_tensor,
                grad_outputs=grad_outputs,
                create_graph=True,
                retain_graph=True,
                only_inputs=True
            )[0]
            
            # Compute Laplacian (sum of second derivatives)
            laplacian = 0
            for i in range(min(3, first_grad.shape[1])):  # Spatial dimensions only
                second_grad = torch.autograd.grad(
                    outputs=first_grad[:, i].sum(),
                    inputs=X_tensor,
                    create_graph=True,
                    retain_graph=True,
                    only_inputs=True
                )[0]
                laplacian += second_grad[:, i]
            
            # Smoothness loss: penalize large Laplacian values
            smoothness_loss = torch.mean(laplacian ** 2)
            
        except Exception as e:
            logger.warning(f"Spatial smoothness loss computation failed: {e}")
            smoothness_loss = torch.tensor(0.0, device=device)
        
        return smoothness_loss
    
    async def _validate_pinn_model(self, pinn_model, validation_data, parameters):
        """Advanced PINN model validation with comprehensive atmospheric physics constraints"""
        pinn_model.eval()
        
        if not validation_data or len(validation_data.get('atmospheric_delays', [])) == 0:
            return 0.0
        
        device = next(pinn_model.parameters()).device
        
        # Prepare multi-scale validation features with atmospheric physics
        val_features = await self._prepare_atmospheric_validation_features(validation_data, parameters)
        val_tensor = torch.FloatTensor(val_features).to(device)
        val_targets = torch.FloatTensor(validation_data['atmospheric_delays']).to(device)
        
        with torch.no_grad():
            val_predictions = pinn_model(val_tensor)
            
            # Multi-component validation loss
            data_loss = F.mse_loss(val_predictions.squeeze(), val_targets)
            
            # Physics-informed validation constraints
            physics_loss = await self._compute_atmospheric_physics_validation(
                val_predictions, val_tensor, validation_data, device
            )
            
            # Spatial coherence validation
            spatial_loss = await self._validate_spatial_coherence(
                val_predictions, validation_data, device
            )
            
            # Temporal consistency validation
            temporal_loss = await self._validate_temporal_consistency(
                val_predictions, validation_data, device
            )
            
            # Combined validation score with physics weighting
            total_loss = (
                0.4 * data_loss + 
                0.3 * physics_loss + 
                0.2 * spatial_loss + 
                0.1 * temporal_loss
            )
        
        return total_loss.item()
    
    async def _adapt_loss_weights(self, current_weights, losses, training_metrics, epoch):
        """Advanced adaptive loss weight adjustment with atmospheric physics constraints"""
        adapted_weights = current_weights.copy()
        
        # Multi-scale loss trend analysis
        recent_window = min(20, len(training_metrics['total_loss']))
        if len(training_metrics['total_loss']) >= recent_window:
            recent_losses = training_metrics['total_loss'][-recent_window:]
            
            # Compute multiple trend indicators
            linear_trend = np.polyfit(range(recent_window), recent_losses, 1)[0]
            loss_variance = np.var(recent_losses)
            convergence_rate = abs(recent_losses[-1] - recent_losses[0]) / (recent_losses[0] + 1e-8)
            
            # Atmospheric physics-informed weight adaptation
            physics_dominance = losses['physics_loss'].item() / (losses['data_loss'].item() + 1e-8)
            atmospheric_coherence = losses.get('atmospheric_coherence_loss', torch.tensor(0.0)).item()
            
            # Adaptive weight adjustment based on atmospheric physics
            if linear_trend > -1e-4:  # Stagnation detection
                if physics_dominance > 5.0:
                    # Physics loss too dominant - reduce physics weight
                    adapted_weights['physics'] *= 0.85
                    adapted_weights['data'] *= 1.1
                    adapted_weights['atmospheric_coherence'] = adapted_weights.get('atmospheric_coherence', 0.1) * 1.2
                else:
                    # Increase physics constraints for better convergence
                    adapted_weights['physics'] *= 1.15
                    adapted_weights['data'] *= 0.9
            
            # Atmospheric coherence adaptation
            if atmospheric_coherence > 0.1:
                adapted_weights['atmospheric_coherence'] = adapted_weights.get('atmospheric_coherence', 0.1) * 0.8
            elif atmospheric_coherence < 0.01:
                adapted_weights['atmospheric_coherence'] = adapted_weights.get('atmospheric_coherence', 0.1) * 1.3
            
            # Temporal consistency weight adaptation
            if 'temporal_consistency_loss' in losses:
                temporal_loss = losses['temporal_consistency_loss'].item()
                if temporal_loss > 0.05:
                    adapted_weights['temporal_consistency'] = adapted_weights.get('temporal_consistency', 0.05) * 1.2
            
            # Ensure weight normalization for atmospheric components
            total_atmospheric_weight = (
                adapted_weights.get('atmospheric_coherence', 0.1) +
                adapted_weights.get('temporal_consistency', 0.05) +
                adapted_weights.get('spatial_smoothness', 0.05)
            )
            
            if total_atmospheric_weight > 0.5:  # Prevent atmospheric weights from dominating
                scale_factor = 0.5 / total_atmospheric_weight
                adapted_weights['atmospheric_coherence'] = adapted_weights.get('atmospheric_coherence', 0.1) * scale_factor
                adapted_weights['temporal_consistency'] = adapted_weights.get('temporal_consistency', 0.05) * scale_factor
                adapted_weights['spatial_smoothness'] = adapted_weights.get('spatial_smoothness', 0.05) * scale_factor
        
        return adapted_weights
    
    async def _fine_tune_with_lbfgs(self, pinn_model, X_tensor, training_data, parameters):
        """Advanced L-BFGS fine-tuning with atmospheric physics constraints"""
        logger.info("Starting advanced L-BFGS fine-tuning with atmospheric physics...")
        
        # Enhanced L-BFGS optimizer with atmospheric-specific parameters
        lbfgs_optimizer = torch.optim.LBFGS(
            pinn_model.parameters(),
            lr=0.05,  # Reduced learning rate for atmospheric stability
            max_iter=100,
            max_eval=150,
            tolerance_grad=1e-8,
            tolerance_change=1e-10,
            history_size=200,
            line_search_fn="strong_wolfe"
        )
        
        # Load atmospheric reference data for physics constraints
        atmospheric_reference = await self._load_atmospheric_reference_data(parameters)
        
        def atmospheric_physics_closure():
            lbfgs_optimizer.zero_grad()
            predictions = pinn_model(X_tensor)
            
            # Multi-component atmospheric loss function
            losses = {}
            
            # Data fidelity loss
            if 'atmospheric_delays' in training_data:
                target_delays = torch.FloatTensor(training_data['atmospheric_delays']).to(X_tensor.device)
                losses['data'] = F.mse_loss(predictions.squeeze(), target_delays)
            else:
                losses['data'] = torch.tensor(0.0, requires_grad=True, device=X_tensor.device)
            
            # Atmospheric physics constraints
            losses['hydrostatic'] = self._compute_hydrostatic_constraint(predictions, X_tensor, atmospheric_reference)
            losses['wet_delay'] = self._compute_wet_delay_constraint(predictions, X_tensor, atmospheric_reference)
            losses['stratification'] = self._compute_atmospheric_stratification_constraint(predictions, X_tensor)
            
            # Spatial coherence constraint
            losses['spatial_coherence'] = self._compute_spatial_coherence_constraint(predictions, X_tensor)
            
            # Temporal smoothness constraint
            if len(predictions) > 1:
                losses['temporal_smoothness'] = self._compute_temporal_smoothness_constraint(predictions, X_tensor)
            else:
                losses['temporal_smoothness'] = torch.tensor(0.0, requires_grad=True, device=X_tensor.device)
            
            # Meteorological consistency constraint
            losses['meteorological'] = self._compute_meteorological_consistency_constraint(
                predictions, X_tensor, atmospheric_reference
            )
            
            # Combined loss with atmospheric physics weighting
            total_loss = (
                0.35 * losses['data'] +
                0.20 * losses['hydrostatic'] +
                0.15 * losses['wet_delay'] +
                0.10 * losses['stratification'] +
                0.10 * losses['spatial_coherence'] +
                0.05 * losses['temporal_smoothness'] +
                0.05 * losses['meteorological']
            )
            
            total_loss.backward()
            return total_loss
        
        # Execute L-BFGS optimization with atmospheric physics
        try:
            initial_loss = None
            for step in range(5):  # Multiple L-BFGS steps for convergence
                loss_value = lbfgs_optimizer.step(atmospheric_physics_closure)
                
                if initial_loss is None:
                    initial_loss = loss_value.item()
                
                current_loss = loss_value.item()
                improvement = (initial_loss - current_loss) / initial_loss if initial_loss > 0 else 0
                
                logger.info(f"L-BFGS step {step + 1}: loss = {current_loss:.6f}, improvement = {improvement:.4f}")
                
                # Early stopping if convergence achieved
                if improvement < 1e-6:
                    logger.info("L-BFGS converged early")
                    break
            
            logger.info("Advanced L-BFGS fine-tuning completed successfully")
            
        except Exception as e:
            logger.warning(f"Advanced L-BFGS fine-tuning failed: {e}")
            # Fallback to simpler optimization if advanced fails
            await self._fallback_lbfgs_optimization(pinn_model, X_tensor, training_data)
    
