    async def _create_validation_split(self, training_data):
        """Create stratified validation split with atmospheric physics considerations"""
        validation_split = 0.2
        n_samples = len(training_data['atmospheric_delays'])
        n_val = int(n_samples * validation_split)
        
        if n_val == 0:
            return {}
        
        # Stratified sampling based on atmospheric conditions
        atmospheric_delays = training_data['atmospheric_delays']
        
        # Create stratification bins based on delay magnitude and temporal characteristics
        delay_percentiles = np.percentile(atmospheric_delays, [25, 50, 75])
        strata = np.digitize(atmospheric_delays, delay_percentiles)
        
        # Ensure temporal distribution in validation set
        if 'temporal_features' in training_data:
            temporal_features = training_data['temporal_features']
            if temporal_features.shape[1] > 0:  # Time-based features available
                time_percentiles = np.percentile(temporal_features[:, 0], [33, 67])
                time_strata = np.digitize(temporal_features[:, 0], time_percentiles)
                # Combine atmospheric and temporal stratification
                combined_strata = strata * 10 + time_strata
            else:
                combined_strata = strata
        else:
            combined_strata = strata
        
        # Stratified sampling
        val_indices = []
        unique_strata = np.unique(combined_strata)
        
        for stratum in unique_strata:
            stratum_indices = np.where(combined_strata == stratum)[0]
            stratum_val_size = max(1, int(len(stratum_indices) * validation_split))
            stratum_val_indices = np.random.choice(
                stratum_indices, 
                size=min(stratum_val_size, len(stratum_indices)), 
                replace=False
            )
            val_indices.extend(stratum_val_indices)
        
        val_indices = np.array(val_indices)
        
        # Create validation dataset with atmospheric metadata
        validation_data = {}
        for key, data in training_data.items():
            if isinstance(data, np.ndarray) and len(data) == n_samples:
                validation_data[key] = data[val_indices]
        
        # Add validation metadata
        validation_data['validation_metadata'] = {
            'validation_size': len(val_indices),
            'stratification_method': 'atmospheric_temporal',
            'delay_range': [float(np.min(atmospheric_delays[val_indices])), 
                           float(np.max(atmospheric_delays[val_indices]))],
            'delay_std': float(np.std(atmospheric_delays[val_indices])),
            'temporal_coverage': self._assess_temporal_coverage(validation_data.get('temporal_features')),
            'spatial_coverage': self._assess_spatial_coverage(validation_data.get('spatial_coordinates'))
        }
        
        logger.info(f"Created stratified validation set: {len(val_indices)} samples")
        logger.info(f"Validation delay range: {validation_data['validation_metadata']['delay_range']}")
        
        return validation_data
    
    async def _generate_synthetic_atmospheric_data(self, parameters):
        """Generate physics-based synthetic atmospheric data with realistic patterns"""
        n_samples = parameters.get('synthetic_samples', 2000)
        
        # Get spatial and temporal bounds from parameters
        spatial_bounds = parameters.get('spatial_bounds', {
            'lat_min': -90, 'lat_max': 90, 'lon_min': -180, 'lon_max': 180, 'alt_min': 0, 'alt_max': 15000
        })
        temporal_bounds = parameters.get('temporal_bounds', {
            'start_date': datetime.now() - timedelta(days=365),
            'end_date': datetime.now()
        })
        
        # Generate realistic spatial coordinates
        lats = np.random.uniform(spatial_bounds['lat_min'], spatial_bounds['lat_max'], n_samples)
        lons = np.random.uniform(spatial_bounds['lon_min'], spatial_bounds['lon_max'], n_samples)
        alts = np.random.exponential(2000, n_samples)  # Exponential distribution for altitude
        alts = np.clip(alts, spatial_bounds['alt_min'], spatial_bounds['alt_max'])
        
        # Generate temporal features
        time_range = (temporal_bounds['end_date'] - temporal_bounds['start_date']).total_seconds()
        timestamps = temporal_bounds['start_date'] + pd.to_timedelta(
            np.random.uniform(0, time_range, n_samples), unit='s'
        )
        
        # Extract temporal features
        day_of_year = np.array([t.timetuple().tm_yday for t in timestamps])
        hour_of_day = np.array([t.hour for t in timestamps])
        
        # Physics-based atmospheric delay generation
        atmospheric_delays = self._generate_physics_based_delays(lats, lons, alts, day_of_year, hour_of_day)
        
        # Generate realistic meteorological features
        meteorological_features = self._generate_meteorological_features(lats, lons, alts, day_of_year, hour_of_day)
        
        # Generate spatial coordinates (normalized)
        spatial_coordinates = np.column_stack([
            (lons - spatial_bounds['lon_min']) / (spatial_bounds['lon_max'] - spatial_bounds['lon_min']),
            (lats - spatial_bounds['lat_min']) / (spatial_bounds['lat_max'] - spatial_bounds['lat_min']),
            alts / spatial_bounds['alt_max']
        ])
        
        # Generate temporal features (normalized)
        temporal_features = np.column_stack([
            day_of_year / 365.0,
            hour_of_day / 24.0,
            np.sin(2 * np.pi * day_of_year / 365.0),  # Seasonal component
            np.cos(2 * np.pi * day_of_year / 365.0),
            np.sin(2 * np.pi * hour_of_day / 24.0),   # Diurnal component
            np.cos(2 * np.pi * hour_of_day / 24.0)
        ])
        
        # Generate quality weights based on atmospheric conditions
        quality_weights = self._generate_quality_weights(meteorological_features, atmospheric_delays)
        
        # Generate physics constraints
        physics_constraints = self._generate_physics_constraints(lats, alts, meteorological_features)
        
        synthetic_data = {
            'atmospheric_delays': atmospheric_delays,
            'meteorological_features': meteorological_features,
            'spatial_coordinates': spatial_coordinates,
            'temporal_features': temporal_features,
            'quality_weights': quality_weights,
            'physics_constraints': physics_constraints,
            'raw_coordinates': np.column_stack([lons, lats, alts]),
            'timestamps': timestamps,
            'generation_metadata': {
                'n_samples': n_samples,
                'spatial_bounds': spatial_bounds,
                'temporal_bounds': temporal_bounds,
                'generation_method': 'physics_based_synthetic',
                'delay_statistics': {
                    'mean': float(np.mean(atmospheric_delays)),
                    'std': float(np.std(atmospheric_delays)),
                    'min': float(np.min(atmospheric_delays)),
                    'max': float(np.max(atmospheric_delays))
                }
            }
        }
        
        logger.info(f"Generated {n_samples} synthetic atmospheric samples")
        logger.info(f"Delay range: {synthetic_data['generation_metadata']['delay_statistics']['min']:.4f} to {synthetic_data['generation_metadata']['delay_statistics']['max']:.4f} m")
        
        return synthetic_data
    
    # Advanced atmospheric physics methods
    
    async def _prepare_atmospheric_validation_features(self, validation_data, parameters):
        """Prepare multi-scale atmospheric validation features"""
        features = []
        
        # Meteorological features with physics-based scaling
        if 'meteorological_features' in validation_data:
            met_features = validation_data['meteorological_features']
            # Apply atmospheric physics scaling
            scaled_met = self._apply_atmospheric_scaling(met_features)
            features.append(scaled_met)
        
        # Spatial coordinates with elevation weighting
        if 'spatial_coordinates' in validation_data:
            spatial_coords = validation_data['spatial_coordinates']
            # Add elevation-dependent atmospheric effects
            elevation_weighted = self._apply_elevation_weighting(spatial_coords)
            features.append(elevation_weighted)
        
        # Temporal features with atmospheric periodicity
        if 'temporal_features' in validation_data:
            temporal_features = validation_data['temporal_features']
            # Add atmospheric temporal patterns
            atmospheric_temporal = self._add_atmospheric_temporal_patterns(temporal_features)
            features.append(atmospheric_temporal)
        
        return np.column_stack(features) if features else np.array([])
    
    async def _compute_atmospheric_physics_validation(self, predictions, inputs, validation_data, device):
        """Compute atmospheric physics validation constraints"""
        physics_loss = torch.tensor(0.0, requires_grad=True, device=device)
        
        # Hydrostatic equilibrium constraint
        if len(predictions) > 1:
            hydrostatic_loss = self._compute_hydrostatic_constraint(predictions, inputs, validation_data)
            physics_loss = physics_loss + 0.4 * hydrostatic_loss
        
        # Wet delay physics constraint
        wet_delay_loss = self._compute_wet_delay_constraint(predictions, inputs, validation_data)
        physics_loss = physics_loss + 0.3 * wet_delay_loss
        
        # Atmospheric stratification constraint
        stratification_loss = self._compute_atmospheric_stratification_constraint(predictions, inputs)
        physics_loss = physics_loss + 0.3 * stratification_loss
        
        return physics_loss
    
    async def _validate_spatial_coherence(self, predictions, validation_data, device):
        """Validate spatial coherence of atmospheric predictions"""
        if len(predictions) < 2:
            return torch.tensor(0.0, device=device)
        
        # Compute spatial gradients
        spatial_coords = validation_data.get('spatial_coordinates')
        if spatial_coords is None:
            return torch.tensor(0.0, device=device)
        
        # Calculate spatial coherence loss
        coherence_loss = self._compute_spatial_coherence_constraint(predictions, torch.FloatTensor(spatial_coords).to(device))
        
        return coherence_loss
    
    async def _validate_temporal_consistency(self, predictions, validation_data, device):
        """Validate temporal consistency of atmospheric predictions"""
        if len(predictions) < 2:
            return torch.tensor(0.0, device=device)
        
        temporal_features = validation_data.get('temporal_features')
        if temporal_features is None:
            return torch.tensor(0.0, device=device)
        
        # Calculate temporal consistency loss
        consistency_loss = self._compute_temporal_smoothness_constraint(predictions, torch.FloatTensor(temporal_features).to(device))
        
        return consistency_loss
    
    def _compute_hydrostatic_constraint(self, predictions, inputs, reference_data):
        """Compute hydrostatic equilibrium constraint for atmospheric delays"""
        if len(predictions) < 2:
            return torch.tensor(0.0, requires_grad=True, device=predictions.device)
        
        # Extract elevation information from inputs
        if inputs.shape[1] >= 3:
            elevations = inputs[:, 2]  # Assuming elevation is third coordinate
            
            # Compute hydrostatic delay gradient with elevation
            elevation_diffs = elevations[1:] - elevations[:-1]
            delay_diffs = predictions[1:] - predictions[:-1]
            
            # Expected hydrostatic gradient (approximately 6.5 mm/km)
            expected_gradient = -6.5e-6 * elevation_diffs  # Convert to meters
            
            # Hydrostatic constraint loss
            hydrostatic_loss = torch.mean((delay_diffs.squeeze() - expected_gradient)**2)
            
            return hydrostatic_loss
        
        return torch.tensor(0.0, requires_grad=True, device=predictions.device)
    
    def _compute_wet_delay_constraint(self, predictions, inputs, reference_data):
        """Compute advanced wet delay physics constraint using atmospheric modeling"""
        if len(predictions) < 2:
            return torch.tensor(0.0, requires_grad=True, device=predictions.device)
        
        device = predictions.device
        
        # Extract atmospheric parameters from inputs
        pressure = inputs.get('pressure', torch.tensor(101325.0, device=device))  # Pa
        temperature = inputs.get('temperature', torch.tensor(288.15, device=device))  # K
        humidity = inputs.get('relative_humidity', torch.tensor(0.5, device=device))  # fraction
        elevation = inputs.get('elevation', torch.tensor(0.0, device=device))  # m
        
        # Compute water vapor pressure using Magnus formula
        # e_s = 610.78 * exp(17.27 * T_c / (T_c + 237.3))
        temp_celsius = temperature - 273.15
        saturation_vapor_pressure = 610.78 * torch.exp(17.27 * temp_celsius / (temp_celsius + 237.3))
        vapor_pressure = humidity * saturation_vapor_pressure
        
        # Compute partial pressure of water vapor
        partial_pressure_h2o = vapor_pressure  # Pa
        
        # Theoretical wet delay using Saastamoinen model
        # ZWD = 0.002277 * (1255/T + 0.05) * e / (1 - 0.00266*cos(2*lat) - 0.00028*h)
        # Simplified for constraint (assuming mid-latitude)
        theoretical_wet_delay = 0.002277 * (1255.0 / temperature + 0.05) * partial_pressure_h2o / (1.0 - 0.00028 * elevation / 1000.0)
        
        # Convert to meters
        theoretical_wet_delay = theoretical_wet_delay / 1000.0  # mm to m
        
        # Physics constraint: predicted wet delay should follow atmospheric physics
        predicted_wet_delay = predictions.squeeze()
        
        # Constraint 1: Magnitude should be physically reasonable (0-50cm)
        magnitude_constraint = torch.relu(torch.abs(predicted_wet_delay) - 0.5) ** 2
        
        # Constraint 2: Should correlate with theoretical model
        if len(predicted_wet_delay) == len(theoretical_wet_delay.expand_as(predicted_wet_delay)):
            correlation_constraint = torch.mean((predicted_wet_delay - theoretical_wet_delay.expand_as(predicted_wet_delay)) ** 2)
        else:
            correlation_constraint = torch.tensor(0.0, device=device)
        
        # Constraint 3: Temporal smoothness (wet delay changes gradually)
        if len(predicted_wet_delay) > 1:
            temporal_gradient = torch.diff(predicted_wet_delay)
            smoothness_constraint = torch.mean(temporal_gradient ** 2)
            # Limit to reasonable change rate (1cm/hour max)
            smoothness_constraint = torch.relu(smoothness_constraint - 0.01) ** 2
        else:
            smoothness_constraint = torch.tensor(0.0, device=device)
        
        # Constraint 4: Hydrostatic equilibrium consideration
        # Wet delay should decrease with elevation following scale height
        scale_height = reference_data.get('water_vapor_scale_height', 2000.0)  # m
        elevation_factor = torch.exp(-elevation / scale_height)
        elevation_constraint = torch.mean((predicted_wet_delay - theoretical_wet_delay * elevation_factor) ** 2)
        
        # Combine constraints with physics-based weighting
        total_constraint = (
            0.3 * magnitude_constraint +
            0.4 * correlation_constraint + 
            0.2 * smoothness_constraint +
            0.1 * elevation_constraint
        )
        
        return total_constraint
    
    def _compute_atmospheric_stratification_constraint(self, predictions, inputs):
        """Compute atmospheric stratification constraint"""
        if len(predictions) < 3:
            return torch.tensor(0.0, requires_grad=True, device=predictions.device)
        
        # Atmospheric delays should show smooth vertical stratification
        if inputs.shape[1] >= 3:
            elevations = inputs[:, 2]
            
            # Sort by elevation
            sorted_indices = torch.argsort(elevations)
            sorted_predictions = predictions[sorted_indices]
            
            # Compute second derivative (curvature) - should be smooth
            if len(sorted_predictions) >= 3:
                second_derivative = sorted_predictions[2:] - 2*sorted_predictions[1:-1] + sorted_predictions[:-2]
                stratification_loss = torch.mean(second_derivative**2)
                return stratification_loss
        
        return torch.tensor(0.0, requires_grad=True, device=predictions.device)
    
    def _compute_spatial_coherence_constraint(self, predictions, spatial_coords):
        """Compute spatial coherence constraint for atmospheric delays"""
        if len(predictions) < 2:
            return torch.tensor(0.0, requires_grad=True, device=predictions.device)
        
        # Compute pairwise distances and delay differences
        n_points = len(predictions)
        coherence_loss = torch.tensor(0.0, requires_grad=True, device=predictions.device)
        
        for i in range(min(n_points, 100)):  # Limit computation for efficiency
            for j in range(i+1, min(n_points, 100)):
                # Spatial distance
                spatial_dist = torch.norm(spatial_coords[i] - spatial_coords[j])
                
                # Delay difference
                delay_diff = torch.abs(predictions[i] - predictions[j])
                
                # Coherence constraint: nearby points should have similar delays
                if spatial_dist < 0.1:  # Within 10% of normalized coordinate space
                    coherence_loss = coherence_loss + delay_diff**2
        
        return coherence_loss / (n_points * (n_points - 1) / 2)
    
    def _compute_temporal_smoothness_constraint(self, predictions, temporal_coords):
        """Compute temporal smoothness constraint"""
        if len(predictions) < 3:
            return torch.tensor(0.0, requires_grad=True, device=predictions.device)
        
        # Sort by time
        if temporal_coords.shape[1] > 0:
            time_indices = torch.argsort(temporal_coords[:, 0])
            sorted_predictions = predictions[time_indices]
            
            # Compute temporal second derivative
            temporal_second_derivative = sorted_predictions[2:] - 2*sorted_predictions[1:-1] + sorted_predictions[:-2]
            smoothness_loss = torch.mean(temporal_second_derivative**2)
            
            return smoothness_loss
        
        return torch.tensor(0.0, requires_grad=True, device=predictions.device)
    
    def _compute_meteorological_consistency_constraint(self, predictions, inputs, reference_data):
        """Compute advanced meteorological consistency constraint using real atmospheric data"""
        device = predictions.device
        
        # Extract meteorological parameters from inputs
        pressure = inputs.get('pressure', torch.tensor(101325.0, device=device))
        temperature = inputs.get('temperature', torch.tensor(288.15, device=device))
        humidity = inputs.get('relative_humidity', torch.tensor(0.5, device=device))
        wind_speed = inputs.get('wind_speed', torch.tensor(5.0, device=device))
        wind_direction = inputs.get('wind_direction', torch.tensor(0.0, device=device))
        
        # Constraint 1: Pressure-temperature relationship (hydrostatic equilibrium)
        # P = P0 * exp(-M*g*h/(R*T)) for isothermal atmosphere
        elevation = inputs.get('elevation', torch.tensor(0.0, device=device))
        expected_pressure = reference_data['standard_pressure'] * torch.exp(
            -0.0289644 * 9.80665 * elevation / (8.31432 * temperature)
        )
        pressure_consistency = torch.mean((pressure - expected_pressure) ** 2) / (expected_pressure ** 2)
        
        # Constraint 2: Temperature lapse rate consistency
        if 'temperature_profile' in inputs and len(inputs['temperature_profile']) > 1:
            temp_profile = torch.tensor(inputs['temperature_profile'], device=device)
            elevation_profile = torch.tensor(inputs.get('elevation_profile', 
                torch.linspace(0, 10000, len(temp_profile))), device=device)
            
            # Compute observed lapse rate
            temp_gradient = torch.diff(temp_profile) / torch.diff(elevation_profile)
            expected_lapse_rate = torch.tensor(reference_data['lapse_rate'], device=device)
            
            # Lapse rate should be within reasonable bounds (-10 to +5 K/km)
            lapse_rate_constraint = torch.mean(torch.relu(torch.abs(temp_gradient - expected_lapse_rate) - 0.005) ** 2)
        else:
            lapse_rate_constraint = torch.tensor(0.0, device=device)
        
        # Constraint 3: Humidity-temperature relationship (Clausius-Clapeyron)
        # Maximum possible humidity decreases with temperature
        temp_celsius = temperature - 273.15
        max_vapor_pressure = 610.78 * torch.exp(17.27 * temp_celsius / (temp_celsius + 237.3))
        current_vapor_pressure = humidity * max_vapor_pressure
        
        # Constraint: current vapor pressure should not exceed saturation
        humidity_constraint = torch.relu(current_vapor_pressure - max_vapor_pressure) ** 2
        
        # Constraint 4: Wind consistency with pressure gradients
        # Geostrophic wind relationship: V_g = (1/f*rho) * grad(P)
        if 'pressure_gradient' in inputs:
            pressure_grad = torch.tensor(inputs['pressure_gradient'], device=device)
            latitude = inputs.get('latitude', torch.tensor(45.0, device=device))  # degrees
            
            # Coriolis parameter
            omega = 7.2921e-5  # Earth's rotation rate (rad/s)
            f = 2 * omega * torch.sin(torch.deg2rad(latitude))
            
            # Air density
            R_specific = 287.0  # J/(kg*K)
            air_density = pressure / (R_specific * temperature)
            
            # Expected geostrophic wind speed
            expected_wind_speed = torch.norm(pressure_grad) / (f * air_density)
            
            # Wind should be reasonably consistent with pressure gradient
            wind_constraint = torch.mean((wind_speed - expected_wind_speed) ** 2) / (expected_wind_speed ** 2 + 1e-6)
        else:
            wind_constraint = torch.tensor(0.0, device=device)
        
        # Constraint 5: Atmospheric stability
        # Richardson number for atmospheric stability
        if 'wind_shear' in inputs and 'buoyancy_frequency' in inputs:
            wind_shear = torch.tensor(inputs['wind_shear'], device=device)
            buoyancy_freq = torch.tensor(inputs['buoyancy_frequency'], device=device)
            
            richardson_number = buoyancy_freq ** 2 / (wind_shear ** 2 + 1e-6)
            
            # Critical Richardson number ~ 0.25 for turbulence onset
            stability_constraint = torch.relu(torch.abs(richardson_number - 0.25) - 1.0) ** 2
        else:
            stability_constraint = torch.tensor(0.0, device=device)
        
        # Combine meteorological constraints
        total_constraint = (
            0.25 * pressure_consistency +
            0.20 * lapse_rate_constraint +
            0.20 * humidity_constraint +
            0.20 * wind_constraint +
            0.15 * stability_constraint
        )
        
        return total_constraint
    
    async def _load_atmospheric_reference_data(self, parameters):
        """Load comprehensive atmospheric reference data from multiple sources"""
        try:
            # Initialize with standard atmosphere model
            reference_data = {
                'standard_pressure': 101325.0,  # Pa
                'standard_temperature': 288.15,  # K
                'lapse_rate': -0.0065,  # K/m
                'scale_height': 8400.0,  # m
                'water_vapor_scale_height': 2000.0,  # m
                'tropopause_height': 11000.0,  # m
                'stratospheric_temperature': 216.65,  # K
            }
            
            # Load location-specific data if available
            location = parameters.get('location')
            if location:
                latitude = location.get('latitude', 0.0)
                longitude = location.get('longitude', 0.0)
                elevation = location.get('elevation', 0.0)
                
                # Adjust reference data based on location
                # Tropical regions have higher tropopause
                if abs(latitude) < 30:
                    reference_data['tropopause_height'] = 17000.0
                    reference_data['lapse_rate'] = -0.0055  # K/m
                # Polar regions have lower tropopause
                elif abs(latitude) > 60:
                    reference_data['tropopause_height'] = 8000.0
                    reference_data['lapse_rate'] = -0.0075  # K/m
                
                # Elevation adjustments
                if elevation > 0:
                    # Adjust standard pressure for elevation
                    reference_data['standard_pressure'] *= np.exp(-elevation / reference_data['scale_height'])
                    reference_data['standard_temperature'] += reference_data['lapse_rate'] * elevation
            
            # Load real-time atmospheric data from external sources
            try:
                from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
                from backend.core.real_data_connectors.base_connector import DataSourceConfig, DataSourceType
                
                # Configure NASA connector for atmospheric data
                nasa_config = DataSourceConfig(
                    source_id="nasa_atmospheric",
                    name="NASA Atmospheric Data",
                    base_url="https://api.nasa.gov/planetary/earth",
                    api_key=os.getenv('NASA_API_KEY'),
                    data_type=DataSourceType.SATELLITE
                )
                
                async with NASAEarthDataConnector(nasa_config) as nasa_connector:
                    # Fetch recent atmospheric observations
                    if location:
                        bbox = [longitude - 0.5, latitude - 0.5, longitude + 0.5, latitude + 0.5]
                        
                        # Get atmospheric profile data
                        atmospheric_data = []
                        async for obs in nasa_connector.fetch_real_time_data(
                            instruments=['AIRS', 'MODIS'],
                            bbox=bbox
                        ):
                            if obs.observation_type in ['atmospheric_profile', 'temperature_profile']:
                                atmospheric_data.append(obs)
                            
                            # Limit to recent data
                            if len(atmospheric_data) >= 10:
                                break
                        
                        # Process atmospheric observations
                        if atmospheric_data:
                            # Extract temperature and pressure profiles
                            temp_profiles = []
                            pressure_profiles = []
                            
                            for obs in atmospheric_data:
                                if 'temperature_profile' in obs.value:
                                    temp_profiles.append(obs.value['temperature_profile'])
                                if 'pressure_profile' in obs.value:
                                    pressure_profiles.append(obs.value['pressure_profile'])
                            
                            # Compute mean profiles
                            if temp_profiles:
                                mean_temp_profile = np.mean(temp_profiles, axis=0)
                                reference_data['observed_temperature_profile'] = mean_temp_profile.tolist()
                            
                            if pressure_profiles:
                                mean_pressure_profile = np.mean(pressure_profiles, axis=0)
                                reference_data['observed_pressure_profile'] = mean_pressure_profile.tolist()
                
            except Exception as e:
                logger.warning(f"Failed to load real-time atmospheric data: {e}")
            
            # Load historical climatology from database
            try:
                async with self.db_integrator.get_postgresql_session() as session:
                    # Query atmospheric climatology
                    if location:
                        climatology_query = """
                        SELECT 
                            AVG(temperature_celsius) as mean_temp,
                            AVG(pressure_hpa) as mean_pressure,
                            AVG(relative_humidity) as mean_humidity,
                            STDDEV(temperature_celsius) as temp_std,
                            STDDEV(pressure_hpa) as pressure_std
                        FROM atmospheric_observations 
                        WHERE ST_DWithin(
                            location::geography,
                            ST_MakePoint(%s, %s)::geography,
                            50000  -- 50km radius
                        )
                        AND observation_time > NOW() - INTERVAL '1 year'
                        """
                        
                        result = await session.execute(
                            climatology_query, 
                            (longitude, latitude)
                        )
                        climatology = result.fetchone()
                        
                        if climatology:
                            reference_data['climatological_temperature'] = float(climatology.mean_temp + 273.15)
                            reference_data['climatological_pressure'] = float(climatology.mean_pressure * 100)  # hPa to Pa
                            reference_data['climatological_humidity'] = float(climatology.mean_humidity / 100)
                            reference_data['temperature_variability'] = float(climatology.temp_std)
                            reference_data['pressure_variability'] = float(climatology.pressure_std * 100)
                
            except Exception as e:
                logger.warning(f"Failed to load climatological data: {e}")
            
            # Load reanalysis data for more accurate reference
            try:
                # Query ERA5 or similar reanalysis data from database
                async with self.db_integrator.get_postgresql_session() as session:
                    if location:
                        reanalysis_query = """
                        SELECT 
                            temperature_2m,
                            surface_pressure,
                            relative_humidity_2m,
                            u_wind_10m,
                            v_wind_10m,
                            total_precipitation
                        FROM era5_reanalysis 
                        WHERE ST_DWithin(
                            location::geography,
                            ST_MakePoint(%s, %s)::geography,
                            25000  -- 25km radius
                        )
                        AND analysis_time > NOW() - INTERVAL '6 hours'
                        ORDER BY analysis_time DESC
                        LIMIT 1
                        """
                        
                        result = await session.execute(
                            reanalysis_query,
                            (longitude, latitude)
                        )
                        reanalysis = result.fetchone()
                        
                        if reanalysis:
                            reference_data['reanalysis_temperature'] = float(reanalysis.temperature_2m)
                            reference_data['reanalysis_pressure'] = float(reanalysis.surface_pressure)
                            reference_data['reanalysis_humidity'] = float(reanalysis.relative_humidity_2m / 100)
                            reference_data['reanalysis_wind_speed'] = float(
                                np.sqrt(reanalysis.u_wind_10m**2 + reanalysis.v_wind_10m**2)
                            )
                            reference_data['reanalysis_wind_direction'] = float(
                                np.degrees(np.arctan2(reanalysis.v_wind_10m, reanalysis.u_wind_10m))
                            )
                
            except Exception as e:
                logger.warning(f"Failed to load reanalysis data: {e}")
            
            return reference_data
            
        except Exception as e:
            logger.error(f"Failed to load atmospheric reference data: {e}")
            # Return basic standard atmosphere model
            return {
                'standard_pressure': 101325.0,
                'standard_temperature': 288.15,
                'lapse_rate': -0.0065,
                'scale_height': 8400.0,
                'water_vapor_scale_height': 2000.0
            }
    
    async def _fallback_lbfgs_optimization(self, pinn_model, X_tensor, training_data):
        """Fallback L-BFGS optimization with simplified constraints"""
        logger.info("Running fallback L-BFGS optimization...")
        
        fallback_optimizer = torch.optim.LBFGS(
            pinn_model.parameters(),
            lr=0.1,
            max_iter=20,
            tolerance_grad=1e-6
        )
        
        def simple_closure():
            fallback_optimizer.zero_grad()
            predictions = pinn_model(X_tensor)
            
            # Simple MSE loss
            if 'atmospheric_delays' in training_data:
                targets = torch.FloatTensor(training_data['atmospheric_delays']).to(X_tensor.device)
                loss = F.mse_loss(predictions.squeeze(), targets)
            else:
                loss = torch.mean(predictions**2)  # Regularization loss
            
            loss.backward()
            return loss
        
        try:
            fallback_optimizer.step(simple_closure)
            logger.info("Fallback L-BFGS optimization completed")
        except Exception as e:
            logger.error(f"Fallback L-BFGS optimization failed: {e}")
    
    # Physics-based data generation methods
    
    def _generate_physics_based_delays(self, lats, lons, alts, day_of_year, hour_of_day):
        """Generate physics-based atmospheric delays"""
        n_samples = len(lats)
        
        # Hydrostatic delay component (elevation dependent)
        hydrostatic_delays = -6.5e-6 * alts  # 6.5 mm/km
        
        # Wet delay component (humidity and temperature dependent)
        # Seasonal variation
        seasonal_factor = 1 + 0.3 * np.sin(2 * np.pi * day_of_year / 365.0)
        
        # Diurnal variation
        diurnal_factor = 1 + 0.1 * np.sin(2 * np.pi * hour_of_day / 24.0)
        
        # Latitude dependence (more water vapor near equator)
        latitude_factor = 1 + 0.5 * np.exp(-np.abs(lats) / 30.0)
        
        # Wet delay
        wet_delays = 0.02 * seasonal_factor * diurnal_factor * latitude_factor * np.random.exponential(1, n_samples)
        
        # Total atmospheric delay
        total_delays = hydrostatic_delays + wet_delays
        
        # Add realistic noise
        noise = np.random.normal(0, 0.005, n_samples)  # 5mm std noise
        
        return total_delays + noise
    
    def _generate_meteorological_features(self, lats, lons, alts, day_of_year, hour_of_day):
        """Generate realistic meteorological features"""
        n_samples = len(lats)
        
        # Temperature (K)
        base_temp = 288.15 - 0.0065 * alts  # Standard atmosphere lapse rate
        seasonal_temp = 10 * np.sin(2 * np.pi * day_of_year / 365.0)
        diurnal_temp = 5 * np.sin(2 * np.pi * hour_of_day / 24.0)
        latitude_temp = -20 * np.abs(lats) / 90.0
        temperature = base_temp + seasonal_temp + diurnal_temp + latitude_temp
        
        # Pressure (Pa)
        pressure = 101325 * np.exp(-alts / 8400.0)  # Barometric formula
        
        # Relative humidity (%)
        base_humidity = 60 + 30 * np.exp(-np.abs(lats) / 30.0)  # Higher near equator
        seasonal_humidity = 20 * np.sin(2 * np.pi * day_of_year / 365.0 + np.pi)  # Opposite phase to temperature
        humidity = np.clip(base_humidity + seasonal_humidity, 10, 95)
        
        # Wind speed (m/s)
        wind_speed = 5 + 10 * np.random.exponential(1, n_samples)
        
        # Wind direction (degrees)
        wind_direction = np.random.uniform(0, 360, n_samples)
        
        # Precipitation (mm/day)
        precipitation = np.random.exponential(2, n_samples) * (humidity / 100.0)
        
        # Cloud cover (%)
        cloud_cover = np.clip(humidity + np.random.normal(0, 20, n_samples), 0, 100)
        
        # Solar radiation (W/m²)
        solar_radiation = 1000 * np.maximum(0, np.sin(2 * np.pi * hour_of_day / 24.0)) * (1 - cloud_cover / 200.0)
        
        return np.column_stack([
            temperature, pressure, humidity, wind_speed, 
            wind_direction, precipitation, cloud_cover, solar_radiation
        ])
    
    def _generate_quality_weights(self, meteorological_features, atmospheric_delays):
        """Generate quality weights based on atmospheric conditions"""
        n_samples = len(atmospheric_delays)
        
        # Base quality
        quality = np.ones(n_samples) * 0.8
        
        # Reduce quality for high humidity (wet delay uncertainty)
        humidity = meteorological_features[:, 2]
        quality *= (1 - 0.3 * (humidity / 100.0))
        
        # Reduce quality for high cloud cover
        cloud_cover = meteorological_features[:, 6]
        quality *= (1 - 0.2 * (cloud_cover / 100.0))
        
        # Reduce quality for extreme delays
        delay_magnitude = np.abs(atmospheric_delays)
        extreme_delay_mask = delay_magnitude > np.percentile(delay_magnitude, 95)
        quality[extreme_delay_mask] *= 0.5
        
        # Add random quality variations
        quality *= np.random.uniform(0.8, 1.0, n_samples)
        
        return np.clip(quality, 0.1, 1.0)
    
    def _generate_physics_constraints(self, lats, alts, meteorological_features):
        """Generate physics constraints for atmospheric modeling"""
        n_samples = len(lats)
        
        # Pressure constraints
        pressure_constraints = meteorological_features[:, 1]  # Pressure from met features
        
        # Temperature constraints
        temperature_constraints = meteorological_features[:, 0]  # Temperature from met features
        
        # Humidity constraints
        humidity_constraints = meteorological_features[:, 2]  # Humidity from met features
        
        return np.column_stack([
            pressure_constraints, temperature_constraints, humidity_constraints
        ])
    
    def _assess_temporal_coverage(self, temporal_features):
        """Assess temporal coverage of validation data"""
        if temporal_features is None or len(temporal_features) == 0:
            return {'coverage': 'none'}
        
        if temporal_features.shape[1] > 0:
            time_range = np.max(temporal_features[:, 0]) - np.min(temporal_features[:, 0])
            return {
                'coverage': 'good' if time_range > 0.5 else 'limited',
                'time_range': float(time_range),
                'n_temporal_samples': len(temporal_features)
            }
        
        return {'coverage': 'none'}
    
    def _assess_spatial_coverage(self, spatial_coordinates):
        """Assess spatial coverage of validation data"""
        if spatial_coordinates is None or len(spatial_coordinates) == 0:
            return {'coverage': 'none'}
        
        if spatial_coordinates.shape[1] >= 2:
            x_range = np.max(spatial_coordinates[:, 0]) - np.min(spatial_coordinates[:, 0])
            y_range = np.max(spatial_coordinates[:, 1]) - np.min(spatial_coordinates[:, 1])
            
            return {
                'coverage': 'good' if min(x_range, y_range) > 0.3 else 'limited',
                'x_range': float(x_range),
                'y_range': float(y_range),
                'n_spatial_samples': len(spatial_coordinates)
            }
        
        return {'coverage': 'none'}
    
    def _apply_atmospheric_scaling(self, met_features):
        """Apply atmospheric physics-based scaling to meteorological features"""
        scaled_features = met_features.copy()
        
        # Temperature scaling (K to normalized)
        if scaled_features.shape[1] > 0:
            scaled_features[:, 0] = (scaled_features[:, 0] - 273.15) / 50.0  # Temperature
        
        # Pressure scaling (Pa to normalized)
        if scaled_features.shape[1] > 1:
            scaled_features[:, 1] = (scaled_features[:, 1] - 101325) / 10000.0  # Pressure
        
        # Humidity scaling (% to normalized)
        if scaled_features.shape[1] > 2:
            scaled_features[:, 2] = scaled_features[:, 2] / 100.0  # Humidity
        
        return scaled_features
    
    def _apply_elevation_weighting(self, spatial_coords):
        """Apply elevation-dependent atmospheric weighting"""
        weighted_coords = spatial_coords.copy()
        
        if weighted_coords.shape[1] >= 3:
            # Apply exponential weighting based on elevation
            elevation_weights = np.exp(-weighted_coords[:, 2] / 0.3)  # Scale height weighting
            weighted_coords = weighted_coords * elevation_weights[:, np.newaxis]
        
        return weighted_coords
    
    def _add_atmospheric_temporal_patterns(self, temporal_features):
        """Add atmospheric temporal patterns to temporal features"""
        enhanced_temporal = temporal_features.copy()
        
        if enhanced_temporal.shape[1] > 0:
            # Add atmospheric delay temporal patterns
            day_of_year = enhanced_temporal[:, 0] * 365.0
            
            # Seasonal atmospheric patterns
            seasonal_pattern = np.sin(2 * np.pi * day_of_year / 365.0)
            
            # Semi-annual pattern
            semi_annual_pattern = np.sin(4 * np.pi * day_of_year / 365.0)
            
            # Add patterns as new features
            enhanced_temporal = np.column_stack([
                enhanced_temporal,
                seasonal_pattern,
                semi_annual_pattern
            ])
        
        return enhanced_temporal
    
    async def _load_era5_atmospheric_data(self, parameters):
        """Load ERA5 reanalysis atmospheric data from Copernicus Climate Data Store"""
        try:
            from backend.core.real_data_connectors.copernicus_connector import CopernicusConnector
            from backend.core.real_data_connectors.base_connector import DataSourceConfig
            
            # Initialize Copernicus connector for ERA5 data
            config = DataSourceConfig(
                base_url="https://cds.climate.copernicus.eu/api/v2",
                api_key=parameters.get('copernicus_api_key', os.getenv('COPERNICUS_API_KEY')),
                username=parameters.get('copernicus_username', os.getenv('COPERNICUS_USERNAME')),
                password=parameters.get('copernicus_password', os.getenv('COPERNICUS_PASSWORD'))
            )
            
            connector = CopernicusConnector(config)
            await connector._authenticate()
            
            # Define spatial and temporal bounds
            spatial_bounds = parameters.get('spatial_bounds', {
                'north': 90, 'south': -90, 'east': 180, 'west': -180
            })
            temporal_bounds = parameters.get('temporal_bounds', {
                'start_date': datetime.now() - timedelta(days=30),
                'end_date': datetime.now()
            })
            
            # ERA5 pressure levels (hPa)
            pressure_levels = [1000, 975, 950, 925, 900, 875, 850, 825, 800, 775, 750, 700, 650, 600, 550, 500, 450, 400, 350, 300, 250, 200, 150, 100, 70, 50, 30, 20, 10]
            
            # Request ERA5 atmospheric data
            era5_request = {
                'product_type': 'reanalysis',
                'format': 'netcdf',
                'variable': [
                    'temperature', 'relative_humidity', 'geopotential',
                    'u_component_of_wind', 'v_component_of_wind',
                    'specific_humidity', 'vertical_velocity'
                ],
                'pressure_level': pressure_levels,
                'year': [str(temporal_bounds['start_date'].year), str(temporal_bounds['end_date'].year)],
                'month': [f"{m:02d}" for m in range(temporal_bounds['start_date'].month, temporal_bounds['end_date'].month + 1)],
                'day': [f"{d:02d}" for d in range(1, 32)],
                'time': [f"{h:02d}:00" for h in range(0, 24, 6)],  # 6-hourly data
                'area': [spatial_bounds['north'], spatial_bounds['west'], spatial_bounds['south'], spatial_bounds['east']],
                'grid': [0.25, 0.25]  # 0.25° x 0.25° resolution
            }
            
            # Download ERA5 data
            era5_data = await self._download_era5_data(connector, era5_request, parameters)
            
            # Process ERA5 data for atmospheric correction
            processed_data = await self._process_era5_atmospheric_data(era5_data, parameters)
            
            logger.info(f"Loaded ERA5 atmospheric data: {len(processed_data['pressure_levels'])} pressure levels")
            logger.info(f"Temporal coverage: {temporal_bounds['start_date']} to {temporal_bounds['end_date']}")
            logger.info(f"Spatial coverage: {spatial_bounds}")
            
            return processed_data
            
        except Exception as e:
            logger.error(f"Failed to load ERA5 atmospheric data: {e}")
            # Fallback to high-quality synthetic data based on ERA5 climatology
            return await self._generate_era5_climatology_data(parameters)
    
    async def _load_gacos_correction_data(self, parameters):
        """Load GACOS (Generic Atmospheric Correction Online Service) atmospheric correction data"""
        try:
            import requests
            import xarray as xr
            from io import BytesIO
            
            # GACOS service configuration
            gacos_base_url = "http://ceg-research.ncl.ac.uk/v2/gacos/"
            
            # Get spatial and temporal parameters
            spatial_bounds = parameters.get('spatial_bounds', {
                'north': 90, 'south': -90, 'east': 180, 'west': -180
            })
            temporal_bounds = parameters.get('temporal_bounds', {
                'start_date': datetime.now() - timedelta(days=30),
                'end_date': datetime.now()
            })
            
            # Query GACOS for available correction maps
            gacos_data = await self._query_gacos_service(gacos_base_url, spatial_bounds, temporal_bounds, parameters)
            
            if gacos_data:
                # Process GACOS correction maps
                processed_gacos = await self._process_gacos_corrections(gacos_data, parameters)
                
                logger.info(f"Loaded GACOS atmospheric corrections: {processed_gacos['correction_maps'].shape}")
                logger.info(f"Uncertainty range: {np.min(processed_gacos['uncertainty_maps']):.4f} to {np.max(processed_gacos['uncertainty_maps']):.4f} m")
                
                return processed_gacos
            else:
                raise Exception("No GACOS data available for specified parameters")
                
        except Exception as e:
            logger.warning(f"Failed to load GACOS correction data: {e}")
            # Generate high-quality synthetic GACOS-like corrections
            return await self._generate_synthetic_gacos_corrections(parameters)
    
