    async def _apply_physics_constraints(self, correction, phase_data, meteo_data):
        """Apply physics-based constraints to atmospheric correction"""
        # Constraint 1: Atmospheric delay should correlate with elevation
        if 'elevation' in meteo_data:
            elevation = meteo_data['elevation']
            if elevation is not None and elevation.shape == correction.shape:
                # Expected atmospheric delay gradient: ~6.5 mm/km elevation
                expected_gradient = 0.0065  # mm/m
                elevation_correction = elevation * expected_gradient
                
                # Blend with ML correction based on confidence
                confidence = meteo_data.get('confidence', 0.5)
                correction = confidence * correction + (1 - confidence) * elevation_correction
        
        # Constraint 2: Smooth spatial variation (atmospheric delays are typically smooth)
        correction = ndimage.gaussian_filter(correction, sigma=2.0)
        
        # Constraint 3: Temporal consistency (atmospheric patterns evolve slowly)
        if hasattr(self, '_previous_correction'):
            temporal_weight = 0.1
            correction = (1 - temporal_weight) * correction + temporal_weight * self._previous_correction
        
        self._previous_correction = correction.copy()
        
        return correction
    
    async def _enforce_spatiotemporal_consistency(self, corrections, uncertainties, phases, parameters):
        """Enforce spatio-temporal consistency in atmospheric corrections"""
        n_ifg, ny, nx = corrections.shape
        
        # Spatial consistency: smooth corrections within each interferogram
        for i in range(n_ifg):
            # Adaptive smoothing based on uncertainty
            sigma = np.clip(2.0 / (uncertainties[i] + 0.1), 0.5, 5.0)
            corrections[i] = ndimage.gaussian_filter(corrections[i], sigma=sigma)
        
        # Temporal consistency: smooth evolution of corrections
        for y in range(ny):
            for x in range(nx):
                time_series = corrections[:, y, x]
                uncertainty_series = uncertainties[:, y, x]
                
                # Weighted temporal smoothing
                weights = 1.0 / (uncertainty_series + 0.01)
                smoothed_series = self._weighted_temporal_smooth(time_series, weights)
                corrections[:, y, x] = smoothed_series
        
        return corrections, uncertainties
    
    def _weighted_temporal_smooth(self, time_series, weights, window_size=5):
        """Apply weighted temporal smoothing"""
        smoothed = np.copy(time_series)
        n = len(time_series)
        
        for i in range(n):
            start_idx = max(0, i - window_size // 2)
            end_idx = min(n, i + window_size // 2 + 1)
            
            window_values = time_series[start_idx:end_idx]
            window_weights = weights[start_idx:end_idx]
            
            if np.sum(window_weights) > 0:
                smoothed[i] = np.average(window_values, weights=window_weights)
        
        return smoothed
    
    async def _fallback_atmospheric_correction(self, phases, historical_data, parameters):
        """Fallback atmospheric correction using robust statistical methods"""
        n_ifg, ny, nx = phases.shape
        corrections = np.zeros_like(phases)
        uncertainties = np.ones_like(phases) * 0.1
        
        # Simple elevation-based correction
        if 'dem' in parameters:
            dem = parameters['dem']
            for i in range(n_ifg):
                # Linear relationship between phase and elevation
                valid_mask = ~np.isnan(phases[i]) & ~np.isnan(dem)
                if np.sum(valid_mask) > 100:
                    phase_valid = phases[i][valid_mask]
                    elev_valid = dem[valid_mask]
                    
                    # Robust linear regression
                    slope, intercept = np.polyfit(elev_valid, phase_valid, 1)
                    corrections[i] = slope * dem + intercept
                    
                    # Uncertainty based on residuals
                    residuals = phase_valid - (slope * elev_valid + intercept)
                    uncertainties[i] = np.full_like(phases[i], np.std(residuals))
        
        return {
            'correction': corrections,
            'uncertainty': uncertainties,
            'method': 'fallback_statistical'
        }
    
    # Helper methods for feature extraction and model utilities
    def _compute_lapse_rate(self, temperature_profile, elevation_profile=None):
        """Compute atmospheric lapse rate with advanced vertical resolution"""
        if len(temperature_profile) < 2:
            return -0.0065  # Standard atmosphere lapse rate
        
        temp_array = np.array(temperature_profile)
        
        if elevation_profile is not None and len(elevation_profile) == len(temperature_profile):
            elev_array = np.array(elevation_profile)
            # Compute lapse rate as dT/dz
            if len(elev_array) > 1:
                # Use finite differences for more accurate gradient
                lapse_rates = np.gradient(temp_array, elev_array)
                # Return mean lapse rate, filtering out extreme values
                valid_rates = lapse_rates[np.abs(lapse_rates) < 0.02]  # Filter unrealistic rates
                return np.mean(valid_rates) if len(valid_rates) > 0 else -0.0065
        
        # If no elevation profile, assume uniform spacing
        return np.gradient(temp_array)[0] if len(temp_array) > 1 else -0.0065
    
    def _compute_atmospheric_stability(self, data_point):
        """Compute comprehensive atmospheric stability using multiple indicators"""
        temp_profile = data_point.get('temperature_profile', [288.15] * 20)
        elevation_profile = data_point.get('elevation_profile')
        humidity_profile = data_point.get('humidity_profile')
        wind_profile = data_point.get('wind_profile')
        
        if len(temp_profile) < 2:
            return 0.0
        
        # 1. Temperature lapse rate stability
        observed_lapse_rate = self._compute_lapse_rate(temp_profile, elevation_profile)
        dry_adiabatic_lapse = -0.0098  # K/m
        moist_adiabatic_lapse = -0.006  # K/m (approximate)
        
        # Stability parameter based on lapse rate
        if observed_lapse_rate > dry_adiabatic_lapse:
            # Unstable (superadiabatic)
            lapse_stability = (observed_lapse_rate - dry_adiabatic_lapse) / abs(dry_adiabatic_lapse)
        elif observed_lapse_rate > moist_adiabatic_lapse:
            # Conditionally unstable
            lapse_stability = 0.5 * (observed_lapse_rate - moist_adiabatic_lapse) / abs(moist_adiabatic_lapse)
        else:
            # Stable
            lapse_stability = (observed_lapse_rate - moist_adiabatic_lapse) / abs(moist_adiabatic_lapse)
        
        # 2. Richardson number (if wind data available)
        richardson_number = 0.0
        if wind_profile and len(wind_profile) >= 2 and elevation_profile:
            try:
                wind_speeds = np.array([w.get('speed', 0) for w in wind_profile])
                elevations = np.array(elevation_profile)
                temperatures = np.array(temp_profile)
                
                # Compute wind shear
                wind_shear = np.gradient(wind_speeds, elevations)
                
                # Compute Brunt-Väisälä frequency (buoyancy frequency)
                g = 9.81  # m/s²
                theta = temperatures * (1000.0 / 1013.25) ** 0.286  # Potential temperature
                theta_gradient = np.gradient(theta, elevations)
                
                # Ensure arrays have compatible dimensions
                min_len = min(len(theta) - 1, len(theta_gradient), len(wind_shear))
                if min_len > 0:
                    brunt_vaisala_freq_squared = (g / theta[:min_len]) * theta_gradient[:min_len]
                    
                    # Richardson number
                    ri_values = brunt_vaisala_freq_squared / (wind_shear[:min_len] ** 2 + 1e-6)
                    richardson_number = np.mean(ri_values[np.isfinite(ri_values)])
                    
            except Exception as e:
                logger.warning(f"Failed to compute Richardson number: {e}")
        
        # 3. Convective Available Potential Energy (CAPE) approximation
        cape_indicator = 0.0
        if humidity_profile and len(humidity_profile) >= 2:
            try:
                # Simplified CAPE calculation
                surface_temp = temp_profile[0]
                surface_humidity = humidity_profile[0]
                
                # Estimate lifting condensation level
                dewpoint = surface_temp - ((100 - surface_humidity * 100) / 5.0)
                lcl_height = 125 * (surface_temp - dewpoint)  # meters
                
                # Estimate CAPE based on temperature excess above environment
                if lcl_height < max(elevation_profile) if elevation_profile else 5000:
                    temp_excess = max(0, surface_temp - np.mean(temp_profile))
                    cape_indicator = temp_excess / 10.0  # Normalized indicator
                    
            except Exception as e:
                logger.warning(f"Failed to compute CAPE indicator: {e}")
        
        # 4. Bulk Richardson number (simplified)
        bulk_richardson = 0.0
        if len(temp_profile) >= 2 and wind_profile and len(wind_profile) >= 2:
            try:
                surface_temp = temp_profile[0]
                upper_temp = temp_profile[-1]
                surface_wind = wind_profile[0].get('speed', 0)
                upper_wind = wind_profile[-1].get('speed', 0)
                
                height_diff = elevation_profile[-1] - elevation_profile[0] if elevation_profile else 1000
                temp_diff = upper_temp - surface_temp
                wind_diff = upper_wind - surface_wind
                
                if wind_diff != 0:
                    bulk_richardson = (9.81 / surface_temp) * (temp_diff * height_diff) / (wind_diff ** 2)
                    
            except Exception as e:
                logger.warning(f"Failed to compute bulk Richardson number: {e}")
        
        # Combine stability indicators
        # Positive values indicate stable conditions, negative indicate unstable
        stability_indicators = {
            'lapse_rate_stability': lapse_stability,
            'richardson_number': richardson_number,
            'cape_indicator': -cape_indicator,  # Negative because high CAPE = unstable
            'bulk_richardson': bulk_richardson
        }
        
        # Weighted combination
        weights = {
            'lapse_rate_stability': 0.4,
            'richardson_number': 0.3,
            'cape_indicator': 0.2,
            'bulk_richardson': 0.1
        }
        
        overall_stability = sum(
            weights[key] * value for key, value in stability_indicators.items()
            if not np.isnan(value) and np.isfinite(value)
        )
        
        # Normalize to [-2, 2] range
        # -2: very unstable, -1: unstable, 0: neutral, 1: stable, 2: very stable
        overall_stability = np.clip(overall_stability, -2.0, 2.0)
        
        return overall_stability
    
    async def _compute_solar_elevation(self, data_point):
        """
        Compute precise solar elevation angle using advanced astronomical algorithms
        with atmospheric refraction correction and database-integrated location data
        """
        try:
            # Extract acquisition time and location from data point
            acquisition_time = data_point.get('acquisition_time', datetime.now())
            if isinstance(acquisition_time, str):
                acquisition_time = datetime.fromisoformat(acquisition_time.replace('Z', '+00:00'))
            
            # Get precise location data from database
            location_data = await self._get_precise_location_data(data_point)
            latitude = location_data['latitude']
            longitude = location_data['longitude']
            elevation_m = location_data['elevation']
            
            # Convert to UTC if not already
            if acquisition_time.tzinfo is None:
                acquisition_time = acquisition_time.replace(tzinfo=timezone.utc)
            elif acquisition_time.tzinfo != timezone.utc:
                acquisition_time = acquisition_time.astimezone(timezone.utc)
            
            # Compute Julian Day Number with high precision
            julian_day = await self._compute_precise_julian_day(acquisition_time)
            
            # Compute solar coordinates using VSOP87 theory
            solar_coords = await self._compute_vsop87_solar_position(julian_day)
            
            # Apply nutation and aberration corrections
            corrected_coords = await self._apply_astronomical_corrections(
                solar_coords, julian_day
            )
            
            # Convert to topocentric coordinates
            topocentric_coords = await self._convert_to_topocentric(
                corrected_coords, latitude, longitude, elevation_m, julian_day
            )
            
            # Apply atmospheric refraction correction
            refracted_elevation = await self._apply_atmospheric_refraction(
                topocentric_coords['elevation'], elevation_m, data_point
            )
            
            # Compute additional solar parameters
            solar_parameters = await self._compute_extended_solar_parameters(
                refracted_elevation, topocentric_coords, julian_day, latitude, longitude
            )
            
            return {
                'elevation_degrees': refracted_elevation,
                'azimuth_degrees': topocentric_coords['azimuth'],
                'distance_au': solar_coords['distance'],
                'equation_of_time_minutes': solar_parameters['equation_of_time'],
                'solar_declination_degrees': corrected_coords['declination'],
                'hour_angle_degrees': topocentric_coords['hour_angle'],
                'air_mass': solar_parameters['air_mass'],
                'extraterrestrial_irradiance': solar_parameters['extraterrestrial_irradiance'],
                'atmospheric_transmission': solar_parameters['atmospheric_transmission'],
                'refraction_correction_degrees': refracted_elevation - topocentric_coords['elevation']
            }
            
        except Exception as e:
            logger.error(f"Advanced solar elevation computation failed: {e}")
            # Fallback to basic calculation
            return await self._fallback_solar_elevation(data_point)
    
    async def _get_precise_location_data(self, data_point):
        """Get precise location data from database with DEM integration"""
        try:
            # Try to get location from data point first
            if 'latitude' in data_point and 'longitude' in data_point:
                lat = float(data_point['latitude'])
                lon = float(data_point['longitude'])
            else:
                # Query database for location based on station/site ID
                location_query = """
                SELECT 
                    ST_Y(location) as latitude,
                    ST_X(location) as longitude,
                    ST_Z(location) as elevation
                FROM geological_structures gs
                WHERE gs.structure_id = %s
                LIMIT 1;
                """
                
                site_id = data_point.get('site_id', data_point.get('station_id', 'default'))
                # Execute real database query for station coordinates
                try:
                    async with self.db_integrator.get_postgresql_session() as session:
                        station_query = """
                        SELECT 
                            ST_Y(location::geometry) as latitude,
                            ST_X(location::geometry) as longitude,
                            ST_Z(location::geometry) as elevation
                        FROM monitoring_stations 
                        WHERE station_code = %s 
                        AND station_type IN ('gps', 'insar', 'tilt', 'strain')
                        ORDER BY installation_date DESC
                        LIMIT 1
                        """
                        
                        result = await session.execute(station_query, (station_id,))
                        station_data = result.fetchone()
                        
                        if station_data:
                            lat, lon = float(station_data.latitude), float(station_data.longitude)
                            elevation = float(station_data.elevation) if station_data.elevation else 0.0
                        else:
                            # Fallback: query volcanic systems for approximate location
                            volcano_query = """
                            SELECT 
                                ST_Y(location::geometry) as latitude,
                                ST_X(location::geometry) as longitude,
                                elevation
                            FROM volcanic_systems 
                            WHERE monitoring_status = 'active'
                            ORDER BY ST_Distance(
                                location::geometry,
                                ST_MakePoint(-120.0, 40.0)
                            )
                            LIMIT 1
                            """
                            
                            result = await session.execute(volcano_query)
                            volcano_data = result.fetchone()
                            
                            if volcano_data:
                                lat, lon = float(volcano_data.latitude), float(volcano_data.longitude)
                                elevation = float(volcano_data.elevation) if volcano_data.elevation else 0.0
                            else:
                                # Final fallback to default coordinates
                                lat, lon, elevation = 40.0, -120.0, 0.0
                                
                except Exception as e:
                    logger.warning(f"Failed to query station coordinates: {e}")
                    lat, lon, elevation = 40.0, -120.0, 0.0
            
            # Get elevation from DEM if not provided
            elevation = data_point.get('elevation', None)
            if elevation is None:
                elevation = await self._get_dem_elevation(lat, lon)
            
            # Apply geodetic corrections for precise positioning
            corrected_coords = await self._apply_geodetic_corrections(lat, lon, elevation)
            
            return {
                'latitude': corrected_coords['latitude'],
                'longitude': corrected_coords['longitude'],
                'elevation': corrected_coords['elevation'],
                'datum': corrected_coords['datum'],
                'geoid_height': corrected_coords['geoid_height']
            }
            
        except Exception as e:
            logger.warning(f"Failed to get precise location data: {e}")
            return {
                'latitude': 40.0,
                'longitude': -120.0,
                'elevation': 1000.0,
                'datum': 'WGS84',
                'geoid_height': 0.0
            }
    
    async def _get_dem_elevation(self, latitude, longitude):
        """Get elevation from high-resolution DEM data"""
        try:
            # Query DEM data from database
            dem_query = """
            SELECT ST_Value(rast, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as elevation
            FROM dem_tiles
            WHERE ST_Intersects(rast, ST_SetSRID(ST_MakePoint(%s, %s), 4326))
            ORDER BY ST_PixelWidth(rast) ASC
            LIMIT 1;
            """
            
            # Execute real database query for elevation data
            try:
                elevation = await self._query_elevation_from_database(latitude, longitude)
            except Exception as e:
                logger.warning(f"Database elevation query failed: {e}")
                # Fallback to external DEM services
                elevation = await self._query_external_elevation_services(latitude, longitude)
            
            return elevation
            
        except Exception as e:
            logger.warning(f"DEM elevation lookup failed: {e}")
            return 1000.0  # Default elevation
    
