    async def _query_multi_resolution_dem_data(self, latitude, longitude):
        """Query multi-resolution DEM data from various sources"""
        try:
            # Create spatial point for queries
            point_wkt = f"POINT({longitude} {latitude})"
            
            # Query high-resolution DEM tiles (e.g., LiDAR, SRTM-GL1)
            high_res_query = """
            WITH point_geom AS (
                SELECT ST_SetSRID(ST_GeomFromText(%s), 4326) as geom
            ),
            dem_hierarchy AS (
                SELECT 
                    dt.tile_id,
                    dt.resolution_m,
                    dt.data_source,
                    dt.acquisition_date,
                    dt.vertical_accuracy_m,
                    ST_Value(dt.raster_data, pg.geom) as elevation_value,
                    ST_PixelWidth(dt.raster_data) as pixel_width,
                    ST_PixelHeight(dt.raster_data) as pixel_height,
                    ST_Distance(ST_Centroid(dt.raster_data), pg.geom) as distance_to_center,
                    CASE 
                        WHEN dt.resolution_m <= 1.0 THEN 'lidar'
                        WHEN dt.resolution_m <= 10.0 THEN 'high_res'
                        WHEN dt.resolution_m <= 30.0 THEN 'medium_res'
                        ELSE 'low_res'
                    END as resolution_category
                FROM dem_tiles dt, point_geom pg
                WHERE ST_Intersects(dt.raster_data, pg.geom)
                AND dt.quality_flag = 'valid'
                ORDER BY dt.resolution_m ASC, dt.vertical_accuracy_m ASC
            )
            SELECT 
                array_agg(elevation_value ORDER BY resolution_m ASC) as elevation_values,
                array_agg(resolution_m ORDER BY resolution_m ASC) as resolutions,
                array_agg(data_source ORDER BY resolution_m ASC) as sources,
                array_agg(vertical_accuracy_m ORDER BY resolution_m ASC) as accuracies,
                array_agg(pixel_width ORDER BY resolution_m ASC) as pixel_widths,
                array_agg(distance_to_center ORDER BY resolution_m ASC) as distances,
                COUNT(*) as tile_count,
                MIN(resolution_m) as best_resolution,
                MAX(vertical_accuracy_m) as worst_accuracy
            FROM dem_hierarchy
            WHERE elevation_value IS NOT NULL;
            """
            
            # Execute query (simulated for now - would use actual database connection)
            dem_data = await self._execute_dem_query(high_res_query, point_wkt)
            
            # Query surrounding topographic context
            context_data = await self._query_topographic_context(latitude, longitude)
            
            # Query geological context for elevation validation
            geological_context = await self._query_geological_elevation_context(latitude, longitude)
            
            return {
                'high_res_available': dem_data['tile_count'] > 0,
                'elevation_values': dem_data.get('elevation_values', []),
                'resolutions': dem_data.get('resolutions', []),
                'data_sources': dem_data.get('sources', []),
                'accuracies': dem_data.get('accuracies', []),
                'best_resolution': dem_data.get('best_resolution', 30.0),
                'topographic_context': context_data,
                'geological_context': geological_context,
                'query_point': {'lat': latitude, 'lon': longitude}
            }
            
        except Exception as e:
            logger.warning(f"DEM data query failed: {e}")
            return {
                'high_res_available': False,
                'elevation_values': [],
                'resolutions': [],
                'data_sources': [],
                'accuracies': [],
                'best_resolution': 30.0,
                'topographic_context': {},
                'geological_context': {},
                'query_point': {'lat': latitude, 'lon': longitude}
            }
    
    async def _execute_dem_query(self, query, point_wkt):
        """Execute comprehensive DEM query using multiple high-resolution data sources"""
        try:
            # Extract coordinates from WKT
            coords = point_wkt.replace('POINT(', '').replace(')', '').split()
            longitude, latitude = float(coords[0]), float(coords[1])
            
            # Query multiple DEM sources from database
            dem_results = await self._query_multi_resolution_dem_data(latitude, longitude)
            
            if dem_results['tile_count'] > 0:
                return dem_results
            
            # Fallback to external DEM services
            external_results = await self._query_external_dem_services(latitude, longitude)
            
            return external_results
            
        except Exception as e:
            logger.error(f"DEM query execution failed: {e}")
            return {
                'tile_count': 0,
                'elevation_values': [],
                'resolutions': [],
                'sources': [],
                'accuracies': []
            }
    
    async def _query_multi_resolution_dem_data(self, latitude, longitude):
        """Query multi-resolution DEM data from PostGIS database"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                # Query DEM tiles at different resolutions
                dem_query = """
                WITH point_location AS (
                    SELECT ST_SetSRID(ST_MakePoint(%s, %s), 4326) as geom
                ),
                dem_tiles AS (
                    SELECT 
                        dt.resolution_meters,
                        dt.data_source,
                        dt.vertical_accuracy_meters,
                        ST_Value(dt.raster, pl.geom) as elevation_value,
                        ST_PixelWidth(dt.raster) as pixel_width,
                        ST_PixelHeight(dt.raster) as pixel_height,
                        dt.acquisition_date,
                        dt.processing_level
                    FROM digital_elevation_models dt
                    CROSS JOIN point_location pl
                    WHERE ST_Intersects(dt.raster, pl.geom)
                    AND dt.elevation_value IS NOT NULL
                    ORDER BY dt.resolution_meters ASC
                )
                SELECT * FROM dem_tiles
                """
                
                result = await session.execute(dem_query, (longitude, latitude))
                dem_data = result.fetchall()
                
                if dem_data:
                    elevations = []
                    resolutions = []
                    sources = []
                    accuracies = []
                    
                    for row in dem_data:
                        if row.elevation_value is not None:
                            elevations.append(float(row.elevation_value))
                            resolutions.append(float(row.resolution_meters))
                            sources.append(row.data_source)
                            accuracies.append(float(row.vertical_accuracy_meters))
                    
                    return {
                        'tile_count': len(elevations),
                        'elevation_values': elevations,
                        'resolutions': resolutions,
                        'sources': sources,
                        'accuracies': accuracies,
                        'best_resolution': min(resolutions) if resolutions else None,
                        'worst_accuracy': max(accuracies) if accuracies else None
                    }
                
                # If no raster data, try point elevation data
                point_elevation_query = """
                SELECT 
                    elevation_meters,
                    data_source,
                    vertical_accuracy_meters,
                    ST_Distance(
                        location::geography,
                        ST_SetSRID(ST_MakePoint(%s, %s), 4326)::geography
                    ) as distance_meters
                FROM elevation_points
                WHERE ST_DWithin(
                    location::geography,
                    ST_SetSRID(ST_MakePoint(%s, %s), 4326)::geography,
                    1000  -- 1km search radius
                )
                ORDER BY distance_meters ASC
                LIMIT 10
                """
                
                result = await session.execute(
                    point_elevation_query, 
                    (longitude, latitude, longitude, latitude)
                )
                point_data = result.fetchall()
                
                if point_data:
                    # Use inverse distance weighting for interpolation
                    elevations = []
                    weights = []
                    sources = []
                    accuracies = []
                    
                    for row in point_data:
                        distance = max(row.distance_meters, 1.0)  # Avoid division by zero
                        weight = 1.0 / (distance ** 2)
                        
                        elevations.append(float(row.elevation_meters))
                        weights.append(weight)
                        sources.append(row.data_source)
                        accuracies.append(float(row.vertical_accuracy_meters))
                    
                    # Weighted average elevation
                    weighted_elevation = sum(e * w for e, w in zip(elevations, weights)) / sum(weights)
                    
                    return {
                        'tile_count': 1,
                        'elevation_values': [weighted_elevation],
                        'resolutions': [30.0],  # Approximate resolution for point interpolation
                        'sources': list(set(sources)),
                        'accuracies': [np.mean(accuracies)],
                        'best_resolution': 30.0,
                        'worst_accuracy': max(accuracies) if accuracies else 10.0
                    }
                
                return {
                    'tile_count': 0,
                    'elevation_values': [],
                    'resolutions': [],
                    'sources': [],
                    'accuracies': []
                }
                
        except Exception as e:
            logger.error(f"Database DEM query failed: {e}")
            return {
                'tile_count': 0,
                'elevation_values': [],
                'resolutions': [],
                'sources': [],
                'accuracies': []
            }
    
    async def _query_external_dem_services(self, latitude, longitude):
        """Query external DEM services as fallback"""
        try:
            from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
            from backend.core.real_data_connectors.usgs_connector import USGSVolcanoConnector
            from backend.core.real_data_connectors.base_connector import DataSourceConfig, DataSourceType
            
            elevations = []
            resolutions = []
            sources = []
            accuracies = []
            
            # Query NASA SRTM data
            try:
                nasa_config = DataSourceConfig(
                    source_id="nasa_srtm",
                    name="NASA SRTM",
                    base_url="https://api.nasa.gov/planetary/earth/elevation",
                    api_key=os.getenv('NASA_API_KEY'),
                    data_type=DataSourceType.SATELLITE
                )
                
                async with NASAEarthDataConnector(nasa_config) as nasa_connector:
                    # Query SRTM elevation
                    srtm_url = f"{nasa_config.base_url}?lon={longitude}&lat={latitude}&units=meters"
                    srtm_response = await nasa_connector._make_request('GET', srtm_url)
                    
                    if srtm_response and 'elevation' in srtm_response:
                        elevations.append(float(srtm_response['elevation']))
                        resolutions.append(30.0)  # SRTM 1-arc-second
                        sources.append('SRTM_GL1')
                        accuracies.append(16.0)  # SRTM vertical accuracy
                        
            except Exception as e:
                logger.warning(f"NASA SRTM query failed: {e}")
            
            # Query USGS elevation services
            try:
                usgs_config = DataSourceConfig(
                    source_id="usgs_elevation",
                    name="USGS Elevation Service",
                    base_url="https://nationalmap.gov/epqs/pqs.php",
                    data_type=DataSourceType.GEOLOGICAL_SURVEY
                )
                
                # Query USGS elevation point query service
                import aiohttp
                async with aiohttp.ClientSession() as session:
                    usgs_url = f"{usgs_config.base_url}?x={longitude}&y={latitude}&units=Meters&output=json"
                    
                    async with session.get(usgs_url) as response:
                        if response.status == 200:
                            usgs_data = await response.json()
                            
                            if 'USGS_Elevation_Point_Query_Service' in usgs_data:
                                elevation_data = usgs_data['USGS_Elevation_Point_Query_Service']
                                if 'Elevation_Query' in elevation_data:
                                    elevation = elevation_data['Elevation_Query']['Elevation']
                                    
                                    if elevation != -1000000:  # USGS no-data value
                                        elevations.append(float(elevation))
                                        resolutions.append(10.0)  # 3DEP 1/3 arc-second
                                        sources.append('USGS_3DEP')
                                        accuracies.append(1.85)  # 3DEP vertical accuracy
                                        
            except Exception as e:
                logger.warning(f"USGS elevation query failed: {e}")
            
            # Query OpenTopography services
            try:
                import aiohttp
                async with aiohttp.ClientSession() as session:
                    # ASTER GDEM
                    aster_url = f"https://cloud.sdsc.edu/v1/elevation?demtype=ASTER&west={longitude}&south={latitude}&east={longitude}&north={latitude}&fmt=json"
                    
                    async with session.get(aster_url) as response:
                        if response.status == 200:
                            aster_data = await response.json()
                            
                            if 'results' in aster_data and len(aster_data['results']) > 0:
                                elevation = aster_data['results'][0]['elevation']
                                elevations.append(float(elevation))
                                resolutions.append(30.0)  # ASTER GDEM resolution
                                sources.append('ASTER_GDEM')
                                accuracies.append(17.0)  # ASTER GDEM accuracy
                                
            except Exception as e:
                logger.warning(f"OpenTopography ASTER query failed: {e}")
            
            return {
                'tile_count': len(elevations),
                'elevation_values': elevations,
                'resolutions': resolutions,
                'sources': sources,
                'accuracies': accuracies,
                'best_resolution': min(resolutions) if resolutions else None,
                'worst_accuracy': max(accuracies) if accuracies else None
            }
            
        except Exception as e:
            logger.error(f"External DEM services query failed: {e}")
            return {
                'tile_count': 0,
                'elevation_values': [],
                'resolutions': [],
                'sources': [],
                'accuracies': []
            }
    
    async def _query_elevation_from_database(self, latitude, longitude):
        """Query elevation from database with high-resolution DEM data"""
        try:
            dem_data = await self._query_multi_resolution_dem_data(latitude, longitude)
            
            if dem_data['tile_count'] > 0:
                # Use highest resolution data available
                elevations = dem_data['elevation_values']
                resolutions = dem_data['resolutions']
                
                # Find highest resolution (smallest value)
                best_idx = resolutions.index(min(resolutions))
                return elevations[best_idx]
            
            return None
            
        except Exception as e:
            logger.error(f"Database elevation query failed: {e}")
            return None
    
    async def _query_external_elevation_services(self, latitude, longitude):
        """Query external elevation services as fallback"""
        try:
            external_data = await self._query_external_dem_services(latitude, longitude)
            
            if external_data['tile_count'] > 0:
                # Use highest resolution data available
                elevations = external_data['elevation_values']
                resolutions = external_data['resolutions']
                
                # Find highest resolution (smallest value)
                best_idx = resolutions.index(min(resolutions))
                return elevations[best_idx]
            
            # Final fallback: estimate from global topographic model
            return await self._estimate_elevation_from_global_model(latitude, longitude)
            
        except Exception as e:
            logger.error(f"External elevation services failed: {e}")
            return 0.0
    
    async def _estimate_elevation_from_global_model(self, latitude, longitude):
        """Advanced elevation estimation using multi-source DEM data and geological modeling"""
        try:
            # Initialize data connectors for DEM access
            from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
            from backend.core.real_data_connectors.copernicus_connector import CopernicusConnector
            from backend.core.real_data_connectors.usgs_connector import USGSVolcanoConnector
            from backend.core.real_data_connectors.base_connector import DataSourceConfig
            from backend.core.gis_database_integration import GISDatabaseIntegrator
            from backend.core.data_transformation.interpolation_engine import InterpolationEngine
            
            # Multi-source elevation data fusion
            elevation_sources = []
            
            # 1. Query high-resolution DEM from database
            gis_integrator = GISDatabaseIntegrator()
            await gis_integrator.initialize()
            
            # Query existing DEM data from PostGIS
            dem_query = """
            SELECT 
                ST_Value(rast, ST_SetSRID(ST_Point(%s, %s), 4326)) as elevation,
                ST_PixelWidth(rast) as resolution,
                acquisition_date,
                data_source,
                vertical_accuracy
            FROM digital_elevation_models 
            WHERE ST_Intersects(rast, ST_SetSRID(ST_Point(%s, %s), 4326))
            ORDER BY ST_PixelWidth(rast) ASC, vertical_accuracy DESC
            LIMIT 5
            """
            
            async with gis_integrator.enhanced_db.get_postgresql_session() as session:
                result = await session.execute(dem_query, (longitude, latitude, longitude, latitude))
                dem_records = result.fetchall()
                
                for record in dem_records:
                    if record.elevation is not None:
                        elevation_sources.append({
                            'elevation': float(record.elevation),
                            'source': record.data_source,
                            'resolution': float(record.resolution),
                            'accuracy': float(record.vertical_accuracy or 10.0),
                            'weight': 1.0 / (record.resolution * (record.vertical_accuracy or 10.0))
                        })
            
            # 2. SRTM/ASTER GDEM data via NASA connector
            nasa_config = DataSourceConfig(
                base_url="https://earthdata.nasa.gov/api",
                api_key=self.config.get('nasa_api_key'),
                username=self.config.get('nasa_username'),
                password=self.config.get('nasa_password')
            )
            
            nasa_connector = NASAEarthDataConnector(nasa_config)
            if await nasa_connector._authenticate():
                # Query SRTM/ASTER elevation data
                srtm_elevation = await self._query_nasa_elevation_data(
                    nasa_connector, latitude, longitude
                )
                if srtm_elevation is not None:
                    elevation_sources.append({
                        'elevation': srtm_elevation,
                        'source': 'NASA_SRTM',
                        'resolution': 30.0,  # 30m resolution
                        'accuracy': 16.0,    # SRTM vertical accuracy
                        'weight': 1.0 / (30.0 * 16.0)
                    })
            
            # 3. Copernicus DEM data
            copernicus_config = DataSourceConfig(
                base_url="https://dataspace.copernicus.eu/api",
                username=self.config.get('copernicus_username'),
                password=self.config.get('copernicus_password')
            )
            
            copernicus_connector = CopernicusConnector(copernicus_config)
            if await copernicus_connector._authenticate():
                copernicus_elevation = await self._query_copernicus_dem_data(
                    copernicus_connector, latitude, longitude
                )
                if copernicus_elevation is not None:
                    elevation_sources.append({
                        'elevation': copernicus_elevation,
                        'source': 'Copernicus_DEM',
                        'resolution': 30.0,  # GLO-30 resolution
                        'accuracy': 4.0,     # Copernicus DEM accuracy
                        'weight': 1.0 / (30.0 * 4.0)
                    })
            
            # 4. Geological context-based elevation modeling
            geological_elevation = await self._estimate_geological_context_elevation(
                latitude, longitude, gis_integrator
            )
            if geological_elevation is not None:
                elevation_sources.append({
                    'elevation': geological_elevation,
                    'source': 'Geological_Model',
                    'resolution': 1000.0,  # Regional scale
                    'accuracy': 50.0,      # Model uncertainty
                    'weight': 1.0 / (1000.0 * 50.0)
                })
            
            # 5. Bathymetry data for oceanic regions
            is_oceanic = await self._classify_oceanic_continental_advanced(
                latitude, longitude, gis_integrator
            )
            
            if is_oceanic:
                bathymetry_elevation = await self._query_bathymetry_data(
                    latitude, longitude, gis_integrator
                )
                if bathymetry_elevation is not None:
                    elevation_sources.append({
                        'elevation': bathymetry_elevation,
                        'source': 'GEBCO_Bathymetry',
                        'resolution': 500.0,   # GEBCO resolution
                        'accuracy': 20.0,      # Bathymetry accuracy
                        'weight': 1.0 / (500.0 * 20.0)
                    })
            
            # 6. Weighted fusion of elevation sources
            if not elevation_sources:
                logger.warning(f"No elevation data found for {latitude}, {longitude}")
                return await self._fallback_elevation_estimation(latitude, longitude)
            
            # Calculate weighted average
            total_weight = sum(source['weight'] for source in elevation_sources)
            weighted_elevation = sum(
                source['elevation'] * source['weight'] for source in elevation_sources
            ) / total_weight
            
            # Calculate uncertainty propagation
            elevation_uncertainty = np.sqrt(sum(
                (source['accuracy'] * source['weight'] / total_weight) ** 2 
                for source in elevation_sources
            ))
            
            # Apply topographic corrections
            corrected_elevation = await self._apply_topographic_corrections(
                weighted_elevation, latitude, longitude, elevation_sources
            )
            
            logger.info(f"Multi-source elevation for {latitude}, {longitude}: "
                       f"{corrected_elevation:.2f}m ±{elevation_uncertainty:.2f}m "
                       f"from {len(elevation_sources)} sources")
            
            return corrected_elevation
            
        except Exception as e:
            logger.error(f"Advanced elevation model failed: {e}")
            return await self._fallback_elevation_estimation(latitude, longitude)
    
    async def _classify_oceanic_continental(self, latitude, longitude):
        """Classify location as oceanic or continental"""
        try:
            # Query geological units or tectonic plates from database
            async with self.db_integrator.get_postgresql_session() as session:
                tectonic_query = """
                SELECT plate_type, crust_type
                FROM tectonic_plates 
                WHERE ST_Contains(
                    geometry,
                    ST_SetSRID(ST_MakePoint(%s, %s), 4326)
                )
                LIMIT 1
                """
                
                result = await session.execute(tectonic_query, (longitude, latitude))
                plate_data = result.fetchone()
                
                if plate_data:
                    return plate_data.crust_type == 'oceanic'
                
                # Fallback: simple distance from coastline
                coastline_query = """
                SELECT ST_Distance(
                    ST_SetSRID(ST_MakePoint(%s, %s), 4326)::geography,
                    coastline.geometry::geography
                ) as distance_to_coast
                FROM coastlines coastline
                ORDER BY distance_to_coast ASC
                LIMIT 1
                """
                
                result = await session.execute(coastline_query, (longitude, latitude))
                coast_data = result.fetchone()
                
                if coast_data:
                    # If more than 200km from coast, likely oceanic
                    return coast_data.distance_to_coast > 200000
                
                return False  # Default to continental
                
        except Exception as e:
            logger.warning(f"Oceanic/continental classification failed: {e}")
            # Simple heuristic: major ocean basins
            if -180 <= longitude <= -30 and 10 <= latitude <= 70:  # Atlantic
                return True
            elif 30 <= longitude <= 180 and -60 <= latitude <= 60:  # Pacific/Indian
                return True
            return False
    
    async def _query_bathymetry_data(self, latitude, longitude, gis_integrator):
        """Query high-resolution bathymetry data from multiple sources"""
        try:
            # 1. Query GEBCO bathymetry from database
            bathymetry_query = """
            SELECT 
                ST_Value(rast, ST_SetSRID(ST_Point(%s, %s), 4326)) as depth,
                ST_PixelWidth(rast) as resolution,
                data_source,
                vertical_accuracy
            FROM bathymetry_grids 
            WHERE ST_Intersects(rast, ST_SetSRID(ST_Point(%s, %s), 4326))
            ORDER BY ST_PixelWidth(rast) ASC
            LIMIT 3
            """
            
            bathymetry_sources = []
            
            async with gis_integrator.enhanced_db.get_postgresql_session() as session:
                result = await session.execute(bathymetry_query, (longitude, latitude, longitude, latitude))
                bathymetry_records = result.fetchall()
                
                for record in bathymetry_records:
                    if record.depth is not None:
                        bathymetry_sources.append({
                            'depth': float(record.depth),
                            'source': record.data_source,
                            'resolution': float(record.resolution),
                            'accuracy': float(record.vertical_accuracy or 20.0)
                        })
            
            # 2. Plate tectonic age-depth modeling
            plate_age = await self._estimate_oceanic_plate_age(latitude, longitude, gis_integrator)
            if plate_age is not None:
                # Parsons & Sclater (1977) age-depth relationship
                # depth = 2500 + 365 * sqrt(age) for age < 70 Ma
                # depth = 6400 - 3200 * exp(-age/62.8) for age >= 70 Ma
                if plate_age < 70:
                    theoretical_depth = -(2500 + 365 * np.sqrt(plate_age))
                else:
                    theoretical_depth = -(6400 - 3200 * np.exp(-plate_age / 62.8))
                
                bathymetry_sources.append({
                    'depth': theoretical_depth,
                    'source': 'Plate_Tectonic_Model',
                    'resolution': 10000.0,  # Regional scale
                    'accuracy': 200.0       # Model uncertainty
                })
            
            # 3. Sediment thickness correction
            sediment_thickness = await self._estimate_sediment_thickness(
                latitude, longitude, gis_integrator
            )
            
            # 4. Weighted fusion of bathymetry sources
            if not bathymetry_sources:
                return None
            
            # Weight by inverse of resolution and accuracy
            total_weight = 0
            weighted_depth = 0
            
            for source in bathymetry_sources:
                weight = 1.0 / (source['resolution'] * source['accuracy'])
                weighted_depth += source['depth'] * weight
                total_weight += weight
            
            final_depth = weighted_depth / total_weight
            
            # Apply sediment correction
            if sediment_thickness is not None:
                final_depth += sediment_thickness  # Sediment makes water shallower
            
            # Apply isostatic corrections for volcanic loading
            isostatic_correction = await self._calculate_volcanic_isostatic_correction(
                latitude, longitude, gis_integrator
            )
            if isostatic_correction is not None:
                final_depth += isostatic_correction
            
            return final_depth
            
        except Exception as e:
            logger.error(f"Bathymetry data query failed: {e}")
            return None
    
    async def _estimate_geological_context_elevation(self, latitude, longitude, gis_integrator):
        """Advanced geological context-based elevation estimation"""
        try:
            # 1. Query geological units and tectonic features
            geological_query = """
            SELECT 
                gu.primary_lithology,
                gu.age_min,
                gu.age_max,
                gu.structural_elevation,
                tf.feature_type,
                tf.slip_rate,
                tf.activity_status,
                ST_Distance(
                    ST_SetSRID(ST_Point(%s, %s), 4326),
                    ST_Centroid(gu.geometry)
                ) as distance_to_unit,
                ST_Distance(
                    ST_SetSRID(ST_Point(%s, %s), 4326),
                    tf.geometry
                ) as distance_to_feature
            FROM geological_units gu
            LEFT JOIN tectonic_features tf ON ST_Intersects(
                ST_Buffer(gu.geometry, 0.1), 
                ST_Buffer(tf.geometry, 0.1)
            )
            WHERE ST_DWithin(
                gu.geometry, 
                ST_SetSRID(ST_Point(%s, %s), 4326), 
                0.5
            )
            ORDER BY distance_to_unit ASC
            LIMIT 10
            """
            
            geological_factors = []
            
            async with gis_integrator.enhanced_db.get_postgresql_session() as session:
                result = await session.execute(geological_query, 
                    (longitude, latitude, longitude, latitude, longitude, latitude))
                geological_records = result.fetchall()
                
                for record in geological_records:
                    # Lithology-based elevation estimation
                    lithology_elevation = self._get_lithology_elevation_tendency(
                        record.primary_lithology
                    )
                    
                    # Age-based elevation (older rocks tend to be more eroded)
                    age_factor = self._calculate_age_elevation_factor(
                        record.age_min, record.age_max
                    )
                    
                    # Tectonic feature influence
                    tectonic_elevation = self._calculate_tectonic_elevation_influence(
                        record.feature_type, record.slip_rate, record.activity_status
                    )
                    
                    # Distance weighting
                    distance_weight = 1.0 / (1.0 + record.distance_to_unit * 111000)  # Convert to meters
                    
                    geological_factors.append({
                        'elevation': lithology_elevation + tectonic_elevation,
                        'age_factor': age_factor,
                        'weight': distance_weight,
                        'lithology': record.primary_lithology
                    })
            
            # 2. Crustal thickness modeling
            crustal_thickness = await self._estimate_crustal_thickness(
                latitude, longitude, gis_integrator
            )
            
            # Airy isostatic elevation: h = (ρm - ρc) * t / ρm
            # where ρm = mantle density, ρc = crustal density, t = crustal thickness
            if crustal_thickness is not None:
                mantle_density = 3300  # kg/m³
                crustal_density = 2700  # kg/m³
                isostatic_elevation = (mantle_density - crustal_density) * crustal_thickness / mantle_density
                
                geological_factors.append({
                    'elevation': isostatic_elevation,
                    'age_factor': 1.0,
                    'weight': 0.3,  # Regional influence
                    'lithology': 'isostatic_model'
                })
            
            # 3. Volcanic edifice modeling
            volcanic_elevation = await self._estimate_volcanic_edifice_contribution(
                latitude, longitude, gis_integrator
            )
            if volcanic_elevation is not None:
                geological_factors.append({
                    'elevation': volcanic_elevation,
                    'age_factor': 1.0,
                    'weight': 0.8,  # High confidence for volcanic features
                    'lithology': 'volcanic_edifice'
                })
            
            # 4. Weighted fusion of geological factors
            if not geological_factors:
                return None
            
            total_weight = sum(factor['weight'] * factor['age_factor'] for factor in geological_factors)
            weighted_elevation = sum(
                factor['elevation'] * factor['weight'] * factor['age_factor'] 
                for factor in geological_factors
            ) / total_weight
            
            # 5. Apply erosion modeling
            erosion_correction = await self._calculate_erosion_correction(
                latitude, longitude, weighted_elevation, gis_integrator
            )
            
            final_elevation = weighted_elevation - erosion_correction
            
            return max(final_elevation, -100)  # Minimum elevation constraint
            
        except Exception as e:
            logger.error(f"Geological context elevation estimation failed: {e}")
            return None
    
