    async def _classify_oceanic_continental_advanced(self, latitude, longitude, gis_integrator):
        """Advanced oceanic vs continental classification using geological data"""
        try:
            # Query crustal type from database
            crustal_query = """
            SELECT 
                crustal_type,
                crustal_age,
                ST_Distance(
                    ST_SetSRID(ST_Point(%s, %s), 4326),
                    geometry
                ) as distance
            FROM crustal_provinces 
            WHERE ST_Contains(geometry, ST_SetSRID(ST_Point(%s, %s), 4326))
            ORDER BY distance ASC
            LIMIT 1
            """
            
            async with gis_integrator.enhanced_db.get_postgresql_session() as session:
                result = await session.execute(crustal_query, (longitude, latitude, longitude, latitude))
                crustal_record = result.fetchone()
                
                if crustal_record:
                    return crustal_record.crustal_type == 'oceanic'
            
            # Fallback to bathymetry-based classification
            bathymetry_query = """
            SELECT ST_Value(rast, ST_SetSRID(ST_Point(%s, %s), 4326)) as depth
            FROM bathymetry_grids 
            WHERE ST_Intersects(rast, ST_SetSRID(ST_Point(%s, %s), 4326))
            ORDER BY ST_PixelWidth(rast) ASC
            LIMIT 1
            """
            
            async with gis_integrator.enhanced_db.get_postgresql_session() as session:
                result = await session.execute(bathymetry_query, (longitude, latitude, longitude, latitude))
                depth_record = result.fetchone()
                
                if depth_record and depth_record.depth is not None:
                    return float(depth_record.depth) < 0  # Negative values indicate below sea level
            
            return False  # Default to continental
            
        except Exception as e:
            logger.error(f"Advanced oceanic/continental classification failed: {e}")
            return False
    
