    async def _calculate_volcanic_isostatic_correction(self, latitude, longitude, gis_integrator):
        """Calculate isostatic correction due to volcanic loading"""
        try:
            # Query nearby volcanic systems
            volcanic_query = """
            SELECT 
                vs.edifice_volume_km3,
                vs.edifice_height_m,
                ST_Distance(
                    ST_SetSRID(ST_Point(%s, %s), 4326),
                    vs.location
                ) as distance_km
            FROM volcanic_systems vs
            WHERE ST_DWithin(
                vs.location, 
                ST_SetSRID(ST_Point(%s, %s), 4326), 
                1.0
            )
            ORDER BY distance_km ASC
            LIMIT 5
            """
            
            total_correction = 0.0
            
            async with gis_integrator.enhanced_db.get_postgresql_session() as session:
                result = await session.execute(volcanic_query, (longitude, latitude, longitude, latitude))
                volcanic_records = result.fetchall()
                
                for record in volcanic_records:
                    if record.edifice_volume_km3 and record.distance_km:
                        # Simple elastic flexure model
                        distance_m = record.distance_km * 1000
                        load_mass = record.edifice_volume_km3 * 1e9 * 2500  # Assume 2500 kg/m³ density
                        
                        # Flexural parameter (simplified)
                        alpha = 100000  # ~100 km flexural parameter
                        
                        # Deflection due to point load
                        deflection = (load_mass / (2 * np.pi * alpha**2)) * np.exp(-distance_m / alpha)
                        total_correction += deflection
            
            return total_correction if total_correction != 0 else None
            
        except Exception as e:
            logger.error(f"Volcanic isostatic correction failed: {e}")
            return None
    
    def _get_lithology_elevation_tendency(self, lithology):
        """Get elevation tendency based on lithology"""
        lithology_elevations = {
            'granite': 800,
            'gneiss': 600,
            'schist': 400,
            'quartzite': 1000,
            'sandstone': 300,
            'limestone': 200,
            'shale': 100,
            'basalt': 500,
            'andesite': 1200,
            'rhyolite': 1500,
            'volcanic_ash': 800,
            'alluvium': 50,
            'glacial_till': 200
        }
        
        return lithology_elevations.get(lithology.lower() if lithology else '', 300)
    
    def _calculate_age_elevation_factor(self, age_min, age_max):
        """Calculate elevation factor based on geological age (erosion effect)"""
        if age_min is None or age_max is None:
            return 1.0
        
        avg_age = (age_min + age_max) / 2
        
        # Exponential decay for erosion effect
        # Younger rocks maintain higher elevations
        if avg_age < 10:  # Cenozoic
            return 1.0
        elif avg_age < 65:  # Mesozoic
            return 0.9
        elif avg_age < 252:  # Paleozoic
            return 0.7
        elif avg_age < 541:  # Proterozoic
            return 0.5
        else:  # Archean
            return 0.3
    
    def _calculate_tectonic_elevation_influence(self, feature_type, slip_rate, activity_status):
        """Calculate elevation influence from tectonic features"""
        if not feature_type:
            return 0
        
        base_elevations = {
            'thrust_fault': 500,
            'reverse_fault': 300,
            'normal_fault': -200,
            'strike_slip_fault': 0,
            'fold_axis': 400,
            'anticline': 600,
            'syncline': -300,
            'volcanic_arc': 1000,
            'rift_valley': -500
        }
        
        base_elevation = base_elevations.get(feature_type.lower(), 0)
        
        # Activity factor
        activity_factor = 1.0
        if activity_status == 'active':
            activity_factor = 1.2
        elif activity_status == 'inactive':
            activity_factor = 0.8
        elif activity_status == 'dormant':
            activity_factor = 0.9
        
        # Slip rate factor
        slip_factor = 1.0
        if slip_rate is not None:
            if slip_rate > 10:  # mm/yr
                slip_factor = 1.5
            elif slip_rate > 1:
                slip_factor = 1.2
            elif slip_rate > 0.1:
                slip_factor = 1.0
            else:
                slip_factor = 0.8
        
        return base_elevation * activity_factor * slip_factor
    
