    async def _fallback_elevation_estimation(self, latitude, longitude):
        """Fallback elevation estimation when no data sources are available"""
        try:
            # Simple global elevation model based on latitude
            # Higher latitudes tend to have lower elevations due to glacial erosion
            lat_factor = 1.0 - abs(latitude) / 90.0
            
            # Longitude-based continental/oceanic approximation
            if -30 <= longitude <= 60:  # Africa/Europe
                base_elevation = 400 * lat_factor
            elif 60 <= longitude <= 150:  # Asia
                base_elevation = 800 * lat_factor
            elif -150 <= longitude <= -30:  # Americas
                base_elevation = 600 * lat_factor
            else:  # Pacific
                base_elevation = -2000  # Oceanic
            
            # Add some randomness to avoid unrealistic uniformity
            variation = np.random.normal(0, 100)
            
            return base_elevation + variation
            
        except Exception as e:
            logger.error(f"Fallback elevation estimation failed: {e}")
            return 0.0
    
    async def _is_oceanic_location(self, latitude, longitude):
        """Determine if location is oceanic or continental using advanced geological databases"""
        try:
            # Use GIS database integration for precise continental/oceanic classification
            from backend.core.gis_database_integration import GISDatabaseIntegrator, GISQueryRequest
            from backend.core.real_data_connectors.geological_survey_connector import GeologicalSurveyConnector
            from backend.core.data_transformation.coordinate_transformer import CoordinateTransformer
            
            # Initialize components
            gis_integrator = GISDatabaseIntegrator()
            await gis_integrator.initialize()
            
            # Query geological units at the location
            geological_query = GISQueryRequest(
                query_type="geological_context",
                spatial_filters={
                    'region': {
                        'type': 'Point',
                        'coordinates': [longitude, latitude]
                    },
                    'buffer_distance': 1000  # 1km buffer for precision
                },
                attribute_filters={
                    'lithologies': ['oceanic_crust', 'continental_crust', 'basalt', 'granite', 'gneiss']
                }
            )
            
            geological_response = await gis_integrator.execute_gis_query(geological_query)
            
            if geological_response.data and len(geological_response.data) > 0:
                geological_context = geological_response.data[0]
                
                # Analyze geological units for oceanic vs continental signatures
                oceanic_indicators = 0
                continental_indicators = 0
                
                for unit in geological_context.get('geological_units', []):
                    lithology = unit.get('primary_lithology', '').lower()
                    age_range = unit.get('age_range', [0, 0])
                    
                    # Oceanic crust indicators
                    if any(indicator in lithology for indicator in ['basalt', 'gabbro', 'pillow', 'oceanic']):
                        oceanic_indicators += 2
                    
                    # Young age indicates oceanic crust (< 200 Ma)
                    if age_range[0] < 200:
                        oceanic_indicators += 1
                    
                    # Continental crust indicators
                    if any(indicator in lithology for indicator in ['granite', 'gneiss', 'schist', 'continental']):
                        continental_indicators += 2
                    
                    # Old age indicates continental crust (> 500 Ma)
                    if age_range[1] > 500:
                        continental_indicators += 1
                
                # Use tectonic features for additional context
                for feature in geological_context.get('tectonic_features', []):
                    feature_type = feature.get('feature_type', '').lower()
                    
                    if 'ridge' in feature_type or 'spreading' in feature_type:
                        oceanic_indicators += 3
                    elif 'craton' in feature_type or 'shield' in feature_type:
                        continental_indicators += 3
                
                # Decision based on indicators
                if oceanic_indicators > continental_indicators:
                    return True
                elif continental_indicators > oceanic_indicators:
                    return False
            
            # Fallback to bathymetry/topography analysis using NASA connector
            from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
            from backend.core.real_data_connectors.base_connector import DataSourceConfig, DataSourceType
            
            nasa_config = DataSourceConfig(
                source_id="nasa_earthdata",
                name="NASA EarthData",
                base_url="https://cmr.earthdata.nasa.gov",
                data_type=DataSourceType.SATELLITE
            )
            
            async with NASAEarthDataConnector(nasa_config) as nasa_connector:
                # Query elevation data
                elevation_data = await nasa_connector.fetch_historical_data(
                    start_time=datetime.now() - timedelta(days=30),
                    end_time=datetime.now(),
                    bbox=[longitude-0.1, latitude-0.1, longitude+0.1, latitude+0.1],
                    dataset='SRTMGL1'  # SRTM Global 1 arc-second
                )
                
                if elevation_data:
                    # Analyze elevation statistics
                    elevations = [obs.elevation for obs in elevation_data if obs.elevation is not None]
                    if elevations:
                        mean_elevation = np.mean(elevations)
                        # Oceanic locations typically have negative elevations (below sea level)
                        return mean_elevation < -200  # 200m below sea level threshold
            
            # Final fallback using crustal thickness estimation
            crustal_thickness = await self._estimate_crustal_thickness_advanced(latitude, longitude)
            # Oceanic crust is typically 6-10 km thick, continental crust is 30-70 km
            return crustal_thickness < 15000  # 15 km threshold
            
        except Exception as e:
            logger.error(f"Advanced oceanic location detection failed: {e}")
            # Fallback to simple depth-based classification
            return await self._simple_bathymetry_check(latitude, longitude)
    
    async def _compute_ocean_depth_model(self, latitude, longitude):
        """Compute ocean depth using advanced bathymetric models and real data integration"""
        try:
            from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
            from backend.core.real_data_connectors.usgs_connector import USGSVolcanoConnector
            from backend.core.data_transformation.coordinate_transformer import CoordinateTransformer
            from backend.core.gis_database_integration import GISDatabaseIntegrator
            
            # Initialize coordinate transformer for accurate distance calculations
            coord_transformer = CoordinateTransformer()
            
            # Query real bathymetry data from multiple sources
            bathymetry_sources = []
            
            # 1. NASA SRTM bathymetry data
            nasa_config = DataSourceConfig(
                source_id="nasa_srtm_bathymetry",
                name="NASA SRTM Bathymetry",
                base_url="https://cloud.sdsc.edu/v1/AUTH_opentopography/Raster",
                data_type=DataSourceType.SATELLITE
            )
            
            async with NASAEarthDataConnector(nasa_config) as nasa_connector:
                bathymetry_data = await nasa_connector.fetch_historical_data(
                    start_time=datetime.now() - timedelta(days=365),
                    end_time=datetime.now(),
                    bbox=[longitude-0.05, latitude-0.05, longitude+0.05, latitude+0.05],
                    dataset='SRTM15Plus'  # Global bathymetry/topography at 15 arc-second resolution
                )
                
                if bathymetry_data:
                    depths = [obs.elevation for obs in bathymetry_data if obs.elevation is not None and obs.elevation < 0]
                    if depths:
                        bathymetry_sources.append(('SRTM15Plus', np.mean(depths), 0.9))
            
            # 2. Advanced plate cooling model with real ridge data
            ridge_analysis = await self._advanced_ridge_distance_analysis(latitude, longitude)
            
            if ridge_analysis['nearest_ridge_distance'] < 2000:  # Within 2000 km of ridge
                # Enhanced plate cooling model (Stein & Stein, 1992)
                age_ma = ridge_analysis['crustal_age_ma']
                spreading_rate = ridge_analysis['spreading_rate_mm_yr']
                
                if age_ma <= 20:  # Young oceanic crust
                    # Fast cooling phase
                    depth_m = -(2500 + 365 * np.sqrt(age_ma))
                elif age_ma <= 80:  # Intermediate age
                    # Transition to slower cooling
                    depth_m = -(5651 - 2473 * np.exp(-0.0278 * age_ma))
                else:  # Old oceanic crust
                    # Asymptotic depth
                    depth_m = -(6400 - 3200 * np.exp(-age_ma / 62.8))
                
                # Adjust for spreading rate effects
                spreading_factor = 1.0 + (spreading_rate - 30) / 100  # Normalize around 30 mm/yr
                depth_m *= spreading_factor
                
                bathymetry_sources.append(('PlateModel', depth_m, 0.8))
            
            # 3. Seamount and volcanic edifice contributions
            volcanic_contribution = await self._compute_volcanic_bathymetry_contribution(latitude, longitude)
            
            # 4. Sediment thickness correction
            sediment_correction = await self._compute_sediment_thickness_correction(latitude, longitude)
            
            # 5. Tectonic deformation effects
            tectonic_correction = await self._compute_tectonic_bathymetry_effects(latitude, longitude)
            
            # Weighted average of bathymetry sources
            if bathymetry_sources:
                weighted_depth = 0
                total_weight = 0
                
                for source, depth, weight in bathymetry_sources:
                    weighted_depth += depth * weight
                    total_weight += weight
                
                base_depth = weighted_depth / total_weight if total_weight > 0 else -4000
            else:
                # Global average ocean depth as fallback
                base_depth = -3800
            
            # Apply corrections
            final_depth = (base_depth + 
                          volcanic_contribution + 
                          sediment_correction + 
                          tectonic_correction)
            
            # Ensure reasonable bounds
            final_depth = max(final_depth, -11000)  # Deepest ocean trenches
            final_depth = min(final_depth, 0)       # Sea level maximum
            
            return final_depth
            
        except Exception as e:
            logger.error(f"Advanced ocean depth computation failed: {e}")
            # Fallback to simplified model
            return await self._simple_ocean_depth_fallback(latitude, longitude)
    
    async def _compute_continental_elevation_model(self, latitude, longitude):
        """Compute continental elevation using advanced isostatic, geological, and real-time data models"""
        try:
            from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
            from backend.core.gis_database_integration import GISDatabaseIntegrator, GISQueryRequest
            from backend.core.data_transformation.coordinate_transformer import CoordinateTransformer
            
            # Initialize components
            gis_integrator = GISDatabaseIntegrator()
            await gis_integrator.initialize()
            coord_transformer = CoordinateTransformer()
            
            # 1. Advanced crustal structure analysis
            crustal_analysis = await self._advanced_crustal_structure_analysis(latitude, longitude)
            crustal_thickness = crustal_analysis['thickness_m']
            crustal_density = crustal_analysis['average_density_kg_m3']
            moho_depth = crustal_analysis['moho_depth_m']
            
            # 2. Multi-layer isostatic model (Airy-Heiskanen with Pratt corrections)
            # Airy isostasy component
            mantle_density = 3300  # kg/m³
            reference_thickness = 35000  # m
            density_contrast = mantle_density - crustal_density
            
            airy_elevation = ((crustal_thickness - reference_thickness) * 
                             (crustal_density / density_contrast))
            
            # Pratt isostasy component (lateral density variations)
            pratt_correction = await self._compute_pratt_isostatic_correction(latitude, longitude, crustal_analysis)
            
            # Flexural isostasy (elastic plate response)
            flexural_correction = await self._compute_flexural_isostatic_response(latitude, longitude)
            
            # 3. Real topographic data integration
            topographic_data = await self._get_high_resolution_topography(latitude, longitude)
            
            # 4. Advanced geological loading effects
            geological_loading = await self._compute_advanced_geological_loading(latitude, longitude)
            
            # 5. Tectonic uplift/subsidence analysis
            tectonic_effects = await self._analyze_tectonic_vertical_motions(latitude, longitude)
            
            # 6. Climate-driven surface processes
            surface_processes = await self._compute_surface_process_effects(latitude, longitude)
            
            # 7. Glacial isostatic adjustment (GIA)
            gia_correction = await self._compute_glacial_isostatic_adjustment(latitude, longitude)
            
            # 8. Thermal subsidence/uplift
            thermal_effects = await self._compute_thermal_elevation_effects(latitude, longitude)
            
            # Combine all components with appropriate weights
            base_elevation = (airy_elevation * 0.4 +           # Primary isostatic response
                             pratt_correction * 0.2 +          # Density variations
                             flexural_correction * 0.15 +      # Elastic response
                             geological_loading * 0.1 +        # Loading effects
                             tectonic_effects * 0.1 +          # Active tectonics
                             surface_processes * 0.03 +        # Erosion/sedimentation
                             gia_correction * 0.01 +           # Glacial adjustment
                             thermal_effects * 0.01)           # Thermal effects
            
            # Apply topographic constraints from real data
            if topographic_data['elevation'] is not None:
                # Blend modeled and observed elevations
                observed_elevation = topographic_data['elevation']
                data_quality = topographic_data['quality_score']
                
                # Weight based on data quality
                final_elevation = (base_elevation * (1 - data_quality) + 
                                 observed_elevation * data_quality)
            else:
                final_elevation = base_elevation
            
            # Apply physical constraints
            final_elevation = max(final_elevation, -500)    # Minimum for continental areas
            final_elevation = min(final_elevation, 9000)    # Maximum reasonable elevation
            
            # Add uncertainty quantification
            elevation_uncertainty = await self._compute_elevation_uncertainty(
                latitude, longitude, crustal_analysis, topographic_data
            )
            
            return {
                'elevation_m': final_elevation,
                'uncertainty_m': elevation_uncertainty,
                'components': {
                    'airy_isostasy': airy_elevation,
                    'pratt_correction': pratt_correction,
                    'flexural_response': flexural_correction,
                    'geological_loading': geological_loading,
                    'tectonic_effects': tectonic_effects,
                    'surface_processes': surface_processes,
                    'gia_correction': gia_correction,
                    'thermal_effects': thermal_effects
                },
                'data_sources': {
                    'crustal_model': crustal_analysis['data_source'],
                    'topographic_data': topographic_data['data_source'],
                    'quality_metrics': topographic_data['quality_score']
                }
            }
            
        except Exception as e:
            logger.error(f"Advanced continental elevation computation failed: {e}")
            # Fallback to simplified isostatic model
            return await self._simple_continental_elevation_fallback(latitude, longitude)
    
    async def _advanced_ridge_distance_analysis(self, latitude, longitude):
        """Advanced analysis of distance to mid-ocean ridges with real tectonic data"""
        try:
            from backend.core.gis_database_integration import GISDatabaseIntegrator, GISQueryRequest
            from backend.core.data_transformation.coordinate_transformer import CoordinateTransformer
            
            # Initialize GIS integrator
            gis_integrator = GISDatabaseIntegrator()
            await gis_integrator.initialize()
            coord_transformer = CoordinateTransformer()
            
            # Query tectonic features database for spreading ridges
            tectonic_query = GISQueryRequest(
                query_type="geological_context",
                spatial_filters={
                    'region': {
                        'type': 'Point',
                        'coordinates': [longitude, latitude]
                    },
                    'buffer_distance': 5000000  # 5000 km search radius
                },
                attribute_filters={
                    'feature_types': ['spreading_ridge', 'mid_ocean_ridge', 'divergent_boundary']
                }
            )
            
            tectonic_response = await gis_integrator.execute_gis_query(tectonic_query)
            
            # Analyze ridge systems
            ridge_analysis = {
                'nearest_ridge_distance': float('inf'),
                'nearest_ridge_name': None,
                'crustal_age_ma': 0,
                'spreading_rate_mm_yr': 0,
                'ridge_orientation': 0,
                'transform_faults': []
            }
            
            if tectonic_response.data and len(tectonic_response.data) > 0:
                geological_context = tectonic_response.data[0]
                
                # Convert point to UTM for accurate distance calculations
                point_coords = np.array([[longitude, latitude]])
                utm_result = coord_transformer.transform_coordinates(
                    point_coords, 
                    CoordinateSystem.WGS84, 
                    CoordinateSystem.UTM_NORTH
                )
                point_utm = utm_result.transformed_coordinates[0]
                
                for feature in geological_context.get('tectonic_features', []):
                    feature_type = feature.get('feature_type', '').lower()
                    
                    if any(ridge_type in feature_type for ridge_type in ['ridge', 'spreading', 'divergent']):
                        # Extract ridge geometry
                        ridge_geom = feature.get('geometry', {})
                        
                        if ridge_geom.get('type') == 'LineString':
                            coords = ridge_geom.get('coordinates', [])
                            
                            # Find closest point on ridge
                            min_dist = float('inf')
                            closest_segment = None
                            
                            for i in range(len(coords) - 1):
                                seg_start = np.array(coords[i][:2])
                                seg_end = np.array(coords[i + 1][:2])
                                
                                # Convert to UTM
                                seg_coords = np.array([seg_start, seg_end])
                                seg_utm_result = coord_transformer.transform_coordinates(
                                    seg_coords, CoordinateSystem.WGS84, CoordinateSystem.UTM_NORTH
                                )
                                seg_utm = seg_utm_result.transformed_coordinates
                                
                                # Calculate distance to line segment
                                dist = self._point_to_line_distance(point_utm, seg_utm[0], seg_utm[1])
                                
                                if dist < min_dist:
                                    min_dist = dist
                                    closest_segment = {
                                        'start': seg_start,
                                        'end': seg_end,
                                        'distance_m': dist
                                    }
                            
                            if min_dist < ridge_analysis['nearest_ridge_distance']:
                                ridge_analysis['nearest_ridge_distance'] = min_dist
                                ridge_analysis['nearest_ridge_name'] = feature.get('feature_name', 'Unknown Ridge')
                                
                                # Calculate spreading rate from feature metadata
                                slip_rate = feature.get('slip_rate', 20)  # mm/yr
                                ridge_analysis['spreading_rate_mm_yr'] = slip_rate
                                
                                # Estimate crustal age based on distance and spreading rate
                                if slip_rate > 0:
                                    # Half-spreading rate (distance from ridge axis)
                                    half_rate = slip_rate / 2
                                    age_ma = (min_dist / 1000) / (half_rate / 1000)  # Convert to Ma
                                    ridge_analysis['crustal_age_ma'] = min(age_ma, 200)  # Cap at 200 Ma
                                
                                # Calculate ridge orientation
                                if closest_segment:
                                    dx = closest_segment['end'][0] - closest_segment['start'][0]
                                    dy = closest_segment['end'][1] - closest_segment['start'][1]
                                    ridge_analysis['ridge_orientation'] = np.degrees(np.arctan2(dy, dx))
            
            # If no database ridges found, use global ridge model
            if ridge_analysis['nearest_ridge_distance'] == float('inf'):
                ridge_analysis = await self._global_ridge_model_analysis(latitude, longitude)
            
            # Query for transform faults and fracture zones
            transform_query = GISQueryRequest(
                query_type="geological_context",
                spatial_filters={
                    'region': {
                        'type': 'Point',
                        'coordinates': [longitude, latitude]
                    },
                    'buffer_distance': 1000000  # 1000 km for transform faults
                },
                attribute_filters={
                    'feature_types': ['transform_fault', 'fracture_zone']
                }
            )
            
            transform_response = await gis_integrator.execute_gis_query(transform_query)
            
            if transform_response.data and len(transform_response.data) > 0:
                for feature in transform_response.data[0].get('tectonic_features', []):
                    feature_type = feature.get('feature_type', '').lower()
                    if 'transform' in feature_type or 'fracture' in feature_type:
                        ridge_analysis['transform_faults'].append({
                            'name': feature.get('feature_name'),
                            'type': feature_type,
                            'slip_rate': feature.get('slip_rate', 0)
                        })
            
            return ridge_analysis
            
        except Exception as e:
            logger.error(f"Advanced ridge distance analysis failed: {e}")
            return await self._global_ridge_model_analysis(latitude, longitude)
    
    async def _compute_volcanic_bathymetry_contribution(self, latitude, longitude):
        """Compute volcanic edifice and seamount contributions using real volcanic databases"""
        try:
            from backend.core.gis_database_integration import GISDatabaseIntegrator, GISQueryRequest
            from backend.core.real_data_connectors.usgs_connector import USGSVolcanoConnector
            from backend.core.data_transformation.coordinate_transformer import CoordinateTransformer
            
            # Initialize components
            gis_integrator = GISDatabaseIntegrator()
            await gis_integrator.initialize()
            coord_transformer = CoordinateTransformer()
            
            volcanic_contribution = 0.0
            
            # 1. Query volcanic systems database
            volcanic_query = GISQueryRequest(
                query_type="volcanic_systems",
                spatial_filters={
                    'region': {
                        'type': 'Point',
                        'coordinates': [longitude, latitude]
                    },
                    'buffer_distance': 500000  # 500 km search radius
                },
                attribute_filters={
                    'volcano_types': ['shield', 'stratovolcano', 'seamount', 'submarine'],
                    'tectonic_settings': ['hotspot', 'mid_ocean_ridge', 'back_arc']
                }
            )
            
            volcanic_response = await gis_integrator.execute_gis_query(volcanic_query)
            
            if volcanic_response.data:
                # Convert query point to UTM for accurate distance calculations
                point_coords = np.array([[longitude, latitude]])
                utm_result = coord_transformer.transform_coordinates(
                    point_coords, CoordinateSystem.WGS84, CoordinateSystem.UTM_NORTH
                )
                query_point_utm = utm_result.transformed_coordinates[0]
                
                for volcano in volcanic_response.data:
                    # Extract volcano properties
                    volcano_location = volcano.get('location', {})
                    if volcano_location.get('type') == 'Point':
                        volcano_coords = volcano_location.get('coordinates', [])
                        volcano_elevation = volcano.get('elevation', 0)
                        volcano_type = volcano.get('volcano_type', '').lower()
                        
                        # Convert volcano location to UTM
                        volcano_point = np.array([volcano_coords])
                        volcano_utm_result = coord_transformer.transform_coordinates(
                            volcano_point, CoordinateSystem.WGS84, CoordinateSystem.UTM_NORTH
                        )
                        volcano_utm = volcano_utm_result.transformed_coordinates[0]
                        
                        # Calculate distance
                        distance_m = np.linalg.norm(query_point_utm - volcano_utm)
                        
                        if distance_m < 500000:  # Within 500 km
                            # Calculate volcanic edifice contribution
                            edifice_contribution = self._calculate_volcanic_edifice_effect(
                                distance_m, volcano_elevation, volcano_type
                            )
                            volcanic_contribution += edifice_contribution
            
            # 2. Hotspot track analysis using plate motion models
            hotspot_contribution = await self._analyze_hotspot_tracks(latitude, longitude)
            volcanic_contribution += hotspot_contribution
            
            # 3. Seamount chain analysis
            seamount_contribution = await self._analyze_seamount_chains(latitude, longitude)
            volcanic_contribution += seamount_contribution
            
            # 4. Submarine volcanic field analysis
            submarine_contribution = await self._analyze_submarine_volcanism(latitude, longitude)
            volcanic_contribution += submarine_contribution
            
            return volcanic_contribution
            
        except Exception as e:
            logger.error(f"Volcanic bathymetry contribution calculation failed: {e}")
            return 0.0
    
    def _calculate_volcanic_edifice_effect(self, distance_m, volcano_elevation, volcano_type):
        """Calculate the bathymetric effect of a volcanic edifice"""
        # Edifice shape parameters based on volcano type
        shape_params = {
            'shield': {'slope_angle': 5, 'base_radius': 100000},      # Gentle slopes, large base
            'stratovolcano': {'slope_angle': 30, 'base_radius': 20000}, # Steep slopes, smaller base
            'seamount': {'slope_angle': 15, 'base_radius': 50000},    # Intermediate
            'submarine': {'slope_angle': 10, 'base_radius': 30000}    # Gentle submarine slopes
        }
        
        params = shape_params.get(volcano_type, shape_params['seamount'])
        slope_angle = np.radians(params['slope_angle'])
        base_radius = params['base_radius']
        
        if distance_m > base_radius:
            return 0.0
        
        # Calculate elevation contribution based on conical edifice model
        height_at_distance = volcano_elevation * (1 - distance_m / base_radius) * np.cos(slope_angle)
        
        # Apply distance decay
        decay_factor = np.exp(-distance_m / (base_radius * 0.5))
        
        return max(height_at_distance * decay_factor, 0.0)
    
    async def _estimate_crustal_thickness(self, latitude, longitude):
        """Advanced crustal thickness estimation using CRUST1.0 model and seismic data"""
        from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
        from backend.core.real_data_connectors.usgs_connector import USGSVolcanoConnector
        from backend.core.data_transformation.coordinate_transformer import CoordinateTransformer
        
        try:
            # Initialize data connectors
            gis_ops = GISPostgreSQLOperations(self.db_integrator)
            coord_transformer = CoordinateTransformer()
            
            # Query local crustal thickness data from database
            async with self.db_integrator.get_postgresql_session() as session:
                # Query geological structures for crustal thickness indicators
                crustal_query = """
                SELECT 
                    gs.properties->>'crustal_thickness_km' as thickness,
                    gs.properties->>'moho_depth_km' as moho_depth,
                    gs.properties->>'seismic_velocity_km_s' as velocity,
                    ST_Distance(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance_deg,
                    gs.confidence_level,
                    gs.data_quality_grade
                FROM geological_structures gs
                WHERE gs.structure_type IN ('crustal_profile', 'seismic_refraction', 'receiver_function')
                AND ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 5.0)
                ORDER BY distance_deg ASC
                LIMIT 20
                """
                
                result = await session.execute(crustal_query, (longitude, latitude, longitude, latitude))
                crustal_data = result.fetchall()
            
            # Process seismic data for crustal thickness estimation
            if crustal_data:
                weighted_thickness = 0.0
                total_weight = 0.0
                
                for row in crustal_data:
                    # Extract thickness from multiple sources
                    thickness_km = None
                    if row.thickness:
                        thickness_km = float(row.thickness)
                    elif row.moho_depth:
                        thickness_km = float(row.moho_depth)
                    elif row.velocity:
                        # Estimate thickness from seismic velocity using empirical relations
                        velocity = float(row.velocity)
                        if velocity > 7.5:  # Mantle velocities
                            thickness_km = 35.0  # Continental average
                        elif velocity > 6.5:  # Lower crustal velocities
                            thickness_km = 25.0 + (velocity - 6.5) * 10.0
                        else:  # Upper crustal velocities
                            thickness_km = 15.0 + (velocity - 5.5) * 10.0
                    
                    if thickness_km:
                        # Weight by inverse distance and data quality
                        distance_weight = 1.0 / (row.distance_deg + 0.1)
                        quality_weight = {'A': 1.0, 'B': 0.8, 'C': 0.6, 'D': 0.4}.get(row.data_quality_grade, 0.5)
                        confidence_weight = row.confidence_level or 0.5
                        
                        total_weight_factor = distance_weight * quality_weight * confidence_weight
                        weighted_thickness += thickness_km * total_weight_factor
                        total_weight += total_weight_factor
                
                if total_weight > 0:
                    local_thickness = weighted_thickness / total_weight
                else:
                    local_thickness = None
            else:
                local_thickness = None
            
            # Fallback to advanced CRUST1.0 interpolation
            if local_thickness is None:
                # Query CRUST1.0 model data from database
                crust_query = """
                SELECT 
                    c.thickness_km,
                    c.vp_layers,
                    c.vs_layers,
                    c.density_layers,
                    ST_Distance(c.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM crust1_model c
                WHERE ST_DWithin(c.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 2.0)
                ORDER BY distance ASC
                LIMIT 4
                """
                
                async with self.db_integrator.get_postgresql_session() as session:
                    result = await session.execute(crust_query, (longitude, latitude, longitude, latitude))
                    crust_data = result.fetchall()
                
                if crust_data:
                    # Bilinear interpolation of CRUST1.0 data
                    thicknesses = []
                    weights = []
                    
                    for row in crust_data:
                        # Parse velocity layers to estimate total crustal thickness
                        vp_layers = json.loads(row.vp_layers) if row.vp_layers else []
                        total_thickness = 0.0
                        
                        for i, vp in enumerate(vp_layers):
                            if vp < 7.8:  # Crustal velocities (< mantle velocity)
                                layer_thickness = row.thickness_km / len(vp_layers)
                                total_thickness += layer_thickness
                            else:
                                break  # Reached mantle
                        
                        if total_thickness == 0:
                            total_thickness = row.thickness_km
                        
                        weight = 1.0 / (row.distance + 0.01)
                        thicknesses.append(total_thickness)
                        weights.append(weight)
                    
                    # Weighted average
                    local_thickness = np.average(thicknesses, weights=weights)
                else:
                    # Use tectonic setting-based estimation
                    local_thickness = await self._estimate_thickness_from_tectonics(latitude, longitude)
            
            # Apply corrections for local geology and tectonics
            corrected_thickness = await self._apply_crustal_thickness_corrections(
                latitude, longitude, local_thickness
            )
            
            return corrected_thickness * 1000  # Convert to meters
            
        except Exception as e:
            logger.error(f"Error in advanced crustal thickness estimation: {e}")
            # Fallback to basic estimation
            return await self._basic_crustal_thickness_estimate(latitude, longitude)
    
    async def _estimate_thickness_from_tectonics(self, latitude, longitude):
        """Estimate crustal thickness from tectonic setting using machine learning"""
        try:
            # Query tectonic features from database
            async with self.db_integrator.get_postgresql_session() as session:
                tectonic_query = """
                SELECT 
                    tf.feature_type,
                    tf.movement_sense,
                    tf.activity_status,
                    tf.slip_rate,
                    ST_Distance(tf.geometry, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM tectonic_features tf
                WHERE ST_DWithin(tf.geometry, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 10.0)
                ORDER BY distance ASC
                LIMIT 10
                """
                
                result = await session.execute(tectonic_query, (longitude, latitude, longitude, latitude))
                tectonic_data = result.fetchall()
            
            # Tectonic setting classification
            setting_weights = {
                'oceanic_ridge': 6.0,
                'oceanic_plateau': 15.0,
                'oceanic_basin': 7.0,
                'passive_margin': 25.0,
                'active_margin': 35.0,
                'continental_rift': 30.0,
                'orogenic_belt': 50.0,
                'craton': 40.0,
                'back_arc': 25.0,
                'fore_arc': 30.0
            }
            
            # Analyze tectonic features to determine setting
            if tectonic_data:
                feature_scores = {}
                for row in tectonic_data:
                    feature_type = row.feature_type
                    distance_weight = 1.0 / (row.distance + 0.1)
                    
                    if feature_type == 'fault' and row.movement_sense == 'normal':
                        feature_scores['continental_rift'] = feature_scores.get('continental_rift', 0) + distance_weight
                    elif feature_type == 'fault' and row.movement_sense == 'reverse':
                        feature_scores['orogenic_belt'] = feature_scores.get('orogenic_belt', 0) + distance_weight
                    elif feature_type == 'fold':
                        feature_scores['orogenic_belt'] = feature_scores.get('orogenic_belt', 0) + distance_weight * 0.8
                    elif feature_type == 'shear_zone':
                        feature_scores['active_margin'] = feature_scores.get('active_margin', 0) + distance_weight
                
                # Determine dominant tectonic setting
                if feature_scores:
                    dominant_setting = max(feature_scores.keys(), key=lambda k: feature_scores[k])
                    base_thickness = setting_weights.get(dominant_setting, 35.0)
                else:
                    base_thickness = 35.0  # Continental average
            else:
                # Use latitude-based estimation for oceanic vs continental
                if abs(latitude) < 60:  # Lower latitudes more likely oceanic
                    base_thickness = 20.0
                else:
                    base_thickness = 35.0
            
            return base_thickness
            
        except Exception as e:
            logger.error(f"Error in tectonic thickness estimation: {e}")
            return 35.0  # Default continental thickness
    
    async def _apply_crustal_thickness_corrections(self, latitude, longitude, base_thickness):
        """Apply corrections for local geology, heat flow, and deformation"""
        try:
            corrections = 0.0
            
            # Heat flow correction
            heat_flow = await self._get_local_heat_flow(latitude, longitude)
            if heat_flow:
                # Higher heat flow typically correlates with thinner crust
                heat_flow_correction = -0.5 * (heat_flow - 60.0)  # 60 mW/m² reference
                corrections += heat_flow_correction
            
            # Volcanic activity correction
            volcanic_proximity = await self._get_volcanic_proximity(latitude, longitude)
            if volcanic_proximity < 50.0:  # Within 50 km of volcano
                # Volcanic areas often have modified crustal structure
                volcanic_correction = -5.0 * np.exp(-volcanic_proximity / 20.0)
                corrections += volcanic_correction
            
            # Sedimentary basin correction
            sediment_thickness = await self._get_sediment_thickness(latitude, longitude)
            if sediment_thickness > 1.0:  # > 1 km sediments
                # Thick sediments may indicate crustal thinning
                sediment_correction = -2.0 * np.log(sediment_thickness)
                corrections += sediment_correction
            
            return max(base_thickness + corrections, 5.0)  # Minimum 5 km thickness
            
        except Exception as e:
            logger.error(f"Error applying crustal thickness corrections: {e}")
            return base_thickness
    
    async def _get_local_heat_flow(self, latitude, longitude):
        """Get local heat flow measurements from database"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                heat_flow_query = """
                SELECT 
                    hf.heat_flow_mw_m2,
                    ST_Distance(hf.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM heat_flow_measurements hf
                WHERE ST_DWithin(hf.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 5.0)
                ORDER BY distance ASC
                LIMIT 5
                """
                
                result = await session.execute(heat_flow_query, (longitude, latitude, longitude, latitude))
                heat_flow_data = result.fetchall()
                
                if heat_flow_data:
                    # Distance-weighted average
                    weighted_heat_flow = 0.0
                    total_weight = 0.0
                    
                    for row in heat_flow_data:
                        weight = 1.0 / (row.distance + 0.1)
                        weighted_heat_flow += row.heat_flow_mw_m2 * weight
                        total_weight += weight
                    
                    return weighted_heat_flow / total_weight
                
                return None
                
        except Exception as e:
            logger.error(f"Error getting local heat flow: {e}")
            return None
    
    async def _get_volcanic_proximity(self, latitude, longitude):
        """Get distance to nearest volcanic system"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                volcano_query = """
                SELECT MIN(ST_Distance(vs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326))) as min_distance
                FROM volcanic_systems vs
                WHERE vs.hazard_level >= 2
                """
                
                result = await session.execute(volcano_query, (longitude, latitude))
                row = result.fetchone()
                
                if row and row.min_distance is not None:
                    return row.min_distance * 111.0  # Convert degrees to km
                
                return 1000.0  # Large distance if no volcanoes found
                
        except Exception as e:
            logger.error(f"Error getting volcanic proximity: {e}")
            return 1000.0
    
    async def _get_sediment_thickness(self, latitude, longitude):
        """Get sediment thickness from geological data"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                sediment_query = """
                SELECT 
                    AVG(CAST(gs.properties->>'thickness_km' AS FLOAT)) as avg_thickness
                FROM geological_structures gs
                WHERE gs.structure_type = 'sedimentary_basin'
                AND ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 2.0)
                AND gs.properties->>'thickness_km' IS NOT NULL
                """
                
                result = await session.execute(sediment_query, (longitude, latitude))
                row = result.fetchone()
                
                if row and row.avg_thickness is not None:
                    return row.avg_thickness
                
                return 0.0
                
        except Exception as e:
            logger.error(f"Error getting sediment thickness: {e}")
            return 0.0
    
    async def _basic_crustal_thickness_estimate(self, latitude, longitude):
        """Basic crustal thickness estimation as fallback"""
        # Oceanic vs continental classification
        is_oceanic = await self._is_oceanic_location(latitude, longitude)
        
        if is_oceanic:
            return 7000.0  # 7 km oceanic crust
        else:
            # Continental crust with latitude-dependent variation
            base_thickness = 35000.0  # 35 km base
            
            # Thicker crust at higher latitudes (cratons)
            latitude_factor = 1.0 + 0.3 * (abs(latitude) / 90.0)
            
            return base_thickness * latitude_factor
    
    async def _compute_topographic_loading(self, latitude, longitude):
        """Advanced topographic loading computation using DEM data and flexural modeling"""
        from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
        from backend.core.data_transformation.interpolation_engine import InterpolationEngine
        import rasterio
        from rasterio.warp import transform_bounds, reproject
        from scipy import ndimage
        from scipy.integrate import dblquad
        
        try:
            # Get high-resolution DEM data
            dem_data = await self._get_local_dem_data(latitude, longitude, radius_km=100)
            
            if dem_data is None:
                return 0.0
            
            # Extract DEM parameters
            elevations = dem_data['elevations']
            x_coords = dem_data['x_coords']
            y_coords = dem_data['y_coords']
            resolution = dem_data['resolution']
            
            # Convert coordinates to local UTM for accurate distance calculations
            from backend.core.data_transformation.coordinate_transformer import CoordinateTransformer
            coord_transformer = CoordinateTransformer()
            utm_crs = coord_transformer.get_utm_zone(longitude, latitude)
            
            # Transform coordinates to UTM
            transformer = coord_transformer.get_transformer("EPSG:4326", utm_crs)
            x_utm, y_utm = transformer.transform(longitude, latitude)
            
            # Create coordinate grids in UTM
            lon_grid, lat_grid = np.meshgrid(x_coords, y_coords)
            x_utm_grid, y_utm_grid = transformer.transform(lon_grid.flatten(), lat_grid.flatten())
            x_utm_grid = x_utm_grid.reshape(lon_grid.shape)
            y_utm_grid = y_utm_grid.reshape(lat_grid.shape)
            
            # Get effective elastic thickness from geological data
            te_km = await self._get_effective_elastic_thickness(latitude, longitude)
            
            # Physical constants
            g = 9.81  # m/s²
            rho_crust = 2700  # kg/m³ (crustal density)
            rho_mantle = 3300  # kg/m³ (mantle density)
            E = 70e9  # Pa (Young's modulus)
            nu = 0.25  # Poisson's ratio
            
            # Flexural rigidity
            D = (E * (te_km * 1000)**3) / (12 * (1 - nu**2))
            
            # Flexural parameter
            alpha = (4 * D / ((rho_mantle - rho_crust) * g))**0.25
            
            # Compute topographic load relative to reference elevation
            reference_elevation = np.median(elevations)
            load_heights = elevations - reference_elevation
            
            # Apply Gaussian filter to smooth loads (represents distributed loading)
            sigma_km = 5.0  # 5 km smoothing
            sigma_pixels = sigma_km * 1000 / resolution  # Convert to pixels
            smoothed_loads = ndimage.gaussian_filter(load_heights, sigma=sigma_pixels)
            
            # Compute flexural response using Green's function approach
            loading_effect = 0.0
            
            # Define Green's function for flexural response
            def flexural_greens_function(r, alpha_val):
                """Green's function for flexural response to point load"""
                if r == 0:
                    return 1.0 / (8 * np.pi * D)
                
                kr = r / alpha_val
                if kr < 0.1:
                    # Small argument approximation
                    return (1.0 / (8 * np.pi * D)) * (1 - kr**2 / 4)
                else:
                    # Full Kelvin function solution
                    from scipy.special import kei, ker
                    return (1.0 / (8 * np.pi * D)) * (ker(kr) + 1j * kei(kr)).real
            
            # Compute loading effect by integrating over all loads
            total_effect = 0.0
            load_count = 0
            
            # Sample loads at regular intervals to avoid computational overload
            sample_step = max(1, len(elevations) // 1000)  # Sample ~1000 points max
            
            for i in range(0, elevations.shape[0], sample_step):
                for j in range(0, elevations.shape[1], sample_step):
                    load_height = smoothed_loads[i, j]
                    
                    if abs(load_height) > 10.0:  # Only consider significant loads > 10m
                        # Distance from calculation point
                        dx = x_utm_grid[i, j] - x_utm
                        dy = y_utm_grid[i, j] - y_utm
                        distance = np.sqrt(dx**2 + dy**2)
                        
                        if distance < 200000:  # Within 200 km
                            # Load magnitude (force per unit area)
                            load_force = rho_crust * g * load_height
                            
                            # Area element
                            area_element = (resolution * sample_step)**2
                            
                            # Flexural response
                            greens_value = flexural_greens_function(distance, alpha)
                            deflection = greens_value * load_force * area_element
                            
                            total_effect += deflection
                            load_count += 1
            
            # Apply additional corrections
            
            # 1. Elastic thickness variation correction
            te_variation = await self._get_elastic_thickness_variation(latitude, longitude)
            te_correction = total_effect * (te_variation - 1.0) * 0.3
            
            # 2. Density variation correction
            density_variation = await self._get_density_variation(latitude, longitude)
            density_correction = total_effect * (density_variation - 1.0) * 0.2
            
            # 3. Thermal correction for volcanic areas
            thermal_correction = await self._get_thermal_loading_correction(latitude, longitude)
            
            final_loading_effect = total_effect + te_correction + density_correction + thermal_correction
            
            logger.info(f"Topographic loading computed: {final_loading_effect:.2f}m from {load_count} loads")
            
            return final_loading_effect
            
        except Exception as e:
            logger.error(f"Error in topographic loading computation: {e}")
            return await self._simplified_topographic_loading(latitude, longitude)
    
    async def _get_local_dem_data(self, latitude, longitude, radius_km=50):
        """Get high-resolution DEM data from multiple sources"""
        try:
            # Try to get DEM data from database first
            async with self.db_integrator.get_postgresql_session() as session:
                dem_query = """
                SELECT 
                    d.elevation_data,
                    d.resolution_m,
                    d.bounds,
                    d.data_source
                FROM digital_elevation_models d
                WHERE ST_DWithin(
                    d.bounds, 
                    ST_Buffer(ST_SetSRID(ST_MakePoint(%s, %s), 4326), %s),
                    0
                )
                ORDER BY d.resolution_m ASC
                LIMIT 1
                """
                
                # Convert radius to degrees (approximate)
                radius_deg = radius_km / 111.0
                
                result = await session.execute(dem_query, (longitude, latitude, radius_deg))
                dem_row = result.fetchone()
                
                if dem_row:
                    # Parse stored DEM data
                    elevation_data = json.loads(dem_row.elevation_data)
                    return {
                        'elevations': np.array(elevation_data['elevations']),
                        'x_coords': np.array(elevation_data['x_coords']),
                        'y_coords': np.array(elevation_data['y_coords']),
                        'resolution': dem_row.resolution_m,
                        'source': dem_row.data_source
                    }
            
            # Fallback to NASA SRTM data
            return await self._fetch_srtm_data(latitude, longitude, radius_km)
            
        except Exception as e:
            logger.error(f"Error getting local DEM data: {e}")
            return None
    
