    async def _fetch_and_process_multi_source_dem(self, latitude, longitude, radius_km, bbox):
        """
        Advanced multi-source DEM acquisition and processing with database integration
        
        Implements sophisticated algorithms for:
        - Multi-source DEM fusion (SRTM, ASTER GDEM, ALOS World 3D, TanDEM-X)
        - Topographic analysis and feature extraction
        - Database caching and optimization
        - Quality assessment and uncertainty quantification
        """
        try:
            from ..core.real_data_connectors.nasa_connector import NASAEarthDataConnector
            from ..core.real_data_connectors.usgs_connector import USGSVolcanoConnector
            from ..core.database_integration import DatabaseManager
            from ..core.data_transformation.topographic_processor import TopographicProcessor
            import rasterio
            from rasterio.warp import reproject, Resampling
            from rasterio.merge import merge
            from scipy.ndimage import gaussian_filter, sobel
            from scipy.interpolate import griddata, RBFInterpolator
            from sklearn.ensemble import RandomForestRegressor
            import xarray as xr
            
            # Initialize database connection for DEM caching
            db_manager = DatabaseManager()
            
            # Check for cached DEM data first
            cached_dem = await self._check_dem_cache(latitude, longitude, radius_km, db_manager)
            if cached_dem and cached_dem['quality_score'] > 0.8:
                logger.info(f"Using high-quality cached DEM for {latitude:.4f}, {longitude:.4f}")
                return cached_dem
            
            # Initialize multi-source DEM acquisition
            dem_sources = {}
            quality_metrics = {}
            
            # 1. NASA EarthData - ASTER GDEM v3 (30m resolution)
            nasa_config = DataSourceConfig(
                source_id="nasa_earthdata",
                name="NASA EarthData",
                base_url="https://earthdata.nasa.gov/api/v1",
                api_key=os.getenv('NASA_EARTHDATA_API_KEY')
            )
            
            async with NASAEarthDataConnector(nasa_config) as nasa_conn:
                aster_dem = await self._fetch_aster_gdem(nasa_conn, bbox)
                if aster_dem:
                    dem_sources['aster'] = aster_dem
                    quality_metrics['aster'] = await self._assess_dem_quality(aster_dem, 'aster')
            
            # 2. USGS - SRTM 1 Arc-Second Global (30m resolution)
            usgs_config = DataSourceConfig(
                source_id="usgs_eros",
                name="USGS EROS",
                base_url="https://earthexplorer.usgs.gov/api/v1.5",
                username=os.getenv('USGS_USERNAME'),
                password=os.getenv('USGS_PASSWORD')
            )
            
            async with USGSVolcanoConnector(usgs_config) as usgs_conn:
                srtm_dem = await self._fetch_srtm_data(usgs_conn, bbox)
                if srtm_dem:
                    dem_sources['srtm'] = srtm_dem
                    quality_metrics['srtm'] = await self._assess_dem_quality(srtm_dem, 'srtm')
            
            # 3. ALOS World 3D - 30m (via external API)
            alos_dem = await self._fetch_alos_world3d(bbox)
            if alos_dem:
                dem_sources['alos'] = alos_dem
                quality_metrics['alos'] = await self._assess_dem_quality(alos_dem, 'alos')
            
            # 4. TanDEM-X 90m (global coverage)
            tandem_dem = await self._fetch_tandem_x(bbox)
            if tandem_dem:
                dem_sources['tandem'] = tandem_dem
                quality_metrics['tandem'] = await self._assess_dem_quality(tandem_dem, 'tandem')
            
            if not dem_sources:
                logger.warning("No DEM sources available, falling back to database interpolation")
                return await self._interpolate_from_database(latitude, longitude, radius_km, db_manager)
            
            # Advanced multi-source DEM fusion using machine learning
            fused_dem = await self._fuse_multi_source_dems(dem_sources, quality_metrics, bbox)
            
            # Topographic analysis and feature extraction
            topo_processor = TopographicProcessor()
            enhanced_dem = await topo_processor.enhance_dem_with_features(fused_dem, {
                'slope_analysis': True,
                'aspect_analysis': True,
                'curvature_analysis': True,
                'drainage_network': True,
                'ridge_valley_detection': True,
                'volcanic_feature_detection': True
            })
            
            # Quality assessment and uncertainty quantification
            final_quality = await self._comprehensive_quality_assessment(enhanced_dem, dem_sources, quality_metrics)
            enhanced_dem['quality_score'] = final_quality['overall_score']
            enhanced_dem['uncertainty_map'] = final_quality['uncertainty_map']
            enhanced_dem['confidence_intervals'] = final_quality['confidence_intervals']
            
            # Cache the processed DEM in database
            await self._cache_dem_in_database(enhanced_dem, latitude, longitude, radius_km, db_manager)
            
            logger.info(f"Successfully processed multi-source DEM with quality score: {final_quality['overall_score']:.3f}")
            return enhanced_dem
            
        except Exception as e:
            logger.error(f"Error in multi-source DEM processing: {e}")
            # Fallback to database interpolation
            return await self._interpolate_from_database(latitude, longitude, radius_km, db_manager)
    
    async def _check_dem_cache(self, latitude, longitude, radius_km, db_manager):
        """Check for cached DEM data in database"""
        try:
            query = """
            SELECT dem_data, quality_score, processing_timestamp, source_combination
            FROM digital_elevation_models 
            WHERE ST_DWithin(
                ST_SetSRID(ST_MakePoint(%s, %s), 4326),
                center_point,
                %s * 1000
            )
            AND processing_timestamp > NOW() - INTERVAL '30 days'
            ORDER BY quality_score DESC, processing_timestamp DESC
            LIMIT 1
            """
            
            result = await db_manager.execute_query(query, (longitude, latitude, radius_km))
            
            if result:
                cached_data = result[0]
                # Deserialize DEM data
                import pickle
                dem_data = pickle.loads(cached_data['dem_data'])
                dem_data['quality_score'] = cached_data['quality_score']
                dem_data['cache_timestamp'] = cached_data['processing_timestamp']
                dem_data['source_combination'] = cached_data['source_combination']
                return dem_data
            
            return None
            
        except Exception as e:
            logger.error(f"Error checking DEM cache: {e}")
            return None
    
    async def _fetch_aster_gdem(self, nasa_conn, bbox):
        """Fetch ASTER GDEM v3 data from NASA EarthData"""
        try:
            # ASTER GDEM v3 collection ID
            collection_id = "C1711961296-LPCLOUD"
            
            search_params = {
                'collection_concept_id': collection_id,
                'bounding_box': f"{bbox[0]},{bbox[1]},{bbox[2]},{bbox[3]}",
                'page_size': 50
            }
            
            # Search for ASTER GDEM granules
            search_url = f"{nasa_conn.config.base_url}/search/granules"
            response = await nasa_conn._make_request('GET', search_url, params=search_params)
            
            if not response or 'feed' not in response or not response['feed'].get('entry'):
                logger.warning("No ASTER GDEM granules found for the specified area")
                return None
            
            # Download and process granules
            granule_data = []
            for entry in response['feed']['entry'][:5]:  # Limit to 5 granules for performance
                download_url = None
                for link in entry.get('links', []):
                    if link.get('rel') == 'http://esipfed.org/ns/fedsearch/1.1/data#':
                        download_url = link['href']
                        break
                
                if download_url:
                    granule_dem = await self._download_and_process_granule(nasa_conn, download_url, bbox)
                    if granule_dem:
                        granule_data.append(granule_dem)
            
            if not granule_data:
                return None
            
            # Mosaic multiple granules if needed
            if len(granule_data) == 1:
                return granule_data[0]
            else:
                return await self._mosaic_dem_granules(granule_data, bbox)
                
        except Exception as e:
            logger.error(f"Error fetching ASTER GDEM: {e}")
            return None
    
