    async def _get_thermal_loading_correction(self, latitude, longitude):
        """Advanced thermal loading correction using multi-source thermal data and physics-based modeling"""
        try:
            # Initialize thermal data collectors
            thermal_data = await self._collect_comprehensive_thermal_data(latitude, longitude)
            
            # Calculate thermal expansion effects using 3D thermal modeling
            thermal_expansion_correction = await self._calculate_3d_thermal_expansion(
                thermal_data, latitude, longitude
            )
            
            # Account for magma chamber thermal effects
            magma_thermal_correction = await self._calculate_magma_chamber_thermal_effects(
                thermal_data, latitude, longitude
            )
            
            # Hydrothermal system effects
            hydrothermal_correction = await self._calculate_hydrothermal_loading_effects(
                thermal_data, latitude, longitude
            )
            
            # Phase change effects (solid-liquid transitions)
            phase_change_correction = await self._calculate_phase_change_loading(
                thermal_data, latitude, longitude
            )
            
            # Combine all thermal effects with physics-based weighting
            total_thermal_correction = (
                thermal_expansion_correction + 
                magma_thermal_correction + 
                hydrothermal_correction + 
                phase_change_correction
            )
            
            # Apply distance-dependent attenuation
            volcanic_proximity = await self._get_volcanic_proximity(latitude, longitude)
            attenuation_factor = np.exp(-volcanic_proximity / 15.0)  # 15 km characteristic length
            
            return total_thermal_correction * attenuation_factor
            
        except Exception as e:
            logger.error(f"Error calculating advanced thermal loading correction: {e}")
            return 0.0
    
