    async def _collect_comprehensive_thermal_data(self, latitude, longitude):
        """Collect multi-source thermal data for advanced thermal modeling"""
        try:
            thermal_data = {
                'satellite_thermal': {},
                'ground_thermal': {},
                'geothermal': {},
                'volcanic_thermal': {},
                'metadata': {}
            }
            
            # Collect NASA satellite thermal data
            try:
                from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
                from backend.core.real_data_connectors.base_connector import DataSourceConfig
                
                nasa_config = DataSourceConfig(
                    name="nasa_thermal",
                    base_url="https://earthdata.nasa.gov/api",
                    api_key=self.config.get('nasa_api_key'),
                    username=self.config.get('nasa_username'),
                    password=self.config.get('nasa_password')
                )
                
                nasa_connector = NASAEarthDataConnector(nasa_config)
                
                # Get recent thermal anomaly data
                bbox = [longitude - 0.5, latitude - 0.5, longitude + 0.5, latitude + 0.5]
                
                thermal_observations = []
                async for obs in nasa_connector.fetch_real_time_data(
                    instruments=['MODIS', 'VIIRS', 'LANDSAT'],
                    bbox=bbox
                ):
                    if obs.observation_type in ['thermal_anomaly', 'thermal_infrared']:
                        thermal_observations.append(obs)
                    
                    if len(thermal_observations) >= 100:  # Limit data collection
                        break
                
                thermal_data['satellite_thermal'] = {
                    'observations': thermal_observations,
                    'data_count': len(thermal_observations),
                    'time_range': self._get_observation_time_range(thermal_observations)
                }
                
            except Exception as e:
                logger.warning(f"Failed to collect NASA thermal data: {e}")
                thermal_data['satellite_thermal'] = {'observations': [], 'error': str(e)}
            
            # Collect ground-based thermal measurements
            thermal_data['ground_thermal'] = await self._collect_ground_thermal_measurements(
                latitude, longitude
            )
            
            # Collect geothermal gradient data
            thermal_data['geothermal'] = await self._collect_geothermal_gradient_data(
                latitude, longitude
            )
            
            # Collect volcanic thermal signatures
            thermal_data['volcanic_thermal'] = await self._collect_volcanic_thermal_signatures(
                latitude, longitude
            )
            
            return thermal_data
            
        except Exception as e:
            logger.error(f"Error collecting comprehensive thermal data: {e}")
            return {'error': str(e)}
    
    async def _calculate_3d_thermal_expansion(self, thermal_data, latitude, longitude):
        """Calculate 3D thermal expansion effects using finite element modeling"""
        try:
            # Extract thermal parameters
            surface_temp = await self._extract_surface_temperature(thermal_data)
            geothermal_gradient = await self._extract_geothermal_gradient(thermal_data)
            thermal_conductivity = await self._get_thermal_conductivity(latitude, longitude)
            
            # Define 3D thermal model parameters
            model_depth = 10000.0  # 10 km depth
            grid_resolution = 500.0  # 500 m resolution
            
            # Create 3D temperature field
            temperature_field = await self._create_3d_temperature_field(
                surface_temp, geothermal_gradient, thermal_conductivity,
                model_depth, grid_resolution, latitude, longitude
            )
            
            # Calculate thermal expansion coefficients for different rock types
            expansion_coefficients = await self._get_thermal_expansion_coefficients(
                latitude, longitude
            )
            
            # Calculate volumetric thermal expansion
            reference_temp = 15.0  # 15°C reference temperature
            thermal_strain = np.zeros_like(temperature_field)
            
            for rock_type, alpha in expansion_coefficients.items():
                rock_mask = await self._get_rock_type_mask(rock_type, latitude, longitude)
                thermal_strain += (temperature_field - reference_temp) * alpha * rock_mask
            
            # Convert thermal strain to surface displacement using Green's functions
            surface_displacement = await self._calculate_thermal_surface_displacement(
                thermal_strain, model_depth, grid_resolution
            )
            
            # Extract displacement at target location
            target_displacement = await self._interpolate_displacement_at_point(
                surface_displacement, latitude, longitude
            )
            
            return target_displacement
            
        except Exception as e:
            logger.error(f"Error calculating 3D thermal expansion: {e}")
            return 0.0
    
    async def _calculate_magma_chamber_thermal_effects(self, thermal_data, latitude, longitude):
        """Calculate thermal effects from magma chamber heating"""
        try:
            # Query magma chamber data
            async with self.db_integrator.get_postgresql_session() as session:
                chamber_query = """
                SELECT 
                    vc.chamber_volume_km3,
                    vc.chamber_depth_km,
                    vc.temperature_c,
                    vc.melt_fraction,
                    ST_Distance(vc.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) * 111.0 as distance_km
                FROM volcanic_chambers vc
                WHERE ST_DWithin(vc.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 0.5)
                ORDER BY distance_km ASC
                LIMIT 5
                """
                
                result = await session.execute(chamber_query, (longitude, latitude, longitude, latitude))
                chambers = result.fetchall()
                
                if not chambers:
                    return 0.0
                
                total_thermal_effect = 0.0
                
                for chamber in chambers:
                    # Calculate thermal anomaly from magma chamber
                    chamber_temp = chamber.temperature_c or 1000.0  # Default magma temperature
                    chamber_depth = chamber.chamber_depth_km or 5.0
                    chamber_volume = chamber.chamber_volume_km3 or 1.0
                    distance = chamber.distance_km or 0.1
                    melt_fraction = chamber.melt_fraction or 0.3
                    
                    # Thermal diffusion model
                    thermal_diffusivity = 1e-6  # m²/s for typical rocks
                    time_scale = 3.15e7  # 1 year in seconds
                    
                    # Calculate thermal penetration depth
                    penetration_depth = np.sqrt(thermal_diffusivity * time_scale)  # meters
                    
                    # Temperature anomaly at surface
                    temp_anomaly = (chamber_temp - 15.0) * melt_fraction * np.exp(
                        -chamber_depth * 1000 / penetration_depth
                    ) * np.exp(-distance / 10.0)  # 10 km characteristic distance
                    
                    # Convert to thermal expansion displacement
                    thermal_expansion_coeff = 3e-5  # 1/K for typical rocks
                    affected_thickness = min(chamber_depth * 1000, penetration_depth)
                    
                    thermal_displacement = temp_anomaly * thermal_expansion_coeff * affected_thickness
                    
                    # Weight by chamber volume
                    volume_weight = np.log10(chamber_volume + 1) / 3.0  # Logarithmic scaling
                    
                    total_thermal_effect += thermal_displacement * volume_weight
                
                return total_thermal_effect
                
        except Exception as e:
            logger.error(f"Error calculating magma chamber thermal effects: {e}")
            return 0.0
    
    async def _calculate_hydrothermal_loading_effects(self, thermal_data, latitude, longitude):
        """Calculate loading effects from hydrothermal systems"""
        try:
            # Query hydrothermal features
            async with self.db_integrator.get_postgresql_session() as session:
                hydrothermal_query = """
                SELECT 
                    gs.properties->>'temperature_c' as temp_c,
                    gs.properties->>'flow_rate_kg_s' as flow_rate,
                    gs.properties->>'depth_m' as depth_m,
                    ST_Distance(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) * 111.0 as distance_km
                FROM geological_structures gs
                WHERE gs.structure_type IN ('hot_spring', 'fumarole', 'hydrothermal_vent')
                AND ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 0.2)
                ORDER BY distance_km ASC
                LIMIT 10
                """
                
                result = await session.execute(hydrothermal_query, (longitude, latitude, longitude, latitude))
                hydrothermal_features = result.fetchall()
                
                if not hydrothermal_features:
                    return 0.0
                
                total_hydrothermal_effect = 0.0
                
                for feature in hydrothermal_features:
                    try:
                        temp_c = float(feature.temp_c) if feature.temp_c else 80.0
                        flow_rate = float(feature.flow_rate) if feature.flow_rate else 1.0
                        depth_m = float(feature.depth_m) if feature.depth_m else 100.0
                        distance_km = feature.distance_km or 0.1
                        
                        # Calculate hydrothermal pressure effects
                        water_density = 1000.0  # kg/m³
                        thermal_expansion_water = 3e-4  # 1/K
                        
                        # Temperature-induced density change
                        density_change = water_density * thermal_expansion_water * (temp_c - 15.0)
                        
                        # Pressure change due to density change
                        pressure_change = density_change * 9.81 * depth_m  # Pa
                        
                        # Convert to surface displacement using elastic half-space model
                        poisson_ratio = 0.25
                        youngs_modulus = 30e9  # Pa
                        
                        # Point load displacement (Boussinesq solution)
                        load_magnitude = pressure_change * np.pi * (flow_rate / water_density)**0.5
                        
                        displacement = (load_magnitude * (1 - poisson_ratio**2)) / (
                            np.pi * youngs_modulus * distance_km * 1000
                        )
                        
                        # Distance attenuation
                        attenuation = np.exp(-distance_km / 5.0)  # 5 km characteristic distance
                        
                        total_hydrothermal_effect += displacement * attenuation
                        
                    except (ValueError, TypeError) as e:
                        logger.warning(f"Error processing hydrothermal feature: {e}")
                        continue
                
                return total_hydrothermal_effect
                
        except Exception as e:
            logger.error(f"Error calculating hydrothermal loading effects: {e}")
            return 0.0
    
    async def _calculate_phase_change_loading(self, thermal_data, latitude, longitude):
        """Calculate loading effects from solid-liquid phase transitions"""
        try:
            # Get temperature data from thermal_data
            surface_temps = []
            if 'satellite_thermal' in thermal_data:
                for obs in thermal_data['satellite_thermal'].get('observations', []):
                    if 'brightness_temperature_k' in obs.value:
                        surface_temps.append(obs.value['brightness_temperature_k'] - 273.15)  # Convert to Celsius
            
            if not surface_temps:
                return 0.0
            
            avg_surface_temp = np.mean(surface_temps)
            
            # Check for phase transition conditions
            melting_point = 1200.0  # °C for typical basaltic rocks
            freezing_point = 0.0    # °C for water
            
            phase_change_effect = 0.0
            
            # Magma solidification/melting effects
            if avg_surface_temp > 100.0:  # Anomalously high surface temperature
                # Estimate subsurface temperature using geothermal gradient
                geothermal_gradient = 25.0  # °C/km default
                depth_to_melting = max(0, (melting_point - avg_surface_temp) / geothermal_gradient)
                
                if depth_to_melting < 10.0:  # Within 10 km depth
                    # Calculate volume change due to melting/solidification
                    density_solid = 2800.0  # kg/m³
                    density_liquid = 2600.0  # kg/m³
                    
                    volume_change_fraction = (density_solid - density_liquid) / density_solid
                    
                    # Estimate affected volume (simplified spherical model)
                    affected_radius = 5000.0 - depth_to_melting * 500.0  # meters
                    affected_volume = (4/3) * np.pi * affected_radius**3
                    
                    # Calculate surface displacement
                    volume_change = affected_volume * volume_change_fraction
                    surface_area = np.pi * affected_radius**2
                    
                    phase_change_effect = volume_change / surface_area  # meters
            
            # Water phase transitions (less significant but included for completeness)
            if avg_surface_temp < 5.0:  # Near freezing conditions
                # Frost heave effects (minimal for volcanic areas)
                frost_heave = 0.001 * (5.0 - avg_surface_temp)  # meters
                phase_change_effect += frost_heave
            
            return phase_change_effect
            
        except Exception as e:
            logger.error(f"Error calculating phase change loading: {e}")
            return 0.0
    
    async def _get_comprehensive_dem_data(self, latitude, longitude, radius_km=50.0):
        """Get high-resolution DEM data from multiple sources with quality assessment"""
        try:
            # Try to get cached DEM data first
            cached_dem = await self._get_cached_dem_data(latitude, longitude, radius_km)
            if cached_dem and cached_dem.get('quality_score', 0) > 0.7:
                return cached_dem
            
            # Collect DEM data from multiple sources
            dem_sources = []
            
            # NASA SRTM data
            try:
                nasa_dem = await self._get_nasa_srtm_data(latitude, longitude, radius_km)
                if nasa_dem:
                    dem_sources.append(('NASA_SRTM', nasa_dem))
            except Exception as e:
                logger.warning(f"Failed to get NASA SRTM data: {e}")
            
            # USGS DEM data
            try:
                usgs_dem = await self._get_usgs_dem_data(latitude, longitude, radius_km)
                if usgs_dem:
                    dem_sources.append(('USGS', usgs_dem))
            except Exception as e:
                logger.warning(f"Failed to get USGS DEM data: {e}")
            
            # Copernicus DEM data (if available)
            try:
                copernicus_dem = await self._get_copernicus_dem_data(latitude, longitude, radius_km)
                if copernicus_dem:
                    dem_sources.append(('Copernicus', copernicus_dem))
            except Exception as e:
                logger.warning(f"Failed to get Copernicus DEM data: {e}")
            
            if not dem_sources:
                logger.warning("No DEM sources available, using fallback")
                return await self._generate_fallback_dem(latitude, longitude, radius_km)
            
            # Merge and validate DEM data
            merged_dem = await self._merge_dem_sources(dem_sources, latitude, longitude, radius_km)
            
            # Cache the result
            await self._cache_dem_data(merged_dem, latitude, longitude, radius_km)
            
            return merged_dem
            
        except Exception as e:
            logger.error(f"Error getting comprehensive DEM data: {e}")
            return await self._generate_fallback_dem(latitude, longitude, radius_km)
    
