    async def _get_comprehensive_climate_data(self, latitude, longitude):
        """Get comprehensive climate data from multiple sources"""
        try:
            climate_data = {}
            
            # Get current climate data
            async with self.db_integrator.get_postgresql_session() as session:
                climate_query = """
                SELECT 
                    cd.annual_precipitation_mm,
                    cd.mean_temperature_c,
                    cd.temperature_range_c,
                    cd.humidity_percent,
                    cd.wind_speed_ms,
                    cd.freeze_thaw_cycles,
                    cd.storm_frequency,
                    ST_Distance(cd.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM climate_data cd
                WHERE ST_DWithin(cd.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 2.0)
                ORDER BY distance ASC
                LIMIT 5
                """
                
                result = await session.execute(climate_query, (longitude, latitude, longitude, latitude))
                climate_records = result.fetchall()
                
                if climate_records:
                    # Distance-weighted average
                    total_weight = 0.0
                    weighted_data = {
                        'precipitation': 0.0,
                        'temperature': 0.0,
                        'temperature_range': 0.0,
                        'humidity': 0.0,
                        'wind_speed': 0.0,
                        'freeze_thaw_cycles': 0.0,
                        'storm_frequency': 0.0
                    }
                    
                    for record in climate_records:
                        weight = 1.0 / (record.distance + 0.1)
                        total_weight += weight
                        
                        weighted_data['precipitation'] += (record.annual_precipitation_mm or 1000) * weight
                        weighted_data['temperature'] += (record.mean_temperature_c or 15) * weight
                        weighted_data['temperature_range'] += (record.temperature_range_c or 20) * weight
                        weighted_data['humidity'] += (record.humidity_percent or 60) * weight
                        weighted_data['wind_speed'] += (record.wind_speed_ms or 5) * weight
                        weighted_data['freeze_thaw_cycles'] += (record.freeze_thaw_cycles or 50) * weight
                        weighted_data['storm_frequency'] += (record.storm_frequency or 10) * weight
                    
                    # Normalize by total weight
                    for key in weighted_data:
                        weighted_data[key] /= total_weight
                    
                    climate_data = weighted_data
                else:
                    # Estimate from latitude and global patterns
                    climate_data = await self._estimate_climate_from_latitude(latitude, longitude)
            
            # Get paleoclimate data for long-term trends
            paleoclimate_data = await self._get_paleoclimate_data(latitude, longitude)
            climate_data['paleoclimate'] = paleoclimate_data
            
            return climate_data
            
        except Exception as e:
            logger.error(f"Error getting comprehensive climate data: {e}")
            return await self._estimate_climate_from_latitude(latitude, longitude)
    
    async def _estimate_climate_from_latitude(self, latitude, longitude):
        """Estimate climate parameters from latitude and global patterns"""
        try:
            # Temperature model based on latitude
            mean_temp = 30 - 0.6 * abs(latitude)  # °C
            
            # Advanced precipitation model using multiple climate mechanisms
            precipitation = await self._advanced_global_precipitation_model(latitude, longitude, mean_temp)
            
            # Other climate parameters
            temperature_range = 15 + 0.3 * abs(latitude)
            humidity = max(30, 80 - 0.5 * abs(latitude))
            wind_speed = 3 + 0.1 * abs(latitude)
            freeze_thaw_cycles = max(0, 100 - 2 * abs(latitude - 45))
            storm_frequency = 5 + 0.2 * abs(latitude - 30)
            
            return {
                'precipitation': precipitation,
                'temperature': mean_temp,
                'temperature_range': temperature_range,
                'humidity': humidity,
                'wind_speed': wind_speed,
                'freeze_thaw_cycles': freeze_thaw_cycles,
                'storm_frequency': storm_frequency
            }
            
        except Exception as e:
            logger.error(f"Error estimating climate from latitude: {e}")
            return {
                'precipitation': 1000,
                'temperature': 15,
                'temperature_range': 20,
                'humidity': 60,
                'wind_speed': 5,
                'freeze_thaw_cycles': 50,
                'storm_frequency': 10
            }
    
    async def _advanced_global_precipitation_model(self, latitude, longitude, temperature):
        """Advanced global precipitation model using multiple climate mechanisms and real data sources"""
        from backend.core.real_data_connectors.copernicus_connector import CopernicusConnector, DataSourceConfig
        from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
        from backend.core.data_transformation.interpolation_engine import InterpolationEngine
        
        try:
            # Initialize precipitation with physics-based atmospheric circulation model
            base_precipitation = await self._calculate_atmospheric_circulation_precipitation(latitude, longitude, temperature)
            
            # Apply multiple enhancement mechanisms
            precipitation_components = {
                'circulation_base': base_precipitation,
                'orographic': 0.0,
                'convective': 0.0,
                'frontal': 0.0,
                'monsoon': 0.0,
                'oceanic': 0.0,
                'topographic': 0.0
            }
            
            # 1. Orographic precipitation enhancement
            orographic_enhancement = await self._calculate_orographic_precipitation(latitude, longitude, base_precipitation)
            precipitation_components['orographic'] = orographic_enhancement
            
            # 2. Convective precipitation (thunderstorms, tropical convection)
            convective_precipitation = await self._calculate_convective_precipitation(latitude, longitude, temperature)
            precipitation_components['convective'] = convective_precipitation
            
            # 3. Frontal precipitation (mid-latitude cyclones)
            frontal_precipitation = await self._calculate_frontal_precipitation(latitude, longitude, temperature)
            precipitation_components['frontal'] = frontal_precipitation
            
            # 4. Monsoon precipitation
            monsoon_precipitation = await self._calculate_monsoon_precipitation(latitude, longitude, temperature)
            precipitation_components['monsoon'] = monsoon_precipitation
            
            # 5. Oceanic moisture transport effects
            oceanic_enhancement = await self._calculate_oceanic_moisture_transport(latitude, longitude)
            precipitation_components['oceanic'] = oceanic_enhancement
            
            # 6. Complex topographic effects
            topographic_effects = await self._calculate_complex_topographic_effects(latitude, longitude)
            precipitation_components['topographic'] = topographic_effects
            
            # Integrate all components with non-linear interactions
            total_precipitation = await self._integrate_precipitation_components(precipitation_components, latitude, longitude)
            
            # Apply climate variability and teleconnections
            climate_variability = await self._apply_climate_variability_effects(latitude, longitude, total_precipitation)
            
            # Final precipitation with uncertainty bounds
            final_precipitation = total_precipitation + climate_variability
            
            # Apply physical constraints
            final_precipitation = max(0.0, min(final_precipitation, 15000.0))  # 0-15m/year physical limits
            
            logger.info(f"Advanced precipitation model: {final_precipitation:.1f}mm/year "
                           f"(components: {precipitation_components})")
            
            return final_precipitation
            
        except Exception as e:
            logger.error(f"Error in advanced precipitation model: {e}")
            # Fallback to enhanced simple model
            return await self._enhanced_simple_precipitation_model(latitude, longitude, temperature)
    
    async def _calculate_atmospheric_circulation_precipitation(self, latitude, longitude, temperature):
        """Calculate precipitation from atmospheric circulation patterns using physics-based models"""
        try:
            # Hadley Cell circulation effects
            hadley_precipitation = 0.0
            
            # Intertropical Convergence Zone (ITCZ)
            if abs(latitude) < 15:
                # ITCZ position varies seasonally (±5° from equator)
                itcz_distance = abs(latitude)
                itcz_strength = np.exp(-itcz_distance / 3.0)  # Exponential decay from ITCZ
                
                # Enhanced precipitation in ITCZ
                hadley_precipitation = 2500 * itcz_strength
                
                # Seasonal ITCZ migration effect
                seasonal_factor = 1.0 + 0.3 * np.cos(np.radians(longitude / 2))  # Longitude-dependent seasonality
                hadley_precipitation *= seasonal_factor
            
            # Subtropical high pressure systems (descending air, low precipitation)
            elif 15 <= abs(latitude) < 35:
                # Subtropical desert belt
                subtropical_distance = abs(abs(latitude) - 25)  # Distance from subtropical high center
                subtropical_dryness = np.exp(-subtropical_distance / 5.0)
                
                # Reduced precipitation in subtropical highs
                hadley_precipitation = 300 * (1.0 - 0.8 * subtropical_dryness)
                
                # Monsoon modification for certain longitudes
                if 60 <= longitude <= 140 and 15 <= latitude <= 35:  # Asian monsoon region
                    monsoon_enhancement = 800 * np.sin(np.radians((longitude - 60) / 80 * 180))
                    hadley_precipitation += max(0, monsoon_enhancement)
            
            # Ferrel Cell (mid-latitudes) - storm tracks and frontal systems
            elif 35 <= abs(latitude) < 65:
                # Mid-latitude storm tracks
                storm_track_base = 800
                
                # Westerly wind belt enhancement
                westerly_factor = 1.0 + 0.4 * np.cos(np.radians(latitude))
                
                # Continental vs oceanic effects
                is_oceanic = await self._is_oceanic_location(latitude, longitude)
                oceanic_factor = 1.3 if is_oceanic else 0.8
                
                hadley_precipitation = storm_track_base * westerly_factor * oceanic_factor
                
                # Jet stream position effects
                jet_stream_latitude = 45 + 10 * np.sin(np.radians(longitude / 4))  # Meandering jet
                jet_distance = abs(latitude - jet_stream_latitude)
                jet_enhancement = 200 * np.exp(-jet_distance / 5.0)
                hadley_precipitation += jet_enhancement
            
            # Polar Cell (high latitudes) - limited moisture, low precipitation
            else:  # abs(latitude) >= 65
                # Polar regions with limited moisture
                polar_base = 200
                
                # Temperature-dependent moisture capacity
                if temperature > -10:
                    temp_factor = 1.0 + (temperature + 10) / 20.0
                else:
                    temp_factor = 0.5 * np.exp((temperature + 10) / 10.0)
                
                hadley_precipitation = polar_base * temp_factor
            
            return max(hadley_precipitation, 50.0)  # Minimum 50mm/year
            
        except Exception as e:
            logger.error(f"Error calculating atmospheric circulation precipitation: {e}")
            return 800.0  # Default value
    
    async def _calculate_orographic_precipitation(self, latitude, longitude, base_precipitation):
        """Calculate orographic precipitation enhancement using real topographic data"""
        try:
            # Get detailed topographic data
            topo_data = await self._get_detailed_topographic_data(latitude, longitude)
            
            if not topo_data:
                return 0.0
            
            elevation = topo_data.get('elevation', 0)
            slope = topo_data.get('slope', 0)
            aspect = topo_data.get('aspect', 0)
            roughness = topo_data.get('roughness', 0)
            
            # Orographic lifting calculation
            orographic_enhancement = 0.0
            
            if elevation > 200:  # Significant topography
                # Elevation effect (increases up to ~3000m, then decreases)
                if elevation < 3000:
                    elevation_factor = (elevation / 3000.0) ** 0.7  # Non-linear increase
                else:
                    # Decrease at very high elevations due to limited moisture
                    elevation_factor = 1.0 * np.exp(-(elevation - 3000) / 2000.0)
                
                # Prevailing wind direction analysis
                prevailing_winds = await self._get_prevailing_wind_direction(latitude, longitude)
                
                # Windward vs leeward effects
                wind_alignment = np.cos(np.radians(aspect - prevailing_winds['direction']))
                windward_factor = 1.0 + 0.8 * max(0, wind_alignment)  # Enhancement on windward side
                
                # Slope steepness effect
                slope_factor = 1.0 + (slope / 45.0) * 0.5  # Up to 50% enhancement for 45° slopes
                
                # Terrain roughness effect (creates turbulence and lifting)
                roughness_factor = 1.0 + roughness * 0.3
                
                # Wind speed effect (stronger winds = more lifting)
                wind_speed = prevailing_winds.get('speed', 5.0)
                wind_speed_factor = min(2.0, 1.0 + (wind_speed - 5.0) / 10.0)
                
                # Calculate total orographic enhancement
                orographic_base = base_precipitation * 0.5  # Up to 50% of base precipitation
                orographic_enhancement = (orographic_base * elevation_factor * 
                                        windward_factor * slope_factor * 
                                        roughness_factor * wind_speed_factor)
                
                # Rain shadow effect (reduce precipitation on leeward side)
                if wind_alignment < -0.5:  # Leeward side
                    rain_shadow_reduction = -orographic_enhancement * 0.7
                    orographic_enhancement = rain_shadow_reduction
            
            return orographic_enhancement
            
        except Exception as e:
            logger.error(f"Error calculating orographic precipitation: {e}")
            return 0.0
    
    async def _calculate_convective_precipitation(self, latitude, longitude, temperature):
        """Calculate convective precipitation from thermodynamic instability"""
        try:
            convective_precipitation = 0.0
            
            # Tropical convection (thunderstorms, tropical cyclones)
            if abs(latitude) < 30 and temperature > 20:
                # Convective Available Potential Energy (CAPE) proxy
                surface_temp = temperature + 273.15  # Convert to Kelvin
                
                # Simplified CAPE calculation
                if surface_temp > 298:  # 25°C threshold for significant convection
                    cape_proxy = (surface_temp - 298) * 100  # J/kg proxy
                    
                    # Convective precipitation based on CAPE
                    convective_base = min(1000, cape_proxy * 2)  # Up to 1000mm from convection
                    
                    # Diurnal cycle effect (afternoon maximum)
                    diurnal_factor = 1.2  # Average enhancement
                    
                    # Moisture availability (higher near coasts and over oceans)
                    moisture_factor = await self._get_moisture_availability_factor(latitude, longitude)
                    
                    # Atmospheric instability from temperature gradients
                    instability_factor = await self._get_atmospheric_instability_factor(latitude, longitude)
                    
                    convective_precipitation = (convective_base * diurnal_factor * 
                                              moisture_factor * instability_factor)
            
            # Mid-latitude convection (less intense but still significant)
            elif 30 <= abs(latitude) < 60 and temperature > 15:
                # Weaker convection in mid-latitudes
                temp_factor = max(0, (temperature - 15) / 15.0)  # Temperature dependence
                
                # Seasonal convection (summer maximum)
                seasonal_factor = 1.0 + 0.5 * temp_factor
                
                convective_precipitation = 200 * temp_factor * seasonal_factor
            
            return max(convective_precipitation, 0.0)
            
        except Exception as e:
            logger.error(f"Error calculating convective precipitation: {e}")
            return 0.0
    
    async def _calculate_frontal_precipitation(self, latitude, longitude, temperature):
        """Calculate frontal precipitation from synoptic-scale weather systems"""
        try:
            frontal_precipitation = 0.0
            
            # Mid-latitude frontal systems (most active 30-70°)
            if 30 <= abs(latitude) <= 70:
                # Base frontal activity
                frontal_base = 400  # mm/year
                
                # Latitude dependence (maximum around 50°)
                lat_factor = np.exp(-((abs(latitude) - 50) / 15.0) ** 2)
                
                # Temperature gradient effects (stronger fronts with larger gradients)
                temp_gradient_factor = await self._get_temperature_gradient_factor(latitude, longitude)
                
                # Storm track positioning
                storm_track_factor = await self._get_storm_track_factor(latitude, longitude)
                
                # Seasonal variation (winter maximum in most regions)
                seasonal_factor = 1.2  # Average annual factor
                
                # Baroclinic instability (temperature contrasts drive frontal systems)
                baroclinic_factor = await self._get_baroclinic_instability_factor(latitude, longitude)
                
                frontal_precipitation = (frontal_base * lat_factor * temp_gradient_factor * 
                                       storm_track_factor * seasonal_factor * baroclinic_factor)
            
            # Tropical frontal systems (less common but can be significant)
            elif abs(latitude) < 30:
                # Tropical fronts and convergence zones
                tropical_front_factor = 0.3  # Reduced frontal activity in tropics
                frontal_precipitation = 150 * tropical_front_factor
            
            return max(frontal_precipitation, 0.0)
            
        except Exception as e:
            logger.error(f"Error calculating frontal precipitation: {e}")
            return 0.0
    
    async def _calculate_monsoon_precipitation(self, latitude, longitude, temperature):
        """Calculate monsoon precipitation using regional monsoon dynamics"""
        try:
            monsoon_precipitation = 0.0
            
            # Asian Monsoon System
            if (5 <= latitude <= 35 and 70 <= longitude <= 140):
                # Summer monsoon strength
                monsoon_strength = await self._get_asian_monsoon_strength(latitude, longitude)
                
                # Topographic enhancement (Western Ghats, Himalayas, etc.)
                topo_enhancement = await self._get_monsoon_topographic_enhancement(latitude, longitude)
                
                # Thermal contrast (land-sea temperature difference)
                thermal_contrast = await self._get_land_sea_thermal_contrast(latitude, longitude)
                
                monsoon_precipitation = monsoon_strength * topo_enhancement * thermal_contrast
            
            # African Monsoon (West African Monsoon)
            elif (5 <= latitude <= 20 and -20 <= longitude <= 50):
                # Sahel precipitation from WAM
                wam_strength = await self._get_west_african_monsoon_strength(latitude, longitude)
                monsoon_precipitation = wam_strength
            
            # Australian Monsoon
            elif (-25 <= latitude <= -10 and 110 <= longitude <= 155):
                # Australian summer monsoon
                aus_monsoon_strength = await self._get_australian_monsoon_strength(latitude, longitude)
                monsoon_precipitation = aus_monsoon_strength
            
            # North American Monsoon
            elif (10 <= latitude <= 35 and -120 <= longitude <= -90):
                # Mexican/Arizona monsoon
                nam_strength = await self._get_north_american_monsoon_strength(latitude, longitude)
                monsoon_precipitation = nam_strength
            
            return max(monsoon_precipitation, 0.0)
            
        except Exception as e:
            logger.error(f"Error calculating monsoon precipitation: {e}")
            return 0.0
    
    async def _calculate_oceanic_moisture_transport(self, latitude, longitude):
        """Calculate precipitation enhancement from oceanic moisture transport"""
        try:
            # Get distance to nearest ocean
            ocean_distance = await self._get_distance_to_ocean(latitude, longitude)
            
            if ocean_distance > 1000:  # More than 1000 km from ocean
                return -200.0  # Continental dryness effect
            
            # Oceanic moisture transport depends on wind patterns and SST
            sst_data = await self._get_sea_surface_temperature_data(latitude, longitude)
            wind_data = await self._get_wind_pattern_data(latitude, longitude)
            
            if not sst_data or not wind_data:
                # Simple distance-based model
                moisture_enhancement = 300 * np.exp(-ocean_distance / 200.0)
                return moisture_enhancement
            
            # Advanced moisture transport calculation
            sst = sst_data.get('temperature', 15.0)  # °C
            wind_speed = wind_data.get('speed', 5.0)  # m/s
            wind_direction = wind_data.get('direction', 270.0)  # degrees
            
            # Evaporation rate from ocean (Clausius-Clapeyron relation)
            saturation_vapor_pressure = 611.2 * np.exp(17.67 * sst / (sst + 243.5))  # Pa
            evaporation_rate = wind_speed * saturation_vapor_pressure / 1000.0  # Simplified
            
            # Moisture transport efficiency (depends on wind direction relative to coast)
            coast_angle = await self._get_coastline_orientation(latitude, longitude)
            transport_efficiency = abs(np.cos(np.radians(wind_direction - coast_angle)))
            
            # Distance decay of moisture transport
            distance_factor = np.exp(-ocean_distance / 300.0)  # 300 km decay scale
            
            moisture_transport = evaporation_rate * transport_efficiency * distance_factor * 50
            
            return max(moisture_transport, 0.0)
            
        except Exception as e:
            logger.error(f"Error calculating oceanic moisture transport: {e}")
            return 0.0
    
    async def _calculate_complex_topographic_effects(self, latitude, longitude):
        """Calculate complex topographic effects beyond simple orographic lifting"""
        try:
            # Get detailed topographic context
            topo_context = await self._get_complex_topographic_context(latitude, longitude)
            
            if not topo_context:
                return 0.0
            
            topographic_effects = 0.0
            
            # Valley channeling effects
            if topo_context.get('in_valley', False):
                valley_width = topo_context.get('valley_width', 1000)  # meters
                valley_depth = topo_context.get('valley_depth', 100)   # meters
                
                # Narrow valleys can enhance precipitation through channeling
                if valley_width < 5000:  # Narrow valley
                    channeling_factor = (5000 - valley_width) / 5000.0
                    valley_enhancement = 100 * channeling_factor * (valley_depth / 100.0)
                    topographic_effects += valley_enhancement
            
            # Mountain barrier effects
            barrier_height = topo_context.get('barrier_height', 0)
            if barrier_height > 1000:  # Significant mountain barrier
                # Precipitation shadow and enhancement patterns
                barrier_distance = topo_context.get('barrier_distance', 10000)
                
                if barrier_distance < 50000:  # Within 50 km of barrier
                    # Windward enhancement, leeward reduction
                    wind_direction = await self._get_local_wind_direction(latitude, longitude)
                    barrier_orientation = topo_context.get('barrier_orientation', 0)
                    
                    alignment = np.cos(np.radians(wind_direction - barrier_orientation))
                    
                    if alignment > 0:  # Windward side
                        barrier_enhancement = 200 * alignment * (barrier_height / 1000.0)
                        topographic_effects += barrier_enhancement
                    else:  # Leeward side (rain shadow)
                        rain_shadow = -150 * abs(alignment) * (barrier_height / 1000.0)
                        topographic_effects += rain_shadow
            
            # Plateau effects
            if topo_context.get('on_plateau', False):
                plateau_elevation = topo_context.get('plateau_elevation', 0)
                
                # High plateaus can have reduced precipitation due to limited moisture
                if plateau_elevation > 2000:
                    plateau_reduction = -100 * ((plateau_elevation - 2000) / 2000.0)
                    topographic_effects += plateau_reduction
            
            # Coastal mountain effects
            if topo_context.get('coastal_mountains', False):
                # Enhanced orographic precipitation near coasts
                coastal_enhancement = 300 * np.exp(-topo_context.get('coast_distance', 100) / 50.0)
                topographic_effects += coastal_enhancement
            
            return topographic_effects
            
        except Exception as e:
            logger.error(f"Error calculating complex topographic effects: {e}")
            return 0.0
    
    async def _integrate_precipitation_components(self, components, latitude, longitude):
        """Integrate precipitation components with non-linear interactions"""
        try:
            # Linear sum of components
            linear_sum = sum(components.values())
            
            # Non-linear interactions between components
            interactions = 0.0
            
            # Orographic-convective interaction (mountains enhance convection)
            if components['orographic'] > 0 and components['convective'] > 0:
                oro_conv_interaction = 0.2 * np.sqrt(components['orographic'] * components['convective'])
                interactions += oro_conv_interaction
            
            # Monsoon-orographic interaction (very strong in monsoon regions)
            if components['monsoon'] > 0 and components['orographic'] > 0:
                monsoon_oro_interaction = 0.5 * np.sqrt(components['monsoon'] * components['orographic'])
                interactions += monsoon_oro_interaction
            
            # Frontal-topographic interaction
            if components['frontal'] > 0 and components['topographic'] != 0:
                frontal_topo_interaction = 0.1 * components['frontal'] * abs(components['topographic']) / 100.0
                interactions += frontal_topo_interaction
            
            # Oceanic-convective interaction (moisture enhances convection)
            if components['oceanic'] > 0 and components['convective'] > 0:
                oceanic_conv_interaction = 0.15 * np.sqrt(components['oceanic'] * components['convective'])
                interactions += oceanic_conv_interaction
            
            # Saturation effects (diminishing returns at high precipitation)
            total_before_saturation = linear_sum + interactions
            
            if total_before_saturation > 3000:  # High precipitation threshold
                saturation_factor = 3000 + np.log(total_before_saturation / 3000.0) * 500
                total_precipitation = saturation_factor
            else:
                total_precipitation = total_before_saturation
            
            return max(total_precipitation, 0.0)
            
        except Exception as e:
            logger.error(f"Error integrating precipitation components: {e}")
            return sum(components.values())  # Fallback to linear sum
    
    async def _apply_climate_variability_effects(self, latitude, longitude, base_precipitation):
        """Apply climate variability and teleconnection effects"""
        try:
            variability_effects = 0.0
            
            # El Niño Southern Oscillation (ENSO) effects
            enso_effect = await self._get_enso_precipitation_effect(latitude, longitude)
            variability_effects += enso_effect
            
            # North Atlantic Oscillation (NAO) effects
            if 30 <= latitude <= 70 and -80 <= longitude <= 40:
                nao_effect = await self._get_nao_precipitation_effect(latitude, longitude)
                variability_effects += nao_effect
            
            # Indian Ocean Dipole (IOD) effects
            if -40 <= latitude <= 40 and 20 <= longitude <= 120:
                iod_effect = await self._get_iod_precipitation_effect(latitude, longitude)
                variability_effects += iod_effect
            
            # Pacific Decadal Oscillation (PDO) effects
            if 20 <= latitude <= 70 and -180 <= longitude <= -100:
                pdo_effect = await self._get_pdo_precipitation_effect(latitude, longitude)
                variability_effects += pdo_effect
            
            # Madden-Julian Oscillation (MJO) effects (tropical regions)
            if abs(latitude) < 30:
                mjo_effect = await self._get_mjo_precipitation_effect(latitude, longitude)
                variability_effects += mjo_effect
            
            # Scale variability effects by base precipitation
            scaled_variability = variability_effects * (base_precipitation / 1000.0)
            
            return scaled_variability
            
        except Exception as e:
            logger.error(f"Error applying climate variability effects: {e}")
            return 0.0
    
    # Helper methods for advanced precipitation calculations
    
    async def _get_detailed_topographic_data(self, latitude, longitude):
        """Get detailed topographic data for orographic calculations"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                topo_query = """
                SELECT 
                    AVG(CAST(gs.properties->>'elevation_m' AS FLOAT)) as elevation,
                    AVG(CAST(gs.properties->>'slope_degrees' AS FLOAT)) as slope,
                    AVG(CAST(gs.properties->>'aspect_degrees' AS FLOAT)) as aspect,
                    AVG(CAST(gs.properties->>'roughness_index' AS FLOAT)) as roughness
                FROM geological_structures gs
                WHERE gs.structure_type = 'topographic_analysis'
                AND ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 0.1)
                """
                
                result = await session.execute(topo_query, (longitude, latitude))
                row = result.fetchone()
                
                if row:
                    return {
                        'elevation': row.elevation or 0.0,
                        'slope': row.slope or 0.0,
                        'aspect': row.aspect or 0.0,
                        'roughness': row.roughness or 0.0
                    }
                
                return None
                
        except Exception as e:
            logger.error(f"Error getting detailed topographic data: {e}")
            return None
    
    async def _get_prevailing_wind_direction(self, latitude, longitude):
        """Get prevailing wind direction and speed"""
        try:
            # Query wind data from database
            async with self.db_integrator.get_postgresql_session() as session:
                wind_query = """
                SELECT 
                    AVG(CAST(cd.properties->>'wind_direction_deg' AS FLOAT)) as direction,
                    AVG(CAST(cd.properties->>'wind_speed_ms' AS FLOAT)) as speed
                FROM climate_data cd
                WHERE ST_DWithin(cd.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1.0)
                AND cd.properties->>'wind_direction_deg' IS NOT NULL
                """
                
                result = await session.execute(wind_query, (longitude, latitude))
                row = result.fetchone()
                
                if row and row.direction is not None:
                    return {
                        'direction': row.direction,
                        'speed': row.speed or 5.0
                    }
                
                # Estimate from global wind patterns
                return await self._estimate_prevailing_winds(latitude, longitude)
                
        except Exception as e:
            logger.error(f"Error getting prevailing wind direction: {e}")
            return {'direction': 270.0, 'speed': 5.0}  # Default westerly
    
    async def _estimate_prevailing_winds(self, latitude, longitude):
        """Advanced prevailing wind estimation using atmospheric circulation models"""
        try:
            # Get real-time atmospheric data from multiple sources
            wind_data = await self._get_advanced_wind_data(latitude, longitude)
            
            if wind_data:
                return wind_data
            
            # Advanced atmospheric circulation model
            # Based on NCEP/NCAR reanalysis climatology
            
            # Seasonal variation
            from datetime import datetime
            day_of_year = datetime.now().timetuple().tm_yday
            seasonal_factor = np.cos(2 * np.pi * (day_of_year - 172) / 365.25)
            
            # Latitude-dependent circulation patterns
            lat_rad = np.radians(latitude)
            
            # Trade winds (0-30°)
            if abs(latitude) < 30:
                # Hadley cell circulation
                base_direction = 45.0 if latitude > 0 else 315.0
                seasonal_shift = 15.0 * seasonal_factor
                direction = base_direction + seasonal_shift
                
                # Trade wind strength varies with ENSO
                enso_factor = await self._get_enso_index()
                base_speed = 6.0 + 2.0 * enso_factor
                speed = base_speed * (1.0 + 0.3 * np.cos(lat_rad))
            
            # Westerlies (30-60°)
            elif 30 <= abs(latitude) < 60:
                # Ferrel cell circulation with jet stream influence
                base_direction = 270.0  # Westerly
                
                # Jet stream meandering
                jet_stream_factor = await self._get_jet_stream_position(latitude, longitude)
                direction_shift = 30.0 * jet_stream_factor * seasonal_factor
                direction = base_direction + direction_shift
                
                # Westerly strength varies with NAO/AO
                nao_factor = await self._get_nao_index()
                base_speed = 8.0 + 3.0 * nao_factor
                speed = base_speed * (1.0 + 0.2 * np.sin(2 * lat_rad))
            
            # Polar easterlies (60-90°)
            else:
                # Polar cell circulation
                base_direction = 90.0  # Easterly
                
                # Arctic Oscillation effects
                ao_factor = await self._get_ao_index()
                direction_shift = 20.0 * ao_factor
                direction = base_direction + direction_shift
                
                speed = 4.0 + 2.0 * abs(ao_factor)
            
            # Topographic modifications
            topo_effects = await self._get_topographic_wind_effects(latitude, longitude)
            direction += topo_effects['direction_shift']
            speed *= topo_effects['speed_factor']
            
            # Coastal effects
            coastal_effects = await self._get_coastal_wind_effects(latitude, longitude)
            if coastal_effects:
                direction += coastal_effects['direction_shift']
                speed *= coastal_effects['speed_factor']
            
            return {
                'direction': direction % 360.0,
                'speed': max(0.5, speed),
                'confidence': 0.7,
                'source': 'advanced_circulation_model'
            }
            
        except Exception as e:
            logger.error(f"Error estimating prevailing winds: {e}")
            return {'direction': 270.0, 'speed': 5.0}
    
    async def _get_advanced_wind_data(self, latitude, longitude):
        """Get advanced wind data from meteorological APIs with multi-level atmospheric analysis"""
        try:
            from backend.core.real_data_connectors.copernicus_connector import CopernicusConnector
            from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
            from backend.core.real_data_connectors.base_connector import DataSourceConfig, DataSourceType
            import numpy as np
            from scipy.interpolate import RegularGridInterpolator
            from datetime import datetime, timedelta
            
            # Initialize atmospheric data connectors
            copernicus_config = DataSourceConfig(
                source_id="copernicus_atmosphere",
                name="Copernicus Atmosphere Monitoring Service",
                base_url="https://ads.atmosphere.copernicus.eu/api/v2",
                data_type=DataSourceType.SATELLITE
            )
            
            nasa_config = DataSourceConfig(
                source_id="nasa_merra2",
                name="NASA MERRA-2 Reanalysis",
                base_url="https://gmao.gsfc.nasa.gov/reanalysis/MERRA-2/data",
                data_type=DataSourceType.SATELLITE
            )
            
            # Multi-source wind data integration
            wind_data = await self._integrate_multi_source_wind_data(
                latitude, longitude, copernicus_config, nasa_config
            )
            
            if wind_data:
                # Apply advanced atmospheric physics corrections
                corrected_data = await self._apply_atmospheric_corrections(wind_data, latitude, longitude)
                return corrected_data
            
            # Fallback to high-resolution numerical weather prediction
            return await self._generate_nwp_wind_field(latitude, longitude)
            
        except Exception as e:
            logger.error(f"Error getting advanced wind data: {e}")
            return await self._generate_nwp_wind_field(latitude, longitude)
    
    async def _integrate_multi_source_wind_data(self, latitude, longitude, copernicus_config, nasa_config):
        """Integrate wind data from multiple atmospheric reanalysis sources"""
        try:
            import asyncio
            from concurrent.futures import ThreadPoolExecutor
            
            # Fetch data from multiple sources concurrently
            tasks = [
                self._fetch_era5_wind_data(latitude, longitude, copernicus_config),
                self._fetch_merra2_wind_data(latitude, longitude, nasa_config),
                self._fetch_gfs_wind_data(latitude, longitude)
            ]
            
            results = await asyncio.gather(*tasks, return_exceptions=True)
            
            # Filter successful results
            valid_results = [r for r in results if not isinstance(r, Exception) and r is not None]
            
            if not valid_results:
                return None
            
            # Weighted ensemble of wind data sources
            return await self._create_wind_ensemble(valid_results, latitude, longitude)
            
        except Exception as e:
            logger.error(f"Error integrating multi-source wind data: {e}")
            return None
    
    async def _fetch_gfs_wind_data(self, latitude, longitude):
        """Fetch high-resolution wind data from NOAA GFS with vertical profile analysis"""
        try:
            import aiohttp
            import numpy as np
            from datetime import datetime, timedelta
            
            # NOAA GFS 0.25-degree resolution data
            base_url = "https://nomads.ncep.noaa.gov/dods/gfs_0p25"
            current_time = datetime.utcnow()
            
            # Get latest available forecast cycle
            forecast_cycle = current_time.replace(hour=(current_time.hour // 6) * 6, minute=0, second=0, microsecond=0)
            
            # Construct GFS data URL
            gfs_url = f"{base_url}/gfs{forecast_cycle.strftime('%Y%m%d')}/gfs_0p25_{forecast_cycle.strftime('%Hz')}"
            
            # Define pressure levels for vertical wind profile
            pressure_levels = [1000, 925, 850, 700, 500, 300, 250, 200, 150, 100]  # hPa
            
            # Calculate grid indices for location
            lat_idx = int((90 - latitude) / 0.25)
            lon_idx = int((longitude + 180) / 0.25)
            
            wind_profile = {}
            
            async with aiohttp.ClientSession() as session:
                for level in pressure_levels:
                    try:
                        # Fetch U and V wind components
                        u_url = f"{gfs_url}.ascii?ugrdprs[0][{level}][{lat_idx}][{lon_idx}]"
                        v_url = f"{gfs_url}.ascii?vgrdprs[0][{level}][{lat_idx}][{lon_idx}]"
                        
                        async with session.get(u_url, timeout=10) as u_response:
                            if u_response.status == 200:
                                u_text = await u_response.text()
                                u_wind = float(u_text.split()[-1])
                        
                        async with session.get(v_url, timeout=10) as v_response:
                            if v_response.status == 200:
                                v_text = await v_response.text()
                                v_wind = float(v_text.split()[-1])
                        
                        # Calculate wind speed and direction
                        wind_speed = np.sqrt(u_wind**2 + v_wind**2)
                        wind_direction = np.degrees(np.arctan2(-u_wind, -v_wind)) % 360
                        
                        wind_profile[level] = {
                            'u_component': u_wind,
                            'v_component': v_wind,
                            'speed': wind_speed,
                            'direction': wind_direction,
                            'pressure_hpa': level
                        }
                        
                    except Exception as e:
                        logger.warning(f"Failed to fetch GFS data for {level} hPa: {e}")
                        continue
            
            if wind_profile:
                # Calculate atmospheric stability parameters
                stability_params = await self._calculate_atmospheric_stability(wind_profile)
                
                return {
                    'source': 'NOAA_GFS',
                    'resolution': '0.25_degree',
                    'forecast_time': forecast_cycle,
                    'vertical_profile': wind_profile,
                    'stability_parameters': stability_params,
                    'quality_score': 0.9
                }
            
            return None
            
        except Exception as e:
            logger.error(f"Error fetching GFS wind data: {e}")
            return None
    
