    async def _fetch_multiple_enso_indices(self):
        """Fetch ENSO indices from multiple authoritative sources"""
        try:
            import asyncio
            import aiohttp
            from datetime import datetime, timedelta
            
            # Define ENSO data sources
            enso_sources = {
                'noaa_oni': {
                    'url': 'https://origin.cpc.ncep.noaa.gov/products/analysis_monitoring/ensostuff/ONI_v5.php',
                    'parser': self._parse_noaa_oni_data
                },
                'jma_sst': {
                    'url': 'https://ds.data.jma.go.jp/tcc/tcc/products/elnino/index.html',
                    'parser': self._parse_jma_sst_data
                },
                'bom_soi': {
                    'url': 'http://www.bom.gov.au/climate/current/soi2.shtml',
                    'parser': self._parse_bom_soi_data
                },
                'real_time_sst': {
                    'url': 'https://www.ncei.noaa.gov/data/sea-surface-temperature-optimum-interpolation/v2.1/access/avhrr/',
                    'parser': self._parse_real_time_sst
                }
            }
            
            # Fetch data from all sources concurrently
            tasks = []
            for source_name, source_config in enso_sources.items():
                task = self._fetch_enso_source_data(source_name, source_config)
                tasks.append(task)
            
            results = await asyncio.gather(*tasks, return_exceptions=True)
            
            # Filter successful results
            valid_indices = {}
            for i, (source_name, result) in enumerate(zip(enso_sources.keys(), results)):
                if not isinstance(result, Exception) and result is not None:
                    valid_indices[source_name] = result
            
            return valid_indices if valid_indices else None
            
        except Exception as e:
            logger.error(f"Error fetching multiple ENSO indices: {e}")
            return None
    
