    async def _parse_noaa_oni_data(self, html_data):
        """Parse NOAA Oceanic Niño Index data"""
        try:
            import re
            from datetime import datetime
            
            # Extract ONI values from HTML table
            oni_pattern = r'<td[^>]*>(\d{4})</td>\s*<td[^>]*>([-+]?\d*\.?\d+)</td>'
            matches = re.findall(oni_pattern, html_data)
            
            if matches:
                # Get most recent ONI value
                latest_year, latest_oni = matches[-1]
                oni_value = float(latest_oni)
                
                # Calculate trend from recent values
                recent_values = [float(match[1]) for match in matches[-12:]]  # Last 12 months
                trend = np.polyfit(range(len(recent_values)), recent_values, 1)[0]
                
                return {
                    'value': oni_value,
                    'trend': trend,
                    'confidence': 0.95,
                    'source': 'NOAA_ONI',
                    'timestamp': datetime.now()
                }
            
            return None
            
        except Exception as e:
            logger.error(f"Error parsing NOAA ONI data: {e}")
            return None
    
    async def _parse_jma_sst_data(self, html_data):
        """Parse Japan Meteorological Agency SST anomaly data"""
        try:
            import re
            from datetime import datetime
            
            # Extract SST anomaly values
            sst_pattern = r'Niño\.3\.4\s*SST\s*anomaly[^:]*:\s*([-+]?\d*\.?\d+)'
            match = re.search(sst_pattern, html_data, re.IGNORECASE)
            
            if match:
                sst_anomaly = float(match.group(1))
                
                # Convert SST anomaly to ENSO index equivalent
                enso_index = sst_anomaly / 0.5  # Normalize to typical ENSO range
                
                return {
                    'value': enso_index,
                    'sst_anomaly': sst_anomaly,
                    'confidence': 0.90,
                    'source': 'JMA_SST',
                    'timestamp': datetime.now()
                }
            
            return None
            
        except Exception as e:
            logger.error(f"Error parsing JMA SST data: {e}")
            return None
    
    async def _parse_bom_soi_data(self, html_data):
        """Parse Australian Bureau of Meteorology Southern Oscillation Index"""
        try:
            import re
            from datetime import datetime
            
            # Extract SOI values
            soi_pattern = r'SOI\s*for\s*\w+\s*\d{4}\s*is\s*([-+]?\d*\.?\d+)'
            match = re.search(soi_pattern, html_data, re.IGNORECASE)
            
            if match:
                soi_value = float(match.group(1))
                
                # Convert SOI to ENSO index (inverse relationship)
                enso_index = -soi_value / 10.0  # SOI typically ranges -35 to +35
                
                return {
                    'value': enso_index,
                    'soi_value': soi_value,
                    'confidence': 0.85,
                    'source': 'BOM_SOI',
                    'timestamp': datetime.now()
                }
            
            return None
            
        except Exception as e:
            logger.error(f"Error parsing BOM SOI data: {e}")
            return None
    
