    async def _fetch_oisst_netcdf_data(self):
        """Fetch NOAA Optimum Interpolation SST NetCDF data"""
        try:
            import aiohttp
            import xarray as xr
            from datetime import datetime, timedelta
            
            # NOAA OISST data URL (daily, 0.25-degree resolution)
            base_url = "https://www.ncei.noaa.gov/data/sea-surface-temperature-optimum-interpolation/v2.1/access/avhrr"
            
            # Get yesterday's data (most recent complete day)
            yesterday = datetime.now() - timedelta(days=1)
            date_str = yesterday.strftime("%Y%m%d")
            
            oisst_url = f"{base_url}/{yesterday.year}/{date_str}/oisst-avhrr-v02r01.{date_str}.nc"
            
            async with aiohttp.ClientSession() as session:
                async with session.get(oisst_url, timeout=60) as response:
                    if response.status == 200:
                        # Read NetCDF data into memory
                        netcdf_data = await response.read()
                        
                        # Open with xarray
                        with xr.open_dataset(BytesIO(netcdf_data)) as ds:
                            # Extract SST data
                            sst = ds['sst'].squeeze()  # Remove time dimension if present
                            
                            # Convert from Kelvin to Celsius if needed
                            if sst.attrs.get('units') == 'kelvin':
                                sst = sst - 273.15
                            
                            # Create comprehensive SST dataset
                            sst_dataset = {
                                'sst': sst.values,
                                'lat': ds['lat'].values,
                                'lon': ds['lon'].values,
                                'time': yesterday,
                                'source': 'NOAA_OISST',
                                'resolution': '0.25_degree',
                                'quality_level': ds.attrs.get('quality_level', 4)
                            }
                            
                            return sst_dataset
            
            return None
            
        except Exception as e:
            logger.warning(f"Failed to fetch OISST data: {e}")
            return None
    
