    async def _fetch_real_time_nao_data(self):
        """Fetch NAO data from multiple meteorological centers"""
        try:
            import asyncio
            import aiohttp
            from datetime import datetime
            
            # NAO data sources
            nao_sources = {
                'noaa_cpc': {
                    'url': 'https://www.cpc.ncep.noaa.gov/products/precip/CWlink/pna/nao.shtml',
                    'parser': self._parse_noaa_nao_data
                },
                'ecmwf': {
                    'url': 'https://apps.ecmwf.int/datasets/data/interim-full-daily/levtype=sfc/',
                    'parser': self._parse_ecmwf_pressure_data
                },
                'uk_met_office': {
                    'url': 'https://www.metoffice.gov.uk/hadobs/hadslp2/data/download.html',
                    'parser': self._parse_hadslp_data
                }
            }
            
            # Fetch data concurrently
            tasks = []
            for source_name, source_config in nao_sources.items():
                task = self._fetch_nao_source_data(source_name, source_config)
                tasks.append(task)
            
            results = await asyncio.gather(*tasks, return_exceptions=True)
            
            # Filter successful results
            valid_data = {}
            for i, (source_name, result) in enumerate(zip(nao_sources.keys(), results)):
                if not isinstance(result, Exception) and result is not None:
                    valid_data[source_name] = result
            
            return valid_data if valid_data else None
            
        except Exception as e:
            logger.error(f"Error fetching real-time NAO data: {e}")
            return None
    
    async def _fetch_nao_source_data(self, source_name, source_config):
        """Fetch NAO data from a specific source"""
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(source_config['url'], timeout=20) as response:
                    if response.status == 200:
                        data = await response.text()
                        return await source_config['parser'](data)
            return None
            
        except Exception as e:
            logger.warning(f"Failed to fetch NAO data from {source_name}: {e}")
            return None
    
    async def _parse_noaa_nao_data(self, html_data):
        """Parse NOAA Climate Prediction Center NAO data"""
        try:
            import re
            from datetime import datetime
            
            # Extract NAO index values from HTML
            nao_pattern = r'(\d{4})\s+(\d{1,2})\s+([-+]?\d*\.?\d+)'
            matches = re.findall(nao_pattern, html_data)
            
            if matches:
                # Get most recent NAO value
                latest_year, latest_month, latest_nao = matches[-1]
                nao_value = float(latest_nao)
                
                # Calculate recent trend
                recent_values = [float(match[2]) for match in matches[-6:]]  # Last 6 months
                if len(recent_values) > 1:
                    trend = np.polyfit(range(len(recent_values)), recent_values, 1)[0]
                else:
                    trend = 0.0
                
                return {
                    'value': nao_value,
                    'trend': trend,
                    'confidence': 0.95,
                    'source': 'NOAA_CPC',
                    'timestamp': datetime.now(),
                    'data_period': f"{latest_year}-{latest_month:02d}"
                }
            
            return None
            
        except Exception as e:
            logger.error(f"Error parsing NOAA NAO data: {e}")
            return None
    
