    async def _fetch_real_time_ao_data(self):
        """Fetch AO data from meteorological centers with polar focus"""
        try:
            import asyncio
            import aiohttp
            from datetime import datetime
            
            # AO data sources
            ao_sources = {
                'noaa_cpc_ao': {
                    'url': 'https://www.cpc.ncep.noaa.gov/products/precip/CWlink/daily_ao_index/ao.shtml',
                    'parser': self._parse_noaa_ao_data
                },
                'ecmwf_polar': {
                    'url': 'https://apps.ecmwf.int/datasets/data/interim-full-daily/levtype=pl/',
                    'parser': self._parse_ecmwf_polar_data
                },
                'ncep_reanalysis': {
                    'url': 'https://psl.noaa.gov/data/gridded/data.ncep.reanalysis.html',
                    'parser': self._parse_ncep_geopotential_data
                }
            }
            
            # Fetch data concurrently
            tasks = []
            for source_name, source_config in ao_sources.items():
                task = self._fetch_ao_source_data(source_name, source_config)
                tasks.append(task)
            
            results = await asyncio.gather(*tasks, return_exceptions=True)
            
            # Filter successful results
            valid_data = {}
            for i, (source_name, result) in enumerate(zip(ao_sources.keys(), results)):
                if not isinstance(result, Exception) and result is not None:
                    valid_data[source_name] = result
            
            return valid_data if valid_data else None
            
        except Exception as e:
            logger.error(f"Error fetching real-time AO data: {e}")
            return None
    
    async def _fetch_ao_source_data(self, source_name, source_config):
        """Fetch AO data from a specific source"""
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(source_config['url'], timeout=25) as response:
                    if response.status == 200:
                        data = await response.text()
                        return await source_config['parser'](data)
            return None
            
        except Exception as e:
            logger.warning(f"Failed to fetch AO data from {source_name}: {e}")
            return None
    
    async def _parse_noaa_ao_data(self, html_data):
        """Parse NOAA Climate Prediction Center AO data"""
        try:
            import re
            from datetime import datetime
            
            # Extract daily AO index values
            ao_pattern = r'(\d{4})\s+(\d{1,2})\s+(\d{1,2})\s+([-+]?\d*\.?\d+)'
            matches = re.findall(ao_pattern, html_data)
            
            if matches:
                # Get most recent AO value
                latest_year, latest_month, latest_day, latest_ao = matches[-1]
                ao_value = float(latest_ao)
                
                # Calculate recent trend (last 10 days)
                recent_values = [float(match[3]) for match in matches[-10:]]
                if len(recent_values) > 1:
                    trend = np.polyfit(range(len(recent_values)), recent_values, 1)[0]
                else:
                    trend = 0.0
                
                # Calculate persistence (AO autocorrelation)
                if len(recent_values) > 5:
                    persistence = np.corrcoef(recent_values[:-1], recent_values[1:])[0, 1]
                else:
                    persistence = 0.5
                
                return {
                    'value': ao_value,
                    'trend': trend,
                    'persistence': persistence,
                    'confidence': 0.95,
                    'source': 'NOAA_CPC_AO',
                    'timestamp': datetime.now(),
                    'data_date': f"{latest_year}-{latest_month:02d}-{latest_day:02d}"
                }
            
            return None
            
        except Exception as e:
            logger.error(f"Error parsing NOAA AO data: {e}")
            return None
    
