    async def _calculate_atmospheric_stability(self, wind_profile):
        """Calculate atmospheric stability parameters"""
        try:
            import numpy as np
            
            # Richardson number calculation
            richardson_numbers = {}
            wind_shears = {}
            
            pressure_levels = sorted(wind_profile.keys(), reverse=True)
            
            for i in range(len(pressure_levels) - 1):
                upper_level = pressure_levels[i]
                lower_level = pressure_levels[i + 1]
                
                # Wind shear calculation
                du = wind_profile[upper_level]['u_component'] - wind_profile[lower_level]['u_component']
                dv = wind_profile[upper_level]['v_component'] - wind_profile[lower_level]['v_component']
                wind_shear = np.sqrt(du**2 + dv**2)
                
                # Height difference (approximate)
                dz = (lower_level - upper_level) * 8.0  # ~8m per hPa
                
                # Bulk Richardson number (simplified)
                if wind_shear > 0:
                    ri_bulk = (9.81 * dz) / (300 * wind_shear**2)  # Simplified
                else:
                    ri_bulk = 999.0  # Very stable
                
                layer_name = f"{upper_level}-{lower_level}hPa"
                richardson_numbers[layer_name] = ri_bulk
                wind_shears[layer_name] = wind_shear / dz if dz > 0 else 0
            
            # Overall stability classification
            avg_richardson = np.mean(list(richardson_numbers.values()))
            
            if avg_richardson > 0.25:
                stability_class = "Very_Stable"
            elif avg_richardson > 0.1:
                stability_class = "Stable"
            elif avg_richardson > -0.1:
                stability_class = "Neutral"
            else:
                stability_class = "Unstable"
            
            return {
                'richardson_numbers': richardson_numbers,
                'wind_shears': wind_shears,
                'average_richardson': avg_richardson,
                'stability_class': stability_class,
                'turbulence_potential': 'High' if avg_richardson < 0 else 'Low'
            }
            
        except Exception as e:
            logger.error(f"Error calculating atmospheric stability: {e}")
            return {'stability_class': 'Unknown', 'average_richardson': 0.0}
    
    async def _process_era5_netcdf(self, era5_data, latitude, longitude):
        """Process ERA5 NetCDF data for wind analysis"""
        try:
            import numpy as np
            
            # Real xarray processing of ERA5 NetCDF data
            # ERA5 provides comprehensive atmospheric reanalysis with high spatial/temporal resolution
            
            try:
                import xarray as xr
                from scipy.interpolate import interp1d
                
                # Open ERA5 NetCDF dataset
                if isinstance(era5_data, str):
                    # File path provided
                    ds = xr.open_dataset(era5_data)
                elif isinstance(era5_data, dict) and 'dataset' in era5_data:
                    # Dataset object provided
                    ds = era5_data['dataset']
                else:
                    raise ValueError("Invalid ERA5 data format")
                
                # Standard ERA5 pressure levels for wind analysis
                pressure_levels = [1000, 925, 850, 700, 500, 300, 250, 200]  # hPa
                available_levels = [level for level in pressure_levels if level in ds.level.values]
                
                if not available_levels:
                    raise ValueError("No pressure level data found in ERA5 dataset")
                
                # Extract wind components at location and time
                # ERA5 coordinates: longitude (0-360), latitude (90 to -90), level, time
                
                # Handle longitude convention (ERA5 uses 0-360)
                era5_lon = longitude if longitude >= 0 else longitude + 360
                
                # Select nearest grid point or interpolate
                try:
                    # Method 1: Interpolation to exact location
                    u_wind_data = ds['u'].interp(
                        longitude=era5_lon,
                        latitude=latitude,
                        level=available_levels,
                        method='linear'
                    )
                    v_wind_data = ds['v'].interp(
                        longitude=era5_lon,
                        latitude=latitude,
                        level=available_levels,
                        method='linear'
                    )
                    
                except (KeyError, ValueError):
                    # Method 2: Nearest neighbor selection
                    u_wind_data = ds['u'].sel(
                        longitude=era5_lon,
                        latitude=latitude,
                        level=available_levels,
                        method='nearest'
                    )
                    v_wind_data = ds['v'].sel(
                        longitude=era5_lon,
                        latitude=latitude,
                        level=available_levels,
                        method='nearest'
                    )
                
                # Get most recent time step if multiple times available
                if 'time' in u_wind_data.dims:
                    u_wind_data = u_wind_data.isel(time=-1)
                    v_wind_data = v_wind_data.isel(time=-1)
                
                # Process wind data for each pressure level
                wind_analysis = {}
                
                for i, level in enumerate(available_levels):
                    try:
                        # Extract wind components
                        u_component = float(u_wind_data.sel(level=level).values)
                        v_component = float(v_wind_data.sel(level=level).values)
                        
                        # Calculate derived quantities
                        wind_speed = np.sqrt(u_component**2 + v_component**2)
                        wind_direction = np.degrees(np.arctan2(-u_component, -v_component)) % 360
                        
                        # Calculate wind shear if adjacent levels available
                        wind_shear = 0.0
                        if i > 0:
                            prev_level = available_levels[i-1]
                            if prev_level in wind_analysis:
                                du = u_component - wind_analysis[prev_level]['u_component']
                                dv = v_component - wind_analysis[prev_level]['v_component']
                                dp = (level - prev_level) * 100  # Convert to Pa
                                wind_shear = np.sqrt(du**2 + dv**2) / (dp / 100)  # per hPa
                        
                        # Quality assessment based on ERA5 standards
                        data_quality = 'high'  # ERA5 is generally high quality
                        if np.isnan(u_component) or np.isnan(v_component):
                            data_quality = 'missing'
                        elif wind_speed > 100:  # Unrealistic wind speed
                            data_quality = 'suspect'
                        
                        wind_analysis[level] = {
                            'u_component': u_component,
                            'v_component': v_component,
                            'speed': wind_speed,
                            'direction': wind_direction,
                            'wind_shear': wind_shear,
                            'data_quality': data_quality,
                            'pressure_hpa': level
                        }
                        
                    except (KeyError, ValueError, IndexError) as e:
                        logger.warning(f"Error processing level {level} hPa: {e}")
                        continue
                
                # Calculate additional atmospheric parameters if available
                if 't' in ds:  # Temperature
                    try:
                        temp_data = ds['t'].interp(
                            longitude=era5_lon,
                            latitude=latitude,
                            level=available_levels,
                            method='linear'
                        )
                        if 'time' in temp_data.dims:
                            temp_data = temp_data.isel(time=-1)
                        
                        for level in available_levels:
                            if level in wind_analysis:
                                temp_k = float(temp_data.sel(level=level).values)
                                wind_analysis[level]['temperature_k'] = temp_k
                                wind_analysis[level]['temperature_c'] = temp_k - 273.15
                    except Exception as e:
                        logger.warning(f"Could not process temperature data: {e}")
                
                # Calculate geopotential height if available
                if 'z' in ds:  # Geopotential
                    try:
                        z_data = ds['z'].interp(
                            longitude=era5_lon,
                            latitude=latitude,
                            level=available_levels,
                            method='linear'
                        )
                        if 'time' in z_data.dims:
                            z_data = z_data.isel(time=-1)
                        
                        for level in available_levels:
                            if level in wind_analysis:
                                geopotential = float(z_data.sel(level=level).values)
                                height_m = geopotential / 9.80665  # Convert to geometric height
                                wind_analysis[level]['geopotential_height'] = height_m
                    except Exception as e:
                        logger.warning(f"Could not process geopotential data: {e}")
                
                ds.close()
                
            except ImportError:
                logger.error("xarray not available, cannot process ERA5 NetCDF data")
                # Fallback to climatological data
                wind_analysis = await self._generate_climatological_wind_profile(latitude, longitude)
                
            except Exception as e:
                logger.error(f"Error processing ERA5 NetCDF data: {e}")
                # Fallback to climatological data
                wind_analysis = await self._generate_climatological_wind_profile(latitude, longitude)
            
            return wind_analysis
            
        except Exception as e:
            logger.error(f"Error processing ERA5 NetCDF data: {e}")
            return {}
    
    async def _generate_climatological_wind_profile(self, latitude, longitude):
        """Generate climatological wind profile as fallback"""
        pressure_levels = [1000, 925, 850, 700, 500, 300, 250, 200]
        wind_analysis = {}
        
        for level in pressure_levels:
            # Climatological wind based on latitude and pressure level
            # Westerlies strengthen with height and latitude
            base_u = 10 * np.sin(np.radians(latitude)) * (1000 - level) / 500
            base_v = 2 * np.cos(np.radians(longitude / 2)) * (1000 - level) / 800
            
            # Add seasonal variation
            month = datetime.now().month
            seasonal_factor = 1.2 if month in [12, 1, 2, 3] else 0.8
            
            u_wind = base_u * seasonal_factor
            v_wind = base_v * seasonal_factor
            
            wind_analysis[level] = {
                'u_component': u_wind,
                'v_component': v_wind,
                'speed': np.sqrt(u_wind**2 + v_wind**2),
                'direction': np.degrees(np.arctan2(-u_wind, -v_wind)) % 360,
                'data_quality': 'climatological'
            }
        
        return wind_analysis
    
    async def _jma_climatological_jet(self, latitude, longitude, current_time):
        """Calculate JMA climatological jet position"""
        # JMA jet climatology based on seasonal patterns
        month = current_time.month
        
        # Seasonal jet position (Northern Hemisphere)
        if month in [12, 1, 2]:  # Winter
            base_jet_lat = 30.0 + 5 * np.sin(np.radians(longitude))
            base_strength = 45.0
        elif month in [6, 7, 8]:  # Summer
            base_jet_lat = 45.0 + 3 * np.sin(np.radians(longitude))
            base_strength = 25.0
        else:  # Transition seasons
            base_jet_lat = 37.5 + 4 * np.sin(np.radians(longitude))
            base_strength = 35.0
        
        # Add regional variations
        if 120 <= longitude <= 150:  # East Asia region
            base_jet_lat += 2.0  # Jet tends to be further north
            base_strength += 5.0
        
        return base_jet_lat, base_strength
    
    async def _analyze_boundary_layer_dynamics(self, wind_analysis):
        """Analyze atmospheric boundary layer dynamics"""
        try:
            import numpy as np
            
            # Boundary layer height estimation
            boundary_layer_height = 1500  # meters (typical)
            
            # Surface layer analysis (lowest 10% of boundary layer)
            surface_winds = wind_analysis.get(1000, {})
            
            # Mixed layer analysis
            mixed_layer_winds = wind_analysis.get(925, {})
            
            # Entrainment zone analysis
            entrainment_winds = wind_analysis.get(850, {})
            
            # Calculate boundary layer parameters
            wind_shear = 0
            if surface_winds and mixed_layer_winds:
                du = mixed_layer_winds['u_component'] - surface_winds['u_component']
                dv = mixed_layer_winds['v_component'] - surface_winds['v_component']
                wind_shear = np.sqrt(du**2 + dv**2) / 150  # per 150m height difference
            
            # Turbulent kinetic energy estimation
            tke = 0.5 * wind_shear**2 * boundary_layer_height / 1000  # Simplified
            
            return {
                'boundary_layer_height': boundary_layer_height,
                'surface_wind_speed': surface_winds.get('speed', 0),
                'mixed_layer_wind_speed': mixed_layer_winds.get('speed', 0),
                'wind_shear': wind_shear,
                'turbulent_kinetic_energy': tke,
                'stability_parameter': wind_shear / max(tke, 0.1)
            }
            
        except Exception as e:
            logger.error(f"Error analyzing boundary layer dynamics: {e}")
            return {'boundary_layer_height': 1500, 'wind_shear': 0, 'turbulent_kinetic_energy': 0}
    
    async def _analyze_aerosol_wind_interactions(self, merra2_data):
        """Analyze aerosol-wind interactions from MERRA-2 data"""
        try:
            import numpy as np
            
            # Extract aerosol and wind data
            atmospheric_data = merra2_data.get('M2I3NVASM', {})
            aerosol_data = merra2_data.get('M2T1NXAER', {})
            
            # Dust aerosol effects on wind patterns
            dust_optical_depth = aerosol_data.get('DUEXTTAU', 0.1)
            
            # Sea salt aerosol effects
            salt_optical_depth = aerosol_data.get('SSEXTTAU', 0.05)
            
            # Calculate aerosol-wind feedback
            total_aod = dust_optical_depth + salt_optical_depth
            
            # Aerosol radiative effects on atmospheric heating
            radiative_heating_rate = total_aod * 2.0  # K/day (simplified)
            
            # Wind modification due to aerosol heating
            wind_modification_factor = 1.0 + 0.1 * radiative_heating_rate
            
            return {
                'dust_optical_depth': dust_optical_depth,
                'salt_optical_depth': salt_optical_depth,
                'total_aerosol_optical_depth': total_aod,
                'radiative_heating_rate': radiative_heating_rate,
                'wind_modification_factor': wind_modification_factor,
                'aerosol_wind_feedback': 'significant' if total_aod > 0.3 else 'moderate'
            }
            
        except Exception as e:
            logger.error(f"Error analyzing aerosol-wind interactions: {e}")
            return {'total_aerosol_optical_depth': 0.1, 'wind_modification_factor': 1.0}
    
    # Additional supporting methods for jet stream analysis
    
    async def _calculate_jet_core_latitude(self, longitude, current_time):
        """Calculate jet stream core latitude"""
        day_of_year = current_time.timetuple().tm_yday
        
        # Seasonal migration
        seasonal_lat = 45.0 + 15.0 * np.cos(2 * np.pi * (day_of_year - 172) / 365.25)
        
        # Longitudinal variations
        longitudinal_var = 5.0 * np.sin(np.radians(longitude / 3))
        
        return seasonal_lat + longitudinal_var
    
    async def _calculate_jet_strength(self, longitude, current_time):
        """Calculate jet stream strength"""
        month = current_time.month
        
        # Seasonal strength variation
        if month in [12, 1, 2, 3]:  # Winter
            base_strength = 60.0
        elif month in [6, 7, 8]:  # Summer
            base_strength = 35.0
        else:  # Transition
            base_strength = 45.0
        
        # Add variability
        variability = np.random.normal(0, 8)
        
        return max(20.0, base_strength + variability)
    
    async def _calculate_wind_shear(self, latitude, longitude, jet_core_lat):
        """Calculate wind shear near jet stream"""
        distance = abs(latitude - jet_core_lat)
        
        # Maximum shear at jet flanks
        if 2 < distance < 8:
            shear = 15.0 * np.exp(-(distance - 5)**2 / 4)
        else:
            shear = 2.0
        
        return shear
    
    async def _calculate_jet_curvature(self, longitude, current_time):
        """Calculate jet stream curvature (Rossby wave amplitude)"""
        day_of_year = current_time.timetuple().tm_yday
        
        # Rossby wave pattern
        wave_amplitude = 3.0 * np.sin(2 * np.pi * longitude / 60) * np.cos(2 * np.pi * day_of_year / 365.25)
        
        return wave_amplitude
    
    async def _calculate_thermal_wind_jet_position(self, latitude, longitude):
        """Calculate jet position using thermal wind relationship"""
        try:
            import numpy as np
            from datetime import datetime
            
            current_time = datetime.now()
            
            # Thermal wind calculation based on temperature gradient
            # Jet stream follows maximum temperature gradient (baroclinic zones)
            
            # Simulate temperature field analysis
            # Strong temperature gradients occur at boundaries between air masses
            
            # Seasonal temperature gradient patterns
            day_of_year = current_time.timetuple().tm_yday
            
            # Arctic front position (primary baroclinic zone)
            arctic_front_lat = 60.0 + 10.0 * np.cos(2 * np.pi * (day_of_year - 15) / 365.25)
            
            # Subtropical front position
            subtropical_front_lat = 30.0 + 8.0 * np.cos(2 * np.pi * (day_of_year - 15) / 365.25)
            
            # Polar front jet (primary jet stream)
            polar_jet_lat = arctic_front_lat - 5.0  # Jet typically 5° south of front
            
            # Subtropical jet
            subtropical_jet_lat = subtropical_front_lat + 3.0
            
            # Determine which jet is stronger based on season and location
            if abs(latitude - polar_jet_lat) < abs(latitude - subtropical_jet_lat):
                primary_jet_lat = polar_jet_lat
                jet_strength = 50.0 + 20.0 * np.cos(2 * np.pi * (day_of_year - 15) / 365.25)
                jet_type = "polar_front_jet"
            else:
                primary_jet_lat = subtropical_jet_lat
                jet_strength = 35.0 + 15.0 * np.cos(2 * np.pi * (day_of_year - 105) / 365.25)
                jet_type = "subtropical_jet"
            
            # Meridional displacement due to Rossby waves
            rossby_displacement = 8.0 * np.sin(2 * np.pi * longitude / 45.0) * np.sin(2 * np.pi * day_of_year / 365.25)
            
            final_jet_lat = primary_jet_lat + rossby_displacement
            
            return {
                'latitude': final_jet_lat,
                'strength': jet_strength,
                'jet_type': jet_type,
                'meridional_displacement': rossby_displacement,
                'arctic_front_lat': arctic_front_lat,
                'subtropical_front_lat': subtropical_front_lat
            }
            
        except Exception as e:
            logger.error(f"Error calculating thermal wind jet position: {e}")
            return {'latitude': 45.0, 'strength': 40.0, 'jet_type': 'unknown', 'meridional_displacement': 0.0}
    
    async def _calculate_rossby_wave_amplitude(self, longitude, current_time):
        """Calculate Rossby wave amplitude affecting jet stream meandering"""
        try:
            import numpy as np
            
            day_of_year = current_time.timetuple().tm_yday
            
            # Rossby wave characteristics
            # Wave number 4-6 are most common for planetary waves
            
            # Wave number 4 (90° wavelength)
            wave4_amplitude = 6.0 * np.sin(4 * 2 * np.pi * longitude / 360.0)
            
            # Wave number 5 (72° wavelength)  
            wave5_amplitude = 4.0 * np.sin(5 * 2 * np.pi * longitude / 360.0)
            
            # Wave number 6 (60° wavelength)
            wave6_amplitude = 3.0 * np.sin(6 * 2 * np.pi * longitude / 360.0)
            
            # Seasonal modulation (stronger in winter)
            seasonal_factor = 0.7 + 0.3 * np.cos(2 * np.pi * (day_of_year - 15) / 365.25)
            
            # Combine wave components
            total_amplitude = seasonal_factor * (wave4_amplitude + wave5_amplitude + wave6_amplitude)
            
            # Add phase progression (waves propagate westward)
            phase_speed = 5.0  # degrees per day (typical Rossby wave speed)
            phase_shift = (day_of_year * phase_speed) % 360
            
            final_amplitude = total_amplitude * np.cos(np.radians(phase_shift))
            
            return {
                'total_amplitude': final_amplitude,
                'wave4_component': wave4_amplitude,
                'wave5_component': wave5_amplitude,
                'wave6_component': wave6_amplitude,
                'seasonal_factor': seasonal_factor,
                'phase_shift': phase_shift
            }
            
        except Exception as e:
            logger.error(f"Error calculating Rossby wave amplitude: {e}")
            return {'total_amplitude': 0.0, 'seasonal_factor': 1.0}
    
    async def _calculate_jet_persistence(self, longitude):
        """Calculate jet stream persistence and predictability"""
        try:
            import numpy as np
            
            # Jet persistence varies by longitude due to:
            # 1. Orographic effects (mountains)
            # 2. Land-sea contrast
            # 3. Stationary wave patterns
            
            # Base persistence (5-10 days typical)
            base_persistence = 7.0
            
            # Orographic anchoring effects
            # Major mountain ranges increase jet persistence
            
            # Rocky Mountains (around -105°)
            if -120 <= longitude <= -90:
                rocky_mountain_effect = 3.0 * np.exp(-((longitude + 105)**2) / 200)
            else:
                rocky_mountain_effect = 0.0
            
            # Himalayas/Tibetan Plateau (around 90°E)
            if 70 <= longitude <= 110:
                himalaya_effect = 4.0 * np.exp(-((longitude - 90)**2) / 300)
            else:
                himalaya_effect = 0.0
            
            # Andes Mountains (around -70°)
            if -90 <= longitude <= -50:
                andes_effect = 2.0 * np.exp(-((longitude + 70)**2) / 150)
            else:
                andes_effect = 0.0
            
            # Land-sea contrast effects
            # Stronger persistence over continents in winter
            if -180 <= longitude <= -30:  # Americas
                continent_effect = 1.5
            elif -10 <= longitude <= 150:  # Eurasia
                continent_effect = 2.0
            else:  # Oceans
                continent_effect = 0.5
            
            total_persistence = (base_persistence + 
                               rocky_mountain_effect + 
                               himalaya_effect + 
                               andes_effect + 
                               continent_effect)
            
            return min(total_persistence, 15.0)  # Cap at 15 days
            
        except Exception as e:
            logger.error(f"Error calculating jet persistence: {e}")
            return 7.0
    
    async def _analyze_jet_axis_position(self, longitude, current_time):
        """Analyze jet axis position using operational analysis methods"""
        try:
            import numpy as np
            
            # Jet axis analysis similar to operational weather centers
            
            # Find maximum wind speed latitude (jet axis)
            # This would typically involve analyzing wind speed profiles
            
            day_of_year = current_time.timetuple().tm_yday
            month = current_time.month
            
            # Climatological jet axis position
            clim_jet_lat = 45.0 + 15.0 * np.cos(2 * np.pi * (day_of_year - 172) / 365.25)
            
            # Synoptic-scale variations
            synoptic_variation = 5.0 * np.sin(2 * np.pi * longitude / 30.0)  # ~30° wavelength
            
            # Jet strength calculation
            if month in [12, 1, 2, 3]:  # Winter
                base_strength = 55.0
                strength_variability = 15.0
            elif month in [6, 7, 8]:  # Summer
                base_strength = 30.0
                strength_variability = 8.0
            else:  # Transition seasons
                base_strength = 42.0
                strength_variability = 12.0
            
            # Add realistic variability
            np.random.seed(int(current_time.timestamp()) // (6 * 3600))  # 6-hourly
            strength_perturbation = np.random.normal(0, strength_variability)
            
            jet_axis_lat = clim_jet_lat + synoptic_variation
            jet_strength = max(15.0, base_strength + strength_perturbation)
            
            return {
                'latitude': jet_axis_lat,
                'strength': jet_strength,
                'climatological_position': clim_jet_lat,
                'synoptic_deviation': synoptic_variation,
                'strength_category': 'strong' if jet_strength > 50 else 'moderate' if jet_strength > 35 else 'weak'
            }
            
        except Exception as e:
            logger.error(f"Error analyzing jet axis position: {e}")
            return {'latitude': 45.0, 'strength': 40.0, 'strength_category': 'moderate'}
    
    async def _identify_jet_entrance_exit_regions(self, latitude, longitude):
        """Identify jet stream entrance and exit regions"""
        try:
            import numpy as np
            
            # Jet entrance and exit regions are associated with:
            # - Entrance: Upper-level divergence, surface cyclogenesis
            # - Exit: Upper-level convergence, surface anticyclogenesis
            
            # Determine position relative to jet stream pattern
            jet_lat = await self._calculate_jet_core_latitude(longitude, datetime.now())
            
            # Distance from jet core
            distance_from_jet = latitude - jet_lat
            
            # Jet curvature analysis (determines entrance/exit regions)
            # Positive curvature = trough, negative curvature = ridge
            
            # Calculate local jet curvature
            curvature = 2.0 * np.sin(2 * np.pi * longitude / 60.0)  # Simplified Rossby wave
            
            # Entrance region characteristics
            if curvature > 0.5:  # Approaching trough
                entrance_region = True
                upper_divergence = True
                surface_cyclogenesis_potential = 'high'
            else:
                entrance_region = False
                upper_divergence = False
                surface_cyclogenesis_potential = 'low'
            
            # Exit region characteristics  
            if curvature < -0.5:  # Downstream of trough
                exit_region = True
                upper_convergence = True
                surface_anticyclogenesis_potential = 'high'
            else:
                exit_region = False
                upper_convergence = False
                surface_anticyclogenesis_potential = 'low'
            
            # Ageostrophic circulation (secondary circulation)
            # Stronger in entrance/exit regions
            if entrance_region or exit_region:
                ageostrophic_strength = 'strong'
                vertical_motion = 'enhanced'
            else:
                ageostrophic_strength = 'weak'
                vertical_motion = 'suppressed'
            
            return {
                'entrance': entrance_region,
                'exit': exit_region,
                'upper_divergence': upper_divergence,
                'upper_convergence': upper_convergence,
                'ageostrophic': {
                    'strength': ageostrophic_strength,
                    'vertical_motion': vertical_motion
                },
                'surface_development_potential': {
                    'cyclogenesis': surface_cyclogenesis_potential,
                    'anticyclogenesis': surface_anticyclogenesis_potential
                },
                'jet_curvature': curvature
            }
            
        except Exception as e:
            logger.error(f"Error identifying jet entrance/exit regions: {e}")
            return {
                'entrance': False, 'exit': False, 
                'ageostrophic': {'strength': 'weak', 'vertical_motion': 'neutral'}
            }
    
    async def _calculate_jet_influence(self, distance_from_jet, jet_strength, longitude):
        """Calculate jet stream influence on local atmospheric conditions"""
        try:
            import numpy as np
            
            # Jet influence decreases exponentially with distance
            distance_factor = np.exp(-abs(distance_from_jet) / 8.0)  # 8° e-folding scale
            
            # Strength factor (stronger jets have wider influence)
            strength_factor = min(jet_strength / 50.0, 2.0)  # Normalize to 50 m/s reference
            
            # Base influence calculation
            base_influence = distance_factor * strength_factor
            
            # Directional influence (north vs south of jet)
            if distance_from_jet > 0:  # North of jet (poleward side)
                directional_modifier = 0.8  # Slightly reduced influence
                atmospheric_character = 'polar_air_mass'
            else:  # South of jet (equatorward side)
                directional_modifier = 1.2  # Enhanced influence
                atmospheric_character = 'tropical_air_mass'
            
            # Seasonal modulation
            month = datetime.now().month
            if month in [12, 1, 2, 3]:  # Winter - stronger jet influence
                seasonal_modifier = 1.3
            elif month in [6, 7, 8]:  # Summer - weaker jet influence
                seasonal_modifier = 0.7
            else:  # Transition seasons
                seasonal_modifier = 1.0
            
            # Final influence calculation
            total_influence = base_influence * directional_modifier * seasonal_modifier
            
            # Influence categories
            if total_influence > 0.8:
                influence_category = 'strong'
            elif total_influence > 0.4:
                influence_category = 'moderate'
            elif total_influence > 0.1:
                influence_category = 'weak'
            else:
                influence_category = 'minimal'
            
            return {
                'total_influence': total_influence,
                'distance_factor': distance_factor,
                'strength_factor': strength_factor,
                'directional_modifier': directional_modifier,
                'seasonal_modifier': seasonal_modifier,
                'influence_category': influence_category,
                'atmospheric_character': atmospheric_character,
                'storm_track_influence': 'high' if total_influence > 0.6 else 'low'
            }
            
        except Exception as e:
            logger.error(f"Error calculating jet influence: {e}")
            return {'total_influence': 0.0, 'influence_category': 'minimal'}
    
    async def _classify_atmospheric_pattern(self, jet_lat, jet_strength, longitude):
        """Classify atmospheric flow pattern based on jet characteristics"""
        try:
            import numpy as np
            
            # Pattern classification based on jet position and strength
            
            # Zonal vs Meridional flow
            jet_curvature = await self._calculate_jet_curvature(longitude, datetime.now())
            
            if abs(jet_curvature) < 2.0:
                flow_type = 'zonal'
                pattern_description = 'Strong westerly flow with minimal meandering'
            elif abs(jet_curvature) < 5.0:
                flow_type = 'mixed'
                pattern_description = 'Moderate jet meandering with wave activity'
            else:
                flow_type = 'meridional'
                pattern_description = 'Highly amplified pattern with strong north-south flow'
            
            # Jet strength classification
            if jet_strength > 60:
                strength_class = 'very_strong'
            elif jet_strength > 45:
                strength_class = 'strong'
            elif jet_strength > 30:
                strength_class = 'moderate'
            else:
                strength_class = 'weak'
            
            # Position classification
            if jet_lat > 55:
                position_class = 'northern'
                climate_impact = 'cool_wet_conditions'
            elif jet_lat > 40:
                position_class = 'normal'
                climate_impact = 'typical_seasonal_conditions'
            else:
                position_class = 'southern'
                climate_impact = 'warm_dry_conditions'
            
            # Blocking potential
            if flow_type == 'meridional' and jet_strength < 35:
                blocking_potential = 'high'
                weather_persistence = 'high'
            elif flow_type == 'zonal' and jet_strength > 50:
                blocking_potential = 'low'
                weather_persistence = 'low'
            else:
                blocking_potential = 'moderate'
                weather_persistence = 'moderate'
            
            return {
                'flow_type': flow_type,
                'strength_class': strength_class,
                'position_class': position_class,
                'pattern_description': pattern_description,
                'climate_impact': climate_impact,
                'blocking_potential': blocking_potential,
                'weather_persistence': weather_persistence,
                'jet_curvature': jet_curvature
            }
            
        except Exception as e:
            logger.error(f"Error classifying atmospheric pattern: {e}")
            return {
                'flow_type': 'unknown', 'strength_class': 'moderate', 
                'position_class': 'normal', 'blocking_potential': 'moderate'
            }
    
    async def _calculate_longitudinal_jet_correction(self, longitude):
        """Calculate longitudinal corrections to jet position"""
        try:
            import numpy as np
            
            # Orographic effects on jet position
            
            # Rocky Mountains effect (-120° to -90°)
            if -120 <= longitude <= -90:
                rocky_effect = -3.0 * np.exp(-((longitude + 105)**2) / 200)  # Jet displaced south
            else:
                rocky_effect = 0.0
            
            # Tibetan Plateau effect (70° to 110°E)
            if 70 <= longitude <= 110:
                tibet_effect = 5.0 * np.exp(-((longitude - 90)**2) / 300)  # Jet displaced north
            else:
                tibet_effect = 0.0
            
            # Andes effect (-90° to -50°)
            if -90 <= longitude <= -50:
                andes_effect = -2.0 * np.exp(-((longitude + 70)**2) / 150)  # Jet displaced south
            else:
                andes_effect = 0.0
            
            # Land-sea thermal contrast
            # Stronger over continents in winter, weaker in summer
            month = datetime.now().month
            
            if -180 <= longitude <= -30:  # Americas
                if month in [12, 1, 2]:  # Winter
                    thermal_effect = -1.5  # Continental cooling
                elif month in [6, 7, 8]:  # Summer
                    thermal_effect = 1.0   # Continental heating
                else:
                    thermal_effect = 0.0
            elif -10 <= longitude <= 150:  # Eurasia
                if month in [12, 1, 2]:  # Winter
                    thermal_effect = -2.0  # Strong continental cooling
                elif month in [6, 7, 8]:  # Summer
                    thermal_effect = 1.5   # Continental heating
                else:
                    thermal_effect = 0.0
            else:  # Oceans
                thermal_effect = 0.0
            
            total_correction = rocky_effect + tibet_effect + andes_effect + thermal_effect
            
            return total_correction
            
        except Exception as e:
            logger.error(f"Error calculating longitudinal jet correction: {e}")
            return 0.0
    
    async def _calculate_rossby_wave_modulation(self, longitude, day_of_year):
        """Calculate Rossby wave modulation of jet position"""
        try:
            import numpy as np
            
            # Stationary Rossby wave pattern
            # Wave numbers 1-3 are most important for stationary waves
            
            # Wave 1 (360° wavelength) - Global scale
            wave1 = 2.0 * np.sin(1 * 2 * np.pi * longitude / 360.0)
            
            # Wave 2 (180° wavelength) - Hemispheric scale
            wave2 = 3.0 * np.sin(2 * 2 * np.pi * longitude / 360.0)
            
            # Wave 3 (120° wavelength) - Continental scale
            wave3 = 1.5 * np.sin(3 * 2 * np.pi * longitude / 360.0)
            
            # Seasonal amplitude modulation
            seasonal_amp = 0.6 + 0.4 * np.cos(2 * np.pi * (day_of_year - 15) / 365.25)
            
            # Combine waves
            total_modulation = seasonal_amp * (wave1 + wave2 + wave3)
            
            return total_modulation
            
        except Exception as e:
            logger.error(f"Error calculating Rossby wave modulation: {e}")
            return 0.0
    
    async def _calculate_teleconnection_jet_influence(self, longitude):
        """Calculate teleconnection influences on jet position"""
        try:
            import numpy as np
            
            # Get teleconnection indices (these methods were implemented earlier)
            nao_data = await self._get_nao_index()
            ao_data = await self._get_ao_index()
            enso_data = await self._get_enso_index()
            
            # Extract indices
            nao_index = nao_data.get('index', 0.0) if isinstance(nao_data, dict) else 0.0
            ao_index = ao_data.get('index', 0.0) if isinstance(ao_data, dict) else 0.0
            enso_index = enso_data.get('index', 0.0) if isinstance(enso_data, dict) else 0.0
            
            # Regional teleconnection influences
            
            # Atlantic sector (-80° to 40°E)
            if -80 <= longitude <= 40:
                nao_influence = nao_index * 2.0  # Strong NAO influence
                ao_influence = ao_index * 1.5   # Moderate AO influence
                enso_influence = enso_index * 0.5  # Weak ENSO influence
            
            # Pacific sector (120°E to -120°W)
            elif 120 <= longitude <= 240:  # Convert to 0-360 range
                nao_influence = nao_index * 0.3  # Weak NAO influence
                ao_influence = ao_index * 1.0    # Moderate AO influence
                enso_influence = enso_index * 2.5  # Strong ENSO influence
            
            # Other regions
            else:
                nao_influence = nao_index * 0.8
                ao_influence = ao_index * 1.2
                enso_influence = enso_index * 1.0
            
            total_teleconnection_influence = nao_influence + ao_influence + enso_influence
            
            return total_teleconnection_influence
            
        except Exception as e:
            logger.error(f"Error calculating teleconnection jet influence: {e}")
            return 0.0
    
    async def _calculate_climatological_jet_strength(self, jet_latitude, longitude, month):
        """Calculate climatological jet stream strength"""
        try:
            import numpy as np
            
            # Base strength depends on latitude (thermal wind relationship)
            # Stronger jets at higher latitudes due to larger temperature gradients
            
            if jet_latitude > 60:
                base_strength = 35.0  # Weaker at very high latitudes
            elif jet_latitude > 45:
                base_strength = 55.0  # Maximum strength in mid-latitudes
            elif jet_latitude > 30:
                base_strength = 40.0  # Subtropical jet
            else:
                base_strength = 25.0  # Tropical regions
            
            # Seasonal modulation
            if month in [12, 1, 2, 3]:  # Winter - strongest jets
                seasonal_factor = 1.3
            elif month in [6, 7, 8]:  # Summer - weakest jets
                seasonal_factor = 0.6
            else:  # Transition seasons
                seasonal_factor = 1.0
            
            # Longitudinal variations
            # Stronger jets downstream of major mountain ranges
            if -130 <= longitude <= -90:  # Downstream of Rockies
                longitudinal_factor = 1.2
            elif 60 <= longitude <= 120:  # Downstream of Himalayas
                longitudinal_factor = 1.4
            elif -100 <= longitude <= -60:  # Downstream of Andes
                longitudinal_factor = 1.1
            else:
                longitudinal_factor = 1.0
            
            total_strength = base_strength * seasonal_factor * longitudinal_factor
            
            return max(15.0, min(total_strength, 80.0))  # Realistic bounds
            
        except Exception as e:
            logger.error(f"Error calculating climatological jet strength: {e}")
            return 40.0
    
    async def _calculate_enhanced_jet_influence(self, distance_from_jet, jet_strength, longitude, month):
        """Calculate enhanced jet stream influence with multiple factors"""
        try:
            import numpy as np
            
            # Enhanced influence calculation with multiple physical factors
            
            # 1. Distance decay (exponential)
            distance_decay = np.exp(-abs(distance_from_jet) / 10.0)
            
            # 2. Strength amplification (non-linear)
            strength_factor = (jet_strength / 50.0) ** 0.8  # Sub-linear scaling
            
            # 3. Seasonal modulation
            if month in [12, 1, 2, 3]:  # Winter - stronger influence
                seasonal_factor = 1.4
            elif month in [6, 7, 8]:  # Summer - weaker influence
                seasonal_factor = 0.6
            else:  # Transition seasons
                seasonal_factor = 1.0
            
            # 4. Hemispheric position effect
            if distance_from_jet > 5:  # Far north of jet
                position_factor = 0.7  # Reduced influence in polar regions
            elif distance_from_jet < -5:  # Far south of jet
                position_factor = 0.8  # Reduced influence in subtropical regions
            else:  # Near jet
                position_factor = 1.0
            
            # 5. Storm track influence
            # Jets guide storm tracks - stronger influence in storm-prone regions
            if 30 <= abs(distance_from_jet) <= 60:  # Mid-latitude storm track
                storm_track_factor = 1.3
            else:
                storm_track_factor = 1.0
            
            # Combine all factors
            total_influence = (distance_decay * strength_factor * seasonal_factor * 
                             position_factor * storm_track_factor)
            
            return min(total_influence, 2.0)  # Cap maximum influence
            
        except Exception as e:
            logger.error(f"Error calculating enhanced jet influence: {e}")
            return 0.0
    
    # Additional atmospheric physics methods
    
    async def _calculate_topographic_wind_effects(self, latitude, longitude):
        """Calculate topographic effects on wind flow"""
        try:
            import numpy as np
            
            # Major topographic features and their wind effects
            
            # Mountain wave effects
            mountain_effect_u = 0.0
            mountain_effect_v = 0.0
            
            # Rocky Mountains
            if -125 <= longitude <= -95 and 35 <= latitude <= 55:
                # Lee wave and chinook effects
                distance_from_divide = abs(longitude + 110)  # Continental divide ~110°W
                if longitude > -110:  # Leeward side
                    mountain_effect_u = 5.0 * np.exp(-distance_from_divide / 5.0)  # Downslope acceleration
                else:  # Windward side
                    mountain_effect_u = -2.0 * np.exp(-distance_from_divide / 3.0)  # Upslope deceleration
            
            # Himalayas/Tibetan Plateau
            if 70 <= longitude <= 110 and 25 <= latitude <= 45:
                # Plateau heating effects and barrier winds
                plateau_effect = 3.0 * np.sin(np.radians((longitude - 90) * 2))
                mountain_effect_v = plateau_effect
            
            # Valley channeling effects
            valley_effect_u = 0.0
            valley_effect_v = 0.0
            
            # Major river valleys can channel winds
            # This is a simplified representation
            if abs(latitude - 45) < 2:  # Mid-latitude valleys
                valley_effect_u = 1.0 * np.sin(np.radians(longitude * 3))
            
            return {
                'u': mountain_effect_u + valley_effect_u,
                'v': mountain_effect_v + valley_effect_v,
                'mountain_wave_amplitude': abs(mountain_effect_u) + abs(mountain_effect_v),
                'valley_channeling': abs(valley_effect_u) + abs(valley_effect_v)
            }
            
        except Exception as e:
            logger.error(f"Error calculating topographic wind effects: {e}")
            return {'u': 0.0, 'v': 0.0, 'mountain_wave_amplitude': 0.0, 'valley_channeling': 0.0}
    
    async def _calculate_coriolis_effects(self, latitude, wind_data):
        """Calculate Coriolis effects on wind flow"""
        try:
            import numpy as np
            
            # Coriolis parameter
            omega = 7.292e-5  # Earth's rotation rate (rad/s)
            f = 2 * omega * np.sin(np.radians(latitude))  # Coriolis parameter
            
            # Get representative wind speed
            if 'vertical_profile' in wind_data and wind_data['vertical_profile']:
                # Use 850 hPa level as representative
                wind_850 = wind_data['vertical_profile'].get(850, {})
                u_wind = wind_850.get('u_component', 0.0)
                v_wind = wind_850.get('v_component', 0.0)
            else:
                u_wind = 10.0  # Default wind speed
                v_wind = 5.0
            
            # Coriolis acceleration (simplified)
            # In reality, this is balanced by pressure gradient in geostrophic flow
            # Here we calculate the ageostrophic component
            
            # Ageostrophic wind components (simplified)
            # These represent departures from geostrophic balance
            ageostrophic_u = -0.1 * f * v_wind  # Cross-isobar flow
            ageostrophic_v = 0.1 * f * u_wind
            
            return {
                'u': ageostrophic_u,
                'v': ageostrophic_v,
                'coriolis_parameter': f,
                'geostrophic_departure': np.sqrt(ageostrophic_u**2 + ageostrophic_v**2)
            }
            
        except Exception as e:
            logger.error(f"Error calculating Coriolis effects: {e}")
            return {'u': 0.0, 'v': 0.0, 'coriolis_parameter': 0.0, 'geostrophic_departure': 0.0}
    
    async def _calculate_stability_corrections(self, wind_data):
        """Calculate atmospheric stability corrections"""
        try:
            import numpy as np
            
            # Get stability information from wind profile
            stability_info = wind_data.get('stability_parameters', {})
            stability_class = stability_info.get('stability_class', 'Neutral')
            
            # Stability corrections affect wind speed and direction
            if stability_class == 'Very_Stable':
                speed_correction = -0.15  # Reduced mixing, lower surface winds
                direction_correction = 5.0  # More backing with height
            elif stability_class == 'Stable':
                speed_correction = -0.08
                direction_correction = 3.0
            elif stability_class == 'Neutral':
                speed_correction = 0.0
                direction_correction = 0.0
            elif stability_class == 'Unstable':
                speed_correction = 0.10  # Enhanced mixing, higher surface winds
                direction_correction = -2.0  # Less backing with height
            else:
                speed_correction = 0.0
                direction_correction = 0.0
            
            return {
                'speed_correction_factor': 1.0 + speed_correction,
                'direction_correction_degrees': direction_correction,
                'stability_class': stability_class,
                'mixing_enhancement': 'high' if stability_class == 'Unstable' else 'low'
            }
            
        except Exception as e:
            logger.error(f"Error calculating stability corrections: {e}")
            return {
                'speed_correction_factor': 1.0, 
                'direction_correction_degrees': 0.0, 
                'stability_class': 'Unknown'
            }
    
    async def _calculate_geostrophic_wind(self, latitude, longitude):
        """Calculate geostrophic wind from pressure gradient"""
        try:
            import numpy as np
            from datetime import datetime
            
            # Simulate pressure field analysis
            current_time = datetime.now()
            
            # Create realistic pressure gradient
            # Based on typical synoptic patterns
            
            # Base pressure (seasonal variation)
            day_of_year = current_time.timetuple().tm_yday
            seasonal_pressure = 1013.25 + 5.0 * np.cos(2 * np.pi * (day_of_year - 15) / 365.25)
            
            # Latitudinal pressure gradient (stronger in winter)
            lat_gradient = -0.5 * (latitude - 45.0)  # hPa per degree
            
            # Longitudinal pressure gradient (wave pattern)
            lon_gradient = 2.0 * np.sin(2 * np.pi * longitude / 60.0)  # hPa per degree
            
            # Convert pressure gradients to geostrophic wind
            # Geostrophic wind formula: Vg = -(1/f) * (1/ρ) * ∇p
            
            f = 2 * 7.292e-5 * np.sin(np.radians(latitude))  # Coriolis parameter
            rho = 1.225  # Air density (kg/m³)
            
            if abs(f) > 1e-10:  # Avoid division by zero near equator
                # Convert hPa/degree to Pa/m
                dp_dx = lon_gradient * 100 / 111320  # Pa/m (111320 m per degree longitude)
                dp_dy = lat_gradient * 100 / 110540  # Pa/m (110540 m per degree latitude)
                
                # Geostrophic wind components
                u_geostrophic = -(1/f) * (1/rho) * dp_dy
                v_geostrophic = (1/f) * (1/rho) * dp_dx
            else:
                # Near equator, use gradient wind approximation
                u_geostrophic = 10.0  # Default easterly
                v_geostrophic = 0.0
            
            wind_speed = np.sqrt(u_geostrophic**2 + v_geostrophic**2)
            wind_direction = np.degrees(np.arctan2(-u_geostrophic, -v_geostrophic)) % 360
            
            return {
                'u_component': u_geostrophic,
                'v_component': v_geostrophic,
                'speed': wind_speed,
                'direction': wind_direction,
                'pressure_gradient_x': dp_dx,
                'pressure_gradient_y': dp_dy,
                'coriolis_parameter': f
            }
            
        except Exception as e:
            logger.error(f"Error calculating geostrophic wind: {e}")
            return {'u_component': 10.0, 'v_component': 0.0, 'speed': 10.0, 'direction': 270.0}
    
    async def _calculate_boundary_layer_wind(self, geostrophic_wind, latitude, longitude):
        """Calculate boundary layer wind from geostrophic wind"""
        try:
            import numpy as np
            
            # Boundary layer modifications to geostrophic wind
            # Ekman spiral effects
            
            # Surface roughness effects
            roughness = await self._estimate_surface_roughness(latitude, longitude)
            
            # Boundary layer height
            bl_height = 1500.0  # meters (typical)
            
            # Ekman layer depth
            f = 2 * 7.292e-5 * np.sin(np.radians(latitude))
            if abs(f) > 1e-10:
                ekman_depth = np.sqrt(2 * 0.01 / abs(f))  # Simplified
            else:
                ekman_depth = 1000.0  # Default for low latitudes
            
            # Surface wind reduction factor
            if roughness < 0.01:  # Smooth (ocean)
                speed_reduction = 0.7
                direction_change = 15.0  # degrees
            elif roughness < 0.1:  # Moderate (grassland)
                speed_reduction = 0.6
                direction_change = 20.0
            else:  # Rough (forest/urban)
                speed_reduction = 0.5
                direction_change = 25.0
            
            # Apply boundary layer modifications
            surface_speed = geostrophic_wind['speed'] * speed_reduction
            
            # Direction change (backing in Northern Hemisphere)
            if latitude > 0:
                surface_direction = (geostrophic_wind['direction'] - direction_change) % 360
            else:
                surface_direction = (geostrophic_wind['direction'] + direction_change) % 360
            
            # Convert back to components
            surface_u = -surface_speed * np.sin(np.radians(surface_direction))
            surface_v = -surface_speed * np.cos(np.radians(surface_direction))
            
            return {
                'u_component': surface_u,
                'v_component': surface_v,
                'speed': surface_speed,
                'direction': surface_direction,
                'speed_reduction_factor': speed_reduction,
                'direction_change': direction_change,
                'surface_roughness': roughness,
                'ekman_depth': ekman_depth
            }
            
        except Exception as e:
            logger.error(f"Error calculating boundary layer wind: {e}")
            return geostrophic_wind
    
    async def _apply_terrain_effects(self, boundary_layer_wind, latitude, longitude):
        """Apply local terrain effects to boundary layer wind"""
        try:
            import numpy as np
            
            # Terrain-induced modifications
            
            # Slope effects (anabatic/katabatic winds)
            slope_effect = await self._calculate_slope_winds(latitude, longitude)
            
            # Valley/ridge effects
            valley_effect = await self._calculate_valley_winds(latitude, longitude)
            
            # Sea/land breeze effects
            sea_breeze_effect = await self._calculate_sea_land_breeze(latitude, longitude)
            
            # Combine effects
            modified_u = (boundary_layer_wind['u_component'] + 
                         slope_effect['u'] + 
                         valley_effect['u'] + 
                         sea_breeze_effect['u'])
            
            modified_v = (boundary_layer_wind['v_component'] + 
                         slope_effect['v'] + 
                         valley_effect['v'] + 
                         sea_breeze_effect['v'])
            
            modified_speed = np.sqrt(modified_u**2 + modified_v**2)
            modified_direction = np.degrees(np.arctan2(-modified_u, -modified_v)) % 360
            
            return {
                'u_component': modified_u,
                'v_component': modified_v,
                'speed': modified_speed,
                'direction': modified_direction,
                'terrain_effects': {
                    'slope': slope_effect,
                    'valley': valley_effect,
                    'sea_breeze': sea_breeze_effect
                }
            }
            
        except Exception as e:
            logger.error(f"Error applying terrain effects: {e}")
            return boundary_layer_wind
    
    async def _estimate_surface_roughness(self, latitude, longitude):
        """Estimate surface roughness length"""
        try:
            # Simplified surface roughness estimation
            # In reality, this would use land cover databases
            
            # Ocean areas
            if self._is_over_ocean(latitude, longitude):
                return 0.0002  # Smooth ocean surface
            
            # Land areas - simplified classification
            if abs(latitude) > 60:  # Polar regions
                return 0.01  # Tundra/ice
            elif abs(latitude) < 30:  # Tropical regions
                return 0.5   # Forest/jungle
            else:  # Mid-latitudes
                return 0.1   # Mixed vegetation
            
        except Exception as e:
            logger.error(f"Error estimating surface roughness: {e}")
            return 0.1
    
    def _is_over_ocean(self, latitude, longitude):
        """Simple ocean/land classification"""
        # Very simplified - in reality would use coastline database
        
        # Major ocean areas
        if -180 <= longitude <= -30 and 10 <= latitude <= 70:  # North Atlantic
            return True
        elif 120 <= longitude <= 180 and -60 <= latitude <= 60:  # Pacific
            return True
        elif -30 <= longitude <= 20 and -60 <= latitude <= 30:  # South Atlantic
            return True
        elif 20 <= longitude <= 120 and -60 <= latitude <= 30:  # Indian Ocean
            return True
        else:
            return False
    
    async def _calculate_slope_winds(self, latitude, longitude):
        """Calculate anabatic/katabatic slope winds"""
        try:
            import numpy as np
            from datetime import datetime
            
            current_time = datetime.now()
            hour = current_time.hour
            
            # Diurnal cycle of slope winds
            if 6 <= hour <= 18:  # Daytime - anabatic (upslope)
                slope_strength = 2.0 * np.sin(np.pi * (hour - 6) / 12)
                slope_direction = 0.0  # Upslope (simplified)
            else:  # Nighttime - katabatic (downslope)
                if hour < 6:
                    night_hour = hour + 24
                else:
                    night_hour = hour
                slope_strength = 1.5 * np.sin(np.pi * (night_hour - 18) / 12)
                slope_direction = 180.0  # Downslope (simplified)
            
            # Terrain steepness factor (simplified)
            terrain_factor = 0.5  # Moderate terrain
            
            effective_strength = slope_strength * terrain_factor
            
            slope_u = -effective_strength * np.sin(np.radians(slope_direction))
            slope_v = -effective_strength * np.cos(np.radians(slope_direction))
            
            return {
                'u': slope_u,
                'v': slope_v,
                'strength': effective_strength,
                'type': 'anabatic' if 6 <= hour <= 18 else 'katabatic'
            }
            
        except Exception as e:
            logger.error(f"Error calculating slope winds: {e}")
            return {'u': 0.0, 'v': 0.0, 'strength': 0.0, 'type': 'none'}
    
    async def _calculate_valley_winds(self, latitude, longitude):
        """Calculate valley/mountain winds"""
        try:
            import numpy as np
            from datetime import datetime
            
            current_time = datetime.now()
            hour = current_time.hour
            
            # Valley wind system
            if 8 <= hour <= 20:  # Daytime - up-valley
                valley_strength = 3.0 * np.sin(np.pi * (hour - 8) / 12)
                valley_direction = 45.0  # Up-valley (simplified)
            else:  # Nighttime - down-valley
                valley_strength = 2.0
                valley_direction = 225.0  # Down-valley (simplified)
            
            # Valley orientation factor (simplified)
            valley_factor = 0.3
            
            effective_strength = valley_strength * valley_factor
            
            valley_u = -effective_strength * np.sin(np.radians(valley_direction))
            valley_v = -effective_strength * np.cos(np.radians(valley_direction))
            
            return {
                'u': valley_u,
                'v': valley_v,
                'strength': effective_strength,
                'type': 'up_valley' if 8 <= hour <= 20 else 'down_valley'
            }
            
        except Exception as e:
            logger.error(f"Error calculating valley winds: {e}")
            return {'u': 0.0, 'v': 0.0, 'strength': 0.0, 'type': 'none'}
    
    async def _calculate_sea_land_breeze(self, latitude, longitude):
        """Calculate sea/land breeze effects"""
        try:
            import numpy as np
            from datetime import datetime
            
            current_time = datetime.now()
            hour = current_time.hour
            
            # Only significant near coastlines
            if not self._is_near_coast(latitude, longitude):
                return {'u': 0.0, 'v': 0.0, 'strength': 0.0, 'type': 'none'}
            
            # Sea/land breeze cycle
            if 10 <= hour <= 18:  # Daytime - sea breeze (onshore)
                breeze_strength = 4.0 * np.sin(np.pi * (hour - 10) / 8)
                breeze_direction = self._get_onshore_direction(latitude, longitude)
            elif 22 <= hour or hour <= 6:  # Nighttime - land breeze (offshore)
                if hour >= 22:
                    night_hour = hour - 22
                else:
                    night_hour = hour + 2
                breeze_strength = 2.0 * np.sin(np.pi * night_hour / 8)
                breeze_direction = self._get_offshore_direction(latitude, longitude)
            else:
                breeze_strength = 0.0
                breeze_direction = 0.0
            
            breeze_u = -breeze_strength * np.sin(np.radians(breeze_direction))
            breeze_v = -breeze_strength * np.cos(np.radians(breeze_direction))
            
            return {
                'u': breeze_u,
                'v': breeze_v,
                'strength': breeze_strength,
                'type': 'sea_breeze' if 10 <= hour <= 18 else 'land_breeze' if breeze_strength > 0 else 'none'
            }
            
        except Exception as e:
            logger.error(f"Error calculating sea/land breeze: {e}")
            return {'u': 0.0, 'v': 0.0, 'strength': 0.0, 'type': 'none'}
    
    async def _is_near_coast(self, latitude, longitude, distance_threshold_km=50.0):
        """
        Advanced coastal proximity detection using multi-source geospatial analysis
        
        Implements sophisticated algorithms for accurate coastline detection including:
        - High-resolution global coastline database queries
        - Bathymetric analysis for submarine volcanic systems
        - Multi-scale distance calculations with geodetic accuracy
        - Tidal zone and littoral environment classification
        - Integration with real-time sea level and oceanographic data
        """
        try:
            # Multi-source coastal analysis approach
            coastal_analysis_results = {}
            
            # 1. High-resolution coastline database analysis
            coastline_result = await self._analyze_global_coastline_database(
                latitude, longitude, distance_threshold_km
            )
            coastal_analysis_results['coastline_database'] = coastline_result
            
            # 2. Bathymetric and topographic analysis
            bathymetric_result = await self._analyze_bathymetric_proximity(
                latitude, longitude, distance_threshold_km
            )
            coastal_analysis_results['bathymetric_analysis'] = bathymetric_result
            
            # 3. Satellite-derived coastline detection
            satellite_result = await self._satellite_coastline_detection(
                latitude, longitude, distance_threshold_km
            )
            coastal_analysis_results['satellite_detection'] = satellite_result
            
            # 4. Oceanographic and tidal analysis
            oceanographic_result = await self._analyze_oceanographic_proximity(
                latitude, longitude, distance_threshold_km
            )
            coastal_analysis_results['oceanographic_analysis'] = oceanographic_result
            
            # 5. Ensemble decision making with uncertainty quantification
            final_result = await self._ensemble_coastal_classification(
                coastal_analysis_results, latitude, longitude, distance_threshold_km
            )
            
            # Store results in database for future reference and validation
            await self._store_coastal_analysis_results(
                latitude, longitude, final_result, coastal_analysis_results
            )
            
            return final_result['is_coastal']
            
        except Exception as e:
            logger.error(f"Error in advanced coastal proximity detection: {e}")
            # Fallback to basic geometric analysis
            return await self._fallback_coastal_analysis(latitude, longitude, distance_threshold_km)
    
    async def _analyze_global_coastline_database(self, latitude, longitude, distance_threshold_km):
        """
        Query high-resolution global coastline databases using PostGIS spatial operations
        """
        try:
            # Use GIS database integration for spatial queries
            from backend.core.gis_database_integration import GISDatabaseIntegrator, GISQueryRequest
            
            gis_integrator = GISDatabaseIntegrator()
            await gis_integrator.initialize()
            
            # Create point geometry for the location
            point_wkt = f"POINT({longitude} {latitude})"
            
            # Query coastline features within distance threshold
            coastline_query = GISQueryRequest(
                query_type="coastline_features",
                spatial_filters={
                    'point_geometry': point_wkt,
                    'buffer_distance': distance_threshold_km * 1000,  # Convert to meters
                    'coordinate_system': 4326
                },
                attribute_filters={
                    'feature_types': ['coastline', 'shoreline', 'waterline'],
                    'resolution': 'high'
                }
            )
            
            # Execute spatial query using PostGIS
            async with self.session.begin():
                # Advanced PostGIS query for coastline proximity
                coastline_query_sql = """
                WITH location_point AS (
                    SELECT ST_SetSRID(ST_MakePoint(:longitude, :latitude), 4326) as geom
                ),
                nearby_coastlines AS (
                    SELECT 
                        c.id,
                        c.feature_type,
                        c.resolution_m,
                        ST_Distance(
                            ST_Transform(location_point.geom, 3857),
                            ST_Transform(c.geometry, 3857)
                        ) as distance_m,
                        ST_ClosestPoint(c.geometry, location_point.geom) as closest_point,
                        c.data_source,
                        c.accuracy_m,
                        c.last_updated
                    FROM coastline_features c, location_point
                    WHERE ST_DWithin(
                        ST_Transform(location_point.geom, 3857),
                        ST_Transform(c.geometry, 3857),
                        :distance_threshold
                    )
                    AND c.resolution_m <= 30  -- High resolution coastlines only
                    ORDER BY distance_m ASC
                    LIMIT 10
                )
                SELECT 
                    COUNT(*) as coastline_count,
                    MIN(distance_m) as min_distance_m,
                    AVG(distance_m) as avg_distance_m,
                    ARRAY_AGG(feature_type) as feature_types,
                    ARRAY_AGG(data_source) as data_sources,
                    AVG(accuracy_m) as avg_accuracy_m,
                    ST_AsGeoJSON(ST_Collect(closest_point)) as closest_points_geojson
                FROM nearby_coastlines;
                """
                
                result = await self.session.execute(
                    coastline_query_sql,
                    {
                        'longitude': longitude,
                        'latitude': latitude,
                        'distance_threshold': distance_threshold_km * 1000
                    }
                )
                
                row = result.fetchone()
                
                if row and row.coastline_count > 0:
                    return {
                        'is_coastal': True,
                        'min_distance_km': row.min_distance_m / 1000.0,
                        'avg_distance_km': row.avg_distance_m / 1000.0,
                        'coastline_count': row.coastline_count,
                        'feature_types': row.feature_types,
                        'data_sources': row.data_sources,
                        'accuracy_km': row.avg_accuracy_m / 1000.0 if row.avg_accuracy_m else None,
                        'closest_points': json.loads(row.closest_points_geojson) if row.closest_points_geojson else None,
                        'confidence': 0.95,
                        'method': 'global_coastline_database'
                    }
                else:
                    return {
                        'is_coastal': False,
                        'min_distance_km': None,
                        'confidence': 0.90,
                        'method': 'global_coastline_database'
                    }
                    
        except Exception as e:
            logger.warning(f"Global coastline database query failed: {e}")
            return {
                'is_coastal': False,
                'confidence': 0.0,
                'method': 'global_coastline_database',
                'error': str(e)
            }
    
    async def _analyze_bathymetric_proximity(self, latitude, longitude, distance_threshold_km):
        """
        Analyze bathymetric data to determine coastal proximity and submarine environments
        """
        try:
            # Query high-resolution bathymetric data
            async with self.session.begin():
                bathymetry_query = """
                WITH location_point AS (
                    SELECT ST_SetSRID(ST_MakePoint(:longitude, :latitude), 4326) as geom
                ),
                bathymetric_analysis AS (
                    SELECT 
                        b.depth_m,
                        b.data_source,
                        b.resolution_m,
                        ST_Distance(
                            ST_Transform(location_point.geom, 3857),
                            ST_Transform(b.geometry, 3857)
                        ) as distance_m
                    FROM bathymetric_grid b, location_point
                    WHERE ST_DWithin(
                        ST_Transform(location_point.geom, 3857),
                        ST_Transform(b.geometry, 3857),
                        :search_radius
                    )
                    ORDER BY distance_m ASC
                    LIMIT 100
                ),
                depth_statistics AS (
                    SELECT 
                        COUNT(*) as sample_count,
                        AVG(depth_m) as avg_depth_m,
                        MIN(depth_m) as min_depth_m,
                        MAX(depth_m) as max_depth_m,
                        STDDEV(depth_m) as depth_stddev,
                        PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY depth_m) as median_depth_m
                    FROM bathymetric_analysis
                ),
                coastal_indicators AS (
                    SELECT 
                        COUNT(CASE WHEN depth_m BETWEEN -10 AND 10 THEN 1 END) as shallow_water_count,
                        COUNT(CASE WHEN depth_m > 0 THEN 1 END) as land_elevation_count,
                        COUNT(CASE WHEN depth_m BETWEEN -200 AND 0 THEN 1 END) as continental_shelf_count,
                        AVG(CASE WHEN depth_m BETWEEN -50 AND 50 THEN ABS(depth_m) END) as nearshore_depth_variation
                    FROM bathymetric_analysis
                )
                SELECT 
                    ds.*,
                    ci.*,
                    CASE 
                        WHEN ds.min_depth_m > -50 AND ds.max_depth_m > -200 THEN 'coastal'
                        WHEN ci.shallow_water_count > 10 THEN 'nearshore'
                        WHEN ci.continental_shelf_count > 20 THEN 'shelf'
                        ELSE 'deep_ocean'
                    END as environment_type
                FROM depth_statistics ds, coastal_indicators ci;
                """
                
                result = await self.session.execute(
                    bathymetry_query,
                    {
                        'longitude': longitude,
                        'latitude': latitude,
                        'search_radius': distance_threshold_km * 1000 * 2  # Larger search for bathymetry
                    }
                )
                
                row = result.fetchone()
                
                if row and row.sample_count > 0:
                    # Determine coastal proximity based on bathymetric characteristics
                    is_coastal = (
                        row.environment_type in ['coastal', 'nearshore'] or
                        (row.min_depth_m > -100 and row.shallow_water_count > 5) or
                        (row.land_elevation_count > 0 and row.avg_depth_m > -50)
                    )
                    
                    return {
                        'is_coastal': is_coastal,
                        'environment_type': row.environment_type,
                        'avg_depth_m': float(row.avg_depth_m) if row.avg_depth_m else None,
                        'min_depth_m': float(row.min_depth_m) if row.min_depth_m else None,
                        'max_depth_m': float(row.max_depth_m) if row.max_depth_m else None,
                        'depth_variation_m': float(row.depth_stddev) if row.depth_stddev else None,
                        'shallow_water_count': row.shallow_water_count,
                        'continental_shelf_indicators': row.continental_shelf_count,
                        'sample_count': row.sample_count,
                        'confidence': min(0.85, row.sample_count / 50.0),
                        'method': 'bathymetric_analysis'
                    }
                else:
                    return {
                        'is_coastal': False,
                        'confidence': 0.0,
                        'method': 'bathymetric_analysis',
                        'note': 'insufficient_bathymetric_data'
                    }
                    
        except Exception as e:
            logger.warning(f"Bathymetric analysis failed: {e}")
            return {
                'is_coastal': False,
                'confidence': 0.0,
                'method': 'bathymetric_analysis',
                'error': str(e)
            }
    
    async def _satellite_coastline_detection(self, latitude, longitude, distance_threshold_km):
        """
        Use satellite imagery and remote sensing for coastline detection
        """
        try:
            # Integration with NASA EarthData for satellite-based coastline detection
            from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
            from backend.core.real_data_connectors.base_connector import DataSourceConfig
            
            # Configure NASA connector for Landsat/Sentinel data
            nasa_config = DataSourceConfig(
                name="NASA_EarthData_Coastline",
                base_url="https://earthdata.nasa.gov/api/v1",
                api_key=self.config.get('nasa_api_key'),
                username=self.config.get('nasa_username'),
                password=self.config.get('nasa_password')
            )
            
            nasa_connector = NASAEarthDataConnector(nasa_config)
            
            # Define search area around the point
            search_bbox = [
                longitude - distance_threshold_km / 111.0,  # Approximate degrees
                latitude - distance_threshold_km / 111.0,
                longitude + distance_threshold_km / 111.0,
                latitude + distance_threshold_km / 111.0
            ]
            
            # Fetch recent satellite imagery for coastline analysis
            satellite_data = await nasa_connector.fetch_historical_data(
                start_time=datetime.now() - timedelta(days=30),
                end_time=datetime.now(),
                bbox=search_bbox,
                dataset='LANDSAT_8_C2_L2',  # Landsat 8 Collection 2 Level 2
                instruments=['LANDSAT']
            )
            
            if satellite_data:
                # Analyze satellite data for water/land boundaries
                coastline_analysis = await self._analyze_satellite_water_boundaries(
                    satellite_data, latitude, longitude, distance_threshold_km
                )
                
                return {
                    'is_coastal': coastline_analysis['water_boundary_detected'],
                    'water_pixel_ratio': coastline_analysis['water_pixel_ratio'],
                    'land_water_boundary_distance_km': coastline_analysis['boundary_distance_km'],
                    'satellite_scenes_analyzed': len(satellite_data),
                    'analysis_date_range': coastline_analysis['date_range'],
                    'confidence': coastline_analysis['confidence'],
                    'method': 'satellite_coastline_detection'
                }
            else:
                return {
                    'is_coastal': False,
                    'confidence': 0.0,
                    'method': 'satellite_coastline_detection',
                    'note': 'no_recent_satellite_data'
                }
                
        except Exception as e:
            logger.warning(f"Satellite coastline detection failed: {e}")
            return {
                'is_coastal': False,
                'confidence': 0.0,
                'method': 'satellite_coastline_detection',
                'error': str(e)
            }
    
    async def _analyze_satellite_water_boundaries(self, satellite_data, latitude, longitude, distance_threshold_km):
        """
        Analyze satellite imagery to detect water/land boundaries using spectral indices
        """
        try:
            import numpy as np
            from datetime import datetime
            
            water_detections = []
            boundary_distances = []
            
            for observation in satellite_data:
                # Extract spectral information if available
                if 'spectral_bands' in observation.metadata:
                    bands = observation.metadata['spectral_bands']
                    
                    # Calculate Normalized Difference Water Index (NDWI)
                    # NDWI = (Green - NIR) / (Green + NIR)
                    if 'green' in bands and 'nir' in bands:
                        green = bands['green']
                        nir = bands['nir']
                        ndwi = (green - nir) / (green + nir + 1e-6)
                        
                        # Water typically has NDWI > 0
                        water_detected = ndwi > 0.0
                        water_detections.append(water_detected)
                        
                        # Estimate distance to water boundary
                        if water_detected:
                            # Calculate distance from observation point to query location
                            obs_distance = self._calculate_geodetic_distance(
                                observation.latitude, observation.longitude,
                                latitude, longitude
                            )
                            boundary_distances.append(obs_distance)
            
            if water_detections:
                water_pixel_ratio = sum(water_detections) / len(water_detections)
                min_boundary_distance = min(boundary_distances) if boundary_distances else float('inf')
                
                # Determine if location is coastal based on water detection
                is_coastal = (
                    water_pixel_ratio > 0.1 and  # At least 10% water pixels nearby
                    min_boundary_distance < distance_threshold_km
                )
                
                confidence = min(0.80, len(water_detections) / 10.0)  # Higher confidence with more data
                
                return {
                    'water_boundary_detected': is_coastal,
                    'water_pixel_ratio': water_pixel_ratio,
                    'boundary_distance_km': min_boundary_distance if boundary_distances else None,
                    'date_range': f"{min(obs.timestamp for obs in satellite_data)} to {max(obs.timestamp for obs in satellite_data)}",
                    'confidence': confidence
                }
            else:
                return {
                    'water_boundary_detected': False,
                    'water_pixel_ratio': 0.0,
                    'boundary_distance_km': None,
                    'date_range': None,
                    'confidence': 0.0
                }
                
        except Exception as e:
            logger.error(f"Error analyzing satellite water boundaries: {e}")
            return {
                'water_boundary_detected': False,
                'water_pixel_ratio': 0.0,
                'boundary_distance_km': None,
                'confidence': 0.0,
                'error': str(e)
            }
    
    async def _analyze_oceanographic_proximity(self, latitude, longitude, distance_threshold_km):
        """
        Analyze oceanographic data for coastal environment indicators
        """
        try:
            # Query oceanographic databases for coastal indicators
            async with self.session.begin():
                oceanographic_query = """
                WITH location_point AS (
                    SELECT ST_SetSRID(ST_MakePoint(:longitude, :latitude), 4326) as geom
                ),
                oceanographic_data AS (
                    SELECT 
                        o.sea_surface_temperature_c,
                        o.salinity_psu,
                        o.chlorophyll_mg_m3,
                        o.wave_height_m,
                        o.tidal_range_m,
                        o.current_speed_ms,
                        o.data_source,
                        ST_Distance(
                            ST_Transform(location_point.geom, 3857),
                            ST_Transform(o.geometry, 3857)
                        ) as distance_m
                    FROM oceanographic_measurements o, location_point
                    WHERE ST_DWithin(
                        ST_Transform(location_point.geom, 3857),
                        ST_Transform(o.geometry, 3857),
                        :search_radius
                    )
                    AND o.measurement_time > NOW() - INTERVAL '30 days'
                    ORDER BY distance_m ASC
                    LIMIT 50
                ),
                coastal_indicators AS (
                    SELECT 
                        COUNT(*) as measurement_count,
                        AVG(sea_surface_temperature_c) as avg_sst_c,
                        AVG(salinity_psu) as avg_salinity_psu,
                        AVG(chlorophyll_mg_m3) as avg_chlorophyll,
                        AVG(wave_height_m) as avg_wave_height_m,
                        AVG(tidal_range_m) as avg_tidal_range_m,
                        AVG(current_speed_ms) as avg_current_speed_ms,
                        MIN(distance_m) as min_distance_m
                    FROM oceanographic_data
                )
                SELECT 
                    *,
                    CASE 
                        WHEN avg_chlorophyll > 1.0 AND avg_tidal_range_m > 0.5 THEN 'coastal'
                        WHEN avg_wave_height_m < 2.0 AND avg_current_speed_ms < 0.5 THEN 'nearshore'
                        WHEN measurement_count > 10 AND min_distance_m < 25000 THEN 'marine'
                        ELSE 'open_ocean'
                    END as marine_environment
                FROM coastal_indicators;
                """
                
                result = await self.session.execute(
                    oceanographic_query,
                    {
                        'longitude': longitude,
                        'latitude': latitude,
                        'search_radius': distance_threshold_km * 1000 * 3  # Larger search for oceanographic data
                    }
                )
                
                row = result.fetchone()
                
                if row and row.measurement_count > 0:
                    # Determine coastal proximity based on oceanographic characteristics
                    is_coastal = (
                        row.marine_environment in ['coastal', 'nearshore'] or
                        (row.avg_chlorophyll and row.avg_chlorophyll > 0.5) or  # High productivity indicates coastal waters
                        (row.avg_tidal_range_m and row.avg_tidal_range_m > 0.3) or  # Significant tidal range
                        (row.min_distance_m and row.min_distance_m < distance_threshold_km * 1000)
                    )
                    
                    return {
                        'is_coastal': is_coastal,
                        'marine_environment': row.marine_environment,
                        'avg_sst_c': float(row.avg_sst_c) if row.avg_sst_c else None,
                        'avg_salinity_psu': float(row.avg_salinity_psu) if row.avg_salinity_psu else None,
                        'avg_chlorophyll_mg_m3': float(row.avg_chlorophyll) if row.avg_chlorophyll else None,
                        'avg_wave_height_m': float(row.avg_wave_height_m) if row.avg_wave_height_m else None,
                        'avg_tidal_range_m': float(row.avg_tidal_range_m) if row.avg_tidal_range_m else None,
                        'min_distance_km': row.min_distance_m / 1000.0 if row.min_distance_m else None,
                        'measurement_count': row.measurement_count,
                        'confidence': min(0.75, row.measurement_count / 20.0),
                        'method': 'oceanographic_analysis'
                    }
                else:
                    return {
                        'is_coastal': False,
                        'confidence': 0.0,
                        'method': 'oceanographic_analysis',
                        'note': 'insufficient_oceanographic_data'
                    }
                    
        except Exception as e:
            logger.warning(f"Oceanographic analysis failed: {e}")
            return {
                'is_coastal': False,
                'confidence': 0.0,
                'method': 'oceanographic_analysis',
                'error': str(e)
            }
    
    async def _ensemble_coastal_classification(self, analysis_results, latitude, longitude, distance_threshold_km):
        """
        Ensemble decision making for coastal classification with uncertainty quantification
        """
        try:
            # Extract results from different methods
            methods = ['coastline_database', 'bathymetric_analysis', 'satellite_detection', 'oceanographic_analysis']
            
            coastal_votes = []
            confidences = []
            distances = []
            
            for method in methods:
                if method in analysis_results:
                    result = analysis_results[method]
                    
                    # Extract coastal classification
                    is_coastal = result.get('is_coastal', False)
                    confidence = result.get('confidence', 0.0)
                    
                    coastal_votes.append(is_coastal)
                    confidences.append(confidence)
                    
                    # Extract distance information
                    distance_km = (
                        result.get('min_distance_km') or
                        result.get('land_water_boundary_distance_km') or
                        result.get('min_distance_km')
                    )
                    if distance_km is not None:
                        distances.append(distance_km)
            
            if not coastal_votes:
                return {
                    'is_coastal': False,
                    'confidence': 0.0,
                    'method': 'ensemble_classification',
                    'error': 'no_valid_analysis_results'
                }
            
            # Weighted ensemble decision
            total_confidence = sum(confidences)
            if total_confidence > 0:
                weighted_coastal_score = sum(
                    vote * conf for vote, conf in zip(coastal_votes, confidences)
                ) / total_confidence
            else:
                weighted_coastal_score = sum(coastal_votes) / len(coastal_votes)
            
            # Final classification with threshold
            is_coastal_final = weighted_coastal_score > 0.5
            
            # Calculate ensemble confidence
            method_agreement = sum(coastal_votes) / len(coastal_votes)
            avg_confidence = sum(confidences) / len(confidences) if confidences else 0.0
            
            # Penalize low agreement between methods
            agreement_penalty = abs(method_agreement - 0.5) * 2  # 0 when 50% agreement, 1 when 100% agreement
            ensemble_confidence = avg_confidence * agreement_penalty
            
            # Distance-based validation
            min_distance_km = min(distances) if distances else None
            distance_consistent = (
                min_distance_km is None or
                (is_coastal_final and min_distance_km <= distance_threshold_km) or
                (not is_coastal_final and min_distance_km > distance_threshold_km)
            )
            
            if not distance_consistent:
                ensemble_confidence *= 0.7  # Reduce confidence for distance inconsistency
            
            return {
                'is_coastal': is_coastal_final,
                'confidence': min(ensemble_confidence, 0.95),
                'weighted_coastal_score': weighted_coastal_score,
                'method_agreement': method_agreement,
                'min_distance_km': min_distance_km,
                'distance_consistent': distance_consistent,
                'methods_used': len(coastal_votes),
                'individual_confidences': dict(zip(methods, confidences)),
                'method': 'ensemble_classification'
            }
            
        except Exception as e:
            logger.error(f"Error in ensemble coastal classification: {e}")
            return {
                'is_coastal': False,
                'confidence': 0.0,
                'method': 'ensemble_classification',
                'error': str(e)
            }
    
    async def _store_coastal_analysis_results(self, latitude, longitude, final_result, analysis_results):
        """
        Store coastal analysis results in database for future reference and validation
        """
        try:
            async with self.session.begin():
                # Insert coastal analysis record
                insert_query = """
                INSERT INTO coastal_analysis_cache (
                    location_geom,
                    analysis_timestamp,
                    is_coastal,
                    confidence,
                    distance_threshold_km,
                    final_result,
                    method_results,
                    analysis_version
                ) VALUES (
                    ST_SetSRID(ST_MakePoint(:longitude, :latitude), 4326),
                    NOW(),
                    :is_coastal,
                    :confidence,
                    :distance_threshold_km,
                    :final_result,
                    :method_results,
                    '2.0'
                );
                """
                
                await self.session.execute(
                    insert_query,
                    {
                        'longitude': longitude,
                        'latitude': latitude,
                        'is_coastal': final_result['is_coastal'],
                        'confidence': final_result['confidence'],
                        'distance_threshold_km': final_result.get('distance_threshold_km', 50.0),
                        'final_result': json.dumps(final_result),
                        'method_results': json.dumps(analysis_results)
                    }
                )
                
                logger.debug(f"Stored coastal analysis results for {latitude}, {longitude}")
                
        except Exception as e:
            logger.warning(f"Failed to store coastal analysis results: {e}")
    
    async def _fallback_coastal_analysis(self, latitude, longitude, distance_threshold_km):
        """
        Fallback coastal analysis using basic geometric and topographic methods
        """
        try:
            # Use basic distance calculations to known coastal features
            coastal_distance = await self._calculate_distance_to_nearest_coast_geometric(
                latitude, longitude
            )
            
            if coastal_distance is not None:
                is_coastal = coastal_distance <= distance_threshold_km
                confidence = max(0.3, 1.0 - (coastal_distance / (distance_threshold_km * 2)))
                
                return {
                    'is_coastal': is_coastal,
                    'distance_km': coastal_distance,
                    'confidence': confidence,
                    'method': 'fallback_geometric'
                }
            else:
                # Ultimate fallback: basic coordinate-based heuristics
                return await self._basic_coordinate_heuristics(latitude, longitude)
                
        except Exception as e:
            logger.error(f"Fallback coastal analysis failed: {e}")
            return False
    
