    def _point_to_line_segment_distance(self, lat, lon, start_point, end_point):
        """
        Calculate distance from point to line segment using geodetic calculations
        """
        try:
            import math
            
            # Convert to radians
            lat_rad = math.radians(lat)
            lon_rad = math.radians(lon)
            start_lat_rad = math.radians(start_point[0])
            start_lon_rad = math.radians(start_point[1])
            end_lat_rad = math.radians(end_point[0])
            end_lon_rad = math.radians(end_point[1])
            
            # Calculate distances to endpoints
            dist_to_start = self._haversine_distance(lat, lon, start_point[0], start_point[1])
            dist_to_end = self._haversine_distance(lat, lon, end_point[0], end_point[1])
            
            # Calculate distance to line (simplified)
            # For more accuracy, would use proper geodetic line calculations
            segment_length = self._haversine_distance(start_point[0], start_point[1], end_point[0], end_point[1])
            
            if segment_length == 0:
                return dist_to_start
            
            # Project point onto line segment
            t = max(0, min(1, (
                (lat - start_point[0]) * (end_point[0] - start_point[0]) +
                (lon - start_point[1]) * (end_point[1] - start_point[1])
            ) / (segment_length ** 2)))
            
            # Calculate projected point
            proj_lat = start_point[0] + t * (end_point[0] - start_point[0])
            proj_lon = start_point[1] + t * (end_point[1] - start_point[1])
            
            # Distance to projected point
            return self._haversine_distance(lat, lon, proj_lat, proj_lon)
            
        except Exception as e:
            logger.error(f"Error calculating point to line segment distance: {e}")
            return min(dist_to_start, dist_to_end)
    
    def _haversine_distance(self, lat1, lon1, lat2, lon2):
        """
        Calculate the great circle distance between two points using the Haversine formula
        """
        import math
        
        # Convert latitude and longitude from degrees to radians
        lat1_rad = math.radians(lat1)
        lon1_rad = math.radians(lon1)
        lat2_rad = math.radians(lat2)
        lon2_rad = math.radians(lon2)
        
        # Haversine formula
        dlat = lat2_rad - lat1_rad
        dlon = lon2_rad - lon1_rad
        
        a = (math.sin(dlat / 2) ** 2 + 
             math.cos(lat1_rad) * math.cos(lat2_rad) * math.sin(dlon / 2) ** 2)
        c = 2 * math.asin(math.sqrt(a))
        
        # Radius of Earth in kilometers
        earth_radius_km = 6371.0
        
        return earth_radius_km * c
    
    def _calculate_geodetic_distance(self, lat1, lon1, lat2, lon2):
        """
        Calculate geodetic distance between two points (wrapper for Haversine)
        """
        return self._haversine_distance(lat1, lon1, lat2, lon2)
    
    async def _basic_coordinate_heuristics(self, latitude, longitude):
        """
        Basic coordinate-based heuristics for coastal proximity (ultimate fallback)
        """
        try:
            # Very basic heuristics based on known geographic patterns
            
            # Check if coordinates are over known ocean areas
            if (
                # Pacific Ocean
                (-180 <= longitude <= -120 and 20 <= latitude <= 60) or
                (120 <= longitude <= 180 and -60 <= latitude <= 60) or
                # Atlantic Ocean  
                (-80 <= longitude <= -20 and 0 <= latitude <= 70) or
                (-60 <= longitude <= 20 and -60 <= latitude <= 0) or
                # Indian Ocean
                (20 <= longitude <= 120 and -60 <= latitude <= 30)
            ):
                return False  # Likely open ocean
            
            # Check if coordinates are in continental interiors
            if (
                # North America interior
                (-120 <= longitude <= -80 and 30 <= latitude <= 60) or
                # Asia interior
                (60 <= longitude <= 120 and 30 <= latitude <= 60) or
                # Africa interior
                (10 <= longitude <= 40 and -30 <= latitude <= 30) or
                # South America interior
                (-80 <= longitude <= -40 and -30 <= latitude <= 10)
            ):
                return False  # Likely continental interior
            
            # Default to potentially coastal for ambiguous areas
            return True
            
        except Exception as e:
            logger.error(f"Error in basic coordinate heuristics: {e}")
            return False
    
    def _get_onshore_direction(self, latitude, longitude):
        """Get onshore wind direction (simplified)"""
        # Very simplified - assumes wind blows from ocean to land
        if longitude < -60:  # Americas - easterly component
            return 90.0
        elif longitude > 100:  # Asia/Australia - westerly component
            return 270.0
        else:  # Europe/Africa - southerly component
            return 180.0
    
    def _get_offshore_direction(self, latitude, longitude):
        """Get offshore wind direction (simplified)"""
        # Opposite of onshore
        onshore = self._get_onshore_direction(latitude, longitude)
        return (onshore + 180.0) % 360.0
    
    async def _get_topographic_wind_effects(self, latitude, longitude):
        """Get topographic effects on wind patterns"""
        try:
            # Get local topography
            elevation_data = await self._get_high_resolution_elevation(latitude, longitude)
            elevation = elevation_data['elevation']
            
            # Get surrounding topography for gradient calculation
            topo_context = await self._get_topographic_context(latitude, longitude)
            
            # Calculate topographic effects
            direction_shift = 0.0
            speed_factor = 1.0
            
            # Elevation effects
            if elevation > 1000:  # High elevation
                speed_factor *= 1.2  # Increased wind speed
                
            # Valley channeling effects
            if topo_context.get('in_valley', False):
                valley_orientation = topo_context.get('valley_orientation', 0)
                direction_shift += valley_orientation * 0.3
                speed_factor *= 1.1
            
            # Mountain barrier effects
            if topo_context.get('mountain_barrier', False):
                barrier_orientation = topo_context.get('barrier_orientation', 0)
                direction_shift += barrier_orientation * 0.2
                speed_factor *= 0.8  # Reduced speed in lee
            
            return {
                'direction_shift': direction_shift,
                'speed_factor': speed_factor
            }
            
        except Exception as e:
            logger.error(f"Error getting topographic wind effects: {e}")
            return {'direction_shift': 0.0, 'speed_factor': 1.0}
    
    async def _get_coastal_wind_effects(self, latitude, longitude):
        """Get coastal effects on wind patterns"""
        try:
            # Check if location is coastal
            distance_to_coast = await self._get_distance_to_coast(latitude, longitude)
            
            if distance_to_coast > 50:  # More than 50km from coast
                return None
            
            # Get coastline orientation
            coastline_data = await self._get_coastline_data(latitude, longitude)
            
            if not coastline_data:
                return None
            
            # Calculate coastal effects
            from datetime import datetime
            hour = datetime.now().hour
            
            # Diurnal cycle effects (sea/land breeze)
            if 6 <= hour <= 18:  # Daytime - sea breeze
                direction_shift = coastline_data['onshore_direction'] - coastline_data['offshore_direction']
                speed_factor = 1.2
            else:  # Nighttime - land breeze
                direction_shift = coastline_data['offshore_direction'] - coastline_data['onshore_direction']
                speed_factor = 0.8
            
            # Distance decay
            distance_factor = np.exp(-distance_to_coast / 20.0)
            direction_shift *= distance_factor
            speed_factor = 1.0 + (speed_factor - 1.0) * distance_factor
            
            return {
                'direction_shift': direction_shift,
                'speed_factor': speed_factor
            }
            
        except Exception as e:
            logger.error(f"Error getting coastal wind effects: {e}")
            return None
    
    async def _get_topographic_context(self, latitude, longitude):
        """Get detailed topographic context for wind analysis"""
        try:
            # Get elevation data in a grid around the point
            grid_size = 0.01  # ~1km resolution
            elevations = []
            coords = []
            
            for i in range(-2, 3):
                for j in range(-2, 3):
                    lat = latitude + i * grid_size
                    lon = longitude + j * grid_size
                    elev_data = await self._get_high_resolution_elevation(lat, lon)
                    elevations.append(elev_data['elevation'])
                    coords.append((lat, lon))
            
            elevations = np.array(elevations).reshape(5, 5)
            
            # Calculate gradients
            grad_y, grad_x = np.gradient(elevations)
            
            # Determine topographic features
            center_elev = elevations[2, 2]
            max_elev = np.max(elevations)
            min_elev = np.min(elevations)
            
            # Valley detection
            in_valley = center_elev < (max_elev - min_elev) * 0.3 + min_elev
            
            # Mountain barrier detection
            mountain_barrier = (max_elev - center_elev) > 500
            
            # Calculate orientations
            valley_orientation = np.degrees(np.arctan2(grad_y[2, 2], grad_x[2, 2]))
            barrier_orientation = valley_orientation + 90  # Perpendicular to valley
            
            return {
                'in_valley': in_valley,
                'valley_orientation': valley_orientation,
                'mountain_barrier': mountain_barrier,
                'barrier_orientation': barrier_orientation,
                'elevation_range': max_elev - min_elev,
                'local_gradient': np.sqrt(grad_x[2, 2]**2 + grad_y[2, 2]**2)
            }
            
        except Exception as e:
            logger.error(f"Error getting topographic context: {e}")
            return {}
    
