    def _calculate_atmospheric_effects(self, lat, lon):
        """Calculate atmospheric effects on spectral bands"""
        # Simplified atmospheric model based on latitude and season
        from datetime import datetime
        
        day_of_year = datetime.now().timetuple().tm_yday
        
        # Atmospheric optical depth varies with latitude and season
        aod_factor = 0.1 + 0.05 * np.sin(np.radians(abs(lat)))  # Higher at equator
        seasonal_factor = 1.0 + 0.1 * np.cos(2 * np.pi * (day_of_year - 172) / 365.25)
        
        # Rayleigh scattering (stronger for shorter wavelengths)
        rayleigh_factors = {
            'Blue': 0.85, 'Green': 0.90, 'Red': 0.95,
            'NIR': 0.98, 'SWIR1': 0.99, 'SWIR2': 0.99
        }
        
        # Apply atmospheric effects
        atmospheric_effects = {}
        for band, rayleigh in rayleigh_factors.items():
            atmospheric_effects[band] = rayleigh * (1.0 - aod_factor * seasonal_factor)
        
        return atmospheric_effects
    
    async def _atmospheric_correction(self, satellite_data):
        """Apply advanced atmospheric correction to satellite imagery"""
        try:
            if not satellite_data or 'bands' not in satellite_data:
                return satellite_data
            
            bands = satellite_data['bands']
            corrected_bands = {}
            
            # Dark Object Subtraction (DOS) method
            for band_name, band_data in bands.items():
                # Find dark objects (water, shadows) for atmospheric correction
                dark_threshold = np.percentile(band_data, 1)  # 1st percentile
                
                # Apply DOS correction
                corrected_bands[band_name] = np.clip(
                    (band_data - dark_threshold) / (1.0 - dark_threshold), 0, 1
                )
            
            # Advanced 6S atmospheric correction with full radiative transfer modeling
            corrected_bands = await self._apply_advanced_6s_correction(corrected_bands, satellite_data)
            
            # Update satellite data
            corrected_data = satellite_data.copy()
            corrected_data['bands'] = corrected_bands
            corrected_data['atmospheric_correction'] = 'DOS_6S'
            
            return corrected_data
            
        except Exception as e:
            logger.error(f"Error in atmospheric correction: {e}")
            return satellite_data
    
    async def _apply_advanced_6s_correction(self, bands, satellite_data):
        """Apply advanced 6S atmospheric correction with full radiative transfer modeling"""
        try:
            from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
            import numpy as np
            from scipy.interpolate import RegularGridInterpolator
            
            # Get real atmospheric data from multiple sources
            atmospheric_data = await self._get_comprehensive_atmospheric_data(satellite_data)
            
            # Load pre-computed 6S lookup tables for Sentinel-2
            lut_6s = await self._load_comprehensive_6s_lut()
            
            corrected_bands = {}
            
            for band_name, band_data in bands.items():
                try:
                    # Get band-specific parameters
                    band_params = self._get_sentinel2_band_parameters(band_name)
                    
                    # Extract atmospheric parameters with spatial variation
                    water_vapor_map = atmospheric_data['water_vapor']
                    ozone_map = atmospheric_data['ozone']
                    aerosol_map = atmospheric_data['aerosol_optical_depth']
                    pressure_map = atmospheric_data['surface_pressure']
                    
                    # Calculate viewing geometry for each pixel
                    geometry_data = await self._calculate_pixel_geometry(satellite_data, band_data.shape)
                    
                    # Initialize correction arrays
                    corrected_data = np.zeros_like(band_data)
                    
                    # Process in blocks for memory efficiency
                    block_size = 256
                    for i in range(0, band_data.shape[0], block_size):
                        for j in range(0, band_data.shape[1], block_size):
                            # Extract block
                            i_end = min(i + block_size, band_data.shape[0])
                            j_end = min(j + block_size, band_data.shape[1])
                            
                            block_data = band_data[i:i_end, j:j_end]
                            block_wv = water_vapor_map[i:i_end, j:j_end]
                            block_ozone = ozone_map[i:i_end, j:j_end]
                            block_aod = aerosol_map[i:i_end, j:j_end]
                            block_pressure = pressure_map[i:i_end, j:j_end]
                            block_geometry = {
                                'solar_zenith': geometry_data['solar_zenith'][i:i_end, j:j_end],
                                'view_zenith': geometry_data['view_zenith'][i:i_end, j:j_end],
                                'relative_azimuth': geometry_data['relative_azimuth'][i:i_end, j:j_end]
                            }
                            
                            # Apply 6S correction to block
                            corrected_block = await self._apply_6s_to_block(
                                block_data, block_wv, block_ozone, block_aod, 
                                block_pressure, block_geometry, band_params, lut_6s
                            )
                            
                            corrected_data[i:i_end, j:j_end] = corrected_block
                    
                    corrected_bands[band_name] = corrected_data
                    
                except Exception as band_error:
                    logger.error(f"Error correcting band {band_name}: {band_error}")
                    corrected_bands[band_name] = band_data  # Fallback to uncorrected
            
            return corrected_bands
            
        except Exception as e:
            logger.error(f"Error in advanced 6S correction: {e}")
            return bands
    
