    async def _query_noaa_shoreline_data(self, latitude, longitude):
        """Query NOAA shoreline database with advanced coastal analysis"""
        try:
            from backend.core.real_data_connectors.usgs_connector import USGSVolcanoConnector
            import numpy as np
            
            # NOAA Digital Coast API endpoints
            noaa_base_url = "https://coast.noaa.gov/arcgis/rest/services"
            
            # Query multiple NOAA services
            services = {
                'shoreline': f"{noaa_base_url}/Shoreline/Shoreline/MapServer",
                'bathymetry': f"{noaa_base_url}/Bathymetry/ETOPO1/MapServer", 
                'coastal_change': f"{noaa_base_url}/CoastalChange/CoastalChange/MapServer",
                'sea_level': f"{noaa_base_url}/SeaLevel/SeaLevel/MapServer"
            }
            
            # Create search buffer around point
            buffer_degrees = 0.01  # ~1km buffer
            bbox = [
                longitude - buffer_degrees,
                latitude - buffer_degrees,
                longitude + buffer_degrees,
                latitude + buffer_degrees
            ]
            
            noaa_data = {}
            
            # Query shoreline data
            shoreline_params = {
                'f': 'json',
                'geometry': f"{bbox[0]},{bbox[1]},{bbox[2]},{bbox[3]}",
                'geometryType': 'esriGeometryEnvelope',
                'spatialRel': 'esriSpatialRelIntersects',
                'outFields': '*',
                'returnGeometry': 'true'
            }
            
            shoreline_response = await self._make_noaa_request(
                f"{services['shoreline']}/query", shoreline_params
            )
            
            if shoreline_response and 'features' in shoreline_response:
                shoreline_features = shoreline_response['features']
                
                # Process shoreline geometry
                coastline_distances = []
                for feature in shoreline_features:
                    if 'geometry' in feature:
                        geom = feature['geometry']
                        if geom['type'] == 'polyline':
                            for path in geom['paths']:
                                for point in path:
                                    dist = self._calculate_haversine_distance(
                                        latitude, longitude, point[1], point[0]
                                    )
                                    coastline_distances.append(dist)
                
                if coastline_distances:
                    noaa_data['min_distance_to_shore'] = min(coastline_distances)
                    noaa_data['shoreline_complexity'] = len(coastline_distances)
            
            # Query bathymetry data
            bathymetry_params = {
                'f': 'json',
                'geometry': f"{longitude},{latitude}",
                'geometryType': 'esriGeometryPoint',
                'layers': 'visible',
                'tolerance': 1,
                'mapExtent': f"{bbox[0]},{bbox[1]},{bbox[2]},{bbox[3]}",
                'imageDisplay': '400,400,96',
                'returnGeometry': 'false'
            }
            
            bathymetry_response = await self._make_noaa_request(
                f"{services['bathymetry']}/identify", bathymetry_params
            )
            
            if bathymetry_response and 'results' in bathymetry_response:
                for result in bathymetry_response['results']:
                    if 'attributes' in result:
                        attrs = result['attributes']
                        if 'Pixel Value' in attrs:
                            noaa_data['etopo1_elevation'] = attrs['Pixel Value']
            
            # Query coastal change data
            coastal_change_response = await self._make_noaa_request(
                f"{services['coastal_change']}/query", shoreline_params
            )
            
            if coastal_change_response and 'features' in coastal_change_response:
                change_rates = []
                for feature in coastal_change_response['features']:
                    if 'attributes' in feature:
                        attrs = feature['attributes']
                        if 'EPR' in attrs:  # End Point Rate
                            change_rates.append(attrs['EPR'])
                
                if change_rates:
                    noaa_data['coastal_change_rate'] = np.mean(change_rates)
                    noaa_data['coastal_stability'] = np.std(change_rates)
            
            return noaa_data if noaa_data else None
            
        except Exception as e:
            logger.error(f"Error querying NOAA shoreline data: {e}")
            return None
    
