    async def _calculate_precise_distance_to_coastlines(self, latitude, longitude):
        """Calculate precise distance to coastlines using multiple high-resolution datasets"""
        try:
            from backend.core.gis_database_integration import GISDatabaseIntegrator
            import numpy as np
            
            # Initialize GIS database integrator
            gis_db = GISDatabaseIntegrator(self.config)
            await gis_db.initialize()
            
            # Query high-resolution coastline datasets
            coastline_sources = [
                'gshhg_full_resolution',  # Global Self-consistent Hierarchical High-resolution Geography
                'natural_earth_coastline',
                'openstreetmap_coastline',
                'noaa_shoreline_vectors'
            ]
            
            min_distances = []
            
            for source in coastline_sources:
                try:
                    # Query coastline data within search radius
                    search_radius_km = 50  # 50km search radius
                    
                    coastline_query = f"""
                    SELECT ST_Distance(
                        ST_GeogFromText('POINT({longitude} {latitude})'),
                        geom
                    ) as distance_m,
                    ST_AsText(ST_ClosestPoint(geom, ST_GeogFromText('POINT({longitude} {latitude})'))) as closest_point
                    FROM {source}
                    WHERE ST_DWithin(
                        ST_GeogFromText('POINT({longitude} {latitude})'),
                        geom,
                        {search_radius_km * 1000}
                    )
                    ORDER BY distance_m
                    LIMIT 1;
                    """
                    
                    result = await gis_db.execute_spatial_query(coastline_query)
                    
                    if result and len(result) > 0:
                        distance_m = result[0]['distance_m']
                        min_distances.append(distance_m)
                        
                except Exception as source_error:
                    logger.warning(f"Error querying {source}: {source_error}")
                    continue
            
            if min_distances:
                # Use the minimum distance from all sources
                precise_distance = min(min_distances)
                
                # Validate using satellite-derived coastline detection
                satellite_distance = await self._validate_coastline_distance_satellite(
                    latitude, longitude, precise_distance
                )
                
                if satellite_distance is not None:
                    # Weight the results: 70% database, 30% satellite validation
                    final_distance = 0.7 * precise_distance + 0.3 * satellite_distance
                else:
                    final_distance = precise_distance
                
                return final_distance
            else:
                # Fallback to satellite-based detection
                return await self._satellite_based_coastline_detection(latitude, longitude)
                
        except Exception as e:
            logger.error(f"Error calculating precise distance to coastlines: {e}")
            # Ultimate fallback using simple geographic estimation
            return await self._geographic_coastline_estimation(latitude, longitude)
    
    async def _coastline_ensemble_analysis(self, coastline_results):
        """Perform ensemble analysis of multiple coastline detection methods"""
        try:
            valid_results = [r for r in coastline_results if r is not None]
            
            if not valid_results:
                return None
            
            if len(valid_results) == 1:
                return valid_results[0]
            
            # Weight results by confidence
            weights = [r['confidence'] for r in valid_results]
            total_weight = sum(weights)
            
            if total_weight == 0:
                return valid_results[0]
            
            # Calculate weighted average orientation
            orientations = [r['coastline_orientation'] for r in valid_results]
            
            # Handle circular averaging for angles
            sin_sum = sum(w * np.sin(np.radians(o)) for w, o in zip(weights, orientations))
            cos_sum = sum(w * np.cos(np.radians(o)) for w, o in zip(weights, orientations))
            
            ensemble_orientation = np.degrees(np.arctan2(sin_sum, cos_sum))
            ensemble_orientation = (ensemble_orientation + 360) % 360
            
            # Calculate ensemble confidence
            orientation_std = np.std(orientations)
            confidence_penalty = min(0.5, orientation_std / 45.0)  # Penalize high variance
            ensemble_confidence = (total_weight / len(valid_results)) * (1.0 - confidence_penalty)
            
            # Combine metadata from all sources
            analysis_methods = [r.get('analysis_method', 'unknown') for r in valid_results]
            
            return {
                'coastline_orientation': ensemble_orientation,
                'onshore_direction': (ensemble_orientation + 90) % 360,
                'offshore_direction': (ensemble_orientation - 90) % 360,
                'coastline_name': f"ensemble_{len(valid_results)}_sources",
                'confidence': min(0.95, ensemble_confidence),
                'analysis_method': 'multi_source_ensemble',
                'source_methods': analysis_methods,
                'source_count': len(valid_results),
                'orientation_std_deg': orientation_std,
                'individual_confidences': weights
            }
            
        except Exception as e:
            logger.error(f"Error in coastline ensemble analysis: {e}")
            return valid_results[0] if valid_results else None
    
    async def _database_coastline_analysis(self, latitude, longitude):
        """Fallback database-driven coastline analysis"""
        try:
            # Query existing geological database for coastline features
            async with self.db_integrator.get_postgresql_session() as session:
                coastline_query = """
                SELECT 
                    gs.structure_type,
                    gs.strike,
                    ST_Distance(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance_deg,
                    gs.properties
                FROM geological_structures gs
                WHERE gs.structure_type ILIKE '%coast%' 
                   OR gs.structure_type ILIKE '%shore%'
                   OR gs.structure_type ILIKE '%beach%'
                AND ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 0.5)
                ORDER BY distance_deg ASC
                LIMIT 5
                """
                
                result = await session.execute(coastline_query, 
                    (longitude, latitude, longitude, latitude))
                rows = result.fetchall()
                
                if rows:
                    closest_feature = rows[0]
                    
                    # Use strike as coastline orientation if available
                    if closest_feature.strike is not None:
                        orientation = closest_feature.strike
                    else:
                        # Estimate from structure type and location
                        orientation = await self._estimate_orientation_from_location(latitude, longitude)
                    
                    return {
                        'coastline_orientation': orientation,
                        'onshore_direction': (orientation + 90) % 360,
                        'offshore_direction': (orientation - 90) % 360,
                        'coastline_name': f"database_{closest_feature.structure_type}",
                        'distance_to_coastline_deg': closest_feature.distance_deg,
                        'distance_to_coastline_km': closest_feature.distance_deg * 111.0,
                        'confidence': max(0.2, 1.0 - closest_feature.distance_deg * 2),
                        'analysis_method': 'database_geological_structures',
                        'structure_type': closest_feature.structure_type
                    }
            
            return None
            
        except Exception as e:
            logger.error(f"Error in database coastline analysis: {e}")
            return None
    
    # Helper methods for coastline analysis
    
    def _calculate_contour_length(self, contour):
        """Calculate the length of a contour in degrees"""
        if len(contour) < 2:
            return 0.0
        
        total_length = 0.0
        for i in range(len(contour) - 1):
            dx = contour[i+1][0] - contour[i][0]
            dy = contour[i+1][1] - contour[i][1]
            total_length += np.sqrt(dx**2 + dy**2)
        
        return total_length
    
    def _calculate_contour_complexity(self, contour):
        """Calculate contour complexity (fractal-like measure)"""
        if len(contour) < 3:
            return 0.0
        
        # Calculate total length vs straight-line distance
        total_length = self._calculate_contour_length(contour)
        straight_distance = np.sqrt(
            (contour[-1][0] - contour[0][0])**2 + 
            (contour[-1][1] - contour[0][1])**2
        )
        
        if straight_distance == 0:
            return 0.0
        
        return total_length / straight_distance
    
    def _calculate_coastline_curvature(self, contour):
        """Calculate local curvature of coastline"""
        if len(contour) < 3:
            return 0.0
        
        curvatures = []
        for i in range(1, len(contour) - 1):
            p1 = np.array(contour[i-1])
            p2 = np.array(contour[i])
            p3 = np.array(contour[i+1])
            
            # Calculate curvature using three points
            v1 = p2 - p1
            v2 = p3 - p2
            
            cross_product = np.cross(v1, v2)
            v1_norm = np.linalg.norm(v1)
            v2_norm = np.linalg.norm(v2)
            
            if v1_norm > 0 and v2_norm > 0:
                curvature = abs(cross_product) / (v1_norm * v2_norm)
                curvatures.append(curvature)
        
        return np.mean(curvatures) if curvatures else 0.0
    
    def _calculate_coastline_roughness(self, contour):
        """Calculate coastline roughness index"""
        if len(contour) < 4:
            return 0.0
        
        # Calculate second derivatives (acceleration)
        second_derivatives = []
        for i in range(1, len(contour) - 1):
            p_prev = np.array(contour[i-1])
            p_curr = np.array(contour[i])
            p_next = np.array(contour[i+1])
            
            second_deriv = p_next - 2*p_curr + p_prev
            second_derivatives.append(np.linalg.norm(second_deriv))
        
        return np.mean(second_derivatives) if second_derivatives else 0.0
    
    def _calculate_fractal_dimension(self, contour):
        """Calculate fractal dimension of coastline"""
        if len(contour) < 4:
            return 1.0
        
        # Box-counting method (simplified)
        scales = [0.01, 0.02, 0.05, 0.1]  # Different box sizes in degrees
        counts = []
        
        for scale in scales:
            # Count boxes that contain part of the coastline
            min_x = min(p[0] for p in contour)
            max_x = max(p[0] for p in contour)
            min_y = min(p[1] for p in contour)
            max_y = max(p[1] for p in contour)
            
            boxes_x = int((max_x - min_x) / scale) + 1
            boxes_y = int((max_y - min_y) / scale) + 1
            
            occupied_boxes = set()
            
            for point in contour:
                box_x = int((point[0] - min_x) / scale)
                box_y = int((point[1] - min_y) / scale)
                occupied_boxes.add((box_x, box_y))
            
            counts.append(len(occupied_boxes))
        
        # Calculate fractal dimension from log-log slope
        if len(counts) >= 2 and all(c > 0 for c in counts):
            log_scales = np.log(scales)
            log_counts = np.log(counts)
            
            # Linear regression
            slope, _ = np.polyfit(log_scales, log_counts, 1)
            fractal_dimension = -slope
            
            return max(1.0, min(2.0, fractal_dimension))
        
        return 1.5  # Default value
    
    def _classify_coastline_type(self, curvature, roughness, fractal_dimension):
        """Classify coastline type based on geometric properties"""
        if curvature < 0.1 and roughness < 0.01:
            return "straight_beach"
        elif curvature > 0.5:
            return "highly_curved_bay"
        elif roughness > 0.05:
            return "rocky_irregular"
        elif fractal_dimension > 1.7:
            return "complex_fjord"
        elif fractal_dimension < 1.3:
            return "simple_coastline"
        else:
            return "moderate_complexity"
    
    def _find_zero_crossings(self, grid):
        """Find zero crossings in elevation/bathymetry grid"""
        zero_crossings = []
        
        for i in range(grid.shape[0] - 1):
            for j in range(grid.shape[1] - 1):
                # Check for sign changes (zero crossings)
                current = grid[i, j]
                right = grid[i, j+1]
                down = grid[i+1, j]
                
                if (current >= 0 and right < 0) or (current < 0 and right >= 0):
                    zero_crossings.append((i, j))
                elif (current >= 0 and down < 0) or (current < 0 and down >= 0):
                    zero_crossings.append((i, j))
        
        return zero_crossings
    
    def _point_to_line_distance(self, point, line_start, line_end):
        """Calculate distance from point to line segment"""
        px, py = point
        x1, y1 = line_start
        x2, y2 = line_end
        
        # Vector from line_start to line_end
        dx = x2 - x1
        dy = y2 - y1
        
        if dx == 0 and dy == 0:
            # Line is actually a point
            return np.sqrt((px - x1)**2 + (py - y1)**2)
        
        # Parameter t for closest point on line
        t = ((px - x1) * dx + (py - y1) * dy) / (dx**2 + dy**2)
        
        # Clamp t to [0, 1] to stay on line segment
        t = max(0, min(1, t))
        
        # Closest point on line segment
        closest_x = x1 + t * dx
        closest_y = y1 + t * dy
        
        # Distance from point to closest point on line
        return np.sqrt((px - closest_x)**2 + (py - closest_y)**2)
    
