    async def _enhanced_simple_precipitation_model(self, latitude, longitude, temperature):
        """Enhanced simple precipitation model as fallback"""
        try:
            # Base precipitation from latitude zones
            if abs(latitude) < 5:  # Equatorial
                base_precip = 2500
            elif abs(latitude) < 15:  # Tropical
                base_precip = 1800
            elif abs(latitude) < 25:  # Subtropical
                base_precip = 600
            elif abs(latitude) < 35:  # Mid-subtropical
                base_precip = 1000
            elif abs(latitude) < 50:  # Temperate
                base_precip = 1200
            elif abs(latitude) < 65:  # Subpolar
                base_precip = 800
            else:  # Polar
                base_precip = 300
            
            # Temperature effects
            temp_factor = max(0.3, 1.0 + (temperature - 15) / 30.0)
            
            # Continental vs oceanic
            is_oceanic = await self._is_oceanic_location(latitude, longitude)
            oceanic_factor = 1.3 if is_oceanic else 0.8
            
            # Longitude effects (simplified continental patterns)
            longitude_factor = 1.0 + 0.2 * np.cos(np.radians(longitude / 3))
            
            final_precip = base_precip * temp_factor * oceanic_factor * longitude_factor
            
            return max(final_precip, 50.0)
            
        except Exception as e:
            logger.error(f"Error in enhanced simple precipitation model: {e}")
            return 1000.0
    
