    async def _compute_advanced_physics_constraints(self, latitude, longitude, acquisition_date):
        """Compute advanced physics constraints using real DEM and atmospheric data"""
        try:
            # Get high-resolution elevation from USGS/NASA DEM data
            elevation_data = await self._get_high_resolution_elevation(latitude, longitude)
            
            # Compute barometric pressure with advanced atmospheric modeling
            pressure_profile = await self._compute_atmospheric_pressure_profile(
                latitude, longitude, elevation_data, acquisition_date
            )
            
            # Compute gravitational effects
            gravity_correction = await self._compute_gravity_correction(
                latitude, longitude, elevation_data
            )
            
            # Compute tidal effects
            tidal_correction = await self._compute_tidal_correction(
                latitude, longitude, acquisition_date
            )
            
            # Compute atmospheric water vapor effects
            water_vapor_delay = await self._compute_water_vapor_delay(
                latitude, longitude, acquisition_date
            )
            
            return [
                pressure_profile['surface_pressure'],
                pressure_profile['pressure_gradient'],
                gravity_correction,
                tidal_correction,
                water_vapor_delay
            ]
            
        except Exception as e:
            logger.error(f"Error computing advanced physics constraints: {e}")
            # Fallback to basic barometric formula
            elevation = await self._get_basic_elevation(latitude, longitude)
            pressure = 101325 * np.exp(-elevation / 8400)
            return [pressure, 0.0, 0.0, 0.0, 0.0]
    
    async def _compute_advanced_refractivity_loss(self, predictions, pressure_data, temperature_data, humidity_data):
        """Compute advanced atmospheric refractivity loss with multi-layer modeling"""
        try:
            # Multi-layer atmospheric refractivity model
            # Based on ITU-R P.453 recommendation for atmospheric refractivity
            
            # Convert inputs to numpy for computation
            pressure = pressure_data.detach().cpu().numpy()
            temperature = temperature_data.detach().cpu().numpy()
            humidity = humidity_data.detach().cpu().numpy() if humidity_data is not None else np.ones_like(pressure) * 50.0
            
            # Compute dry air refractivity
            N_dry = 77.6 * pressure / temperature
            
            # Compute water vapor pressure
            e_s = 6.1078 * np.exp(17.269 * (temperature - 273.15) / (temperature - 35.86))  # Saturation vapor pressure
            e = humidity / 100.0 * e_s  # Actual vapor pressure
            
            # Compute wet refractivity
            N_wet = 72.0 * e / temperature + 3.75e5 * e / (temperature ** 2)
            
            # Total refractivity
            N_total = N_dry + N_wet
            
            # Convert back to tensor
            device = predictions.device
            refractivity_tensor = torch.FloatTensor(N_total * 1e-6).to(device)
            
            # Compute loss with uncertainty weighting
            residuals = predictions.squeeze() - refractivity_tensor
            weights = 1.0 / (1.0 + torch.abs(residuals))  # Robust weighting
            
            return torch.mean(weights * residuals ** 2)
            
        except Exception as e:
            logger.error(f"Error computing advanced refractivity loss: {e}")
            # Fallback to simple model
            refractivity = 77.6 * pressure_data.squeeze() / temperature_data
            return torch.mean((predictions.squeeze() - refractivity * 1e-6) ** 2)
    
    async def _compute_advanced_atmospheric_loss(self, predictions, training_data, X_tensor):
        """Compute advanced physics-informed loss with multi-scale atmospheric modeling"""
        try:
            device = X_tensor.device
            
            if len(training_data['atmospheric_delays']) > 0:
                target_delays = torch.FloatTensor(training_data['atmospheric_delays']).to(device)
                
                # Multi-component loss function
                # 1. Data fitting loss
                data_loss = F.mse_loss(predictions.squeeze(), target_delays)
                
                # 2. Physics consistency loss
                physics_loss = await self._compute_physics_consistency_loss(predictions, X_tensor)
                
                # 3. Temporal smoothness loss
                temporal_loss = await self._compute_temporal_smoothness_loss(predictions, training_data)
                
                # 4. Spatial coherence loss
                spatial_loss = await self._compute_spatial_coherence_loss(predictions, training_data)
                
                # Weighted combination
                total_loss = (
                    0.4 * data_loss +
                    0.3 * physics_loss +
                    0.2 * temporal_loss +
                    0.1 * spatial_loss
                )
                
                return total_loss
            else:
                # Regularization loss when no target data
                return torch.mean(predictions ** 2) + 0.01 * torch.mean(torch.abs(predictions))
                
        except Exception as e:
            logger.error(f"Error computing advanced atmospheric loss: {e}")
            # Fallback to simple loss
            if len(training_data['atmospheric_delays']) > 0:
                target_delays = torch.FloatTensor(training_data['atmospheric_delays']).to(device)
                return F.mse_loss(predictions.squeeze(), target_delays)
            else:
                return torch.mean(predictions ** 2)
    
