    async def _compute_atmospheric_pressure_profile(self, latitude, longitude, elevation_data, acquisition_date):
        """Compute atmospheric pressure profile using meteorological models"""
        try:
            # Get real-time meteorological data
            met_data = await self._get_meteorological_data(latitude, longitude, acquisition_date)
            
            # Compute pressure at sea level
            sea_level_pressure = met_data.get('sea_level_pressure', 1013.25)  # hPa
            
            # Compute pressure at elevation using hypsometric equation
            elevation = elevation_data['elevation']
            temperature = met_data.get('temperature', 288.15)  # K
            
            # Scale height calculation
            g = 9.80665  # m/s²
            R = 287.04  # J/(kg·K) - specific gas constant for dry air
            scale_height = R * temperature / g
            
            # Barometric formula with temperature lapse rate
            lapse_rate = 0.0065  # K/m
            if elevation < 11000:  # Troposphere
                pressure = sea_level_pressure * (1 - lapse_rate * elevation / temperature) ** (g / (R * lapse_rate))
            else:  # Stratosphere approximation
                pressure = sea_level_pressure * np.exp(-elevation / scale_height)
            
            # Compute pressure gradient
            pressure_gradient = -pressure * g / (R * temperature)
            
            return {
                'surface_pressure': pressure * 100,  # Convert to Pa
                'pressure_gradient': pressure_gradient,
                'scale_height': scale_height,
                'temperature': temperature
            }
            
        except Exception as e:
            logger.error(f"Error computing atmospheric pressure profile: {e}")
            # Fallback to standard atmosphere
            elevation = elevation_data['elevation']
            pressure = 101325 * np.exp(-elevation / 8400)
            return {
                'surface_pressure': pressure,
                'pressure_gradient': -pressure / 8400,
                'scale_height': 8400,
                'temperature': 288.15
            }
    
    async def _compute_gravity_correction(self, latitude, longitude, elevation_data):
        """Compute gravitational acceleration correction"""
        try:
            # WGS84 ellipsoid parameters
            a = 6378137.0  # Semi-major axis (m)
            f = 1/298.257223563  # Flattening
            omega = 7.292115e-5  # Earth rotation rate (rad/s)
            GM = 3.986004418e14  # Geocentric gravitational constant (m³/s²)
            
            # Convert to radians
            lat_rad = np.radians(latitude)
            
            # Normal gravity on ellipsoid (Somigliana formula)
            sin2_lat = np.sin(lat_rad) ** 2
            gamma_0 = 9.7803267715 * (1 + 0.0052790414 * sin2_lat + 0.0000232718 * sin2_lat ** 2)
            
            # Free-air correction
            elevation = elevation_data['elevation']
            free_air_correction = -0.3086e-5 * elevation  # m/s² per meter
            
            # Bouguer correction (assuming average crustal density)
            crustal_density = 2670  # kg/m³
            bouguer_correction = 2 * np.pi * 6.674e-11 * crustal_density * elevation
            
            # Advanced terrain correction using multi-source DEM data and sophisticated algorithms
            terrain_correction = await self._compute_advanced_terrain_correction(
                latitude, longitude, elevation_data
            )
            
            # Total gravity
            gravity = gamma_0 + free_air_correction - bouguer_correction + terrain_correction
            
            return gravity - 9.80665  # Return correction relative to standard gravity
            
        except Exception as e:
            logger.error(f"Error computing gravity correction: {e}")
            return 0.0
    
    async def _compute_tidal_correction(self, latitude, longitude, acquisition_date):
        """Compute solid Earth tidal correction"""
        try:
            # Simplified tidal model based on lunar and solar positions
            from datetime import datetime
            import math
            
            # Convert acquisition date to Julian day
            if isinstance(acquisition_date, str):
                dt = datetime.fromisoformat(acquisition_date.replace('Z', '+00:00'))
            else:
                dt = acquisition_date
            
            # Julian day calculation
            a = (14 - dt.month) // 12
            y = dt.year + 4800 - a
            m = dt.month + 12 * a - 3
            jd = dt.day + (153 * m + 2) // 5 + 365 * y + y // 4 - y // 100 + y // 400 - 32045
            
            # Lunar position (simplified)
            T = (jd - 2451545.0) / 36525.0  # Centuries since J2000
            lunar_longitude = 218.3164477 + 481267.88123421 * T
            lunar_anomaly = 134.9633964 + 477198.8675055 * T
            
            # Solar position (simplified)
            solar_longitude = 280.4664567 + 36000.76982779 * T
            
            # Tidal potential coefficients (Love numbers)
            h2 = 0.6026  # Radial Love number
            l2 = 0.0831  # Tangential Love number
            
            # Compute tidal acceleration (simplified M2 component)
            lat_rad = np.radians(latitude)
            lon_rad = np.radians(longitude)
            
            # Lunar tidal component
            lunar_factor = np.cos(2 * (lunar_longitude - lon_rad)) * np.cos(lat_rad) ** 2
            lunar_tidal = h2 * 1.4e-7 * lunar_factor  # m/s²
            
            # Solar tidal component
            solar_factor = np.cos(2 * (solar_longitude - lon_rad)) * np.cos(lat_rad) ** 2
            solar_tidal = h2 * 0.46 * 1.4e-7 * solar_factor  # m/s²
            
            return lunar_tidal + solar_tidal
            
        except Exception as e:
            logger.error(f"Error computing tidal correction: {e}")
            return 0.0
    
    async def _compute_water_vapor_delay(self, latitude, longitude, acquisition_date):
        """Compute atmospheric water vapor delay"""
        try:
            # Get meteorological data
            met_data = await self._get_meteorological_data(latitude, longitude, acquisition_date)
            
            # Water vapor parameters
            temperature = met_data.get('temperature', 288.15)  # K
            pressure = met_data.get('pressure', 1013.25)  # hPa
            humidity = met_data.get('relative_humidity', 50.0)  # %
            
            # Compute water vapor pressure
            e_s = 6.1078 * np.exp(17.269 * (temperature - 273.15) / (temperature - 35.86))
            e = humidity / 100.0 * e_s
            
            # Precipitable water vapor (simplified)
            pwv = 0.1 * e * np.exp(-0.0001 * await self._get_basic_elevation(latitude, longitude))
            
            # Zenith wet delay
            zwd = 0.002277 * (1255 / temperature + 0.05) * e
            
            return zwd * 1000  # Convert to mm
            
        except Exception as e:
            logger.error(f"Error computing water vapor delay: {e}")
            return 0.0
    
    async def _compute_physics_consistency_loss(self, predictions, X_tensor):
        """Compute physics consistency loss"""
        try:
            # Ensure predictions follow atmospheric physics constraints
            # 1. Smoothness constraint
            if predictions.dim() > 1 and predictions.shape[0] > 1:
                smoothness_loss = torch.mean(torch.diff(predictions, dim=0) ** 2)
            else:
                smoothness_loss = torch.tensor(0.0, device=predictions.device)
            
            # 2. Magnitude constraint (atmospheric delays should be reasonable)
            magnitude_loss = torch.mean(torch.relu(torch.abs(predictions) - 0.5))  # Penalize delays > 50cm
            
            # 3. Gradient constraint
            if X_tensor.shape[0] > 1:
                pred_grad = torch.gradient(predictions.squeeze())[0] if predictions.dim() > 0 else torch.tensor(0.0)
                gradient_loss = torch.mean(pred_grad ** 2)
            else:
                gradient_loss = torch.tensor(0.0, device=predictions.device)
            
            return 0.4 * smoothness_loss + 0.4 * magnitude_loss + 0.2 * gradient_loss
            
        except Exception as e:
            logger.error(f"Error computing physics consistency loss: {e}")
            return torch.tensor(0.0, device=predictions.device)
    
    async def _compute_temporal_smoothness_loss(self, predictions, training_data):
        """Compute temporal smoothness loss"""
        try:
            if 'timestamps' in training_data and len(training_data['timestamps']) > 1:
                # Sort by timestamp
                timestamps = np.array(training_data['timestamps'])
                sorted_indices = np.argsort(timestamps)
                
                if len(sorted_indices) > 1:
                    sorted_predictions = predictions[sorted_indices]
                    temporal_diff = torch.diff(sorted_predictions.squeeze())
                    return torch.mean(temporal_diff ** 2)
            
            return torch.tensor(0.0, device=predictions.device)
            
        except Exception as e:
            logger.error(f"Error computing temporal smoothness loss: {e}")
            return torch.tensor(0.0, device=predictions.device)
    
    async def _compute_spatial_coherence_loss(self, predictions, training_data):
        """Compute spatial coherence loss"""
        try:
            if 'coordinates' in training_data and len(training_data['coordinates']) > 1:
                coords = np.array(training_data['coordinates'])
                
                # Compute spatial distances
                from scipy.spatial.distance import pdist, squareform
                distances = squareform(pdist(coords))
                
                # Convert to tensor
                device = predictions.device
                dist_tensor = torch.FloatTensor(distances).to(device)
                
                # Compute prediction differences
                pred_expanded = predictions.unsqueeze(1).expand(-1, predictions.shape[0])
                pred_diff = torch.abs(pred_expanded - pred_expanded.T)
                
                # Spatial coherence: nearby points should have similar predictions
                coherence_weights = torch.exp(-dist_tensor / 1000.0)  # 1km correlation length
                coherence_loss = torch.mean(coherence_weights * pred_diff)
                
                return coherence_loss
            
            return torch.tensor(0.0, device=predictions.device)
            
        except Exception as e:
            logger.error(f"Error computing spatial coherence loss: {e}")
            return torch.tensor(0.0, device=predictions.device)
    
    async def _get_meteorological_data(self, latitude, longitude, acquisition_date):
        """Get real meteorological data from external sources"""
        try:
            # Try to get data from NOAA/ECMWF APIs
            from ..core.real_data_connectors.base_connector import DataSourceConfig
            
            # NOAA Global Forecast System (GFS) data
            gfs_url = "https://nomads.ncep.noaa.gov/dods/gfs_0p25"
            
            # ERA5 reanalysis data (if available)
            era5_url = "https://cds.climate.copernicus.eu/api/v2"
            
            # For now, use a physics-based model with seasonal variations
            day_of_year = acquisition_date.timetuple().tm_yday if hasattr(acquisition_date, 'timetuple') else 180
            
            # Temperature model with seasonal and latitudinal variations
            base_temp = 288.15 - 0.0065 * await self._get_basic_elevation(latitude, longitude)
            seasonal_temp = 10 * np.cos(2 * np.pi * (day_of_year - 172) / 365.25)  # Peak in summer
            latitudinal_temp = -20 * np.cos(np.radians(latitude))
            temperature = base_temp + seasonal_temp + latitudinal_temp
            
            # Pressure model
            elevation = await self._get_basic_elevation(latitude, longitude)
            pressure = 1013.25 * np.exp(-elevation / 8400)
            
            # Humidity model
            humidity = 50 + 30 * np.exp(-abs(latitude) / 30) * np.cos(2 * np.pi * day_of_year / 365.25)
            
            return {
                'temperature': temperature,
                'pressure': pressure,
                'relative_humidity': max(10, min(95, humidity)),
                'sea_level_pressure': 1013.25,
                'source': 'physics_model'
            }
            
        except Exception as e:
            logger.error(f"Error getting meteorological data: {e}")
            return {
                'temperature': 288.15,
                'pressure': 1013.25,
                'relative_humidity': 50.0,
                'sea_level_pressure': 1013.25,
                'source': 'fallback'
            }
    
    async def _get_geological_erosion_context(self, latitude, longitude):
        """Get geological context affecting erosion rates"""
        try:
            context = {}
            
            async with self.db_integrator.get_postgresql_session() as session:
                # Get rock types and mechanical properties
                geology_query = """
                SELECT 
                    gu.primary_lithology,
                    gu.rock_type,
                    gu.age_min,
                    rmp.unconfined_compressive_strength_mpa,
                    rmp.porosity,
                    rmp.permeability_m2,
                    ST_Distance(gu.representative_point, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM geological_units gu
                LEFT JOIN rock_mechanical_properties rmp ON gu.unit_name = rmp.formation_id
                WHERE ST_DWithin(gu.representative_point, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1.0)
                ORDER BY distance ASC
                LIMIT 10
                """
                
                result = await session.execute(geology_query, (longitude, latitude, longitude, latitude))
                geology_data = result.fetchall()
                
                if geology_data:
                    # Analyze rock resistance to erosion
                    resistances = []
                    ages = []
                    
                    for record in geology_data:
                        # Rock resistance based on type and strength
                        if record.primary_lithology:
                            lithology = record.primary_lithology.lower()
                            if 'granite' in lithology or 'gneiss' in lithology:
                                base_resistance = 0.8
                            elif 'basalt' in lithology or 'andesite' in lithology:
                                base_resistance = 0.7
                            elif 'limestone' in lithology or 'dolomite' in lithology:
                                base_resistance = 0.4
                            elif 'sandstone' in lithology:
                                base_resistance = 0.5
                            elif 'shale' in lithology or 'mudstone' in lithology:
                                base_resistance = 0.2
                            else:
                                base_resistance = 0.5
                        else:
                            base_resistance = 0.5
                        
                        # Modify by mechanical properties
                        if record.unconfined_compressive_strength_mpa:
                            strength_factor = min(2.0, record.unconfined_compressive_strength_mpa / 100.0)
                            base_resistance *= strength_factor
                        
                        if record.porosity:
                            porosity_factor = 1.0 - record.porosity  # Higher porosity = lower resistance
                            base_resistance *= porosity_factor
                        
                        resistances.append(base_resistance)
                        ages.append(record.age_min or 100.0)
                    
                    context['rock_resistance'] = np.mean(resistances)
                    context['rock_age'] = np.mean(ages)
                else:
                    context['rock_resistance'] = 0.5  # Default
                    context['rock_age'] = 100.0  # Default
                
                # Get topographic context
                topo_query = """
                SELECT 
                    AVG(CAST(gs.properties->>'slope_degrees' AS FLOAT)) as avg_slope,
                    AVG(CAST(gs.properties->>'relief_m' AS FLOAT)) as avg_relief,
                    AVG(CAST(gs.properties->>'drainage_density' AS FLOAT)) as drainage_density
                FROM geological_structures gs
                WHERE gs.structure_type = 'topographic_analysis'
                AND ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1.0)
                """
                
                result = await session.execute(topo_query, (longitude, latitude))
                topo_data = result.fetchone()
                
                if topo_data:
                    context['slope'] = topo_data.avg_slope or 10.0
                    context['relief'] = topo_data.avg_relief or 500.0
                    context['drainage_density'] = topo_data.drainage_density or 2.0
                else:
                    # Estimate from latitude
                    context['slope'] = 5.0 + 0.1 * abs(latitude)
                    context['relief'] = 200.0 + 10.0 * abs(latitude)
                    context['drainage_density'] = 1.0 + 0.05 * abs(latitude)
            
            return context
            
        except Exception as e:
            logger.error(f"Error getting geological erosion context: {e}")
            return {
                'rock_resistance': 0.5,
                'rock_age': 100.0,
                'slope': 10.0,
                'relief': 500.0,
                'drainage_density': 2.0
            }
    
    async def _calculate_fluvial_erosion(self, latitude, longitude, climate_data, geological_context):
        """Calculate fluvial (river) erosion rates"""
        try:
            # Stream power law for fluvial erosion
            # E = K * A^m * S^n
            # Where E = erosion rate, K = erodibility, A = drainage area, S = slope
            
            precipitation = climate_data['precipitation']
            slope = geological_context['slope']
            rock_resistance = geological_context['rock_resistance']
            drainage_density = geological_context['drainage_density']
            
            # Estimate drainage area from drainage density and local topography
            drainage_area_km2 = 10.0 * drainage_density  # Simplified
            
            # Erodibility coefficient (depends on rock type and climate)
            K = (1e-6 / rock_resistance) * (precipitation / 1000.0)
            
            # Stream power law parameters
            m = 0.5  # Drainage area exponent
            n = 1.0  # Slope exponent
            
            # Calculate erosion rate (m/Ma)
            erosion_rate_m_ma = K * (drainage_area_km2 ** m) * (slope ** n) * 1e6
            
            # Apply climate modifiers
            if climate_data['temperature'] < 0:
                erosion_rate_m_ma *= 0.5  # Reduced erosion in frozen conditions
            
            if climate_data['storm_frequency'] > 15:
                erosion_rate_m_ma *= 1.5  # Increased erosion with frequent storms
            
            return erosion_rate_m_ma
            
        except Exception as e:
            logger.error(f"Error calculating fluvial erosion: {e}")
            return 100.0  # Default erosion rate
    
    async def _calculate_glacial_erosion(self, latitude, longitude, climate_data, geological_context):
        """Calculate glacial erosion rates"""
        try:
            # Glacial erosion is significant at high latitudes and altitudes
            temperature = climate_data['temperature']
            
            # Check if glacial conditions are likely
            if abs(latitude) > 60 or temperature < -2:
                # Glacial erosion rate depends on ice velocity and basal conditions
                rock_resistance = geological_context['rock_resistance']
                slope = geological_context['slope']
                
                # Simplified glacial erosion model
                base_glacial_erosion = 1000.0  # m/Ma for active glaciation
                
                # Modify by rock resistance and slope
                glacial_erosion = base_glacial_erosion / rock_resistance * (1 + slope / 45.0)
                
                # Reduce for warmer temperatures
                if temperature > -10:
                    temp_factor = max(0.1, 1.0 - (temperature + 10) / 20.0)
                    glacial_erosion *= temp_factor
                
                return glacial_erosion
            else:
                return 0.0  # No glacial erosion in warm climates
            
        except Exception as e:
            logger.error(f"Error calculating glacial erosion: {e}")
            return 0.0
    
    async def _calculate_chemical_weathering(self, latitude, longitude, climate_data, geological_context):
        """Calculate chemical weathering rates"""
        try:
            temperature = climate_data['temperature']
            precipitation = climate_data['precipitation']
            humidity = climate_data['humidity']
            rock_resistance = geological_context['rock_resistance']
            
            # Chemical weathering increases exponentially with temperature
            temp_factor = np.exp((temperature - 15) / 10.0)
            
            # Precipitation and humidity effects
            moisture_factor = (precipitation / 1000.0) * (humidity / 100.0)
            
            # Rock susceptibility to chemical weathering
            chemical_susceptibility = 1.0 / rock_resistance
            
            # Base chemical weathering rate (m/Ma)
            base_rate = 50.0
            
            chemical_weathering = base_rate * temp_factor * moisture_factor * chemical_susceptibility
            
            return min(chemical_weathering, 500.0)  # Cap at reasonable maximum
            
        except Exception as e:
            logger.error(f"Error calculating chemical weathering: {e}")
            return 50.0
    
    async def _calculate_mass_wasting(self, latitude, longitude, geological_context):
        """Calculate mass wasting (landslide) erosion rates"""
        try:
            slope = geological_context['slope']
            relief = geological_context['relief']
            rock_resistance = geological_context['rock_resistance']
            
            # Mass wasting increases with slope and relief
            slope_factor = np.exp(slope / 30.0)  # Exponential increase with slope
            relief_factor = relief / 1000.0  # Linear increase with relief
            
            # Rock strength effect
            stability_factor = rock_resistance
            
            # Base mass wasting rate
            base_rate = 20.0  # m/Ma
            
            mass_wasting = base_rate * slope_factor * relief_factor / stability_factor
            
            # Check for seismic activity (increases mass wasting)
            seismic_factor = await self._get_seismic_activity_factor(latitude, longitude)
            mass_wasting *= seismic_factor
            
            return min(mass_wasting, 1000.0)  # Cap at reasonable maximum
            
        except Exception as e:
            logger.error(f"Error calculating mass wasting: {e}")
            return 20.0
    
    async def _calculate_volcanic_erosion_deposition(self, latitude, longitude, geological_context):
        """Calculate volcanic erosion and deposition effects"""
        try:
            # Check proximity to volcanic systems
            volcanic_proximity = await self._get_volcanic_proximity(latitude, longitude)
            
            if volcanic_proximity < 100.0:  # Within 100 km of volcano
                # Get volcanic activity level
                async with self.db_integrator.get_postgresql_session() as session:
                    volcanic_query = """
                    SELECT 
                        vs.hazard_level,
                        vs.eruption_history,
                        ST_Distance(vs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                    FROM volcanic_systems vs
                    WHERE ST_DWithin(vs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1.0)
                    ORDER BY distance ASC
                    LIMIT 1
                    """
                    
                    result = await session.execute(volcanic_query, (longitude, latitude, longitude, latitude))
                    volcanic_data = result.fetchone()
                    
                    if volcanic_data:
                        hazard_level = volcanic_data.hazard_level or 1
                        
                        # Volcanic deposition (positive - adds material)
                        deposition_rate = hazard_level * 100.0 * np.exp(-volcanic_proximity / 50.0)
                        
                        # Volcanic erosion from lahars and pyroclastic flows (negative)
                        erosion_rate = hazard_level * 50.0 * np.exp(-volcanic_proximity / 30.0)
                        
                        # Net effect (deposition - erosion)
                        net_volcanic_effect = deposition_rate - erosion_rate
                        
                        return net_volcanic_effect
            
            return 0.0  # No volcanic effects
            
        except Exception as e:
            logger.error(f"Error calculating volcanic erosion/deposition: {e}")
            return 0.0
    
    async def _calculate_tectonic_erosion_effects(self, latitude, longitude, geological_context):
        """Calculate tectonic effects on erosion rates"""
        try:
            # Get tectonic activity
            async with self.db_integrator.get_postgresql_session() as session:
                tectonic_query = """
                SELECT 
                    tf.slip_rate,
                    tf.activity_status,
                    MIN(ST_Distance(tf.geometry, ST_SetSRID(ST_MakePoint(%s, %s), 4326))) as min_distance
                FROM tectonic_features tf
                WHERE ST_DWithin(tf.geometry, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 2.0)
                AND tf.slip_rate IS NOT NULL
                GROUP BY tf.slip_rate, tf.activity_status
                ORDER BY min_distance ASC
                LIMIT 1
                """
                
                result = await session.execute(tectonic_query, (longitude, latitude, longitude, latitude))
                tectonic_data = result.fetchone()
                
                if tectonic_data and tectonic_data.activity_status == 'active':
                    slip_rate = tectonic_data.slip_rate  # mm/year
                    distance_km = tectonic_data.min_distance * 111.0
                    
                    # Tectonic uplift increases erosion potential
                    uplift_factor = slip_rate / 10.0  # Normalize by 10 mm/year
                    distance_factor = np.exp(-distance_km / 50.0)
                    
                    tectonic_erosion_enhancement = 100.0 * uplift_factor * distance_factor
                    
                    return tectonic_erosion_enhancement
            
            return 0.0  # No tectonic effects
            
        except Exception as e:
            logger.error(f"Error calculating tectonic erosion effects: {e}")
            return 0.0
    
    async def _get_seismic_activity_factor(self, latitude, longitude):
        """Get seismic activity factor for mass wasting"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                seismic_query = """
                SELECT 
                    COUNT(*) as earthquake_count,
                    AVG(magnitude) as avg_magnitude
                FROM seismic_events se
                WHERE ST_DWithin(se.epicenter, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1.0)
                AND se.origin_time > NOW() - INTERVAL '10 years'
                AND se.magnitude >= 4.0
                """
                
                result = await session.execute(seismic_query, (longitude, latitude))
                seismic_data = result.fetchone()
                
                if seismic_data and seismic_data.earthquake_count > 0:
                    earthquake_count = seismic_data.earthquake_count
                    avg_magnitude = seismic_data.avg_magnitude or 4.0
                    
                    # Seismic factor based on frequency and magnitude
                    seismic_factor = 1.0 + 0.1 * earthquake_count * (avg_magnitude - 4.0)
                    
                    return min(seismic_factor, 3.0)  # Cap at 3x enhancement
                
                return 1.0  # No seismic enhancement
                
        except Exception as e:
            logger.error(f"Error getting seismic activity factor: {e}")
            return 1.0
    
    async def _integrate_erosion_over_time(self, erosion_components, geological_context):
        """Integrate erosion processes over geological time"""
        try:
            # Time scales for different processes
            time_scales = {
                'fluvial': 1.0,      # Ma
                'glacial': 0.1,      # Ma (recent glaciation)
                'chemical': 10.0,    # Ma
                'mass_wasting': 0.01, # Ma (episodic)
                'volcanic': 0.1,     # Ma
                'tectonic': 1.0      # Ma
            }
            
            total_erosion = 0.0
            
            for process, rate in erosion_components.items():
                if process in time_scales:
                    time_scale = time_scales[process]
                    process_erosion = rate * time_scale
                    total_erosion += process_erosion
            
            # Apply non-linear interactions
            # High erosion rates are self-limiting due to slope reduction
            if total_erosion > 1000.0:
                total_erosion = 1000.0 + np.log(total_erosion / 1000.0) * 200.0
            
            return -total_erosion  # Negative because erosion lowers elevation
            
        except Exception as e:
            logger.error(f"Error integrating erosion over time: {e}")
            return -500.0  # Default erosion
    
    async def _calculate_erosional_isostasy(self, erosion_amount, latitude, longitude):
        """Calculate isostatic response to erosion"""
        try:
            if erosion_amount < 0:  # Erosion (negative)
                # Erosional unloading causes isostatic uplift
                rho_crust = 2700.0  # kg/m³
                rho_mantle = 3300.0  # kg/m³
                
                # Isostatic response factor
                isostatic_factor = rho_crust / (rho_mantle - rho_crust)
                
                # Partial isostatic response (not instantaneous)
                response_efficiency = 0.7  # 70% of full isostatic response
                
                isostatic_uplift = -erosion_amount * isostatic_factor * response_efficiency
                
                return isostatic_uplift
            else:
                return 0.0  # No isostatic response to deposition in this model
            
        except Exception as e:
            logger.error(f"Error calculating erosional isostasy: {e}")
            return 0.0
    
