    async def _integrate_paleoclimate_proxies(self, latitude, longitude):
        """Integrate multiple paleoclimate proxy records from databases"""
        try:
            proxy_data = {}
            
            # Query paleoclimate proxy data from geological database
            async with self.db_integrator.get_postgresql_session() as session:
                proxy_query = """
                SELECT 
                    gs.age,
                    gs.properties->>'proxy_type' as proxy_type,
                    gs.properties->>'temperature_c' as temperature,
                    gs.properties->>'precipitation_mm' as precipitation,
                    gs.properties->>'co2_ppm' as co2_concentration,
                    gs.properties->>'ice_volume' as ice_volume,
                    gs.properties->>'sea_level_m' as sea_level,
                    gs.properties->>'isotope_d18o' as delta_18o,
                    gs.properties->>'isotope_d13c' as delta_13c,
                    gs.confidence_level,
                    gs.data_quality_grade,
                    ST_Distance(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM geological_structures gs
                WHERE gs.structure_type = 'paleoclimate_proxy'
                AND ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 10.0)
                AND gs.age IS NOT NULL
                AND gs.age <= 65.0
                ORDER BY gs.age ASC, distance ASC
                """
                
                result = await session.execute(proxy_query, (longitude, latitude, longitude, latitude))
                proxy_records = result.fetchall()
                
                if proxy_records:
                    # Organize proxy data by type and age
                    for record in proxy_records:
                        age_ma = record.age
                        proxy_type = record.proxy_type or 'unknown'
                        
                        if proxy_type not in proxy_data:
                            proxy_data[proxy_type] = []
                        
                        proxy_entry = {
                            'age_ma': age_ma,
                            'temperature_c': float(record.temperature) if record.temperature else None,
                            'precipitation_mm': float(record.precipitation) if record.precipitation else None,
                            'co2_ppm': float(record.co2_concentration) if record.co2_concentration else None,
                            'ice_volume': float(record.ice_volume) if record.ice_volume else None,
                            'sea_level_m': float(record.sea_level) if record.sea_level else None,
                            'delta_18o': float(record.delta_18o) if record.delta_18o else None,
                            'delta_13c': float(record.delta_13c) if record.delta_13c else None,
                            'confidence': record.confidence_level or 0.5,
                            'quality': record.data_quality_grade or 'C',
                            'distance_km': record.distance * 111.0
                        }
                        
                        proxy_data[proxy_type].append(proxy_entry)
            
            # Supplement with external paleoclimate databases
            external_proxies = await self._fetch_external_paleoclimate_proxies(latitude, longitude)
            
            # Merge external data with database records
            for proxy_type, records in external_proxies.items():
                if proxy_type in proxy_data:
                    proxy_data[proxy_type].extend(records)
                else:
                    proxy_data[proxy_type] = records
            
            return proxy_data
            
        except Exception as e:
            logger.error(f"Error integrating paleoclimate proxies: {e}")
            return {}
    
    async def _reconstruct_isotope_temperatures(self, latitude, longitude, proxy_data):
        """Reconstruct temperature using oxygen isotope paleothermometry"""
        try:
            temperature_reconstruction = {}
            
            # Process marine foraminiferal δ18O records
            if 'marine_foraminifera' in proxy_data:
                marine_temps = []
                
                for record in proxy_data['marine_foraminifera']:
                    if record.get('delta_18o') is not None:
                        # Shackleton (1974) paleotemperature equation
                        # T(°C) = 16.9 - 4.38(δ18O_calcite - δ18O_water) + 0.10(δ18O_calcite - δ18O_water)²
                        
                        delta_18o_calcite = record['delta_18o']
                        
                        # Estimate δ18O of seawater (varies with ice volume)
                        ice_volume = record.get('ice_volume', 0.0)
                        delta_18o_seawater = -1.0 + ice_volume * 1.2  # Simplified ice volume effect
                        
                        # Calculate temperature
                        delta_diff = delta_18o_calcite - delta_18o_seawater
                        temperature = 16.9 - 4.38 * delta_diff + 0.10 * delta_diff**2
                        
                        marine_temps.append({
                            'age_ma': record['age_ma'],
                            'temperature_c': temperature,
                            'confidence': record['confidence'],
                            'method': 'foraminiferal_d18o'
                        })
                
                temperature_reconstruction['marine_isotope'] = marine_temps
            
            # Process ice core δ18O records
            if 'ice_cores' in proxy_data:
                ice_temps = []
                
                for record in proxy_data['ice_cores']:
                    if record.get('delta_18o') is not None:
                        # Dansgaard (1964) relationship for ice cores
                        # ΔT = 1.5 * Δδ18O (for Greenland)
                        # Regional calibration needed
                        
                        delta_18o = record['delta_18o']
                        
                        # Regional calibration factors
                        if abs(latitude) > 60:  # Polar regions
                            calibration_factor = 1.5
                        elif abs(latitude) > 40:  # Mid-latitudes
                            calibration_factor = 2.0
                        else:  # Lower latitudes
                            calibration_factor = 2.5
                        
                        # Reference δ18O for modern conditions
                        modern_d18o = -35.0 if abs(latitude) > 60 else -25.0
                        
                        temperature_anomaly = calibration_factor * (delta_18o - modern_d18o)
                        modern_temp = await self._estimate_mean_temperature(latitude, longitude)
                        
                        ice_temps.append({
                            'age_ma': record['age_ma'],
                            'temperature_c': modern_temp + temperature_anomaly,
                            'confidence': record['confidence'],
                            'method': 'ice_core_d18o'
                        })
                
                temperature_reconstruction['ice_core_isotope'] = ice_temps
            
            # Process speleothem δ18O records
            if 'speleothems' in proxy_data:
                speleothem_temps = []
                
                for record in proxy_data['speleothems']:
                    if record.get('delta_18o') is not None:
                        # Speleothem δ18O reflects both temperature and precipitation δ18O
                        # Hendy et al. (2002) calibration
                        
                        delta_18o = record['delta_18o']
                        
                        # Regional precipitation δ18O model
                        precip_d18o = -8.0 + 0.2 * latitude  # Simplified latitudinal gradient
                        
                        # Temperature sensitivity (varies by region)
                        temp_sensitivity = 0.24  # ‰/°C (typical for mid-latitudes)
                        
                        # Calculate temperature anomaly
                        modern_speleothem_d18o = -6.0  # Typical modern value
                        temp_anomaly = (delta_18o - modern_speleothem_d18o) / temp_sensitivity
                        
                        modern_temp = await self._estimate_mean_temperature(latitude, longitude)
                        
                        speleothem_temps.append({
                            'age_ma': record['age_ma'],
                            'temperature_c': modern_temp + temp_anomaly,
                            'confidence': record['confidence'] * 0.8,  # Lower confidence due to complexity
                            'method': 'speleothem_d18o'
                        })
                
                temperature_reconstruction['speleothem_isotope'] = speleothem_temps
            
            return temperature_reconstruction
            
        except Exception as e:
            logger.error(f"Error reconstructing isotope temperatures: {e}")
            return {}
    
