    async def _integrate_ice_core_paleoclimate(self, latitude, longitude):
        """Integrate ice core paleoclimate data with regional scaling"""
        try:
            ice_core_data = {}
            
            # Query ice core proxy data
            async with self.db_integrator.get_postgresql_session() as session:
                ice_core_query = """
                SELECT 
                    gs.age,
                    gs.properties->>'ice_core_site' as site_name,
                    gs.properties->>'temperature_anomaly_c' as temp_anomaly,
                    gs.properties->>'accumulation_rate' as accumulation,
                    gs.properties->>'dust_flux' as dust_flux,
                    gs.properties->>'volcanic_sulfate' as volcanic_sulfate,
                    gs.properties->>'atmospheric_co2' as co2_ppm,
                    gs.properties->>'atmospheric_ch4' as ch4_ppb,
                    gs.confidence_level,
                    ST_Distance(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM geological_structures gs
                WHERE gs.structure_type = 'ice_core_record'
                AND gs.age IS NOT NULL
                AND gs.age <= 0.8  -- Last 800 ka (typical ice core range)
                ORDER BY gs.age ASC
                """
                
                result = await session.execute(ice_core_query, (longitude, latitude))
                ice_records = result.fetchall()
                
                if ice_records:
                    # Process ice core records with regional scaling
                    temperature_records = []
                    atmospheric_records = []
                    
                    for record in ice_records:
                        distance_km = record.distance * 111.0
                        
                        # Regional temperature scaling
                        if record.temp_anomaly:
                            temp_anomaly = float(record.temp_anomaly)
                            
                            # Scale temperature anomaly by distance and latitude
                            distance_factor = np.exp(-distance_km / 2000.0)  # 2000 km scale
                            latitude_factor = np.cos(np.radians(abs(latitude) - abs(record.distance)))
                            
                            scaled_temp_anomaly = temp_anomaly * distance_factor * latitude_factor
                            
                            temperature_records.append({
                                'age_ma': record.age,
                                'temperature_anomaly_c': scaled_temp_anomaly,
                                'confidence': record.confidence_level or 0.7,
                                'site': record.site_name,
                                'distance_km': distance_km
                            })
                        
                        # Atmospheric composition records
                        if record.co2_ppm or record.ch4_ppb:
                            atmospheric_records.append({
                                'age_ma': record.age,
                                'co2_ppm': float(record.co2_ppm) if record.co2_ppm else None,
                                'ch4_ppb': float(record.ch4_ppb) if record.ch4_ppb else None,
                                'confidence': record.confidence_level or 0.8
                            })
                    
                    ice_core_data['temperature'] = temperature_records
                    ice_core_data['atmospheric_composition'] = atmospheric_records
            
            return ice_core_data
            
        except Exception as e:
            logger.error(f"Error integrating ice core paleoclimate: {e}")
            return {}
    
    async def _calculate_orbital_climate_forcing(self, latitude, longitude):
        """Calculate orbital forcing effects on paleoclimate using Milankovitch cycles"""
        try:
            orbital_forcing = {}
            
            # Time series for last 65 Ma
            time_points = np.arange(0, 65.1, 0.1)  # 100 ka resolution
            
            # Orbital parameters (simplified astronomical solution)
            eccentricity = []
            obliquity = []
            precession = []
            insolation = []
            
            for age_ma in time_points:
                # Eccentricity cycle (100 ka and 400 ka components)
                ecc = 0.0167 + 0.02 * np.sin(2 * np.pi * age_ma / 0.1) + 0.01 * np.sin(2 * np.pi * age_ma / 0.4)
                eccentricity.append(ecc)
                
                # Obliquity cycle (41 ka)
                obl = 23.5 + 1.5 * np.sin(2 * np.pi * age_ma / 0.041)
                obliquity.append(obl)
                
                # Precession cycle (19-23 ka)
                prec = np.sin(2 * np.pi * age_ma / 0.021)
                precession.append(prec)
                
                # Calculate insolation at given latitude
                # Simplified Berger (1978) formula
                lat_rad = np.radians(latitude)
                obl_rad = np.radians(obl)
                
                # Summer solstice insolation
                if latitude >= 0:  # Northern hemisphere
                    solar_constant = 1365  # W/m²
                    insolation_val = solar_constant * (1 + ecc * np.cos(prec)) * np.sin(lat_rad) * np.sin(obl_rad)
                else:  # Southern hemisphere
                    solar_constant = 1365
                    insolation_val = solar_constant * (1 + ecc * np.cos(prec + np.pi)) * np.sin(lat_rad) * np.sin(obl_rad)
                
                insolation.append(insolation_val)
            
            orbital_forcing = {
                'time_ma': time_points.tolist(),
                'eccentricity': eccentricity,
                'obliquity': obliquity,
                'precession': precession,
                'insolation_w_m2': insolation,
                'latitude': latitude
            }
            
            # Calculate climate sensitivity to orbital forcing
            climate_sensitivity = await self._calculate_orbital_climate_sensitivity(latitude, longitude)
            orbital_forcing['climate_sensitivity'] = climate_sensitivity
            
            return orbital_forcing
            
        except Exception as e:
            logger.error(f"Error calculating orbital climate forcing: {e}")
            return {}
    
    async def _ml_paleoclimate_synthesis(self, isotope_temps, marine_records, terrestrial_records,
                                       ice_core_data, speleothem_data, palynological_data,
                                       geochemical_proxies, orbital_forcing, tectonic_paleoclimate,
                                       volcanic_paleoclimate, latitude, longitude):
        """Machine learning synthesis of paleoclimate data using ensemble methods"""
        try:
            from sklearn.ensemble import RandomForestRegressor, GradientBoostingRegressor
            from sklearn.gaussian_process import GaussianProcessRegressor
            from sklearn.preprocessing import StandardScaler
            from sklearn.model_selection import cross_val_score
            import pandas as pd
            
            # Compile all paleoclimate data into unified time series
            unified_data = await self._compile_unified_paleoclimate_dataset(
                isotope_temps, marine_records, terrestrial_records,
                ice_core_data, speleothem_data, palynological_data,
                geochemical_proxies, orbital_forcing, tectonic_paleoclimate,
                volcanic_paleoclimate
            )
            
            if not unified_data or len(unified_data) < 10:
                return await self._fallback_paleoclimate_model(latitude, longitude)
            
            # Convert to DataFrame for ML processing
            df = pd.DataFrame(unified_data)
            
            # Feature engineering
            features = []
            targets = []
            
            for _, row in df.iterrows():
                feature_vector = []
                
                # Temporal features
                feature_vector.append(row.get('age_ma', 0))
                feature_vector.append(np.sin(2 * np.pi * row.get('age_ma', 0) / 0.1))  # 100 ka cycle
                feature_vector.append(np.sin(2 * np.pi * row.get('age_ma', 0) / 0.041))  # 41 ka cycle
                feature_vector.append(np.sin(2 * np.pi * row.get('age_ma', 0) / 0.021))  # 21 ka cycle
                
                # Orbital features
                feature_vector.append(row.get('eccentricity', 0.0167))
                feature_vector.append(row.get('obliquity', 23.5))
                feature_vector.append(row.get('precession', 0))
                feature_vector.append(row.get('insolation', 400))
                
                # Proxy data features
                feature_vector.append(row.get('marine_temperature', 15))
                feature_vector.append(row.get('terrestrial_temperature', 15))
                feature_vector.append(row.get('ice_core_temperature', 15))
                feature_vector.append(row.get('co2_ppm', 280))
                feature_vector.append(row.get('ice_volume', 0))
                feature_vector.append(row.get('sea_level', 0))
                
                # Tectonic and volcanic features
                feature_vector.append(row.get('tectonic_uplift_rate', 0))
                feature_vector.append(row.get('volcanic_forcing', 0))
                
                # Geographic features
                feature_vector.append(latitude)
                feature_vector.append(longitude)
                feature_vector.append(abs(latitude))  # Distance from equator
                
                features.append(feature_vector)
                
                # Target variables
                target_temp = row.get('consensus_temperature', 15)
                target_precip = row.get('consensus_precipitation', 1000)
                targets.append([target_temp, target_precip])
            
            features = np.array(features)
            targets = np.array(targets)
            
            # Standardize features
            scaler = StandardScaler()
            features_scaled = scaler.fit_transform(features)
            
            # Ensemble ML models
            models = {
                'random_forest': RandomForestRegressor(n_estimators=100, random_state=42),
                'gradient_boosting': GradientBoostingRegressor(n_estimators=100, random_state=42),
                'gaussian_process': GaussianProcessRegressor(random_state=42)
            }
            
            # Train ensemble models
            trained_models = {}
            model_scores = {}
            
            for model_name, model in models.items():
                try:
                    model.fit(features_scaled, targets)
                    
                    # Cross-validation score
                    cv_scores = cross_val_score(model, features_scaled, targets, cv=5, scoring='neg_mean_squared_error')
                    model_scores[model_name] = -np.mean(cv_scores)
                    
                    trained_models[model_name] = model
                    
                except Exception as e:
                    logger.warning(f"Failed to train {model_name}: {e}")
            
            # Generate paleoclimate predictions
            time_grid = np.arange(0, 65.1, 0.1)
            paleoclimate_predictions = []
            
            for age_ma in time_grid:
                # Create feature vector for prediction
                pred_features = [
                    age_ma,
                    np.sin(2 * np.pi * age_ma / 0.1),
                    np.sin(2 * np.pi * age_ma / 0.041),
                    np.sin(2 * np.pi * age_ma / 0.021),
                    0.0167 + 0.02 * np.sin(2 * np.pi * age_ma / 0.1),  # Eccentricity
                    23.5 + 1.5 * np.sin(2 * np.pi * age_ma / 0.041),   # Obliquity
                    np.sin(2 * np.pi * age_ma / 0.021),                # Precession
                    400,  # Baseline insolation
                    15, 15, 15,  # Baseline temperatures
                    280, 0, 0,   # Baseline CO2, ice volume, sea level
                    0, 0,        # Baseline tectonic and volcanic
                    latitude, longitude, abs(latitude)
                ]
                
                pred_features_scaled = scaler.transform([pred_features])
                
                # Ensemble prediction
                ensemble_predictions = []
                ensemble_weights = []
                
                for model_name, model in trained_models.items():
                    try:
                        prediction = model.predict(pred_features_scaled)[0]
                        weight = 1.0 / (model_scores[model_name] + 1e-6)  # Inverse error weighting
                        
                        ensemble_predictions.append(prediction)
                        ensemble_weights.append(weight)
                        
                    except Exception as e:
                        logger.warning(f"Prediction failed for {model_name}: {e}")
                
                if ensemble_predictions:
                    # Weighted ensemble average
                    ensemble_weights = np.array(ensemble_weights)
                    ensemble_weights /= np.sum(ensemble_weights)
                    
                    final_prediction = np.average(ensemble_predictions, axis=0, weights=ensemble_weights)
                    
                    paleoclimate_predictions.append({
                        'age_ma': age_ma,
                        'temperature_c': final_prediction[0],
                        'precipitation_mm': final_prediction[1],
                        'confidence': np.mean(ensemble_weights),
                        'model_count': len(ensemble_predictions)
                    })
            
            return {
                'ml_predictions': paleoclimate_predictions,
                'model_performance': model_scores,
                'feature_importance': await self._analyze_feature_importance(trained_models, scaler),
                'uncertainty_bounds': await self._calculate_ml_uncertainty_bounds(paleoclimate_predictions)
            }
            
        except Exception as e:
            logger.error(f"Error in ML paleoclimate synthesis: {e}")
            return await self._fallback_paleoclimate_model(latitude, longitude)
    
