    async def _synthesize_regional_paleoclimate(self, enhanced_data, uncertainty_analysis, latitude, longitude):
        """Synthesize regional paleoclimate with corrections"""
        try:
            # Extract ML predictions if available
            if 'ml_predictions' in enhanced_data:
                predictions = enhanced_data['ml_predictions']
                
                # Calculate trends and statistics
                temperature_trend = 0.0
                precipitation_trend = 0.0
                glaciation_periods = []
                
                if len(predictions) > 1:
                    # Calculate linear trends
                    ages = [p['age_ma'] for p in predictions]
                    temps = [p['temperature_c'] for p in predictions]
                    precips = [p['precipitation_mm'] for p in predictions]
                    
                    # Linear regression for trends
                    temp_trend_coeff = np.polyfit(ages, temps, 1)[0]
                    precip_trend_coeff = np.polyfit(ages, precips, 1)[0]
                    
                    temperature_trend = temp_trend_coeff  # °C/Ma
                    precipitation_trend = precip_trend_coeff  # mm/year/Ma
                    
                    # Identify glaciation periods (temperature < threshold)
                    modern_temp = await self._estimate_mean_temperature(latitude, longitude)
                    glaciation_threshold = modern_temp - 5.0  # 5°C below modern
                    
                    in_glaciation = False
                    glaciation_start = None
                    
                    for pred in sorted(predictions, key=lambda x: x['age_ma'], reverse=True):
                        if pred['temperature_c'] < glaciation_threshold:
                            if not in_glaciation:
                                glaciation_start = pred['age_ma']
                                in_glaciation = True
                        else:
                            if in_glaciation:
                                glaciation_periods.append({
                                    'start_ma': glaciation_start,
                                    'end_ma': pred['age_ma'],
                                    'intensity': (glaciation_threshold - min(temps)) / 10.0
                                })
                                in_glaciation = False
                
                return {
                    'temperature_trend': temperature_trend,
                    'precipitation_trend': precipitation_trend,
                    'glaciation_periods': glaciation_periods,
                    'ml_predictions': predictions,
                    'uncertainty': uncertainty_analysis,
                    'regional_factors': await self._assess_regional_paleoclimate_factors(latitude, longitude)
                }
            
            # Fallback if no ML predictions
            return await self._fallback_paleoclimate_model(latitude, longitude)
            
        except Exception as e:
            logger.error(f"Error synthesizing regional paleoclimate: {e}")
            return await self._fallback_paleoclimate_model(latitude, longitude)
    
