    async def _fallback_paleoclimate_model(self, latitude, longitude):
        """Fallback paleoclimate model using established knowledge"""
        try:
            # Enhanced fallback based on established paleoclimate knowledge
            paleoclimate = {
                'temperature_trend': -0.8,  # Cenozoic cooling trend
                'precipitation_trend': -50.0,  # Gradual drying trend
                'glaciation_periods': []
            }
            
            # Regional glaciation patterns
            if abs(latitude) > 60:  # High latitudes
                paleoclimate['glaciation_periods'] = [
                    {'start_ma': 2.6, 'end_ma': 0.0, 'intensity': 0.9},  # Quaternary
                    {'start_ma': 34.0, 'end_ma': 23.0, 'intensity': 0.6}  # Oligocene
                ]
            elif abs(latitude) > 40:  # Mid-latitudes
                paleoclimate['glaciation_periods'] = [
                    {'start_ma': 2.6, 'end_ma': 0.0, 'intensity': 0.5},  # Quaternary (reduced)
                ]
            
            # Tectonic and geographic modifications
            if 'Himalayas' in await self._get_regional_tectonic_context(latitude, longitude):
                paleoclimate['temperature_trend'] -= 0.3  # Enhanced cooling from uplift
            
            return paleoclimate
            
        except Exception as e:
            logger.error(f"Error in fallback paleoclimate model: {e}")
            return {
                'temperature_trend': -0.5,
                'precipitation_trend': 0.0,
                'glaciation_periods': []
            }
    
