    async def _simplified_erosion_calculation(self, latitude, longitude):
        """Simplified erosion calculation as fallback"""
        try:
            # Basic climate estimation
            annual_precip = 1000 + 500 * np.cos(np.radians(latitude * 2))
            mean_temp = 25 - 0.5 * abs(latitude)
            
            # Simple erosion rate model
            erosion_rate_mm_yr = 0.05 * (annual_precip / 1000.0) * np.exp(-abs(mean_temp - 15) / 25.0)
            
            # Cumulative erosion over 5 Ma
            geological_time_ma = 5.0
            cumulative_erosion_m = erosion_rate_mm_yr * geological_time_ma * 1e6 / 1000.0
            
            return -cumulative_erosion_m  # Negative for erosion
            
        except Exception as e:
            logger.error(f"Error in simplified erosion calculation: {e}")
            return -250.0  # Default erosion
    
    async def _estimate_annual_precipitation(self, latitude, longitude):
        """Advanced precipitation estimation using satellite data and climate models"""
        from backend.core.real_data_connectors.copernicus_connector import CopernicusConnector
        from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
        
        try:
            # First try to get precipitation data from database
            async with self.db_integrator.get_postgresql_session() as session:
                precip_query = """
                SELECT 
                    cd.annual_precipitation_mm,
                    cd.seasonal_variation,
                    cd.data_source,
                    cd.measurement_period,
                    ST_Distance(cd.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM climate_data cd
                WHERE ST_DWithin(cd.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1.0)
                AND cd.annual_precipitation_mm IS NOT NULL
                ORDER BY distance ASC, cd.measurement_period DESC
                LIMIT 10
                """
                
                result = await session.execute(precip_query, (longitude, latitude, longitude, latitude))
                precip_data = result.fetchall()
                
                if precip_data:
                    # Calculate distance-weighted average
                    weighted_precip = 0.0
                    total_weight = 0.0
                    
                    for record in precip_data:
                        weight = 1.0 / (record.distance + 0.01)  # Inverse distance weighting
                        
                        # Quality weight based on data source
                        source_weights = {
                            'weather_station': 1.0,
                            'satellite_gpm': 0.9,
                            'satellite_trmm': 0.8,
                            'reanalysis_era5': 0.7,
                            'interpolated': 0.5
                        }
                        source_weight = source_weights.get(record.data_source, 0.6)
                        
                        final_weight = weight * source_weight
                        weighted_precip += record.annual_precipitation_mm * final_weight
                        total_weight += final_weight
                    
                    if total_weight > 0:
                        observed_precip = weighted_precip / total_weight
                        
                        # Apply topographic and orographic corrections
                        corrected_precip = await self._apply_orographic_corrections(
                            latitude, longitude, observed_precip
                        )
                        
                        return corrected_precip
            
            # Fallback to satellite precipitation estimates
            satellite_precip = await self._get_satellite_precipitation(latitude, longitude)
            if satellite_precip:
                return satellite_precip
            
            # Final fallback to advanced climate model
            return await self._advanced_precipitation_model(latitude, longitude)
            
        except Exception as e:
            logger.error(f"Error in advanced precipitation estimation: {e}")
            return await self._basic_precipitation_estimate(latitude, longitude)
    
    async def _apply_orographic_corrections(self, latitude, longitude, base_precipitation):
        """Apply orographic (topographic) corrections to precipitation"""
        try:
            # Get local topography
            async with self.db_integrator.get_postgresql_session() as session:
                topo_query = """
                SELECT 
                    AVG(CAST(gs.properties->>'elevation_m' AS FLOAT)) as avg_elevation,
                    AVG(CAST(gs.properties->>'slope_degrees' AS FLOAT)) as avg_slope,
                    AVG(CAST(gs.properties->>'aspect_degrees' AS FLOAT)) as avg_aspect
                FROM geological_structures gs
                WHERE gs.structure_type = 'topographic_analysis'
                AND ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 0.5)
                """
                
                result = await session.execute(topo_query, (longitude, latitude))
                topo_data = result.fetchone()
                
                if topo_data and topo_data.avg_elevation:
                    elevation = topo_data.avg_elevation
                    slope = topo_data.avg_slope or 0.0
                    aspect = topo_data.avg_aspect or 0.0
                    
                    # Elevation effect (orographic lifting)
                    # Precipitation increases with elevation up to ~3000m, then decreases
                    if elevation < 3000:
                        elevation_factor = 1.0 + (elevation / 3000.0) * 0.5
                    else:
                        elevation_factor = 1.5 * np.exp(-(elevation - 3000) / 2000.0)
                    
                    # Slope effect (windward vs leeward)
                    # Assume prevailing winds from west (270°)
                    prevailing_wind = 270.0
                    wind_alignment = np.cos(np.radians(aspect - prevailing_wind))
                    slope_factor = 1.0 + 0.3 * wind_alignment * (slope / 45.0)
                    
                    corrected_precip = base_precipitation * elevation_factor * slope_factor
                    
                    return max(corrected_precip, 50.0)  # Minimum 50 mm/year
                
                return base_precipitation
                
        except Exception as e:
            logger.error(f"Error applying orographic corrections: {e}")
            return base_precipitation
    
    async def _get_satellite_precipitation(self, latitude, longitude):
        """Get satellite-based precipitation estimates"""
        try:
            # Query satellite precipitation data from database
            async with self.db_integrator.get_postgresql_session() as session:
                satellite_query = """
                SELECT 
                    sp.precipitation_mm_day,
                    sp.satellite_mission,
                    sp.acquisition_date,
                    ST_Distance(sp.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM satellite_precipitation sp
                WHERE ST_DWithin(sp.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 0.5)
                AND sp.acquisition_date > NOW() - INTERVAL '5 years'
                ORDER BY distance ASC, sp.acquisition_date DESC
                LIMIT 100
                """
                
                result = await session.execute(satellite_query, (longitude, latitude, longitude, latitude))
                satellite_data = result.fetchall()
                
                if satellite_data:
                    # Calculate annual precipitation from daily data
                    daily_precips = []
                    weights = []
                    
                    for record in satellite_data:
                        daily_precip = record.precipitation_mm_day
                        distance_weight = 1.0 / (record.distance + 0.01)
                        
                        # Mission quality weights
                        mission_weights = {
                            'GPM': 1.0,
                            'TRMM': 0.9,
                            'IMERG': 0.95,
                            'PERSIANN': 0.7
                        }
                        mission_weight = mission_weights.get(record.satellite_mission, 0.8)
                        
                        final_weight = distance_weight * mission_weight
                        daily_precips.append(daily_precip)
                        weights.append(final_weight)
                    
                    # Weighted average daily precipitation
                    avg_daily_precip = np.average(daily_precips, weights=weights)
                    
                    # Convert to annual (accounting for seasonal variation)
                    seasonal_factor = await self._get_seasonal_precipitation_factor(latitude)
                    annual_precip = avg_daily_precip * 365.25 * seasonal_factor
                    
                    return annual_precip
                
                return None
                
        except Exception as e:
            logger.error(f"Error getting satellite precipitation: {e}")
            return None
    
    async def _get_seasonal_precipitation_factor(self, latitude):
        """Get seasonal precipitation variation factor"""
        try:
            # Seasonal variation depends on latitude and climate zone
            if abs(latitude) < 10:  # Tropical
                return 1.2  # High seasonal variation (wet/dry seasons)
            elif abs(latitude) < 30:  # Subtropical
                return 0.9  # Lower annual total due to dry seasons
            elif abs(latitude) < 60:  # Temperate
                return 1.0  # Moderate seasonal variation
            else:  # Polar
                return 0.8  # Low precipitation, concentrated in summer
                
        except Exception as e:
            logger.error(f"Error getting seasonal precipitation factor: {e}")
            return 1.0
    
    async def _advanced_precipitation_model(self, latitude, longitude):
        """Advanced precipitation model using multiple climate factors"""
        try:
            # Get oceanic/continental classification
            is_oceanic = await self._is_oceanic_location(latitude, longitude)
            
            # Base precipitation from latitude (ITCZ, subtropical highs, etc.)
            if abs(latitude) < 5:  # Equatorial (ITCZ)
                base_precip = 2500
            elif abs(latitude) < 15:  # Tropical
                base_precip = 1800
            elif abs(latitude) < 25:  # Subtropical dry
                base_precip = 600
            elif abs(latitude) < 35:  # Subtropical wet
                base_precip = 1200
            elif abs(latitude) < 50:  # Temperate
                base_precip = 1000
            elif abs(latitude) < 65:  # Subpolar
                base_precip = 800
            else:  # Polar
                base_precip = 300
            
            # Continental vs oceanic effects
            if is_oceanic:
                oceanic_factor = 1.3  # Higher precipitation over oceans
            else:
                # Distance from coast effect
                coast_distance = await self._get_distance_to_coast(latitude, longitude)
                if coast_distance < 100:  # Within 100 km of coast
                    oceanic_factor = 1.1
                elif coast_distance < 500:  # 100-500 km from coast
                    oceanic_factor = 0.9
                else:  # Continental interior
                    oceanic_factor = 0.7
            
            # Monsoon effects
            monsoon_factor = await self._get_monsoon_factor(latitude, longitude)
            
            # Topographic effects (simplified)
            elevation_factor = await self._get_elevation_precipitation_factor(latitude, longitude)
            
            # Calculate final precipitation
            final_precip = base_precip * oceanic_factor * monsoon_factor * elevation_factor
            
            return max(final_precip, 50.0)  # Minimum 50 mm/year
            
        except Exception as e:
            logger.error(f"Error in advanced precipitation model: {e}")
            return 1000.0  # Default value
    
    async def _get_distance_to_coast(self, latitude, longitude):
        """Get distance to nearest coastline"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                coast_query = """
                SELECT MIN(ST_Distance(cl.geometry, ST_SetSRID(ST_MakePoint(%s, %s), 4326))) as min_distance
                FROM coastlines cl
                """
                
                result = await session.execute(coast_query, (longitude, latitude))
                row = result.fetchone()
                
                if row and row.min_distance is not None:
                    return row.min_distance * 111.0  # Convert degrees to km
                
                # Estimate based on simple land/ocean classification
                is_oceanic = await self._is_oceanic_location(latitude, longitude)
                return 0.0 if is_oceanic else 200.0  # Default distances
                
        except Exception as e:
            logger.error(f"Error getting distance to coast: {e}")
            return 200.0  # Default continental distance
    
    async def _get_monsoon_factor(self, latitude, longitude):
        """Get monsoon precipitation enhancement factor"""
        try:
            # Monsoon regions and their enhancement factors
            monsoon_regions = [
                {'name': 'Asian_Monsoon', 'lat_range': (5, 35), 'lon_range': (70, 140), 'factor': 1.8},
                {'name': 'African_Monsoon', 'lat_range': (5, 20), 'lon_range': (-20, 50), 'factor': 1.5},
                {'name': 'Australian_Monsoon', 'lat_range': (-25, -10), 'lon_range': (110, 155), 'factor': 1.6},
                {'name': 'American_Monsoon', 'lat_range': (10, 35), 'lon_range': (-120, -90), 'factor': 1.4}
            ]
            
            for region in monsoon_regions:
                lat_min, lat_max = region['lat_range']
                lon_min, lon_max = region['lon_range']
                
                if lat_min <= latitude <= lat_max and lon_min <= longitude <= lon_max:
                    return region['factor']
            
            return 1.0  # No monsoon enhancement
            
        except Exception as e:
            logger.error(f"Error getting monsoon factor: {e}")
            return 1.0
    
    async def _get_elevation_precipitation_factor(self, latitude, longitude):
        """Get elevation-based precipitation factor"""
        try:
            # Get elevation from basic estimation
            elevation = await self._get_basic_elevation(latitude, longitude)
            
            # Precipitation generally increases with elevation up to ~3000m
            if elevation < 1000:
                return 1.0
            elif elevation < 3000:
                return 1.0 + (elevation - 1000) / 2000.0 * 0.5  # Up to 50% increase
            else:
                # Decreases at very high elevations
                return 1.5 * np.exp(-(elevation - 3000) / 2000.0)
                
        except Exception as e:
            logger.error(f"Error getting elevation precipitation factor: {e}")
            return 1.0
    
    async def _basic_precipitation_estimate(self, latitude, longitude):
        """Basic precipitation estimate as fallback"""
        try:
            # Simple latitudinal model
            lat_factor = np.cos(np.radians(latitude * 2))  # ITCZ and mid-latitude patterns
            
            # Continental vs oceanic effects
            is_oceanic = await self._is_oceanic_location(latitude, longitude)
            oceanic_factor = 1.5 if is_oceanic else 1.0
            
            # Base precipitation (mm/year)
            base_precip = 1000 * (1 + lat_factor) * oceanic_factor
            
            return max(base_precip, 100)  # Minimum 100 mm/year
            
        except Exception as e:
            logger.error(f"Error in basic precipitation estimate: {e}")
            return 1000.0  # Default value
    
    async def _estimate_mean_temperature(self, latitude, longitude):
        """Advanced temperature estimation using climate data and topographic corrections"""
        from backend.core.real_data_connectors.copernicus_connector import CopernicusConnector
        
        try:
            # First try to get temperature data from database
            async with self.db_integrator.get_postgresql_session() as session:
                temp_query = """
                SELECT 
                    cd.mean_temperature_c,
                    cd.temperature_range_c,
                    cd.seasonal_temperature_variation,
                    cd.data_source,
                    cd.measurement_period,
                    ST_Distance(cd.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM climate_data cd
                WHERE ST_DWithin(cd.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1.0)
                AND cd.mean_temperature_c IS NOT NULL
                ORDER BY distance ASC, cd.measurement_period DESC
                LIMIT 10
                """
                
                result = await session.execute(temp_query, (longitude, latitude, longitude, latitude))
                temp_data = result.fetchall()
                
                if temp_data:
                    # Calculate distance-weighted average
                    weighted_temp = 0.0
                    total_weight = 0.0
                    
                    for record in temp_data:
                        weight = 1.0 / (record.distance + 0.01)  # Inverse distance weighting
                        
                        # Quality weight based on data source
                        source_weights = {
                            'weather_station': 1.0,
                            'satellite_modis': 0.9,
                            'reanalysis_era5': 0.8,
                            'interpolated': 0.6
                        }
                        source_weight = source_weights.get(record.data_source, 0.7)
                        
                        final_weight = weight * source_weight
                        weighted_temp += record.mean_temperature_c * final_weight
                        total_weight += final_weight
                    
                    if total_weight > 0:
                        observed_temp = weighted_temp / total_weight
                        
                        # Apply topographic and local corrections
                        corrected_temp = await self._apply_temperature_corrections(
                            latitude, longitude, observed_temp
                        )
                        
                        return corrected_temp
            
            # Fallback to satellite temperature data
            satellite_temp = await self._get_satellite_temperature(latitude, longitude)
            if satellite_temp is not None:
                return satellite_temp
            
            # Final fallback to advanced temperature model
            return await self._advanced_temperature_model(latitude, longitude)
            
        except Exception as e:
            logger.error(f"Error in advanced temperature estimation: {e}")
            return await self._basic_temperature_estimate(latitude, longitude)
    
    async def _apply_temperature_corrections(self, latitude, longitude, base_temperature):
        """Apply topographic and local corrections to temperature"""
        try:
            corrections = 0.0
            
            # 1. Elevation correction (lapse rate)
            elevation = await self._get_basic_elevation(latitude, longitude)
            if elevation > 0:
                # Standard atmospheric lapse rate: 6.5°C/km
                # But varies with humidity and season
                humidity_factor = await self._get_local_humidity_factor(latitude, longitude)
                
                # Dry adiabatic lapse rate: 9.8°C/km
                # Moist adiabatic lapse rate: ~6.5°C/km
                lapse_rate = 9.8 - 3.3 * humidity_factor  # °C/km
                
                elevation_correction = -(elevation / 1000.0) * lapse_rate
                corrections += elevation_correction
            
            # 2. Continental vs oceanic effect
            is_oceanic = await self._is_oceanic_location(latitude, longitude)
            if not is_oceanic:
                # Continental areas have larger temperature ranges
                distance_to_coast = await self._get_distance_to_coast(latitude, longitude)
                if distance_to_coast > 100:  # More than 100 km from coast
                    continentality_effect = -2.0 * np.log(distance_to_coast / 100.0)
                    corrections += continentality_effect
            
            # 3. Urban heat island effect
            urban_factor = await self._get_urban_heat_island_factor(latitude, longitude)
            corrections += urban_factor
            
            # 4. Volcanic thermal effects
            volcanic_thermal_effect = await self._get_volcanic_thermal_effect(latitude, longitude)
            corrections += volcanic_thermal_effect
            
            # 5. Albedo effects (snow, ice, vegetation)
            albedo_effect = await self._get_albedo_temperature_effect(latitude, longitude)
            corrections += albedo_effect
            
            corrected_temp = base_temperature + corrections
            
            return corrected_temp
            
        except Exception as e:
            logger.error(f"Error applying temperature corrections: {e}")
            return base_temperature
    
    async def _get_local_humidity_factor(self, latitude, longitude):
        """Get local humidity factor for lapse rate calculation"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                humidity_query = """
                SELECT 
                    AVG(cd.humidity_percent) as avg_humidity
                FROM climate_data cd
                WHERE ST_DWithin(cd.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1.0)
                AND cd.humidity_percent IS NOT NULL
                """
                
                result = await session.execute(humidity_query, (longitude, latitude))
                row = result.fetchone()
                
                if row and row.avg_humidity is not None:
                    return row.avg_humidity / 100.0  # Convert to fraction
                
                # Estimate from precipitation and temperature
                precipitation = await self._basic_precipitation_estimate(latitude, longitude)
                base_temp = 25 - 0.5 * abs(latitude)
                
                # Higher precipitation and moderate temperatures = higher humidity
                humidity_estimate = min(0.9, 0.3 + (precipitation / 3000.0) + 0.2 * np.exp(-abs(base_temp - 20) / 15.0))
                
                return humidity_estimate
                
        except Exception as e:
            logger.error(f"Error getting local humidity factor: {e}")
            return 0.6  # Default moderate humidity
    
    async def _get_urban_heat_island_factor(self, latitude, longitude):
        """Get urban heat island temperature effect"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                urban_query = """
                SELECT 
                    ld.land_use_type,
                    ld.population_density,
                    ST_Distance(ld.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM land_use_data ld
                WHERE ST_DWithin(ld.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 0.1)
                AND ld.land_use_type IN ('urban', 'industrial', 'residential')
                ORDER BY distance ASC
                LIMIT 5
                """
                
                result = await session.execute(urban_query, (longitude, latitude, longitude, latitude))
                urban_data = result.fetchall()
                
                if urban_data:
                    max_urban_effect = 0.0
                    
                    for record in urban_data:
                        distance_km = record.distance * 111.0
                        
                        # Urban heat island intensity based on land use and population
                        if record.land_use_type == 'urban':
                            base_effect = 3.0  # °C
                        elif record.land_use_type == 'industrial':
                            base_effect = 2.0  # °C
                        else:  # residential
                            base_effect = 1.0  # °C
                        
                        # Population density effect
                        if record.population_density:
                            pop_factor = min(2.0, record.population_density / 1000.0)
                            base_effect *= pop_factor
                        
                        # Distance decay
                        distance_factor = np.exp(-distance_km / 5.0)  # 5 km decay scale
                        urban_effect = base_effect * distance_factor
                        
                        max_urban_effect = max(max_urban_effect, urban_effect)
                    
                    return max_urban_effect
                
                return 0.0  # No urban effect
                
        except Exception as e:
            logger.error(f"Error getting urban heat island factor: {e}")
            return 0.0
    
    async def _get_volcanic_thermal_effect(self, latitude, longitude):
        """Get volcanic thermal effects on local temperature"""
        try:
            volcanic_proximity = await self._get_volcanic_proximity(latitude, longitude)
            
            if volcanic_proximity < 50.0:  # Within 50 km of volcano
                # Get volcanic activity level
                async with self.db_integrator.get_postgresql_session() as session:
                    volcanic_query = """
                    SELECT 
                        vs.hazard_level,
                        vs.monitoring_status,
                        CAST(vs.geological_context->>'geothermal_activity' AS FLOAT) as geothermal_activity
                    FROM volcanic_systems vs
                    WHERE ST_DWithin(vs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 0.5)
                    ORDER BY ST_Distance(vs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) ASC
                    LIMIT 1
                    """
                    
                    result = await session.execute(volcanic_query, (longitude, latitude, longitude, latitude))
                    volcanic_data = result.fetchone()
                    
                    if volcanic_data:
                        hazard_level = volcanic_data.hazard_level or 1
                        geothermal_activity = volcanic_data.geothermal_activity or 0.0
                        
                        # Thermal effect based on activity and distance
                        base_thermal_effect = (hazard_level * 0.5) + (geothermal_activity * 2.0)
                        distance_factor = np.exp(-volcanic_proximity / 20.0)
                        
                        thermal_effect = base_thermal_effect * distance_factor
                        
                        return thermal_effect
            
            return 0.0  # No volcanic thermal effect
            
        except Exception as e:
            logger.error(f"Error getting volcanic thermal effect: {e}")
            return 0.0
    
    async def _get_albedo_temperature_effect(self, latitude, longitude):
        """Get albedo-related temperature effects"""
        try:
            # Get land cover information
            async with self.db_integrator.get_postgresql_session() as session:
                landcover_query = """
                SELECT 
                    lc.cover_type,
                    lc.albedo,
                    lc.coverage_fraction
                FROM land_cover lc
                WHERE ST_DWithin(lc.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 0.1)
                ORDER BY lc.coverage_fraction DESC
                LIMIT 5
                """
                
                result = await session.execute(landcover_query, (longitude, latitude))
                landcover_data = result.fetchall()
                
                if landcover_data:
                    weighted_albedo_effect = 0.0
                    total_coverage = 0.0
                    
                    for record in landcover_data:
                        coverage = record.coverage_fraction or 0.0
                        albedo = record.albedo or 0.15  # Default albedo
                        
                        # Albedo temperature effect (higher albedo = cooler)
                        # Reference albedo: 0.15 (typical land surface)
                        albedo_anomaly = albedo - 0.15
                        temp_effect = -albedo_anomaly * 10.0  # -10°C per unit albedo increase
                        
                        weighted_albedo_effect += temp_effect * coverage
                        total_coverage += coverage
                    
                    if total_coverage > 0:
                        return weighted_albedo_effect / total_coverage
                
                # Estimate based on latitude (snow/ice at high latitudes)
                if abs(latitude) > 60:
                    return -2.0  # Cooler due to snow/ice
                elif abs(latitude) < 30:
                    return 1.0  # Warmer due to low albedo surfaces
                
                return 0.0  # No albedo effect
                
        except Exception as e:
            logger.error(f"Error getting albedo temperature effect: {e}")
            return 0.0
    
    async def _get_satellite_temperature(self, latitude, longitude):
        """Get satellite-based temperature data"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                satellite_temp_query = """
                SELECT 
                    st.land_surface_temperature_k,
                    st.satellite_mission,
                    st.acquisition_date,
                    ST_Distance(st.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance
                FROM satellite_temperature st
                WHERE ST_DWithin(st.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 0.1)
                AND st.acquisition_date > NOW() - INTERVAL '2 years'
                ORDER BY distance ASC, st.acquisition_date DESC
                LIMIT 50
                """
                
                result = await session.execute(satellite_temp_query, (longitude, latitude, longitude, latitude))
                satellite_data = result.fetchall()
                
                if satellite_data:
                    # Calculate weighted average
                    temperatures_k = []
                    weights = []
                    
                    for record in satellite_data:
                        temp_k = record.land_surface_temperature_k
                        distance_weight = 1.0 / (record.distance + 0.001)
                        
                        # Mission quality weights
                        mission_weights = {
                            'MODIS': 1.0,
                            'VIIRS': 0.95,
                            'Landsat': 0.9,
                            'ASTER': 0.85
                        }
                        mission_weight = mission_weights.get(record.satellite_mission, 0.8)
                        
                        final_weight = distance_weight * mission_weight
                        temperatures_k.append(temp_k)
                        weights.append(final_weight)
                    
                    # Weighted average and convert to Celsius
                    avg_temp_k = np.average(temperatures_k, weights=weights)
                    avg_temp_c = avg_temp_k - 273.15
                    
                    # Convert land surface temperature to air temperature
                    # LST is typically 2-5°C higher than air temperature during day
                    air_temp_c = avg_temp_c - 3.0  # Approximate correction
                    
                    return air_temp_c
                
                return None
                
        except Exception as e:
            logger.error(f"Error getting satellite temperature: {e}")
            return None
    
    async def _advanced_temperature_model(self, latitude, longitude):
        """Advanced temperature model using multiple climate factors"""
        try:
            # Base temperature from latitude (solar radiation effect)
            # Account for seasonal variation and solar declination
            base_temp = 15.0 + 15.0 * np.cos(np.radians(latitude))  # °C
            
            # Elevation correction
            elevation = await self._get_basic_elevation(latitude, longitude)
            elevation_correction = -(elevation / 1000.0) * 6.5  # Standard lapse rate
            
            # Continental vs oceanic effect
            is_oceanic = await self._is_oceanic_location(latitude, longitude)
            if is_oceanic:
                oceanic_moderation = 0.0  # Oceans moderate temperature
            else:
                distance_to_coast = await self._get_distance_to_coast(latitude, longitude)
                # Continental effect increases with distance from coast
                continental_effect = -3.0 * np.tanh(distance_to_coast / 500.0)
                oceanic_moderation = continental_effect
            
            # Seasonal and diurnal corrections (use annual mean)
            seasonal_correction = 0.0  # Annual mean
            
            # Atmospheric circulation effects
            circulation_effect = await self._get_atmospheric_circulation_effect(latitude, longitude)
            
            final_temp = base_temp + elevation_correction + oceanic_moderation + circulation_effect
            
            return final_temp
            
        except Exception as e:
            logger.error(f"Error in advanced temperature model: {e}")
            return 15.0  # Default temperature
    
    async def _get_atmospheric_circulation_effect(self, latitude, longitude):
        """Get atmospheric circulation effects on temperature"""
        try:
            # Major circulation patterns and their temperature effects
            
            # Hadley Cell effects
            if abs(latitude) < 30:
                if abs(latitude) < 10:  # ITCZ
                    return 5.0  # Warmer due to subsidence and low pressure
                else:  # Subtropical high
                    return 2.0  # Warmer due to subsidence
            
            # Ferrel Cell effects (mid-latitudes)
            elif abs(latitude) < 60:
                return -1.0  # Cooler due to storm tracks and mixing
            
            # Polar Cell effects
            else:
                return -10.0  # Much cooler due to polar conditions
                
        except Exception as e:
            logger.error(f"Error getting atmospheric circulation effect: {e}")
            return 0.0
    
    async def _basic_temperature_estimate(self, latitude, longitude):
        """Basic temperature estimate as fallback"""
        try:
            # Simple latitudinal temperature gradient
            base_temp = 30 - 0.5 * abs(latitude)  # °C
            
            # Elevation effect (rough estimate)
            elevation_estimate = 1000.0  # Rough estimate for lapse rate calculation
            lapse_rate = 0.0065  # °C/m
            temp_correction = -lapse_rate * elevation_estimate
            
            return base_temp + temp_correction
            
        except Exception as e:
            logger.error(f"Error in basic temperature estimate: {e}")
            return 15.0  # Default temperature
    
    async def _compute_tectonic_elevation_contribution(self, latitude, longitude):
        """Compute tectonic contribution to elevation"""
        # Active tectonic zones
        tectonic_zones = [
            {'name': 'Ring of Fire', 'lat': 0, 'lon': -120, 'radius': 50, 'uplift': 1000},
            {'name': 'Alpine-Himalayan', 'lat': 35, 'lon': 50, 'radius': 30, 'uplift': 2000},
            {'name': 'East African Rift', 'lat': 0, 'lon': 35, 'radius': 20, 'uplift': 500}
        ]
        
        tectonic_contribution = 0.0
        for zone in tectonic_zones:
            distance = np.sqrt(
                (latitude - zone['lat'])**2 + 
                (longitude - zone['lon'])**2
            )
            
            if distance < zone['radius']:
                # Gaussian uplift pattern
                contribution = zone['uplift'] * np.exp(-(distance / zone['radius'])**2)
                tectonic_contribution += contribution
        
        return tectonic_contribution
    
    async def _compute_volcanic_elevation_contribution(self, latitude, longitude):
        """Compute volcanic contribution to elevation"""
        # Query volcanic systems from database
        volcanic_query = """
        SELECT 
            ST_Y(location) as lat,
            ST_X(location) as lon,
            elevation,
            volcano_type,
            last_eruption_date,
            ST_Distance(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) as distance_deg
        FROM volcanic_systems
        WHERE ST_DWithin(location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 5.0)
        ORDER BY distance_deg ASC
        LIMIT 10;
        """
        
        # Simulate volcanic data (in real implementation, would query database)
        volcanic_systems = await self._get_nearby_volcanic_systems(latitude, longitude)
        
        volcanic_contribution = 0.0
        for volcano in volcanic_systems:
            distance_km = volcano['distance_deg'] * 111.0  # Convert degrees to km
            
            # Volcanic edifice contribution
            if distance_km < 50:  # Within 50 km
                edifice_height = volcano.get('elevation', 1000)
                decay_factor = np.exp(-distance_km / 20.0)  # 20 km decay length
                contribution = edifice_height * decay_factor * 0.1  # 10% contribution
                volcanic_contribution += contribution
        
        return volcanic_contribution
    
