    def _calculate_depth_gradient(self, depths, distances):
        """Calculate depth gradient for seamount detection"""
        if len(depths) < 2:
            return 0.0
        
        # Sort by distance and calculate gradient
        sorted_data = sorted(zip(distances, depths))
        distances_sorted = [d[0] for d in sorted_data]
        depths_sorted = [d[1] for d in sorted_data]
        
        # Calculate average gradient over multiple distance intervals
        gradients = []
        for i in range(1, len(depths_sorted)):
            dist_diff = distances_sorted[i] - distances_sorted[i-1]
            depth_diff = depths_sorted[i] - depths_sorted[i-1]
            
            if dist_diff > 0:
                gradient = abs(depth_diff) / dist_diff
                gradients.append(gradient)
        
        return np.mean(gradients) if gradients else 0.0
    
