    async def _statistical_bathymetry_fusion(self, bathymetry_sources, latitude, longitude):
        """
        Advanced statistical fusion of bathymetric datasets with outlier detection
        """
        try:
            import numpy as np
            from scipy.stats import chi2, t
            from sklearn.preprocessing import RobustScaler
            
            if len(bathymetry_sources) < 2:
                source_data = list(bathymetry_sources.values())[0]
                return source_data['depth'], source_data['uncertainty']
            
            # Extract depths, uncertainties, and quality scores
            depths = np.array([source['depth'] for source in bathymetry_sources.values()])
            uncertainties = np.array([source['uncertainty'] for source in bathymetry_sources.values()])
            qualities = np.array([source['source_quality'] for source in bathymetry_sources.values()])
            
            # Robust outlier detection using modified Z-score
            median_depth = np.median(depths)
            mad = np.median(np.abs(depths - median_depth))
            modified_z_scores = 0.6745 * (depths - median_depth) / (mad + 1e-10)
            
            # Filter outliers (|modified_z| > 3.5)
            outlier_mask = np.abs(modified_z_scores) <= 3.5
            if np.sum(outlier_mask) >= 2:
                depths = depths[outlier_mask]
                uncertainties = uncertainties[outlier_mask]
                qualities = qualities[outlier_mask]
            
            # Compute inverse-variance weights with quality adjustment
            weights = (qualities**2) / (uncertainties**2 + 1e-10)
            weights = weights / np.sum(weights)
            
            # Weighted fusion
            fused_depth = np.sum(weights * depths)
            
            # Uncertainty propagation with inter-source correlation
            fusion_uncertainty = np.sqrt(np.sum((weights * uncertainties)**2))
            
            # Chi-square goodness-of-fit test
            chi_square = np.sum(weights * (depths - fused_depth)**2 / (uncertainties**2 + 1e-10))
            dof = len(depths) - 1
            if dof > 0:
                p_value = 1 - chi2.cdf(chi_square, dof)
                if p_value < 0.05:  # Significant inconsistency
                    fusion_uncertainty *= np.sqrt(chi_square / dof)
            
            # Iterative robust estimation
            for iteration in range(3):
                residuals = np.abs(depths - fused_depth)
                robust_weights = weights * np.exp(-residuals**2 / (2 * fusion_uncertainty**2))
                robust_weights = robust_weights / np.sum(robust_weights)
                
                new_depth = np.sum(robust_weights * depths)
                if np.abs(new_depth - fused_depth) < 0.1:
                    break
                fused_depth = new_depth
            
            return fused_depth, fusion_uncertainty
            
        except Exception as e:
            logger.error(f"Statistical bathymetry fusion failed: {e}")
            depths = [source['depth'] for source in bathymetry_sources.values()]
            return np.median(depths), np.std(depths)
    
