    async def _analyze_bathymetric_tectonic_context(self, latitude, longitude, depth):
        """
        Analyze tectonic context for bathymetric depth validation
        """
        try:
            from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
            
            gis_ops = GISPostgreSQLOperations(self.db_config)
            
            # Query tectonic setting
            tectonic_setting = await gis_ops.query_marine_tectonic_setting(latitude, longitude)
            
            if not tectonic_setting:
                return {'validation_score': 0.5}
            
            setting_type = tectonic_setting.get('setting_type')
            
            # Expected depth ranges for marine tectonic settings
            depth_expectations = {
                'abyssal_plain': {'mean': -4500, 'std': 800, 'range': (-6000, -3000)},
                'mid_ocean_ridge': {'mean': -2500, 'std': 600, 'range': (-3500, -1500)},
                'oceanic_trench': {'mean': -7000, 'std': 1500, 'range': (-11000, -5000)},
                'continental_shelf': {'mean': -100, 'std': 80, 'range': (-200, 0)},
                'continental_slope': {'mean': -1500, 'std': 1000, 'range': (-3000, -200)},
                'back_arc_basin': {'mean': -3000, 'std': 800, 'range': (-4500, -1500)},
                'fore_arc_basin': {'mean': -2000, 'std': 600, 'range': (-3000, -1000)},
                'transform_fault': {'mean': -3500, 'std': 1200, 'range': (-6000, -1000)}
            }
            
            if setting_type in depth_expectations:
                expected = depth_expectations[setting_type]
                
                # Compute validation score
                if depth is not None:
                    z_score = (depth - expected['mean']) / expected['std']
                    validation_score = np.exp(-0.5 * z_score**2)
                    
                    # Check if within expected range
                    in_range = expected['range'][0] <= depth <= expected['range'][1]
                    
                    return {
                        'setting_type': setting_type,
                        'expected_depth': expected['mean'],
                        'validation_score': validation_score,
                        'z_score': z_score,
                        'in_expected_range': in_range,
                        'expected_range': expected['range']
                    }
            
            return {'validation_score': 0.5, 'setting_type': setting_type}
            
        except Exception as e:
            logger.error(f"Bathymetric tectonic context analysis failed: {e}")
            return {'validation_score': 0.5}
    
