    async def _fallback_solar_elevation(self, data_point):
        """Fallback solar elevation calculation"""
        acquisition_time = data_point.get('acquisition_time', datetime.now())
        if isinstance(acquisition_time, str):
            acquisition_time = datetime.fromisoformat(acquisition_time.replace('Z', '+00:00'))
        
        day_of_year = acquisition_time.timetuple().tm_yday
        hour = acquisition_time.hour + acquisition_time.minute / 60.0
        
        # Solar declination
        declination = 23.45 * np.sin(np.radians(360 * (284 + day_of_year) / 365))
        
        # Hour angle
        hour_angle = 15 * (hour - 12)
        
        # Default latitude
        latitude = data_point.get('latitude', 40.0)
        
        # Solar elevation
        elevation = np.arcsin(
            np.sin(np.radians(declination)) * np.sin(np.radians(latitude)) +
            np.cos(np.radians(declination)) * np.cos(np.radians(latitude)) * np.cos(np.radians(hour_angle))
        )
        
        return {
            'elevation_degrees': np.degrees(elevation),
            'azimuth_degrees': await self._compute_precise_solar_azimuth(latitude, longitude, timestamp),
            'distance_au': 1.0,
            'equation_of_time_minutes': 0.0,
            'solar_declination_degrees': declination,
            'hour_angle_degrees': hour_angle,
            'air_mass': 2.0,
            'extraterrestrial_irradiance': 1361.0,
            'atmospheric_transmission': 0.7,
            'refraction_correction_degrees': 0.0
        }
    
    async def _compute_advanced_topographic_derivatives(self, dem, resolution, coordinate_system='geographic'):
        """
        Compute advanced topographic derivatives using sophisticated algorithms
        
        Implements multiple methods:
        - Horn's method for slope/aspect with edge handling
        - Zevenbergen-Thorne algorithm for curvature
        - Multi-scale analysis for terrain roughness
        - Geomorphometric parameters for landscape analysis
        """
        try:
            import numpy as np
            from scipy import ndimage
            from scipy.spatial.distance import pdist, squareform
            
            # Ensure DEM is properly conditioned
            dem_filtered = await self._condition_dem_for_analysis(dem)
            
            # 1. Horn's method for slope and aspect (improved edge handling)
            slope, aspect = await self._compute_horn_slope_aspect(dem_filtered, resolution, coordinate_system)
            
            # 2. Zevenbergen-Thorne curvature analysis
            curvatures = await self._compute_zevenbergen_thorne_curvature(dem_filtered, resolution)
            
            # 3. Multi-scale terrain roughness
            roughness_metrics = await self._compute_multiscale_roughness(dem_filtered, resolution)
            
            # 4. Advanced geomorphometric parameters
            geomorphometry = await self._compute_geomorphometric_parameters(
                dem_filtered, slope, aspect, curvatures, resolution
            )
            
            # 5. Terrain classification using machine learning
            terrain_classes = await self._classify_terrain_morphology(
                dem_filtered, slope, aspect, curvatures, roughness_metrics
            )
            
            return {
                'slope': slope,
                'aspect': aspect,
                'curvatures': curvatures,
                'roughness_metrics': roughness_metrics,
                'geomorphometry': geomorphometry,
                'terrain_classes': terrain_classes,
                'processing_metadata': {
                    'method': 'advanced_topographic_derivatives',
                    'resolution': resolution,
                    'coordinate_system': coordinate_system,
                    'dem_shape': dem.shape
                }
            }
            
        except Exception as e:
            logger.error(f"Advanced topographic derivatives computation failed: {e}")
            # Fallback to basic methods
            return await self._compute_basic_topographic_derivatives(dem, resolution)
    
    async def _compute_horn_slope_aspect(self, dem, resolution, coordinate_system):
        """Horn's method for slope and aspect with improved edge handling"""
        try:
            ny, nx = dem.shape
            
            # Handle coordinate system scaling
            if coordinate_system == 'geographic':
                # Convert degrees to meters at center latitude
                center_lat = 0.0  # Would be computed from actual coordinates
                dx_scale = 111320 * np.cos(np.radians(center_lat))
                dy_scale = 111320
            else:
                dx_scale = dy_scale = resolution
            
            # Horn's 3x3 convolution kernels with proper scaling
            kernel_x = np.array([[-1, 0, 1], [-2, 0, 2], [-1, 0, 1]]) / (8 * dx_scale)
            kernel_y = np.array([[-1, -2, -1], [0, 0, 0], [1, 2, 1]]) / (8 * dy_scale)
            
            # Apply convolution with edge handling
            dz_dx = ndimage.convolve(dem, kernel_x, mode='nearest')
            dz_dy = ndimage.convolve(dem, kernel_y, mode='nearest')
            
            # Compute slope (in radians, then convert to degrees)
            slope_rad = np.arctan(np.sqrt(dz_dx**2 + dz_dy**2))
            slope = np.degrees(slope_rad)
            
            # Compute aspect (0-360 degrees, 0=North, 90=East)
            aspect_rad = np.arctan2(dz_dy, -dz_dx)
            aspect = np.degrees(aspect_rad)
            aspect = (90 - aspect) % 360  # Convert to geographic convention
            
            # Handle flat areas (slope < 0.1 degrees)
            flat_mask = slope < 0.1
            aspect[flat_mask] = -1  # No aspect for flat areas
            
            return slope, aspect
            
        except Exception as e:
            logger.error(f"Horn slope/aspect computation failed: {e}")
            # Fallback to simple gradient
            gy, gx = np.gradient(dem)
            slope = np.degrees(np.arctan(np.sqrt(gx**2 + gy**2)))
            aspect = np.degrees(np.arctan2(-gx, gy)) % 360
            return slope, aspect
    
    async def _compute_zevenbergen_thorne_curvature(self, dem, resolution):
        """Zevenbergen-Thorne algorithm for curvature computation"""
        try:
            # Second-order finite difference coefficients
            ny, nx = dem.shape
            
            # Pad DEM for edge handling
            dem_padded = np.pad(dem, 1, mode='edge')
            
            # Extract 3x3 neighborhoods
            z1 = dem_padded[:-2, :-2]  # Top-left
            z2 = dem_padded[:-2, 1:-1]  # Top-center
            z3 = dem_padded[:-2, 2:]    # Top-right
            z4 = dem_padded[1:-1, :-2]  # Middle-left
            z5 = dem_padded[1:-1, 1:-1] # Center
            z6 = dem_padded[1:-1, 2:]   # Middle-right
            z7 = dem_padded[2:, :-2]    # Bottom-left
            z8 = dem_padded[2:, 1:-1]   # Bottom-center
            z9 = dem_padded[2:, 2:]     # Bottom-right
            
            # Second derivatives
            L = resolution
            zxx = (z4 - 2*z5 + z6) / (L**2)
            zyy = (z2 - 2*z5 + z8) / (L**2)
            zxy = (z1 - z3 - z7 + z9) / (4 * L**2)
            
            # First derivatives
            zx = (z6 - z4) / (2 * L)
            zy = (z8 - z2) / (2 * L)
            
            # Curvature measures
            # Profile curvature (curvature in direction of steepest slope)
            p = zx**2 + zy**2
            profile_curvature = np.where(p > 1e-10, 
                                       (zxx * zx**2 + 2 * zxy * zx * zy + zyy * zy**2) / (p * np.sqrt(p)),
                                       0.0)
            
            # Planform curvature (curvature perpendicular to direction of steepest slope)
            planform_curvature = np.where(p > 1e-10,
                                        (zxx * zy**2 - 2 * zxy * zx * zy + zyy * zx**2) / (p * np.sqrt(1 + p)),
                                        0.0)
            
            # Mean curvature
            mean_curvature = -0.5 * (zxx + zyy)
            
            # Gaussian curvature
            gaussian_curvature = zxx * zyy - zxy**2
            
            return {
                'profile_curvature': profile_curvature,
                'planform_curvature': planform_curvature,
                'mean_curvature': mean_curvature,
                'gaussian_curvature': gaussian_curvature,
                'second_derivatives': {
                    'zxx': zxx, 'zyy': zyy, 'zxy': zxy
                }
            }
            
        except Exception as e:
            logger.error(f"Zevenbergen-Thorne curvature computation failed: {e}")
            return {
                'profile_curvature': np.zeros_like(dem),
                'planform_curvature': np.zeros_like(dem),
                'mean_curvature': np.zeros_like(dem),
                'gaussian_curvature': np.zeros_like(dem)
            }
    
    async def _compute_multiscale_roughness(self, dem, resolution):
        """Multi-scale terrain roughness analysis"""
        try:
            from scipy import ndimage
            
            roughness_metrics = {}
            
            # 1. Vector Ruggedness Measure (VRM)
            vrm = await self._compute_vector_ruggedness_measure(dem, resolution)
            roughness_metrics['vector_ruggedness'] = vrm
            
            # 2. Terrain Ruggedness Index (TRI)
            tri = await self._compute_terrain_ruggedness_index(dem)
            roughness_metrics['terrain_ruggedness_index'] = tri
            
            # 3. Topographic Position Index (TPI) at multiple scales
            tpi_scales = [3, 9, 27]  # Different neighborhood sizes
            for scale in tpi_scales:
                tpi = await self._compute_topographic_position_index(dem, scale)
                roughness_metrics[f'tpi_scale_{scale}'] = tpi
            
            # 4. Surface roughness using standard deviation
            window_sizes = [3, 5, 9]
            for window_size in window_sizes:
                kernel = np.ones((window_size, window_size)) / (window_size**2)
                local_mean = ndimage.convolve(dem, kernel, mode='nearest')
                local_std = np.sqrt(ndimage.convolve((dem - local_mean)**2, kernel, mode='nearest'))
                roughness_metrics[f'surface_roughness_{window_size}x{window_size}'] = local_std
            
            # 5. Fractal dimension using variogram analysis
            fractal_dim = await self._compute_fractal_dimension(dem, resolution)
            roughness_metrics['fractal_dimension'] = fractal_dim
            
            return roughness_metrics
            
        except Exception as e:
            logger.error(f"Multi-scale roughness computation failed: {e}")
            return {'surface_roughness_3x3': np.std(dem) * np.ones_like(dem)}
    
    async def _compute_vector_ruggedness_measure(self, dem, resolution):
        """Vector Ruggedness Measure (VRM) for terrain complexity"""
        try:
            from scipy import ndimage
            
            # Compute slope and aspect
            gy, gx = np.gradient(dem)
            slope = np.arctan(np.sqrt(gx**2 + gy**2))
            aspect = np.arctan2(gy, gx)
            
            # Convert to unit vectors
            unit_x = np.sin(slope) * np.cos(aspect)
            unit_y = np.sin(slope) * np.sin(aspect)
            unit_z = np.cos(slope)
            
            # Compute VRM using 3x3 neighborhood
            kernel = np.ones((3, 3)) / 9
            
            mean_x = ndimage.convolve(unit_x, kernel, mode='nearest')
            mean_y = ndimage.convolve(unit_y, kernel, mode='nearest')
            mean_z = ndimage.convolve(unit_z, kernel, mode='nearest')
            
            # VRM is 1 minus the magnitude of the mean unit vector
            mean_magnitude = np.sqrt(mean_x**2 + mean_y**2 + mean_z**2)
            vrm = 1.0 - mean_magnitude
            
            return vrm
            
        except Exception as e:
            logger.error(f"VRM computation failed: {e}")
            return np.zeros_like(dem)
    
    async def _compute_terrain_ruggedness_index(self, dem):
        """Terrain Ruggedness Index (TRI)"""
        try:
            from scipy import ndimage
            
            # TRI is the mean absolute difference between center cell and neighbors
            kernel = np.array([[1, 1, 1], [1, -8, 1], [1, 1, 1]])
            tri = np.abs(ndimage.convolve(dem, kernel, mode='nearest'))
            
            return tri
            
        except Exception as e:
            logger.error(f"TRI computation failed: {e}")
            return np.zeros_like(dem)
    
    async def _compute_topographic_position_index(self, dem, neighborhood_size):
        """Topographic Position Index (TPI)"""
        try:
            from scipy import ndimage
            
            # Create circular kernel
            y, x = np.ogrid[-neighborhood_size//2:neighborhood_size//2+1, 
                           -neighborhood_size//2:neighborhood_size//2+1]
            mask = x**2 + y**2 <= (neighborhood_size//2)**2
            kernel = mask.astype(float)
            kernel[neighborhood_size//2, neighborhood_size//2] = 0  # Exclude center
            kernel = kernel / np.sum(kernel)  # Normalize
            
            # Compute mean elevation in neighborhood
            mean_elevation = ndimage.convolve(dem, kernel, mode='nearest')
            
            # TPI is difference between center and neighborhood mean
            tpi = dem - mean_elevation
            
            return tpi
            
        except Exception as e:
            logger.error(f"TPI computation failed: {e}")
            return np.zeros_like(dem)
    
    async def _compute_fractal_dimension(self, dem, resolution):
        """Compute fractal dimension using variogram analysis"""
        try:
            from scipy.spatial.distance import pdist, squareform
            
            # Sample points for variogram analysis (subsample for efficiency)
            ny, nx = dem.shape
            step = max(1, min(ny, nx) // 100)  # Sample ~100 points per dimension
            
            y_indices = np.arange(0, ny, step)
            x_indices = np.arange(0, nx, step)
            
            # Extract elevation values at sample points
            elevations = dem[np.ix_(y_indices, x_indices)]
            
            # Create coordinate arrays
            y_coords, x_coords = np.meshgrid(y_indices * resolution, x_indices * resolution, indexing='ij')
            
            # Flatten for distance computation
            coords = np.column_stack([y_coords.flatten(), x_coords.flatten()])
            elevations_flat = elevations.flatten()
            
            # Compute pairwise distances and elevation differences
            distances = pdist(coords)
            elev_diffs = pdist(elevations_flat.reshape(-1, 1))
            
            # Bin distances for variogram
            max_dist = np.max(distances) / 3  # Use 1/3 of maximum distance
            n_bins = 20
            dist_bins = np.linspace(0, max_dist, n_bins + 1)
            
            variogram_values = []
            variogram_distances = []
            
            for i in range(n_bins):
                mask = (distances >= dist_bins[i]) & (distances < dist_bins[i + 1])
                if np.sum(mask) > 0:
                    gamma = 0.5 * np.mean(elev_diffs[mask]**2)
                    variogram_values.append(gamma)
                    variogram_distances.append((dist_bins[i] + dist_bins[i + 1]) / 2)
            
            # Fit power law to variogram: γ(h) = C * h^(2H)
            # where H is the Hurst exponent, and fractal dimension D = 3 - H
            if len(variogram_values) > 3:
                log_dist = np.log(np.array(variogram_distances))
                log_gamma = np.log(np.array(variogram_values))
                
                # Linear regression in log space
                coeffs = np.polyfit(log_dist, log_gamma, 1)
                hurst_exponent = coeffs[0] / 2
                fractal_dimension = 3 - hurst_exponent
                
                # Constrain to reasonable range
                fractal_dimension = np.clip(fractal_dimension, 2.0, 3.0)
            else:
                fractal_dimension = 2.5  # Default value
            
            return fractal_dimension * np.ones_like(dem)
            
        except Exception as e:
            logger.error(f"Fractal dimension computation failed: {e}")
            return 2.5 * np.ones_like(dem)
    
    async def _compute_precise_line_of_sight_vector(self, parameters, latitude, longitude, timestamp):
        """
        Compute precise line-of-sight vector using satellite orbital mechanics
        
        Integrates:
        - Precise satellite ephemeris data
        - Earth rotation effects
        - Atmospheric refraction corrections
        - Relativistic effects for high precision
        """
        try:
            from backend.core.real_data_connectors.copernicus_connector import CopernicusConnector
            from backend.core.data_transformation.coordinate_transformer import CoordinateTransformer
            
            satellite = parameters.get('satellite', 'Sentinel-1A')
            
            # 1. Acquire precise orbital data
            orbital_data = await self._acquire_precise_orbital_data(satellite, timestamp)
            
            if orbital_data:
                # 2. Compute satellite position at acquisition time
                sat_position = await self._compute_satellite_position(
                    orbital_data, timestamp, latitude, longitude
                )
                
                # 3. Compute ground target position in ECEF coordinates
                transformer = CoordinateTransformer()
                target_ecef = await transformer.geodetic_to_ecef(latitude, longitude, 0.0)
                
                # 4. Compute look vector in ECEF
                look_vector_ecef = sat_position - target_ecef
                look_vector_ecef = look_vector_ecef / np.linalg.norm(look_vector_ecef)
                
                # 5. Transform to local ENU coordinates
                look_vector_enu = await transformer.ecef_to_enu(
                    look_vector_ecef, latitude, longitude
                )
                
                # 6. Apply atmospheric refraction correction
                corrected_vector = await self._apply_atmospheric_refraction_correction(
                    look_vector_enu, latitude, longitude, timestamp
                )
                
                # 7. Compute incidence and heading angles
                incidence_angle = np.degrees(np.arccos(-corrected_vector[2]))
                heading_angle = np.degrees(np.arctan2(corrected_vector[0], corrected_vector[1]))
                
                return {
                    'los_vector_enu': corrected_vector,
                    'incidence_angle': incidence_angle,
                    'heading_angle': heading_angle,
                    'satellite_position': sat_position,
                    'orbital_data_quality': orbital_data.get('quality', 'unknown')
                }
            
            else:
                # Fallback to approximate calculation
                logger.warning("Precise orbital data unavailable, using approximate LOS")
                return await self._compute_approximate_los_vector(parameters)
                
        except Exception as e:
            logger.error(f"Precise LOS vector computation failed: {e}")
            return await self._compute_approximate_los_vector(parameters)
    
    async def _create_advanced_basis_functions(self, y_norm, x_norm, dem_derivatives, parameters):
        """
        Create advanced basis functions for atmospheric modeling
        
        Combines multiple basis function types:
        - Topography-aware polynomials
        - Adaptive radial basis functions
        - Wavelet basis functions
        - Physics-informed basis functions
        """
        try:
            basis_functions = []
            
            # 1. Topography-aware polynomial basis
            topo_poly = await self._create_topography_aware_polynomials(
                y_norm, x_norm, dem_derivatives, degree=4
            )
            basis_functions.append(topo_poly)
            
            # 2. Adaptive RBF based on topographic complexity
            adaptive_rbf = await self._create_adaptive_rbf_functions(
                y_norm, x_norm, dem_derivatives
            )
            basis_functions.append(adaptive_rbf)
            
            # 3. Wavelet basis for multi-scale atmospheric effects
            wavelet_basis = await self._create_wavelet_basis_functions(
                y_norm, x_norm, scales=[1, 2, 4, 8]
            )
            basis_functions.append(wavelet_basis)
            
            # 4. Physics-informed basis functions
            physics_basis = await self._create_physics_informed_basis(
                y_norm, x_norm, dem_derivatives, parameters
            )
            basis_functions.append(physics_basis)
            
            # Concatenate all basis functions
            combined_basis = np.concatenate(basis_functions, axis=-1)
            
            return combined_basis
            
        except Exception as e:
            logger.error(f"Advanced basis function creation failed: {e}")
            # Fallback to simple polynomial basis
            return await self._create_simple_polynomial_basis(y_norm, x_norm, degree=3)
    
    async def _create_topography_aware_polynomials(self, y_norm, x_norm, dem_derivatives, degree=4):
        """Create polynomial basis functions that adapt to topographic complexity"""
        try:
            slope = dem_derivatives.get('slope', np.zeros_like(y_norm))
            curvature = dem_derivatives.get('curvatures', {}).get('mean_curvature', np.zeros_like(y_norm))
            
            # Normalize topographic parameters
            slope_norm = slope / (np.nanmax(slope) + 1e-6)
            curvature_norm = curvature / (np.nanmax(np.abs(curvature)) + 1e-6)
            
            basis_functions = []
            
            # Standard polynomial terms
            for i in range(degree + 1):
                for j in range(degree + 1 - i):
                    poly_term = (x_norm ** i) * (y_norm ** j)
                    basis_functions.append(poly_term)
            
            # Topography-modulated polynomial terms
            for i in range(degree):
                for j in range(degree - i):
                    # Slope-modulated terms
                    slope_poly = (x_norm ** i) * (y_norm ** j) * slope_norm
                    basis_functions.append(slope_poly)
                    
                    # Curvature-modulated terms
                    curv_poly = (x_norm ** i) * (y_norm ** j) * curvature_norm
                    basis_functions.append(curv_poly)
            
            return np.stack(basis_functions, axis=-1)
            
        except Exception as e:
            logger.error(f"Topography-aware polynomial creation failed: {e}")
            return self._create_simple_polynomial_basis(y_norm, x_norm, degree)
    
    async def _create_adaptive_rbf_functions(self, y_norm, x_norm, dem_derivatives):
        """Create adaptive RBF functions based on topographic complexity"""
        try:
            slope = dem_derivatives.get('slope', np.zeros_like(y_norm))
            roughness = dem_derivatives.get('roughness_metrics', {}).get('surface_roughness_3x3', np.zeros_like(y_norm))
            
            # Adaptive center placement based on topographic complexity
            complexity = slope + roughness
            complexity_norm = complexity / (np.nanmax(complexity) + 1e-6)
            
            # More centers in complex areas
            n_centers_base = 25
            n_centers_adaptive = int(n_centers_base * (1 + np.nanmean(complexity_norm)))
            
            # Place centers using importance sampling
            centers = await self._place_adaptive_rbf_centers(
                y_norm, x_norm, complexity_norm, n_centers_adaptive
            )
            
            # Compute RBF values with adaptive bandwidth
            points = np.column_stack([y_norm.flatten(), x_norm.flatten()])
            distances = cdist(points, centers)
            
            # Adaptive bandwidth based on local complexity
            complexity_flat = complexity_norm.flatten()
            sigma_base = 0.3
            sigma_adaptive = sigma_base / (1 + complexity_flat.reshape(-1, 1))
            
            rbf_values = np.exp(-distances**2 / (2 * sigma_adaptive**2))
            
            return rbf_values.reshape(y_norm.shape + (len(centers),))
            
        except Exception as e:
            logger.error(f"Adaptive RBF creation failed: {e}")
            return self._create_simple_rbf_functions(y_norm, x_norm, 25)
    
    async def _create_wavelet_basis_functions(self, y_norm, x_norm, scales=[1, 2, 4, 8]):
        """Create wavelet basis functions for multi-scale atmospheric effects"""
        try:
            import pywt
            
            basis_functions = []
            
            # 2D Daubechies wavelets at multiple scales
            wavelet = 'db4'
            
            for scale in scales:
                # Create scaled coordinate grids
                y_scaled = y_norm * scale
                x_scaled = x_norm * scale
                
                # Wavelet functions
                psi_y = np.array([pywt.dwt_single(row, wavelet)[1] for row in y_scaled])
                psi_x = np.array([pywt.dwt_single(col, wavelet)[1] for col in x_scaled.T]).T
                
                # 2D wavelet as outer product
                wavelet_2d = np.outer(psi_y.flatten(), psi_x.flatten()).reshape(y_norm.shape)
                basis_functions.append(wavelet_2d)
            
            return np.stack(basis_functions, axis=-1)
            
        except Exception as e:
            logger.error(f"Wavelet basis creation failed: {e}")
            # Fallback to sinusoidal basis
            basis_functions = []
            for scale in scales:
                sin_y = np.sin(2 * np.pi * y_norm * scale)
                cos_x = np.cos(2 * np.pi * x_norm * scale)
                basis_functions.append(sin_y * cos_x)
            
            return np.stack(basis_functions, axis=-1)
    
    async def _create_physics_informed_basis(self, y_norm, x_norm, dem_derivatives, parameters):
        """Create physics-informed basis functions for atmospheric modeling"""
        try:
            elevation = dem_derivatives.get('elevation', np.zeros_like(y_norm))
            slope = dem_derivatives.get('slope', np.zeros_like(y_norm))
            
            # Normalize elevation
            elev_norm = elevation / (np.nanmax(elevation) + 1e-6)
            
            basis_functions = []
            
            # 1. Hydrostatic delay basis (elevation-dependent)
            hydrostatic_basis = np.exp(-elev_norm / 8.0)  # Scale height ~8km
            basis_functions.append(hydrostatic_basis)
            
            # 2. Wet delay basis (topography-dependent)
            wet_delay_basis = elev_norm * np.exp(-elev_norm / 2.0)  # Lower scale height
            basis_functions.append(wet_delay_basis)
            
            # 3. Turbulent mixing basis (slope-dependent)
            slope_norm = slope / (np.nanmax(slope) + 1e-6)
            turbulent_basis = slope_norm * (1 + np.sin(2 * np.pi * x_norm) * np.cos(2 * np.pi * y_norm))
            basis_functions.append(turbulent_basis)
            
            # 4. Stratified flow basis (for mountain waves)
            mountain_wave_basis = elev_norm * np.sin(4 * np.pi * x_norm) * np.exp(-y_norm**2)
            basis_functions.append(mountain_wave_basis)
            
            # 5. Thermal convection basis
            thermal_basis = (1 - elev_norm) * np.exp(-(x_norm**2 + y_norm**2) / 0.5)
            basis_functions.append(thermal_basis)
            
            return np.stack(basis_functions, axis=-1)
            
        except Exception as e:
            logger.error(f"Physics-informed basis creation failed: {e}")
            # Fallback to simple exponential basis
            return np.stack([
                np.exp(-x_norm**2 - y_norm**2),
                np.exp(-2*(x_norm**2 + y_norm**2)),
                np.exp(-0.5*(x_norm**2 + y_norm**2))
            ], axis=-1)
    
    async def _prepare_training_data(self, features, parameters):
        """
        Prepare comprehensive training data from historical atmospheric patterns
        
        Integrates multiple data sources:
        - Historical InSAR atmospheric corrections
        - Meteorological reanalysis data (ERA5, MERRA-2)
        - Ground-based weather station data
        - Satellite atmospheric products (MODIS, VIIRS)
        - Radiosonde atmospheric profiles
        """
        try:
            from backend.core.gis_database_integration import GISDatabaseIntegrator
            from backend.core.real_data_connectors.copernicus_connector import CopernicusConnector
            from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
            import pandas as pd
            from datetime import datetime, timedelta
            
            logger.info("Preparing comprehensive atmospheric training data")
            
            # Initialize data integrators
            gis_integrator = GISDatabaseIntegrator(self.config)
            await gis_integrator.initialize()
            
            # Extract spatial and temporal parameters
            latitude = parameters.get('latitude', 0.0)
            longitude = parameters.get('longitude', 0.0)
            analysis_date = parameters.get('analysis_date', datetime.utcnow())
            
            # Define training data collection period (2 years historical)
            end_date = analysis_date
            start_date = end_date - timedelta(days=730)
            
            training_features = []
            training_targets = []
            
            # 1. Query historical InSAR atmospheric corrections from database
            historical_corrections = await self._query_historical_atmospheric_corrections(
                latitude, longitude, start_date, end_date, gis_integrator
            )
            
            # 2. Acquire ERA5 reanalysis data for atmospheric parameters
            era5_data = await self._acquire_era5_atmospheric_training_data(
                latitude, longitude, start_date, end_date
            )
            
            # 3. Acquire MODIS atmospheric products
            modis_data = await self._acquire_modis_atmospheric_data(
                latitude, longitude, start_date, end_date
            )
            
            # 4. Query ground-based weather station data
            weather_station_data = await self._query_weather_station_data(
                latitude, longitude, start_date, end_date, gis_integrator
            )
            
            # 5. Acquire radiosonde atmospheric profiles
            radiosonde_data = await self._acquire_radiosonde_profiles(
                latitude, longitude, start_date, end_date
            )
            
            # Synchronize and merge all data sources
            synchronized_data = await self._synchronize_atmospheric_datasets(
                historical_corrections, era5_data, modis_data, 
                weather_station_data, radiosonde_data
            )
            
            # Extract features and targets for ML training
            for record in synchronized_data:
                # Atmospheric features
                feature_vector = await self._extract_atmospheric_feature_vector(record)
                
                # Target: observed atmospheric correction
                target_correction = record.get('atmospheric_correction', 0.0)
                
                if feature_vector is not None and target_correction is not None:
                    training_features.append(feature_vector)
                    training_targets.append(target_correction)
            
            if training_features:
                X_train = np.array(training_features)
                y_train = np.array(training_targets)
                
                logger.info(f"Prepared training data: {X_train.shape[0]} samples, {X_train.shape[1]} features")
                
                return X_train, y_train
            else:
                logger.warning("No training data available for atmospheric correction")
                return np.array([]).reshape(0, 50), np.array([])  # 50 expected features
                
        except Exception as e:
            logger.error(f"Training data preparation failed: {e}")
            return np.array([]).reshape(0, 50), np.array([])
    
    async def _bootstrap_uncertainty(self, model, features, X_train, y_train, n_bootstrap=50):
        """Advanced Bayesian bootstrap uncertainty estimation with conformal prediction"""
        if len(X_train) == 0:
            return np.ones(len(features)) * 0.1
        
        # Import required libraries for advanced uncertainty quantification
        from sklearn.ensemble import RandomForestRegressor
        from sklearn.gaussian_process import GaussianProcessRegressor
        from sklearn.gaussian_process.kernels import RBF, Matern, WhiteKernel
        from scipy.stats import norm, t
        import warnings
        warnings.filterwarnings('ignore')
        
        # Bayesian bootstrap with Dirichlet weights
        predictions = []
        prediction_intervals = []
        
        # Generate Dirichlet weights for Bayesian bootstrap
        dirichlet_weights = np.random.dirichlet(np.ones(len(X_train)), size=n_bootstrap)
        
        for i in range(n_bootstrap):
            try:
                # Weighted bootstrap sample using Dirichlet weights
                weights = dirichlet_weights[i] * len(X_train)
                
                # Create weighted training set
                if hasattr(model, 'sample_weight'):
                    # For models that support sample weights
                    model_copy = type(model)(**model.get_params())
                    model_copy.fit(X_train, y_train, sample_weight=weights)
                else:
                    # For models without sample weight support, use resampling
                    indices = np.random.choice(len(X_train), size=len(X_train), 
                                             replace=True, p=weights/np.sum(weights))
                    X_boot = X_train[indices]
                    y_boot = y_train[indices]
                    
                    model_copy = type(model)(**model.get_params())
                    model_copy.fit(X_boot, y_boot)
                
                # Make prediction
                pred = model_copy.predict(features)
                predictions.append(pred)
                
                # Compute prediction intervals using quantile regression if available
                if hasattr(model_copy, 'predict_quantiles'):
                    lower = model_copy.predict_quantiles(features, quantiles=[0.025])
                    upper = model_copy.predict_quantiles(features, quantiles=[0.975])
                    prediction_intervals.append((lower, upper))
                
            except Exception as e:
                logger.warning(f"Bootstrap iteration {i} failed: {e}")
                continue
        
        if not predictions:
            return np.ones(len(features)) * 0.1
        
        predictions = np.array(predictions)
        
        # Advanced uncertainty quantification using multiple methods
        
        # 1. Epistemic uncertainty (model uncertainty)
        epistemic_uncertainty = np.std(predictions, axis=0)
        
        # 2. Aleatoric uncertainty (data noise) using residual analysis
        if len(predictions) > 1:
            residuals = []
            for pred in predictions:
                # Estimate residuals from cross-validation
                cv_residuals = self._estimate_cv_residuals(model, X_train, y_train)
                residuals.extend(cv_residuals)
            
            aleatoric_uncertainty = np.std(residuals) * np.ones(len(features))
        else:
            aleatoric_uncertainty = np.zeros(len(features))
        
        # 3. Conformal prediction intervals
        conformal_uncertainty = await self._compute_conformal_uncertainty(
            model, X_train, y_train, features, predictions
        )
        
        # 4. Combine uncertainties using uncertainty propagation
        total_uncertainty = np.sqrt(
            epistemic_uncertainty**2 + 
            aleatoric_uncertainty**2 + 
            conformal_uncertainty**2
        )
        
        # 5. Apply heteroscedastic correction based on input features
        heteroscedastic_factor = await self._compute_heteroscedastic_factor(features, X_train)
        total_uncertainty *= heteroscedastic_factor
        
        return total_uncertainty
    
    async def _compute_adaptive_weights(self, predictions, uncertainties, phase_data):
        """Advanced multi-criteria adaptive weighting with real-time atmospheric data integration"""
        from sklearn.metrics import mean_squared_error, mean_absolute_error
        from scipy.spatial.distance import pdist, squareform
        from scipy.stats import entropy
        import asyncio
        
        weights = {}
        
        # Fetch real-time atmospheric data for weighting
        atmospheric_data = await self._fetch_atmospheric_conditions(phase_data)
        
        # Initialize weight components
        uncertainty_weights = {}
        performance_weights = {}
        stability_weights = {}
        atmospheric_weights = {}
        diversity_weights = {}
        
        # 1. Uncertainty-based weighting (inverse uncertainty with confidence intervals)
        for model_name in predictions.keys():
            uncertainty = uncertainties[model_name]
            
            # Compute confidence-adjusted uncertainty weight
            confidence_interval = np.percentile(uncertainty, [25, 75])
            uncertainty_stability = 1.0 / (confidence_interval[1] - confidence_interval[0] + 1e-6)
            
            # Weight inversely proportional to uncertainty, adjusted by stability
            uncertainty_weights[model_name] = uncertainty_stability / (np.mean(uncertainty) + 1e-6)
        
        # 2. Performance-based weighting using cross-validation and temporal consistency
        for model_name in predictions.keys():
            pred = predictions[model_name]
            
            # Temporal consistency score
            temporal_consistency = await self._compute_temporal_consistency(pred, phase_data)
            
            # Spatial coherence score
            spatial_coherence = await self._compute_spatial_coherence(pred, phase_data)
            
            # Physical plausibility score
            physical_plausibility = await self._assess_physical_plausibility(pred, phase_data)
            
            # Combine performance metrics
            performance_weights[model_name] = (
                0.4 * temporal_consistency + 
                0.3 * spatial_coherence + 
                0.3 * physical_plausibility
            )
        
        # 3. Model stability weighting based on prediction variance across bootstrap samples
        for model_name in predictions.keys():
            pred = predictions[model_name]
            
            # Compute local prediction stability
            if len(pred.shape) > 1:
                local_variance = np.var(pred, axis=0)
                stability_score = 1.0 / (np.mean(local_variance) + 1e-6)
            else:
                stability_score = 1.0
            
            stability_weights[model_name] = stability_score
        
        # 4. Atmospheric condition weighting
        for model_name in predictions.keys():
            # Weight based on model's historical performance under current atmospheric conditions
            atm_weight = await self._compute_atmospheric_performance_weight(
                model_name, atmospheric_data, phase_data
            )
            atmospheric_weights[model_name] = atm_weight
        
        # 5. Ensemble diversity weighting to promote complementary models
        prediction_matrix = np.array([predictions[name].flatten() for name in predictions.keys()])
        
        if len(prediction_matrix) > 1:
            # Compute pairwise correlations
            correlation_matrix = np.corrcoef(prediction_matrix)
            
            for i, model_name in enumerate(predictions.keys()):
                # Diversity score based on average correlation with other models
                other_correlations = correlation_matrix[i, :]
                other_correlations = other_correlations[other_correlations != 1.0]  # Exclude self-correlation
                
                if len(other_correlations) > 0:
                    diversity_score = 1.0 - np.mean(np.abs(other_correlations))
                else:
                    diversity_score = 1.0
                
                diversity_weights[model_name] = max(0.1, diversity_score)  # Minimum weight
        else:
            for model_name in predictions.keys():
                diversity_weights[model_name] = 1.0
        
        # 6. Combine all weight components using learned coefficients
        weight_coefficients = await self._learn_weight_coefficients(
            predictions, uncertainties, phase_data, atmospheric_data
        )
        
        total_weight = 0
        for model_name in predictions.keys():
            combined_weight = (
                weight_coefficients['uncertainty'] * uncertainty_weights[model_name] +
                weight_coefficients['performance'] * performance_weights[model_name] +
                weight_coefficients['stability'] * stability_weights[model_name] +
                weight_coefficients['atmospheric'] * atmospheric_weights[model_name] +
                weight_coefficients['diversity'] * diversity_weights[model_name]
            )
            
            # Apply temporal decay for model performance
            temporal_decay = await self._compute_temporal_decay_factor(model_name, phase_data)
            combined_weight *= temporal_decay
            
            weights[model_name] = max(0.01, combined_weight)  # Minimum weight threshold
            total_weight += weights[model_name]
        
        # Normalize weights with entropy regularization to prevent over-concentration
        if total_weight > 0:
            for model_name in weights:
                weights[model_name] /= total_weight
            
            # Apply entropy regularization
            weight_values = list(weights.values())
            weight_entropy = entropy(weight_values)
            
            # If entropy is too low (weights too concentrated), apply smoothing
            if weight_entropy < 0.5:  # Threshold for minimum diversity
                smoothing_factor = 0.1
                n_models = len(weights)
                
                for model_name in weights:
                    weights[model_name] = (
                        (1 - smoothing_factor) * weights[model_name] + 
                        smoothing_factor / n_models
                    )
        
        return weights
    
    async def _evaluate_correction_performance(self, phases, corrections):
        """Comprehensive atmospheric correction performance evaluation with multi-scale analysis"""
        from scipy import ndimage, signal
        from scipy.stats import pearsonr, spearmanr, ks_2samp
        from sklearn.metrics import mutual_info_score
        import cv2
        
        # Initialize performance metrics dictionary
        performance_metrics = {}
        
        # 1. Basic statistical improvements
        original_std = np.nanstd(phases, axis=(1, 2))
        corrected_phases = phases - corrections
        corrected_std = np.nanstd(corrected_phases, axis=(1, 2))
        
        performance_metrics.update({
            'improvement_ratio': np.nanmean(original_std / (corrected_std + 1e-6)),
            'original_std': np.nanmean(original_std),
            'corrected_std': np.nanmean(corrected_std),
            'noise_reduction': 1 - np.nanmean(corrected_std) / np.nanmean(original_std)
        })
        
        # 2. Multi-scale spatial coherence analysis
        spatial_coherence = await self._analyze_spatial_coherence(phases, corrected_phases)
        performance_metrics['spatial_coherence'] = spatial_coherence
        
        # 3. Temporal consistency evaluation
        temporal_consistency = await self._analyze_temporal_consistency(phases, corrected_phases)
        performance_metrics['temporal_consistency'] = temporal_consistency
        
        # 4. Spectral analysis of corrections
        spectral_analysis = await self._analyze_correction_spectrum(phases, corrections)
        performance_metrics['spectral_analysis'] = spectral_analysis
        
        # 5. Physical plausibility assessment
        physical_metrics = await self._assess_correction_physics(phases, corrections)
        performance_metrics['physical_plausibility'] = physical_metrics
        
        # 6. Atmospheric model validation using external data
        atmospheric_validation = await self._validate_atmospheric_corrections(corrections)
        performance_metrics['atmospheric_validation'] = atmospheric_validation
        
        # 7. Uncertainty quantification of corrections
        correction_uncertainty = await self._quantify_correction_uncertainty(corrections)
        performance_metrics['correction_uncertainty'] = correction_uncertainty
        
        # 8. Cross-validation performance
        cv_performance = await self._cross_validate_corrections(phases, corrections)
        performance_metrics['cross_validation'] = cv_performance
        
        # 9. Residual analysis
        residual_analysis = await self._analyze_correction_residuals(phases, corrections)
        performance_metrics['residual_analysis'] = residual_analysis
        
        # 10. Overall quality score
        quality_components = [
            performance_metrics['improvement_ratio'],
            spatial_coherence['overall_score'],
            temporal_consistency['overall_score'],
            physical_metrics['plausibility_score'],
            atmospheric_validation['validation_score']
        ]
        
        # Weight components based on reliability
        weights = [0.25, 0.20, 0.20, 0.20, 0.15]
        overall_quality = np.average(quality_components, weights=weights)
        performance_metrics['overall_quality_score'] = overall_quality
        
        return performance_metrics
    
    async def _compute_feature_importance(self, ensemble_models):
        """Advanced feature importance analysis with SHAP values and permutation importance"""
        from sklearn.inspection import permutation_importance
        from sklearn.model_selection import cross_val_score
        import shap
        
        importance_dict = {}
        
        # Get training data from database for importance analysis
        training_data = await self._fetch_training_data_for_importance()
        
        if training_data is None:
            # Fallback to basic importance if no training data available
            for model_name, model in ensemble_models.items():
                if hasattr(model, 'feature_importances_'):
                    importance_dict[model_name] = {
                        'basic_importance': model.feature_importances_,
                        'method': 'tree_based'
                    }
                elif hasattr(model, 'coef_'):
                    importance_dict[model_name] = {
                        'basic_importance': np.abs(model.coef_),
                        'method': 'linear_coefficients'
                    }
            return importance_dict
        
        X_train, y_train = training_data['features'], training_data['targets']
        feature_names = training_data.get('feature_names', [f'feature_{i}' for i in range(X_train.shape[1])])
        
        for model_name, model in ensemble_models.items():
            try:
                model_importance = {}
                
                # 1. Basic model-specific importance
                if hasattr(model, 'feature_importances_'):
                    model_importance['tree_importance'] = model.feature_importances_
                elif hasattr(model, 'coef_'):
                    model_importance['linear_coefficients'] = np.abs(model.coef_)
                
                # 2. Permutation importance (model-agnostic)
                try:
                    perm_importance = permutation_importance(
                        model, X_train, y_train, 
                        n_repeats=10, 
                        random_state=42,
                        scoring='neg_mean_squared_error'
                    )
                    model_importance['permutation_importance'] = {
                        'importances_mean': perm_importance.importances_mean,
                        'importances_std': perm_importance.importances_std
                    }
                except Exception as e:
                    logger.warning(f"Permutation importance failed for {model_name}: {e}")
                
                # 3. SHAP values for explainable AI
                try:
                    # Select appropriate SHAP explainer based on model type
                    if hasattr(model, 'predict_proba'):
                        # For probabilistic models
                        explainer = shap.Explainer(model.predict_proba, X_train[:100])  # Sample for efficiency
                    else:
                        # For regression models
                        explainer = shap.Explainer(model.predict, X_train[:100])
                    
                    # Compute SHAP values for a representative sample
                    sample_size = min(50, len(X_train))
                    sample_indices = np.random.choice(len(X_train), sample_size, replace=False)
                    X_sample = X_train[sample_indices]
                    
                    shap_values = explainer(X_sample)
                    
                    model_importance['shap_values'] = {
                        'mean_abs_shap': np.mean(np.abs(shap_values.values), axis=0),
                        'shap_std': np.std(shap_values.values, axis=0),
                        'feature_interactions': await self._compute_shap_interactions(shap_values)
                    }
                    
                except Exception as e:
                    logger.warning(f"SHAP analysis failed for {model_name}: {e}")
                
                # 4. Mutual information-based importance
                try:
                    from sklearn.feature_selection import mutual_info_regression
                    
                    mi_scores = mutual_info_regression(X_train, y_train, random_state=42)
                    model_importance['mutual_information'] = mi_scores
                    
                except Exception as e:
                    logger.warning(f"Mutual information analysis failed for {model_name}: {e}")
                
                # 5. Correlation-based importance
                try:
                    correlations = []
                    for i in range(X_train.shape[1]):
                        corr, _ = pearsonr(X_train[:, i], y_train)
                        correlations.append(abs(corr))
                    
                    model_importance['correlation_importance'] = np.array(correlations)
                    
                except Exception as e:
                    logger.warning(f"Correlation analysis failed for {model_name}: {e}")
                
                # 6. Recursive feature elimination importance
                try:
                    from sklearn.feature_selection import RFE
                    
                    # Use a simple estimator for RFE
                    from sklearn.linear_model import LinearRegression
                    rfe_estimator = LinearRegression()
                    
                    rfe = RFE(estimator=rfe_estimator, n_features_to_select=min(10, X_train.shape[1]))
                    rfe.fit(X_train, y_train)
                    
                    model_importance['rfe_ranking'] = rfe.ranking_
                    model_importance['rfe_support'] = rfe.support_
                    
                except Exception as e:
                    logger.warning(f"RFE analysis failed for {model_name}: {e}")
                
                # 7. Stability-based importance (feature stability across bootstrap samples)
                stability_importance = await self._compute_stability_importance(
                    model, X_train, y_train, feature_names
                )
                model_importance['stability_importance'] = stability_importance
                
                # 8. Physical relevance scoring
                physical_relevance = await self._score_physical_relevance(feature_names)
                model_importance['physical_relevance'] = physical_relevance
                
                # 9. Combine importances into unified score
                unified_importance = await self._combine_importance_scores(model_importance, feature_names)
                model_importance['unified_importance'] = unified_importance
                
                # Add metadata
                model_importance['feature_names'] = feature_names
                model_importance['model_type'] = type(model).__name__
                model_importance['analysis_timestamp'] = datetime.now().isoformat()
                
                importance_dict[model_name] = model_importance
                
            except Exception as e:
                logger.error(f"Feature importance analysis failed for {model_name}: {e}")
                # Fallback to basic importance
                if hasattr(model, 'feature_importances_'):
                    importance_dict[model_name] = {
                        'basic_importance': model.feature_importances_,
                        'method': 'fallback_tree_based'
                    }
                elif hasattr(model, 'coef_'):
                    importance_dict[model_name] = {
                        'basic_importance': np.abs(model.coef_),
                        'method': 'fallback_linear'
                    }
        
        return importance_dict
    
    async def _extract_seasonal_trend(self, phases, historical_data):
        """Advanced seasonal trend extraction using multi-scale decomposition and real atmospheric data"""
        from scipy import signal
        from scipy.fft import fft, fftfreq
        from sklearn.decomposition import FastICA, PCA
        from statsmodels.tsa.seasonal import seasonal_decompose, STL
        from statsmodels.tsa.stattools import adfuller
        import pywt
        
        n_ifg = phases.shape[0]
        
        # Get temporal information from database
        temporal_info = await self._fetch_temporal_metadata(phases, historical_data)
        acquisition_dates = temporal_info.get('dates', [])
        
        if len(acquisition_dates) != n_ifg:
            # Fallback to uniform time spacing
            acquisition_dates = pd.date_range(
                start='2020-01-01', 
                periods=n_ifg, 
                freq='12D'  # Typical SAR repeat cycle
            )
        
        # Convert to time series for analysis
        time_series_data = []
        for i in range(n_ifg):
            # Compute spatial mean for time series analysis
            spatial_mean = np.nanmean(phases[i])
            time_series_data.append(spatial_mean)
        
        time_series = pd.Series(time_series_data, index=acquisition_dates)
        
        # 1. Multi-scale wavelet decomposition for seasonal extraction
        seasonal_components = {}
        
        # Wavelet decomposition
        try:
            # Use Daubechies wavelets for multi-resolution analysis
            coeffs = pywt.wavedec(time_series.values, 'db8', level=6)
            
            # Reconstruct components at different scales
            for level in range(1, min(6, len(coeffs))):
                # Zero out all coefficients except current level
                coeffs_level = [np.zeros_like(c) for c in coeffs]
                coeffs_level[level] = coeffs[level]
                
                reconstructed = pywt.waverec(coeffs_level, 'db8')
                
                # Analyze periodicity of this component
                period_days = await self._estimate_component_period(reconstructed, acquisition_dates)
                
                if 300 <= period_days <= 400:  # Annual component
                    seasonal_components['annual'] = reconstructed[:n_ifg]
                elif 150 <= period_days <= 200:  # Semi-annual component
                    seasonal_components['semi_annual'] = reconstructed[:n_ifg]
                elif 80 <= period_days <= 120:  # Seasonal component
                    seasonal_components['seasonal'] = reconstructed[:n_ifg]
                
        except Exception as e:
            logger.warning(f"Wavelet decomposition failed: {e}")
        
        # 2. STL (Seasonal and Trend decomposition using Loess) decomposition
        try:
            if len(time_series) >= 24:  # Need sufficient data points
                stl = STL(time_series, seasonal=13, period=365//12)  # Monthly seasonality
                stl_result = stl.fit()
                
                seasonal_components['stl_seasonal'] = stl_result.seasonal.values
                seasonal_components['stl_trend'] = stl_result.trend.values
                seasonal_components['stl_residual'] = stl_result.resid.values
                
        except Exception as e:
            logger.warning(f"STL decomposition failed: {e}")
        
        # 3. Fourier analysis for harmonic components
        try:
            # Compute FFT
            fft_values = fft(time_series.values)
            frequencies = fftfreq(len(time_series), d=1)  # Assuming daily sampling
            
            # Find dominant frequencies
            power_spectrum = np.abs(fft_values)**2
            dominant_freqs = frequencies[np.argsort(power_spectrum)[-10:]]  # Top 10 frequencies
            
            # Reconstruct seasonal components from dominant frequencies
            seasonal_reconstruction = np.zeros(n_ifg)
            
            for freq in dominant_freqs:
                if freq != 0:  # Skip DC component
                    period_days = 1.0 / abs(freq)
                    
                    # Focus on seasonal periods (30-400 days)
                    if 30 <= period_days <= 400:
                        # Find the corresponding FFT coefficient
                        freq_idx = np.argmin(np.abs(frequencies - freq))
                        amplitude = np.abs(fft_values[freq_idx]) / len(time_series)
                        phase = np.angle(fft_values[freq_idx])
                        
                        # Generate harmonic component
                        time_indices = np.arange(n_ifg)
                        harmonic = amplitude * np.cos(2 * np.pi * freq * time_indices + phase)
                        seasonal_reconstruction += harmonic
            
            seasonal_components['fourier_seasonal'] = seasonal_reconstruction
            
        except Exception as e:
            logger.warning(f"Fourier analysis failed: {e}")
        
        # 4. Fetch real atmospheric seasonal patterns from external data
        atmospheric_seasonal = await self._fetch_atmospheric_seasonal_patterns(
            acquisition_dates, phases.shape[1:3]  # Spatial dimensions
        )
        if atmospheric_seasonal is not None:
            seasonal_components['atmospheric_seasonal'] = atmospheric_seasonal
        
        # 5. Independent Component Analysis (ICA) for blind source separation
        try:
            if len(seasonal_components) >= 2:
                # Stack components for ICA
                component_matrix = np.array([comp for comp in seasonal_components.values()])
                
                # Apply ICA
                ica = FastICA(n_components=min(3, len(seasonal_components)), random_state=42)
                ica_components = ica.fit_transform(component_matrix.T).T
                
                for i, ica_comp in enumerate(ica_components):
                    seasonal_components[f'ica_component_{i}'] = ica_comp
                    
        except Exception as e:
            logger.warning(f"ICA decomposition failed: {e}")
        
        # 6. Machine learning-based seasonal extraction
        ml_seasonal = await self._ml_seasonal_extraction(time_series, acquisition_dates)
        if ml_seasonal is not None:
            seasonal_components['ml_seasonal'] = ml_seasonal
        
        # 7. Combine seasonal components using weighted ensemble
        if seasonal_components:
            # Compute weights based on component quality
            component_weights = {}
            
            for comp_name, component in seasonal_components.items():
                # Quality metrics: periodicity strength, smoothness, physical plausibility
                periodicity_score = await self._assess_periodicity_strength(component, acquisition_dates)
                smoothness_score = await self._assess_component_smoothness(component)
                physical_score = await self._assess_physical_plausibility_seasonal(component)
                
                # Combined quality score
                quality_score = 0.4 * periodicity_score + 0.3 * smoothness_score + 0.3 * physical_score
                component_weights[comp_name] = quality_score
            
            # Normalize weights
            total_weight = sum(component_weights.values())
            if total_weight > 0:
                for comp_name in component_weights:
                    component_weights[comp_name] /= total_weight
            
            # Weighted combination
            combined_seasonal = np.zeros(n_ifg)
            for comp_name, component in seasonal_components.items():
                weight = component_weights.get(comp_name, 0)
                combined_seasonal += weight * component[:n_ifg]
            
            # Store individual components and weights for analysis
            seasonal_result = {
                'combined_seasonal': combined_seasonal,
                'individual_components': seasonal_components,
                'component_weights': component_weights,
                'extraction_metadata': {
                    'n_components': len(seasonal_components),
                    'temporal_span_days': (acquisition_dates[-1] - acquisition_dates[0]).days,
                    'extraction_timestamp': datetime.now().isoformat()
                }
            }
            
            return seasonal_result
        
        else:
            # Fallback to simple harmonic model if all methods fail
            logger.warning("All seasonal extraction methods failed, using simple harmonic model")
            time_indices = np.arange(n_ifg)
            simple_seasonal = (
                0.5 * np.sin(2 * np.pi * time_indices / 365.25) +  # Annual
                0.3 * np.sin(2 * np.pi * time_indices / 182.625) +  # Semi-annual
                0.2 * np.sin(2 * np.pi * time_indices / 91.3125)    # Quarterly
            )
            
            return {
                'combined_seasonal': simple_seasonal,
                'individual_components': {'simple_harmonic': simple_seasonal},
                'component_weights': {'simple_harmonic': 1.0},
                'extraction_metadata': {
                    'method': 'fallback_harmonic',
                    'extraction_timestamp': datetime.now().isoformat()
                }
            }
    
    async def _compute_temporal_correlation(self, phases):
        """Advanced temporal correlation analysis with multi-scale and network-based approaches"""
        from scipy.stats import pearsonr, spearmanr, kendalltau
        from scipy.spatial.distance import pdist, squareform
        from sklearn.metrics import mutual_info_score
        from sklearn.preprocessing import StandardScaler
        import networkx as nx
        from scipy import ndimage
        
        n_ifg, height, width = phases.shape
        
        # Initialize correlation analysis results
        correlation_results = {
            'pairwise_correlations': {},
            'temporal_networks': {},
            'correlation_patterns': {},
            'stability_metrics': {}
        }
        
        # 1. Multi-scale pairwise correlations
        correlation_matrices = {}
        
        # Full spatial correlation
        full_spatial_corr = np.zeros((n_ifg, n_ifg))
        for i in range(n_ifg):
            for j in range(i, n_ifg):
                # Flatten and remove NaN values
                phase_i = phases[i].flatten()
                phase_j = phases[j].flatten()
                
                valid_mask = ~(np.isnan(phase_i) | np.isnan(phase_j))
                if np.sum(valid_mask) > 100:  # Minimum valid pixels
                    corr, p_value = pearsonr(phase_i[valid_mask], phase_j[valid_mask])
                    full_spatial_corr[i, j] = corr
                    full_spatial_corr[j, i] = corr
        
        correlation_matrices['full_spatial'] = full_spatial_corr
        
        # Regional correlation analysis
        regions = await self._define_correlation_regions(phases)
        
        for region_name, region_mask in regions.items():
            region_corr = np.zeros((n_ifg, n_ifg))
            
            for i in range(n_ifg):
                for j in range(i, n_ifg):
                    # Extract regional data
                    phase_i_region = phases[i][region_mask]
                    phase_j_region = phases[j][region_mask]
                    
                    valid_mask = ~(np.isnan(phase_i_region) | np.isnan(phase_j_region))
                    if np.sum(valid_mask) > 50:
                        corr, _ = pearsonr(phase_i_region[valid_mask], phase_j_region[valid_mask])
                        region_corr[i, j] = corr
                        region_corr[j, i] = corr
            
            correlation_matrices[f'region_{region_name}'] = region_corr
        
        # 2. Multi-type correlation measures
        correlation_types = {}
        
        # Pearson correlation (linear relationships)
        correlation_types['pearson'] = full_spatial_corr
        
        # Spearman correlation (monotonic relationships)
        spearman_corr = np.zeros((n_ifg, n_ifg))
        for i in range(n_ifg):
            for j in range(i, n_ifg):
                phase_i = phases[i].flatten()
                phase_j = phases[j].flatten()
                valid_mask = ~(np.isnan(phase_i) | np.isnan(phase_j))
                
                if np.sum(valid_mask) > 100:
                    corr, _ = spearmanr(phase_i[valid_mask], phase_j[valid_mask])
                    spearman_corr[i, j] = corr
                    spearman_corr[j, i] = corr
        
        correlation_types['spearman'] = spearman_corr
        
        # Mutual information (nonlinear dependencies)
        mi_matrix = await self._compute_mutual_information_matrix(phases)
        correlation_types['mutual_information'] = mi_matrix
        
        # 3. Temporal network analysis
        # Create correlation networks for different thresholds
        thresholds = [0.3, 0.5, 0.7, 0.9]
        
        for threshold in thresholds:
            # Create adjacency matrix
            adj_matrix = (np.abs(full_spatial_corr) > threshold).astype(int)
            
            # Create network graph
            G = nx.from_numpy_array(adj_matrix)
            
            # Compute network metrics
            network_metrics = {
                'clustering_coefficient': nx.average_clustering(G),
                'path_length': nx.average_shortest_path_length(G) if nx.is_connected(G) else np.inf,
                'density': nx.density(G),
                'degree_centrality': dict(nx.degree_centrality(G)),
                'betweenness_centrality': dict(nx.betweenness_centrality(G)),
                'eigenvector_centrality': dict(nx.eigenvector_centrality(G, max_iter=1000)),
                'communities': list(nx.community.greedy_modularity_communities(G))
            }
            
            correlation_results['temporal_networks'][f'threshold_{threshold}'] = network_metrics
        
        # 4. Sliding window correlation analysis
        window_sizes = [3, 5, 7, 10]  # Different temporal windows
        
        for window_size in window_sizes:
            if window_size < n_ifg:
                sliding_correlations = []
                
                for start_idx in range(n_ifg - window_size + 1):
                    end_idx = start_idx + window_size
                    window_phases = phases[start_idx:end_idx]
                    
                    # Compute correlation within window
                    window_corr = np.zeros((window_size, window_size))
                    for i in range(window_size):
                        for j in range(i, window_size):
                            phase_i = window_phases[i].flatten()
                            phase_j = window_phases[j].flatten()
                            valid_mask = ~(np.isnan(phase_i) | np.isnan(phase_j))
                            
                            if np.sum(valid_mask) > 100:
                                corr, _ = pearsonr(phase_i[valid_mask], phase_j[valid_mask])
                                window_corr[i, j] = corr
                                window_corr[j, i] = corr
                    
                    # Store window statistics
                    sliding_correlations.append({
                        'mean_correlation': np.mean(window_corr[np.triu_indices(window_size, k=1)]),
                        'std_correlation': np.std(window_corr[np.triu_indices(window_size, k=1)]),
                        'max_correlation': np.max(window_corr[np.triu_indices(window_size, k=1)]),
                        'window_center': start_idx + window_size // 2
                    })
                
                correlation_results['correlation_patterns'][f'sliding_window_{window_size}'] = sliding_correlations
        
        # 5. Lag correlation analysis
        max_lag = min(10, n_ifg // 2)
        lag_correlations = {}
        
        for lag in range(1, max_lag + 1):
            lag_corr_values = []
            
            for i in range(n_ifg - lag):
                j = i + lag
                phase_i = phases[i].flatten()
                phase_j = phases[j].flatten()
                valid_mask = ~(np.isnan(phase_i) | np.isnan(phase_j))
                
                if np.sum(valid_mask) > 100:
                    corr, _ = pearsonr(phase_i[valid_mask], phase_j[valid_mask])
                    lag_corr_values.append(corr)
            
            if lag_corr_values:
                lag_correlations[lag] = {
                    'mean': np.mean(lag_corr_values),
                    'std': np.std(lag_corr_values),
                    'values': lag_corr_values
                }
        
        correlation_results['correlation_patterns']['lag_correlations'] = lag_correlations
        
        # 6. Spatial correlation patterns
        spatial_patterns = await self._analyze_spatial_correlation_patterns(phases, full_spatial_corr)
        correlation_results['correlation_patterns']['spatial_patterns'] = spatial_patterns
        
        # 7. Correlation stability analysis
        stability_metrics = await self._assess_correlation_stability(phases, correlation_matrices)
        correlation_results['stability_metrics'] = stability_metrics
        
        # 8. Physical interpretation of correlations
        physical_interpretation = await self._interpret_correlation_physics(
            correlation_results, phases
        )
        correlation_results['physical_interpretation'] = physical_interpretation
        
        # 9. Database integration - store correlation patterns
        await self._store_correlation_analysis(correlation_results)
        
        # 10. Generate correlation summary
        correlation_summary = {
            'mean_temporal_correlation': np.mean(np.diag(full_spatial_corr, k=1)),
            'correlation_decay_rate': await self._compute_correlation_decay_rate(lag_correlations),
            'dominant_correlation_scale': await self._find_dominant_correlation_scale(correlation_results),
            'correlation_anisotropy': await self._compute_correlation_anisotropy(spatial_patterns),
            'temporal_coherence_length': await self._estimate_coherence_length(correlation_results)
        }
        
        correlation_results['summary'] = correlation_summary
        
        return correlation_results
    
    async def _compute_atmospheric_memory(self, historical_data):
        """Advanced atmospheric memory analysis using real meteorological data and machine learning"""
        from sklearn.preprocessing import StandardScaler
        from sklearn.decomposition import PCA
        from sklearn.cluster import KMeans
        from scipy.stats import autocorr, partial_autocorr
        from statsmodels.tsa.stattools import acf, pacf, adfuller
        from statsmodels.tsa.arima.model import ARIMA
        import pandas as pd
        
        # Initialize atmospheric memory analysis
        memory_analysis = {
            'persistence_metrics': {},
            'temporal_patterns': {},
            'predictability_scores': {},
            'atmospheric_regimes': {}
        }
        
        # 1. Fetch comprehensive atmospheric data from multiple sources
        atmospheric_data = await self._fetch_comprehensive_atmospheric_data(historical_data)
        
        if atmospheric_data is None or len(atmospheric_data) < 10:
            logger.warning("Insufficient atmospheric data, using climatological estimates")
            return await self._estimate_climatological_memory(historical_data)
        
        # 2. Multi-variable atmospheric memory analysis
        variables = ['pressure', 'temperature', 'humidity', 'wind_speed', 'precipitable_water']
        
        for variable in variables:
            if variable in atmospheric_data:
                var_data = atmospheric_data[variable]
                
                # Autocorrelation analysis
                try:
                    # Compute autocorrelation function
                    autocorr_values = acf(var_data, nlags=min(50, len(var_data)//4), fft=True)
                    
                    # Find decorrelation time (e-folding time)
                    decorr_threshold = 1/np.e  # ~0.368
                    decorr_time = np.argmax(autocorr_values < decorr_threshold)
                    if decorr_time == 0:
                        decorr_time = len(autocorr_values) - 1
                    
                    # Compute integral time scale
                    integral_scale = np.trapz(autocorr_values[autocorr_values > 0])
                    
                    memory_analysis['persistence_metrics'][variable] = {
                        'decorrelation_time': decorr_time,
                        'integral_scale': integral_scale,
                        'autocorr_function': autocorr_values.tolist(),
                        'persistence_strength': autocorr_values[1] if len(autocorr_values) > 1 else 0
                    }
                    
                except Exception as e:
                    logger.warning(f"Autocorrelation analysis failed for {variable}: {e}")
        
        # 3. Partial autocorrelation analysis for memory order
        for variable in variables:
            if variable in atmospheric_data:
                try:
                    var_data = atmospheric_data[variable]
                    pacf_values = pacf(var_data, nlags=min(20, len(var_data)//4))
                    
                    # Determine memory order (AR order)
                    significant_lags = np.where(np.abs(pacf_values[1:]) > 0.1)[0] + 1
                    memory_order = significant_lags[-1] if len(significant_lags) > 0 else 1
                    
                    memory_analysis['persistence_metrics'][variable]['memory_order'] = memory_order
                    memory_analysis['persistence_metrics'][variable]['pacf_values'] = pacf_values.tolist()
                    
                except Exception as e:
                    logger.warning(f"PACF analysis failed for {variable}: {e}")
        
        # 4. ARIMA modeling for atmospheric predictability
        arima_results = {}
        
        for variable in variables:
            if variable in atmospheric_data:
                try:
                    var_data = atmospheric_data[variable]
                    
                    # Test for stationarity
                    adf_result = adfuller(var_data)
                    is_stationary = adf_result[1] < 0.05
                    
                    # Fit ARIMA model
                    if is_stationary:
                        # Try different ARIMA orders
                        best_aic = np.inf
                        best_model = None
                        
                        for p in range(0, 4):
                            for d in range(0, 2):
                                for q in range(0, 4):
                                    try:
                                        model = ARIMA(var_data, order=(p, d, q))
                                        fitted_model = model.fit()
                                        
                                        if fitted_model.aic < best_aic:
                                            best_aic = fitted_model.aic
                                            best_model = fitted_model
                                    except:
                                        continue
                        
                        if best_model is not None:
                            # Compute predictability metrics
                            residuals = best_model.resid
                            predictability_score = 1 - np.var(residuals) / np.var(var_data)
                            
                            arima_results[variable] = {
                                'order': best_model.model.order,
                                'aic': best_aic,
                                'predictability_score': predictability_score,
                                'residual_variance': np.var(residuals),
                                'model_params': best_model.params.tolist()
                            }
                
                except Exception as e:
                    logger.warning(f"ARIMA modeling failed for {variable}: {e}")
        
        memory_analysis['predictability_scores'] = arima_results
        
        # 5. Atmospheric regime identification using clustering
        try:
            # Prepare multivariate atmospheric state vectors
            state_vectors = []
            timestamps = []
            
            for i, timestamp in enumerate(atmospheric_data.get('timestamps', [])):
                state_vector = []
                for variable in variables:
                    if variable in atmospheric_data and i < len(atmospheric_data[variable]):
                        state_vector.append(atmospheric_data[variable][i])
                
                if len(state_vector) == len(variables):
                    state_vectors.append(state_vector)
                    timestamps.append(timestamp)
            
            if len(state_vectors) > 10:
                state_matrix = np.array(state_vectors)
                
                # Standardize features
                scaler = StandardScaler()
                state_matrix_scaled = scaler.fit_transform(state_matrix)
                
                # PCA for dimensionality reduction
                pca = PCA(n_components=min(3, state_matrix_scaled.shape[1]))
                state_pca = pca.fit_transform(state_matrix_scaled)
                
                # K-means clustering to identify regimes
                n_regimes = min(5, len(state_vectors) // 5)
                if n_regimes >= 2:
                    kmeans = KMeans(n_clusters=n_regimes, random_state=42)
                    regime_labels = kmeans.fit_predict(state_pca)
                    
                    # Analyze regime persistence
                    regime_transitions = np.diff(regime_labels)
                    transition_rate = np.sum(regime_transitions != 0) / len(regime_transitions)
                    
                    # Compute regime-specific memory characteristics
                    regime_memory = {}
                    for regime_id in range(n_regimes):
                        regime_mask = regime_labels == regime_id
                        regime_duration = np.sum(regime_mask)
                        
                        if regime_duration > 5:
                            # Analyze memory within this regime
                            regime_indices = np.where(regime_mask)[0]
                            
                            # Compute typical regime duration
                            regime_runs = []
                            current_run = 1
                            
                            for i in range(1, len(regime_labels)):
                                if regime_labels[i] == regime_labels[i-1] and regime_labels[i] == regime_id:
                                    current_run += 1
                                else:
                                    if regime_labels[i-1] == regime_id:
                                        regime_runs.append(current_run)
                                        current_run = 1
                            
                            if regime_labels[-1] == regime_id:
                                regime_runs.append(current_run)
                            
                            regime_memory[regime_id] = {
                                'frequency': regime_duration / len(regime_labels),
                                'mean_duration': np.mean(regime_runs) if regime_runs else 1,
                                'max_duration': np.max(regime_runs) if regime_runs else 1,
                                'persistence_factor': np.mean(regime_runs) / len(regime_labels) if regime_runs else 0
                            }
                    
                    memory_analysis['atmospheric_regimes'] = {
                        'n_regimes': n_regimes,
                        'transition_rate': transition_rate,
                        'regime_memory': regime_memory,
                        'regime_centers': kmeans.cluster_centers_.tolist(),
                        'pca_explained_variance': pca.explained_variance_ratio_.tolist()
                    }
        
        except Exception as e:
            logger.warning(f"Atmospheric regime analysis failed: {e}")
        
        # 6. Seasonal memory patterns
        seasonal_memory = await self._analyze_seasonal_atmospheric_memory(atmospheric_data)
        memory_analysis['temporal_patterns']['seasonal'] = seasonal_memory
        
        # 7. Diurnal memory patterns
        diurnal_memory = await self._analyze_diurnal_atmospheric_memory(atmospheric_data)
        memory_analysis['temporal_patterns']['diurnal'] = diurnal_memory
        
        # 8. Cross-variable memory coupling
        cross_memory = await self._analyze_cross_variable_memory(atmospheric_data, variables)
        memory_analysis['temporal_patterns']['cross_variable'] = cross_memory
        
        # 9. Compute overall atmospheric memory factor
        overall_memory_factors = []
        
        # Weight different components
        for variable in variables:
            if variable in memory_analysis['persistence_metrics']:
                persistence = memory_analysis['persistence_metrics'][variable]['persistence_strength']
                overall_memory_factors.append(persistence)
        
        # Add regime persistence
        if 'atmospheric_regimes' in memory_analysis:
            regime_persistence = np.mean([
                regime_info['persistence_factor'] 
                for regime_info in memory_analysis['atmospheric_regimes']['regime_memory'].values()
            ])
            overall_memory_factors.append(regime_persistence)
        
        # Add predictability scores
        if arima_results:
            predictability = np.mean([
                result['predictability_score'] 
                for result in arima_results.values()
            ])
            overall_memory_factors.append(predictability)
        
        # Compute weighted average
        if overall_memory_factors:
            overall_memory = np.mean(overall_memory_factors)
        else:
            overall_memory = 0.5  # Default moderate memory
        
        # 10. Store results in database
        await self._store_atmospheric_memory_analysis(memory_analysis, historical_data)
        
        # Return comprehensive memory analysis
        memory_analysis['overall_memory_factor'] = overall_memory
        memory_analysis['analysis_timestamp'] = datetime.now().isoformat()
        memory_analysis['data_quality'] = await self._assess_atmospheric_data_quality(atmospheric_data)
        
        return memory_analysis
    
    async def _estimate_cv_residuals(self, model, X_train, y_train, cv_folds=5):
        """Estimate cross-validation residuals for uncertainty quantification"""
        from sklearn.model_selection import KFold
        
        residuals = []
        kf = KFold(n_splits=cv_folds, shuffle=True, random_state=42)
        
        for train_idx, val_idx in kf.split(X_train):
            X_fold_train, X_fold_val = X_train[train_idx], X_train[val_idx]
            y_fold_train, y_fold_val = y_train[train_idx], y_train[val_idx]
            
            try:
                model_copy = type(model)(**model.get_params())
                model_copy.fit(X_fold_train, y_fold_train)
                y_pred = model_copy.predict(X_fold_val)
                
                fold_residuals = y_fold_val - y_pred
                residuals.extend(fold_residuals)
            except Exception as e:
                logger.warning(f"CV fold failed: {e}")
                continue
        
        return residuals
    
    async def _compute_conformal_uncertainty(self, model, X_train, y_train, features, predictions):
        """Compute conformal prediction intervals"""
        from sklearn.model_selection import train_test_split
        
        try:
            # Split data for conformal prediction
            X_proper_train, X_calib, y_proper_train, y_calib = train_test_split(
                X_train, y_train, test_size=0.2, random_state=42
            )
            
            # Train model on proper training set
            model_copy = type(model)(**model.get_params())
            model_copy.fit(X_proper_train, y_proper_train)
            
            # Compute nonconformity scores on calibration set
            y_calib_pred = model_copy.predict(X_calib)
            nonconformity_scores = np.abs(y_calib - y_calib_pred)
            
            # Compute quantile for desired confidence level (95%)
            alpha = 0.05
            q_level = np.ceil((len(nonconformity_scores) + 1) * (1 - alpha)) / len(nonconformity_scores)
            q_level = min(q_level, 1.0)
            
            quantile = np.quantile(nonconformity_scores, q_level)
            
            # Return conformal uncertainty as the quantile
            return np.full(len(features), quantile)
            
        except Exception as e:
            logger.warning(f"Conformal prediction failed: {e}")
            return np.zeros(len(features))
    
    async def _compute_heteroscedastic_factor(self, features, X_train):
        """Compute heteroscedastic correction factor based on input features"""
        try:
            # Simple heteroscedastic model based on feature magnitude
            feature_norms = np.linalg.norm(features, axis=1) if len(features.shape) > 1 else np.abs(features)
            train_norms = np.linalg.norm(X_train, axis=1) if len(X_train.shape) > 1 else np.abs(X_train)
            
            # Normalize by training data statistics
            norm_mean = np.mean(train_norms)
            norm_std = np.std(train_norms)
            
            normalized_norms = (feature_norms - norm_mean) / (norm_std + 1e-6)
            
            # Heteroscedastic factor: higher uncertainty for extreme values
            heteroscedastic_factor = 1.0 + 0.1 * np.abs(normalized_norms)
            
            return heteroscedastic_factor
            
        except Exception as e:
            logger.warning(f"Heteroscedastic correction failed: {e}")
            return np.ones(len(features))
    
