            cv_performance = await self._assess_cross_validation_performance(
                displacement_ts, velocity_map
            )
            
            # Residual analysis
            residual_analysis = await self._analyze_inversion_residuals(
                displacement_ts, velocity_map
            )
            
            # Model comparison with external data
