    async def _compute_flexural_response(self, latitude, longitude, crustal_thickness):
        """
        Compute flexural isostatic response to regional loading
        using elastic plate theory
        """
        try:
            import numpy as np
            from scipy.special import kei, ker
            
            # Elastic parameters
            young_modulus = 70e9  # Pa - typical crustal Young's modulus
            poisson_ratio = 0.25  # Typical Poisson's ratio
            
            # Flexural rigidity
            elastic_thickness = min(crustal_thickness * 0.1, 30000)  # Effective elastic thickness
            flexural_rigidity = (young_modulus * elastic_thickness**3) / (12 * (1 - poisson_ratio**2))
            
            # Characteristic flexural wavelength
            rho_mantle = 3300  # kg/m³
            g = 9.81  # m/s²
            alpha = (4 * flexural_rigidity / (rho_mantle * g))**(1/4)
            
            # Query regional topographic loads
            regional_loads = await self._get_regional_topographic_loads(
                latitude, longitude, radius_km=alpha/1000
            )
            
            flexural_correction = 0.0
            
            if regional_loads:
                for load in regional_loads:
                    # Distance to load
                    distance = self._haversine_distance(
                        latitude, longitude, 
                        load['latitude'], load['longitude']
                    ) * 1000  # Convert to meters
                    
                    if distance > 0:
                        # Flexural response using Kelvin functions
                        r_norm = distance / alpha
                        if r_norm < 10:  # Avoid numerical issues
                            deflection = (load['load'] / (2 * np.pi * flexural_rigidity)) * \
                                       (kei(r_norm) * np.cos(r_norm) + ker(r_norm) * np.sin(r_norm))
                            flexural_correction += deflection
            
            return flexural_correction
            
        except Exception as e:
            logger.error(f"Flexural response computation failed: {e}")
            return 0.0
    
    async def _detect_volcanic_deformation_patterns(self, deformation_ts, latitude, longitude):
        """
        Detect characteristic volcanic deformation patterns in InSAR time series
        """
        try:
            import numpy as np
            from scipy.signal import find_peaks, savgol_filter
            from sklearn.cluster import DBSCAN
            
            if not deformation_ts or len(deformation_ts) < 10:
                return None
            
            # Extract displacement time series
            times = np.array([point['time'] for point in deformation_ts])
            displacements = np.array([point['displacement'] for point in deformation_ts])
            
            # Smooth the time series
            if len(displacements) > 5:
                smoothed = savgol_filter(displacements, 
                                       window_length=min(5, len(displacements)//2*2+1), 
                                       polyorder=2)
            else:
                smoothed = displacements
            
            # Detect significant deformation events
            peaks, _ = find_peaks(np.abs(smoothed), height=np.std(smoothed))
            
            patterns = {
                'inflation_events': [],
                'deflation_events': [],
                'episodic_events': [],
                'linear_trend': 0.0,
                'pattern_strength': 0.0
            }
            
            if len(peaks) > 0:
                # Classify peaks as inflation or deflation
                for peak in peaks:
                    if smoothed[peak] > 0:
                        patterns['inflation_events'].append({
                            'time': times[peak],
                            'magnitude': smoothed[peak]
                        })
                    else:
                        patterns['deflation_events'].append({
                            'time': times[peak],
                            'magnitude': abs(smoothed[peak])
                        })
                
                # Compute pattern strength
                patterns['pattern_strength'] = np.std(smoothed) / (np.mean(np.abs(smoothed)) + 1e-10)
            
            # Linear trend analysis
            if len(times) > 2:
                coeffs = np.polyfit(times, displacements, 1)
                patterns['linear_trend'] = coeffs[0]  # mm/year or similar
            
            return patterns
            
        except Exception as e:
            logger.error(f"Volcanic deformation pattern detection failed: {e}")
            return None
    
    async def _fit_mogi_source_model(self, deformation_ts, latitude, longitude):
        """
        Fit Mogi point source model to deformation data
        """
        try:
            import numpy as np
            from scipy.optimize import minimize
            
            if not deformation_ts or len(deformation_ts) < 5:
                return None
            
            # Extract spatial deformation data
            lats = np.array([point['latitude'] for point in deformation_ts])
            lons = np.array([point['longitude'] for point in deformation_ts])
            displacements = np.array([point['displacement'] for point in deformation_ts])
            
            # Convert to local coordinates (meters from center)
            center_lat, center_lon = np.mean(lats), np.mean(lons)
            x_coords = (lons - center_lon) * 111320 * np.cos(np.radians(center_lat))
            y_coords = (lats - center_lat) * 111320
            
            def mogi_model(params, x, y):
                """Mogi point source model"""
                x0, y0, depth, volume_change = params
                
                # Distance from source
                r = np.sqrt((x - x0)**2 + (y - y0)**2 + depth**2)
                
                # Mogi formula for vertical displacement
                nu = 0.25  # Poisson's ratio
                displacement = ((1 - nu) * volume_change) / (np.pi * r**3) * depth
                
                return displacement
            
            def objective(params):
                """Objective function for optimization"""
                predicted = mogi_model(params, x_coords, y_coords)
                residuals = displacements - predicted
                return np.sum(residuals**2)
            
            # Initial parameter guess
            initial_params = [0, 0, 5000, 1e6]  # x0, y0, depth(m), volume_change(m³)
            
            # Parameter bounds
            bounds = [(-10000, 10000),   # x0
                     (-10000, 10000),   # y0
                     (1000, 20000),     # depth
                     (-1e8, 1e8)]       # volume_change
            
            # Optimize
            result = minimize(objective, initial_params, bounds=bounds, method='L-BFGS-B')
            
            if result.success:
                x0, y0, depth, volume_change = result.x
                
                # Convert back to geographic coordinates
                source_lon = center_lon + x0 / (111320 * np.cos(np.radians(center_lat)))
                source_lat = center_lat + y0 / 111320
                
                # Compute fit quality
                predicted = mogi_model(result.x, x_coords, y_coords)
                r_squared = 1 - np.sum((displacements - predicted)**2) / np.sum((displacements - np.mean(displacements))**2)
                
                return {
                    'source_latitude': source_lat,
                    'source_longitude': source_lon,
                    'depth': depth,
                    'volume_change': volume_change,
                    'fit_quality': max(0, r_squared),
                    'rms_residual': np.sqrt(np.mean((displacements - predicted)**2))
                }
            
            return None
            
        except Exception as e:
            logger.error(f"Mogi source model fitting failed: {e}")
            return None
    
    async def _classify_deformation_pattern(self, mogi_params):
        """Classify deformation pattern based on Mogi model parameters"""
        try:
            volume_change = mogi_params.get('volume_change', 0)
            depth = mogi_params.get('depth', 0)
            
            if abs(volume_change) < 1e4:
                return 'negligible'
            elif volume_change > 0:
                if depth < 3000:
                    return 'shallow_inflation'
                elif depth < 8000:
                    return 'intermediate_inflation'
                else:
                    return 'deep_inflation'
            else:
                if depth < 3000:
                    return 'shallow_deflation'
                elif depth < 8000:
                    return 'intermediate_deflation'
                else:
                    return 'deep_deflation'
                    
        except Exception as e:
            logger.error(f"Deformation pattern classification failed: {e}")
            return 'unknown'
    
