    def _haversine_distance(self, lat1, lon1, lat2, lon2):
        """Calculate haversine distance between two points in kilometers"""
        import math
        
        # Convert to radians
        lat1, lon1, lat2, lon2 = map(math.radians, [lat1, lon1, lat2, lon2])
        
        # Haversine formula
        dlat = lat2 - lat1
        dlon = lon2 - lon1
        a = math.sin(dlat/2)**2 + math.cos(lat1) * math.cos(lat2) * math.sin(dlon/2)**2
        c = 2 * math.asin(math.sqrt(a))
        
        # Earth radius in kilometers
        r = 6371
        
        return c * r    
  
    async def _climatic_geomorphological_modeling(self, latitude, longitude):
        """
        Elevation modeling based on climatic controls and geomorphological processes
        """
        try:
            from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
            import numpy as np
            
            gis_ops = GISPostgreSQLOperations(self.db_config)
            
            # Query climatic data
            climate_data = await gis_ops.query_climate_data(latitude, longitude)
            
            if not climate_data:
                return None
            
            # Extract climatic variables
            mean_annual_temp = climate_data.get('mean_annual_temperature', 15.0)
            annual_precipitation = climate_data.get('annual_precipitation', 1000.0)
            aridity_index = climate_data.get('aridity_index', 0.5)
            
            # Geomorphological process rates based on climate
            # Erosion rate modeling (Milliman & Syvitski, 1992; Montgomery & Brandon, 2002)
            erosion_rate = self._compute_climate_erosion_rate(
                mean_annual_temp, annual_precipitation, aridity_index
            )
            
            # Tectonic uplift vs erosion equilibrium
            # Assume steady-state landscape evolution
            equilibrium_elevation = await self._compute_erosion_uplift_equilibrium(
                latitude, longitude, erosion_rate
            )
            
            if equilibrium_elevation is not None:
                # Uncertainty based on climatic variability
                temp_variability = climate_data.get('temperature_variability', 5.0)
                precip_variability = climate_data.get('precipitation_variability', 200.0)
                
                uncertainty = np.sqrt(
                    (temp_variability * 50)**2 +  # 50m per degree uncertainty
                    (precip_variability * 0.5)**2  # 0.5m per mm uncertainty
                )
                
                return {
                    'elevation': equilibrium_elevation,
                    'uncertainty': uncertainty,
                    'method': 'Climatic_Geomorphological',
                    'erosion_rate': erosion_rate,
                    'climate_factors': {
                        'temperature': mean_annual_temp,
                        'precipitation': annual_precipitation,
                        'aridity': aridity_index
                    }
                }
            
            return None
            
        except Exception as e:
            logger.error(f"Climatic geomorphological modeling failed: {e}")
            return None
    
    async def _regional_geological_interpolation(self, latitude, longitude):
        """
        Regional geological context interpolation using known elevation points
        """
        try:
            from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
            from scipy.interpolate import RBFInterpolator
            import numpy as np
            
            gis_ops = GISPostgreSQLOperations(self.db_config)
            
            # Query regional elevation control points
            control_points = await gis_ops.query_regional_elevation_control_points(
                center_lat=latitude,
                center_lon=longitude,
                radius_km=500,  # 500km search radius
                min_points=10
            )
            
            if not control_points or len(control_points) < 10:
                return None
            
            # Extract coordinates and elevations
            coords = np.array([[p['latitude'], p['longitude']] for p in control_points])
            elevations = np.array([p['elevation'] for p in control_points])
            weights = np.array([p.get('quality_weight', 1.0) for p in control_points])
            
            # Radial Basis Function interpolation with geological constraints
            rbf_interpolator = RBFInterpolator(
                coords,
                elevations,
                kernel='thin_plate_spline',
                smoothing=0.1,
                degree=1
            )
            
            # Interpolate at target location
            target_coord = np.array([[latitude, longitude]])
            interpolated_elevation = rbf_interpolator(target_coord)[0]
            
            # Estimate uncertainty based on distance to control points
            distances = np.sqrt(np.sum((coords - target_coord)**2, axis=1))
            min_distance = np.min(distances)
            mean_distance = np.mean(distances)
            
            # Uncertainty increases with distance from control points
            distance_uncertainty = min_distance * 10  # 10m per degree distance
            interpolation_uncertainty = np.std(elevations) / np.sqrt(len(elevations))
            
            total_uncertainty = np.sqrt(distance_uncertainty**2 + interpolation_uncertainty**2)
            
            return {
                'elevation': interpolated_elevation,
                'uncertainty': total_uncertainty,
                'method': 'Regional_RBF_Interpolation',
                'control_points': len(control_points),
                'min_distance_km': min_distance * 111,  # Convert to km
                'interpolation_quality': 1.0 / (1.0 + mean_distance)
            }
            
        except Exception as e:
            logger.error(f"Regional geological interpolation failed: {e}")
            return None
    
    async def _bayesian_elevation_fusion(self, elevation_estimates):
        """
        Bayesian model averaging for optimal elevation estimation
        """
        try:
            import numpy as np
            from scipy.stats import norm
            
            if not elevation_estimates:
                return None
            
            # Extract estimates, uncertainties, and confidences
            estimates = []
            uncertainties = []
            confidences = []
            
            for method, data in elevation_estimates.items():
                estimates.append(data['elevation'])
                uncertainties.append(data['uncertainty'])
                confidences.append(data['confidence'])
            
            estimates = np.array(estimates)
            uncertainties = np.array(uncertainties)
            confidences = np.array(confidences)
            
            # Bayesian weights based on confidence and inverse uncertainty
            precision = 1.0 / (uncertainties**2 + 1e-10)  # Avoid division by zero
            weights = confidences * precision
            weights = weights / np.sum(weights)  # Normalize
            
            # Weighted mean
            fused_elevation = np.sum(weights * estimates)
            
            # Uncertainty propagation with correlation consideration
            fused_uncertainty = np.sqrt(np.sum((weights * uncertainties)**2))
            
            # Model uncertainty (disagreement between methods)
            model_uncertainty = np.sqrt(np.sum(weights * (estimates - fused_elevation)**2))
            
            # Total uncertainty
            total_uncertainty = np.sqrt(fused_uncertainty**2 + model_uncertainty**2)
            
            # Confidence based on agreement between methods
            agreement_score = 1.0 / (1.0 + model_uncertainty / 100.0)  # 100m characteristic scale
            overall_confidence = np.mean(confidences) * agreement_score
            
            return {
                'elevation': fused_elevation,
                'uncertainty': total_uncertainty,
                'confidence': overall_confidence,
                'method': 'Bayesian_Model_Averaging',
                'contributing_methods': list(elevation_estimates.keys()),
                'model_uncertainty': model_uncertainty,
                'measurement_uncertainty': fused_uncertainty,
                'weights': dict(zip(elevation_estimates.keys(), weights))
            }
            
        except Exception as e:
            logger.error(f"Bayesian elevation fusion failed: {e}")
            return None
    
