    async def _compute_advanced_airy_isostasy(self, crustal_structure, latitude, longitude):
        """
        Advanced Airy isostatic model with variable crustal densities and layered structure
        """
        try:
            import numpy as np
            
            if not crustal_structure:
                return None
            
            # Extract layered crustal structure
            crustal_layers = crustal_structure.get('layers', [])
            if not crustal_layers:
                return None
            
            # Compute total crustal column mass
            total_crustal_mass = 0.0
            total_thickness = 0.0
            
            for layer in crustal_layers:
                thickness = layer.get('thickness', 0)  # meters
                density = layer.get('density', 2670)   # kg/m³
                layer_mass = thickness * density
                total_crustal_mass += layer_mass
                total_thickness += thickness
            
            # Average crustal density
            avg_crustal_density = total_crustal_mass / total_thickness if total_thickness > 0 else 2670
            
            # Mantle density with temperature correction
            mantle_temperature = crustal_structure.get('mantle_temperature', 1600)  # K
            reference_temp = 1600  # K
            thermal_expansion = 3e-5  # K⁻¹
            
            reference_mantle_density = 3300  # kg/m³
            mantle_density = reference_mantle_density * (1 - thermal_expansion * (mantle_temperature - reference_temp))
            
            # Water density for oceanic regions
            water_density = 1030  # kg/m³
            
            # Determine if oceanic or continental
            is_oceanic = await self._determine_oceanic_continental(latitude, longitude, crustal_structure)
            
            if is_oceanic:
                # Oceanic Airy isostasy
                reference_oceanic_thickness = 7000  # meters
                reference_water_depth = 4000       # meters
                
                thickness_anomaly = total_thickness - reference_oceanic_thickness
                
                # Airy compensation including water loading
                elevation = -(reference_water_depth + 
                            thickness_anomaly * (avg_crustal_density - mantle_density) / 
                            (mantle_density - water_density))
            else:
                # Continental Airy isostasy
                reference_continental_thickness = 35000  # meters
                
                thickness_anomaly = total_thickness - reference_continental_thickness
                
                # Airy compensation
                elevation = thickness_anomaly * (avg_crustal_density / (mantle_density - avg_crustal_density))
            
            # Uncertainty estimation based on density variations
            density_uncertainty = np.std([layer.get('density_uncertainty', 50) for layer in crustal_layers])
            thickness_uncertainty = np.sqrt(np.sum([layer.get('thickness_uncertainty', 1000)**2 for layer in crustal_layers]))
            
            # Propagate uncertainties
            elevation_uncertainty = np.sqrt(
                (thickness_uncertainty * avg_crustal_density / (mantle_density - avg_crustal_density))**2 +
                (total_thickness * density_uncertainty / (mantle_density - avg_crustal_density))**2
            )
            
            return {
                'elevation': elevation,
                'uncertainty': elevation_uncertainty,
                'avg_crustal_density': avg_crustal_density,
                'mantle_density': mantle_density,
                'total_thickness': total_thickness,
                'is_oceanic': is_oceanic,
                'model_type': 'advanced_airy'
            }
            
        except Exception as e:
            logger.error(f"Advanced Airy isostasy computation failed: {e}")
            return None
    
    async def _compute_pratt_isostasy_with_density_variations(self, crustal_structure, latitude, longitude):
        """
        Pratt isostatic model with lateral density variations and compensation depth optimization
        """
        try:
            import numpy as np
            from scipy.optimize import minimize_scalar
            
            if not crustal_structure:
                return None
            
            # Extract crustal parameters
            crustal_layers = crustal_structure.get('layers', [])
            if not crustal_layers:
                return None
            
            # Compute depth-dependent density profile
            depth_density_profile = []
            cumulative_depth = 0
            
            for layer in crustal_layers:
                thickness = layer.get('thickness', 0)
                density = layer.get('density', 2670)
                
                depth_density_profile.append({
                    'depth_top': cumulative_depth,
                    'depth_bottom': cumulative_depth + thickness,
                    'density': density
                })
                cumulative_depth += thickness
            
            # Query regional density variations
            if latitude is not None and longitude is not None:
                from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
                gis_ops = GISPostgreSQLOperations(self.db_config)
                
                regional_density_data = await gis_ops.query_regional_density_variations(
                    latitude, longitude, radius_km=200
                )
            else:
                regional_density_data = None
            
            # Optimize compensation depth for Pratt model
            def pratt_objective(compensation_depth):
                """Objective function for Pratt compensation depth optimization"""
                try:
                    # Compute column mass to compensation depth
                    column_mass = 0.0
                    current_depth = 0.0
                    
                    for layer_data in depth_density_profile:
                        layer_top = layer_data['depth_top']
                        layer_bottom = min(layer_data['depth_bottom'], compensation_depth)
                        
                        if layer_bottom > layer_top:
                            layer_thickness = layer_bottom - layer_top
                            layer_density = layer_data['density']
                            column_mass += layer_thickness * layer_density
                        
                        if layer_bottom >= compensation_depth:
                            break
                    
                    # Reference column mass (average regional)
                    if regional_density_data:
                        reference_mass = regional_density_data.get('average_column_mass', 0)
                    else:
                        # Estimate reference mass
                        reference_density = 2800  # kg/m³ average crustal density
                        reference_mass = compensation_depth * reference_density
                    
                    # Pratt isostatic imbalance
                    mass_imbalance = abs(column_mass - reference_mass)
                    return mass_imbalance
                    
                except Exception as e:
                    return 1e10  # Large penalty for errors
            
            # Optimize compensation depth
            optimization_result = minimize_scalar(
                pratt_objective,
                bounds=(10000, 100000),  # 10-100 km depth range
                method='bounded'
            )
            
            if optimization_result.success:
                optimal_compensation_depth = optimization_result.x
                
                # Compute Pratt elevation
                column_mass = 0.0
                for layer_data in depth_density_profile:
                    layer_top = layer_data['depth_top']
                    layer_bottom = min(layer_data['depth_bottom'], optimal_compensation_depth)
                    
                    if layer_bottom > layer_top:
                        layer_thickness = layer_bottom - layer_top
                        layer_density = layer_data['density']
                        column_mass += layer_thickness * layer_density
                
                # Reference parameters
                reference_density = 2800  # kg/m³
                mantle_density = 3300     # kg/m³
                
                # Pratt elevation calculation
                mass_excess = column_mass - (optimal_compensation_depth * reference_density)
                pratt_elevation = mass_excess / (mantle_density - reference_density)
                
                # Uncertainty estimation
                density_uncertainties = [layer.get('density_uncertainty', 50) for layer in crustal_layers]
                avg_density_uncertainty = np.mean(density_uncertainties)
                
                elevation_uncertainty = (optimal_compensation_depth * avg_density_uncertainty) / \
                                      (mantle_density - reference_density)
                
                return {
                    'elevation': pratt_elevation,
                    'uncertainty': elevation_uncertainty,
                    'compensation_depth': optimal_compensation_depth,
                    'column_mass': column_mass,
                    'mass_imbalance': optimization_result.fun,
                    'model_type': 'pratt_optimized'
                }
            
            return None
            
        except Exception as e:
            logger.error(f"Pratt isostasy computation failed: {e}")
            return None
    
