    async def _compute_standard_atmosphere_pressure(self, latitude, longitude):
        """
        Compute standard atmosphere pressure based on location
        """
        try:
            import numpy as np
            
            # Query elevation for pressure calculation
            from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
            gis_ops = GISPostgreSQLOperations(self.db_integrator)
            
            elevation_query = f"""
            SELECT ST_Value(rast, ST_SetSRID(ST_MakePoint({longitude}, {latitude}), 4326)) as elevation
            FROM digital_elevation_models 
            WHERE ST_Intersects(rast, ST_SetSRID(ST_MakePoint({longitude}, {latitude}), 4326))
            ORDER BY ST_PixelWidth(rast) ASC
            LIMIT 1
            """
            
            async with gis_ops.db.get_postgresql_session() as session:
                result = await session.execute(elevation_query)
                elevation_data = result.fetchone()
            
            elevation = elevation_data.elevation if elevation_data else 0.0
            
            # Barometric formula
            p0 = 1013.25  # Sea level pressure (hPa)
            T0 = 288.15   # Sea level temperature (K)
            L = 0.0065    # Temperature lapse rate (K/m)
            g = 9.80665   # Gravity (m/s²)
            M = 0.0289644 # Molar mass of air (kg/mol)
            R = 8.31432   # Gas constant (J/(mol·K))
            
            # Pressure at elevation
            pressure = p0 * (1 - L * elevation / T0) ** (g * M / (R * L))
            
            return {
                'surface_pressure_hpa': pressure,
                'temperature_k': T0 - L * elevation,
                'elevation_m': elevation
            }
            
        except Exception as e:
            logger.error(f"Standard atmosphere pressure computation failed: {e}")
            return {'surface_pressure_hpa': 1013.25}
    
    async def _compute_oceanic_loading_effects(self, latitude, longitude):
        """
        Compute oceanic loading effects on geoid
        """
        try:
            # Check if location is near ocean
            ocean_distance = await self._compute_distance_to_ocean(latitude, longitude)
            
            if ocean_distance > 100000:  # More than 100 km from ocean
                return 0.0
            
            # Query ocean tide data
            tide_data = await self._query_ocean_tide_data(latitude, longitude)
            
            if not tide_data:
                return 0.0
            
            # Ocean loading Green's functions (simplified)
            loading_coefficient = 0.1  # mm per cm of water equivalent
            
            # Current sea level anomaly
            sea_level_anomaly = tide_data.get('sea_level_anomaly_cm', 0.0)
            
            # Distance weighting
            distance_weight = np.exp(-ocean_distance / 50000)  # 50 km decay scale
            
            # Loading effect
            loading_effect = loading_coefficient * sea_level_anomaly * distance_weight / 1000  # Convert to m
            
            return loading_effect
            
        except Exception as e:
            logger.error(f"Oceanic loading computation failed: {e}")
            return 0.0
    
    async def _compute_distance_to_ocean(self, latitude, longitude):
        """
        Compute distance to nearest ocean
        """
        try:
            from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
            
            gis_ops = GISPostgreSQLOperations(self.db_integrator)
            
            ocean_distance_query = f"""
            SELECT ST_Distance(
                ST_SetSRID(ST_MakePoint({longitude}, {latitude}), 4326),
                ST_ClosestPoint(
                    geometry, 
                    ST_SetSRID(ST_MakePoint({longitude}, {latitude}), 4326)
                )
            ) * 111320 as distance_m
            FROM ocean_boundaries 
            ORDER BY ST_Distance(
                geometry, 
                ST_SetSRID(ST_MakePoint({longitude}, {latitude}), 4326)
            ) ASC
            LIMIT 1
            """
            
            async with gis_ops.db.get_postgresql_session() as session:
                result = await session.execute(ocean_distance_query)
                distance_data = result.fetchone()
            
            return distance_data.distance_m if distance_data else 1000000  # 1000 km default
            
        except Exception as e:
            logger.error(f"Distance to ocean computation failed: {e}")
            return 1000000
    
