    async def _compute_polar_motion_effects(self, latitude, longitude):
        """
        Compute polar motion effects on geoid
        """
        try:
            import numpy as np
            
            # Query current polar motion parameters
            polar_motion_data = await self._query_polar_motion_data()
            
            if not polar_motion_data:
                return 0.0
            
            # Polar motion coordinates (arcseconds)
            xp = polar_motion_data.get('x_pole_arcsec', 0.0)
            yp = polar_motion_data.get('y_pole_arcsec', 0.0)
            
            # Convert to radians
            xp_rad = xp * np.pi / (180 * 3600)
            yp_rad = yp * np.pi / (180 * 3600)
            
            # Site coordinates
            lat_rad = np.radians(latitude)
            lon_rad = np.radians(longitude)
            
            # Polar motion effect on geoid (simplified)
            # Based on IERS Conventions 2010
            polar_motion_effect = (
                xp_rad * np.cos(lon_rad) * np.sin(lat_rad) +
                yp_rad * np.sin(lon_rad) * np.sin(lat_rad)
            ) * 6378136.3  # Earth radius in meters
            
            return polar_motion_effect
            
        except Exception as e:
            logger.error(f"Polar motion effects computation failed: {e}")
            return 0.0
    
