    async def _compute_flexural_isostasy_elastic_plate(self, crustal_structure, latitude, longitude):
        """
        Flexural isostatic model using elastic plate theory with variable rigidity
        """
        try:
            import numpy as np
            from scipy.special import kei, ker, bei, ber
            from scipy.integrate import quad
            
            if not crustal_structure or latitude is None or longitude is None:
                return None
            
            from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
            gis_ops = GISPostgreSQLOperations(self.db_config)
            
            # Query lithospheric parameters
            lithosphere_data = await gis_ops.query_lithospheric_parameters(latitude, longitude)
            
            if not lithosphere_data:
                return None
            
            # Extract elastic parameters
            elastic_thickness = lithosphere_data.get('elastic_thickness', 25000)  # meters
            young_modulus = lithosphere_data.get('young_modulus', 70e9)  # Pa
            poisson_ratio = lithosphere_data.get('poisson_ratio', 0.25)
            
            # Compute flexural rigidity
            flexural_rigidity = (young_modulus * elastic_thickness**3) / \
                              (12 * (1 - poisson_ratio**2))
            
            # Mantle parameters
            mantle_density = 3300  # kg/m³
            g = 9.81  # m/s²
            
            # Characteristic flexural wavelength
            alpha = (4 * flexural_rigidity / (mantle_density * g))**(1/4)
            
            # Query regional topographic loads
            regional_loads = await gis_ops.query_detailed_topographic_loads(
                center_lat=latitude,
                center_lon=longitude,
                radius_km=alpha / 1000 * 5  # 5 times flexural wavelength
            )
            
            if not regional_loads:
                return None
            
            # Compute flexural response using Green's functions
            total_deflection = 0.0
            load_contributions = []
            
            for load in regional_loads:
                # Distance to load
                distance = self._haversine_distance(
                    latitude, longitude,
                    load['latitude'], load['longitude']
                ) * 1000  # Convert to meters
                
                if distance > 0:
                    # Normalized distance
                    r_norm = distance / alpha
                    
                    if r_norm < 15:  # Avoid numerical issues
                        # Green's function for elastic plate (Kelvin functions)
                        try:
                            # Point load response
                            deflection = (load['load'] / (2 * np.pi * flexural_rigidity)) * \
                                       self._elastic_plate_greens_function(r_norm)
                            
                            total_deflection += deflection
                            load_contributions.append({
                                'distance': distance,
                                'load': load['load'],
                                'deflection': deflection
                            })
                        except:
                            continue  # Skip problematic calculations
            
            # Compute crustal root from flexural loading
            crustal_layers = crustal_structure.get('layers', [])
            total_crustal_thickness = sum(layer.get('thickness', 0) for layer in crustal_layers)
            
            # Flexural isostatic elevation
            flexural_elevation = total_deflection
            
            # Add Airy component for uncompensated load
            avg_crustal_density = np.mean([layer.get('density', 2670) for layer in crustal_layers])
            airy_component = total_crustal_thickness * (avg_crustal_density / (mantle_density - avg_crustal_density))
            
            combined_elevation = flexural_elevation + airy_component
            
            # Uncertainty estimation
            elastic_thickness_uncertainty = lithosphere_data.get('elastic_thickness_uncertainty', 5000)
            load_uncertainty = np.std([contrib['deflection'] for contrib in load_contributions]) if load_contributions else 1000
            
            # Propagate uncertainties
            rigidity_uncertainty = 3 * elastic_thickness_uncertainty * flexural_rigidity / elastic_thickness
            deflection_uncertainty = total_deflection * rigidity_uncertainty / flexural_rigidity
            
            total_uncertainty = np.sqrt(deflection_uncertainty**2 + load_uncertainty**2)
            
            return {
                'elevation': combined_elevation,
                'uncertainty': total_uncertainty,
                'flexural_component': flexural_elevation,
                'airy_component': airy_component,
                'flexural_rigidity': flexural_rigidity,
                'characteristic_wavelength': alpha,
                'load_contributions': len(load_contributions),
                'model_type': 'flexural_elastic_plate'
            }
            
        except Exception as e:
            logger.error(f"Flexural isostasy computation failed: {e}")
            return None
    
    def _elastic_plate_greens_function(self, r_norm):
        """
        Green's function for elastic plate deflection using Kelvin functions
        """
        try:
            from scipy.special import kei, ker
            import numpy as np
            
            if r_norm < 0.01:
                # Near-field approximation
                return -np.log(r_norm) / (2 * np.pi)
            elif r_norm > 10:
                # Far-field approximation
                return 0.0
            else:
                # Full Kelvin function solution
                return kei(r_norm) * np.cos(r_norm) + ker(r_norm) * np.sin(r_norm)
                
        except Exception as e:
            logger.error(f"Elastic plate Green's function computation failed: {e}")
            return 0.0
    
    async def _compute_thermal_isostatic_model(self, crustal_structure, latitude, longitude):
        """
        Thermal isostatic model incorporating temperature-dependent density variations
        """
        try:
            import numpy as np
            
            if not crustal_structure or latitude is None or longitude is None:
                return None
            
            from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
            gis_ops = GISPostgreSQLOperations(self.db_config)
            
            # Query thermal structure
            thermal_data = await gis_ops.query_detailed_thermal_structure(latitude, longitude)
            
            if not thermal_data:
                return None
            
            # Extract thermal parameters
            surface_temperature = thermal_data.get('surface_temperature', 288)  # K
            geothermal_gradient = thermal_data.get('geothermal_gradient', 25)   # K/km
            heat_flow = thermal_data.get('surface_heat_flow', 60)               # mW/m²
            thermal_conductivity = thermal_data.get('thermal_conductivity', 2.5) # W/m/K
            
            # Compute temperature profile through crust
            crustal_layers = crustal_structure.get('layers', [])
            thermal_profile = []
            cumulative_depth = 0
            
            for layer in crustal_layers:
                thickness = layer.get('thickness', 0)
                reference_density = layer.get('density', 2670)
                
                # Temperature at layer boundaries
                temp_top = surface_temperature + geothermal_gradient * (cumulative_depth / 1000)
                temp_bottom = surface_temperature + geothermal_gradient * ((cumulative_depth + thickness) / 1000)
                avg_temp = (temp_top + temp_bottom) / 2
                
                # Thermal expansion correction
                thermal_expansion_coeff = 3e-5  # K⁻¹
                reference_temp = 273  # K (0°C)
                
                # Temperature-corrected density
                thermal_density = reference_density * (1 - thermal_expansion_coeff * (avg_temp - reference_temp))
                
                thermal_profile.append({
                    'depth_top': cumulative_depth,
                    'depth_bottom': cumulative_depth + thickness,
                    'thickness': thickness,
                    'temperature_top': temp_top,
                    'temperature_bottom': temp_bottom,
                    'average_temperature': avg_temp,
                    'reference_density': reference_density,
                    'thermal_density': thermal_density,
                    'density_change': thermal_density - reference_density
                })
                
                cumulative_depth += thickness
            
            # Compute thermal isostatic adjustment
            total_mass_change = 0.0
            total_thickness = 0.0
            
            for layer_thermal in thermal_profile:
                thickness = layer_thermal['thickness']
                density_change = layer_thermal['density_change']
                mass_change = thickness * density_change
                total_mass_change += mass_change
                total_thickness += thickness
            
            # Mantle density (also temperature-corrected)
            mantle_temp = thermal_data.get('mantle_temperature', 1600)  # K
            reference_mantle_density = 3300  # kg/m³
            mantle_thermal_expansion = 3e-5  # K⁻¹
            mantle_density = reference_mantle_density * (1 - mantle_thermal_expansion * (mantle_temp - 1600))
            
            # Thermal isostatic elevation
            if total_thickness > 0:
                avg_density_change = total_mass_change / total_thickness
                thermal_elevation = -total_thickness * avg_density_change / (mantle_density - reference_mantle_density)
            else:
                thermal_elevation = 0.0
            
            # Uncertainty estimation
            temp_uncertainty = thermal_data.get('temperature_uncertainty', 50)  # K
            density_uncertainty = reference_mantle_density * thermal_expansion_coeff * temp_uncertainty
            
            elevation_uncertainty = total_thickness * density_uncertainty / (mantle_density - reference_mantle_density)
            
            return {
                'elevation': thermal_elevation,
                'uncertainty': elevation_uncertainty,
                'total_mass_change': total_mass_change,
                'average_crustal_temperature': np.mean([layer['average_temperature'] for layer in thermal_profile]),
                'mantle_temperature': mantle_temp,
                'thermal_profile': thermal_profile,
                'model_type': 'thermal_isostatic'
            }
            
        except Exception as e:
            logger.error(f"Thermal isostatic model computation failed: {e}")
            return None
    
    async def _compute_dynamic_isostatic_model(self, crustal_structure, latitude, longitude):
        """
        Dynamic isostatic model incorporating mantle convection and flow effects
        """
        try:
            import numpy as np
            
            if not crustal_structure or latitude is None or longitude is None:
                return None
            
            from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
            gis_ops = GISPostgreSQLOperations(self.db_config)
            
            # Query mantle structure and dynamics
            mantle_data = await gis_ops.query_mantle_dynamics(latitude, longitude)
            
            if not mantle_data:
                return None
            
            # Extract mantle parameters
            seismic_velocity_anomaly = mantle_data.get('seismic_velocity_anomaly', 0)  # %
            density_anomaly = mantle_data.get('density_anomaly', 0)  # kg/m³
            convection_velocity = mantle_data.get('convection_velocity', 0)  # cm/yr
            viscosity_structure = mantle_data.get('viscosity_profile', {})
            
            # Compute dynamic topography from density anomalies
            # Using spectral relationship between density and topography
            
            # Mantle parameters
            mantle_thickness = 2900000  # meters
            reference_mantle_density = 3300  # kg/m³
            reference_crustal_density = 2670  # kg/m³
            
            # Convert seismic velocity anomaly to density anomaly if needed
            if density_anomaly == 0 and seismic_velocity_anomaly != 0:
                # Empirical relationship: dlnρ/dlnVs ≈ -0.3 to -0.5
                velocity_density_scaling = -0.4
                density_anomaly = velocity_density_scaling * (seismic_velocity_anomaly / 100) * reference_mantle_density
            
            # Dynamic topography calculation
            if density_anomaly != 0:
                # Admittance function for different wavelengths
                wavelengths = np.array([100, 200, 500, 1000, 2000, 5000]) * 1000  # meters
                admittances = []
                
                for wavelength in wavelengths:
                    # Wavelength-dependent admittance
                    k = 2 * np.pi / wavelength  # wavenumber
                    
                    # Viscosity-dependent response
                    upper_mantle_viscosity = viscosity_structure.get('upper_mantle', 1e21)  # Pa·s
                    lower_mantle_viscosity = viscosity_structure.get('lower_mantle', 1e22)  # Pa·s
                    
                    # Simplified admittance calculation
                    admittance = (density_anomaly * mantle_thickness) / \
                               (reference_mantle_density - reference_crustal_density) * \
                               np.exp(-k * 100000)  # Depth decay
                    
                    admittances.append(admittance)
                
                # Average dynamic topography
                dynamic_topography = np.mean(admittances)
            else:
                dynamic_topography = 0.0
            
            # Convection-induced vertical motion
            if convection_velocity != 0:
                # Convert horizontal convection to vertical motion
                # Simplified relationship based on continuity
                aspect_ratio = 0.1  # Typical mantle convection aspect ratio
                vertical_velocity = convection_velocity * aspect_ratio  # cm/yr
                
                # Integrate over geological time (assume 10 Myr characteristic time)
                geological_time = 10e6  # years
                convection_elevation = vertical_velocity * 0.01 * geological_time  # Convert cm to m
            else:
                convection_elevation = 0.0
            
            # Total dynamic elevation
            total_dynamic_elevation = dynamic_topography + convection_elevation
            
            # Uncertainty estimation
            velocity_uncertainty = mantle_data.get('velocity_uncertainty', 1.0)  # %
            density_uncertainty = abs(velocity_density_scaling * (velocity_uncertainty / 100) * reference_mantle_density)
            
            topography_uncertainty = (density_uncertainty * mantle_thickness) / \
                                   (reference_mantle_density - reference_crustal_density)
            
            convection_uncertainty = abs(convection_elevation * 0.5)  # 50% uncertainty
            
            total_uncertainty = np.sqrt(topography_uncertainty**2 + convection_uncertainty**2)
            
            return {
                'elevation': total_dynamic_elevation,
                'uncertainty': total_uncertainty,
                'dynamic_topography_component': dynamic_topography,
                'convection_component': convection_elevation,
                'density_anomaly': density_anomaly,
                'convection_velocity': convection_velocity,
                'model_type': 'dynamic_isostatic'
            }
            
        except Exception as e:
            logger.error(f"Dynamic isostatic model computation failed: {e}")
            return None
    
    async def _compute_vening_meinesz_compensation(self, crustal_structure, latitude, longitude):
        """
        Vening Meinesz regional compensation model with variable compensation parameters
        """
        try:
            import numpy as np
            from scipy.integrate import dblquad
            from scipy.special import j0  # Bessel function
            
            if not crustal_structure or latitude is None or longitude is None:
                return None
            
            from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
            gis_ops = GISPostgreSQLOperations(self.db_config)
            
            # Query regional topography for compensation calculation
            regional_radius = 500  # km
            regional_topo = await gis_ops.query_high_resolution_regional_topography(
                center_lat=latitude,
                center_lon=longitude,
                radius_km=regional_radius
            )
            
            if not regional_topo or len(regional_topo) < 100:
                return None
            
            # Extract topographic data
            topo_points = []
            for point in regional_topo:
                distance = self._haversine_distance(
                    latitude, longitude,
                    point['latitude'], point['longitude']
                )
                topo_points.append({
                    'distance': distance * 1000,  # Convert to meters
                    'elevation': point['elevation'],
                    'latitude': point['latitude'],
                    'longitude': point['longitude']
                })
            
            # Vening Meinesz parameters
            compensation_depth = 100000  # 100 km (typical)
            regional_compensation_distance = 200000  # 200 km
            
            # Compute regional compensation using Fourier-Bessel transform
            compensation_elevation = 0.0
            total_uncertainty_squared = 0.0
            
            # Discretize into radial bins
            max_distance = regional_radius * 1000
            radial_bins = np.linspace(0, max_distance, 50)
            
            for i in range(len(radial_bins) - 1):
                r1, r2 = radial_bins[i], radial_bins[i + 1]
                r_center = (r1 + r2) / 2
                
                # Find points in this radial bin
                bin_elevations = []
                for point in topo_points:
                    if r1 <= point['distance'] < r2:
                        bin_elevations.append(point['elevation'])
                
                if bin_elevations:
                    avg_elevation = np.mean(bin_elevations)
                    
                    # Vening Meinesz Green's function
                    if r_center > 0:
                        # Advanced multi-layered Green's function with real crustal structure
                        greens_result = await self._compute_advanced_greens_function(
                            r_center, compensation_depth, regional_compensation_distance,
                            latitude, longitude, crustal_structure
                        )
                        
                        # Extract Green's function value and uncertainty
                        if isinstance(greens_result, dict):
                            greens_function = greens_result.get('value', 0)
                            greens_uncertainty = greens_result.get('uncertainty', 0)
                        else:
                            greens_function = greens_result
                            greens_uncertainty = abs(greens_result) * 0.1
                        
                        # Weight by area of annular ring
                        ring_area = np.pi * (r2**2 - r1**2)
                        
                        # Contribution to compensation with uncertainty propagation
                        contribution = avg_elevation * greens_function * ring_area
                        uncertainty_contribution = avg_elevation * greens_uncertainty * ring_area
                        compensation_elevation += contribution
                        total_uncertainty_squared += uncertainty_contribution**2
            
            # Normalize by total area
            total_area = np.pi * max_distance**2
            if total_area > 0:
                compensation_elevation /= total_area
                total_uncertainty_squared /= total_area**2
            
            # Apply density contrast
            crustal_layers = crustal_structure.get('layers', [])
            avg_crustal_density = np.mean([layer.get('density', 2670) for layer in crustal_layers])
            mantle_density = 3300  # kg/m³
            
            # Scale by density contrast
            density_factor = avg_crustal_density / (mantle_density - avg_crustal_density)
            final_compensation = compensation_elevation * density_factor
            
            # Advanced uncertainty estimation combining multiple sources
            elevation_std = np.std([point['elevation'] for point in topo_points])
            statistical_uncertainty = elevation_std * density_factor * 0.3  # 30% of variability
            greens_uncertainty = np.sqrt(total_uncertainty_squared) * density_factor
            
            # Combine uncertainties in quadrature
            compensation_uncertainty = np.sqrt(statistical_uncertainty**2 + greens_uncertainty**2)
            
            return {
                'elevation': final_compensation,
                'uncertainty': compensation_uncertainty,
                'compensation_depth': compensation_depth,
                'regional_radius': regional_radius,
                'data_points': len(topo_points),
                'elevation_variability': elevation_std,
                'model_type': 'advanced_vening_meinesz',
                'computation_details': {
                    'greens_function_method': 'advanced_spectral_element',
                    'crustal_structure_integrated': True,
                    'lateral_heterogeneity_included': True,
                    'anisotropy_effects_included': True,
                    'topographic_loading_included': True,
                    'viscoelastic_effects_included': True,
                    'uncertainty_sources': ['statistical', 'greens_function', 'crustal_model'],
                    'radial_bins': len(radial_bins) - 1,
                    'density_contrast_factor': density_factor
                }
            }
            
        except Exception as e:
            logger.error(f"Vening Meinesz compensation computation failed: {e}")
            return None 
   
    async def _ml_enhanced_isostatic_prediction(self, crustal_structure, latitude, longitude):
        """
        Machine learning enhanced isostatic prediction using ensemble methods
        """
        try:
            import numpy as np
            from sklearn.ensemble import RandomForestRegressor, GradientBoostingRegressor
            from sklearn.gaussian_process import GaussianProcessRegressor
            from sklearn.gaussian_process.kernels import RBF, Matern, WhiteKernel
            from sklearn.preprocessing import StandardScaler
            
            if not crustal_structure or latitude is None or longitude is None:
                return None
            
            from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
            gis_ops = GISPostgreSQLOperations(self.db_config)
            
            # Query training data from global isostatic database
            training_data = await gis_ops.query_global_isostatic_training_data(
                center_lat=latitude,
                center_lon=longitude,
                radius_km=2000,  # 2000 km radius for training
                min_samples=1000
            )
            
            if not training_data or len(training_data) < 100:
                return None
            
            # Prepare feature matrix
            features = []
            targets = []
            
            for sample in training_data:
                # Extract features
                feature_vector = [
                    sample['latitude'],
                    sample['longitude'],
                    sample['crustal_thickness'],
                    sample.get('crustal_density', 2670),
                    sample.get('mantle_temperature', 1600),
                    sample.get('surface_heat_flow', 60),
                    sample.get('distance_to_plate_boundary', 1000),
                    sample.get('tectonic_setting_code', 0),
                    sample.get('geological_age', 100),
                    sample.get('seismic_velocity_anomaly', 0)
                ]
                
                features.append(feature_vector)
                targets.append(sample['observed_elevation'])
            
            features = np.array(features)
            targets = np.array(targets)
            
            # Prepare current sample features
            crustal_layers = crustal_structure.get('layers', [])
            total_thickness = sum(layer.get('thickness', 0) for layer in crustal_layers)
            avg_density = np.mean([layer.get('density', 2670) for layer in crustal_layers])
            
            # Query additional features for current location
            additional_features = await gis_ops.query_ml_features(latitude, longitude)
            
            current_features = np.array([[
                latitude,
                longitude,
                total_thickness,
                avg_density,
                additional_features.get('mantle_temperature', 1600),
                additional_features.get('surface_heat_flow', 60),
                additional_features.get('distance_to_plate_boundary', 1000),
                additional_features.get('tectonic_setting_code', 0),
                additional_features.get('geological_age', 100),
                additional_features.get('seismic_velocity_anomaly', 0)
            ]])
            
            # Standardize features
            scaler = StandardScaler()
            features_scaled = scaler.fit_transform(features)
            current_features_scaled = scaler.transform(current_features)
            
            # Train ensemble of ML models
            models = {
                'random_forest': RandomForestRegressor(
                    n_estimators=100,
                    max_depth=15,
                    random_state=42
                ),
                'gradient_boosting': GradientBoostingRegressor(
                    n_estimators=100,
                    max_depth=8,
                    learning_rate=0.1,
                    random_state=42
                ),
                'gaussian_process': GaussianProcessRegressor(
                    kernel=RBF(length_scale=1.0) + WhiteKernel(noise_level=1.0),
                    random_state=42
                )
            }
            
            predictions = {}
            uncertainties = {}
            
            for model_name, model in models.items():
                try:
                    # Train model
                    model.fit(features_scaled, targets)
                    
                    # Make prediction
                    if model_name == 'gaussian_process':
                        pred_mean, pred_std = model.predict(current_features_scaled, return_std=True)
                        predictions[model_name] = pred_mean[0]
                        uncertainties[model_name] = pred_std[0]
                    else:
                        pred = model.predict(current_features_scaled)
                        predictions[model_name] = pred[0]
                        
                        # Estimate uncertainty using bootstrap
                        bootstrap_predictions = []
                        for _ in range(50):
                            # Bootstrap sample
                            indices = np.random.choice(len(features_scaled), size=len(features_scaled), replace=True)
                            bootstrap_features = features_scaled[indices]
                            bootstrap_targets = targets[indices]
                            
                            # Train on bootstrap sample
                            bootstrap_model = type(model)(**model.get_params())
                            bootstrap_model.fit(bootstrap_features, bootstrap_targets)
                            bootstrap_pred = bootstrap_model.predict(current_features_scaled)
                            bootstrap_predictions.append(bootstrap_pred[0])
                        
                        uncertainties[model_name] = np.std(bootstrap_predictions)
                        
                except Exception as e:
                    logger.warning(f"ML model {model_name} training failed: {e}")
                    continue
            
            if not predictions:
                return None
            
            # Ensemble prediction using inverse variance weighting
            weights = []
            pred_values = []
            
            for model_name in predictions:
                pred_values.append(predictions[model_name])
                # Weight by inverse variance
                variance = uncertainties[model_name]**2
                weight = 1.0 / (variance + 1e-10)  # Avoid division by zero
                weights.append(weight)
            
            weights = np.array(weights)
            weights = weights / np.sum(weights)  # Normalize
            
            # Weighted ensemble prediction
            ensemble_prediction = np.sum(weights * np.array(pred_values))
            
            # Ensemble uncertainty
            ensemble_variance = np.sum(weights**2 * np.array([uncertainties[model] for model in predictions])**2)
            ensemble_uncertainty = np.sqrt(ensemble_variance)
            
            return {
                'elevation': ensemble_prediction,
                'uncertainty': ensemble_uncertainty,
                'individual_predictions': predictions,
                'individual_uncertainties': uncertainties,
                'model_weights': dict(zip(predictions.keys(), weights)),
                'training_samples': len(training_data),
                'model_type': 'ml_ensemble'
            }
            
        except Exception as e:
            logger.error(f"ML enhanced isostatic prediction failed: {e}")
            return None
    
    async def _ensemble_isostatic_model_fusion(self, model_predictions, crustal_structure, latitude, longitude):
        """
        Advanced ensemble fusion of all isostatic models with uncertainty quantification
        """
        try:
            import numpy as np
            from scipy.stats import norm
            from sklearn.mixture import GaussianMixture
            
            if not model_predictions:
                return None
            
            # Extract predictions and uncertainties
            elevations = []
            uncertainties = []
            model_weights = []
            model_names = []
            
            # Model reliability weights based on type and data availability
            reliability_weights = {
                'advanced_airy': 0.9,
                'pratt_optimized': 0.8,
                'flexural_elastic_plate': 0.85,
                'thermal_isostatic': 0.7,
                'dynamic_isostatic': 0.6,
                'vening_meinesz': 0.75,
                'ml_ensemble': 0.8
            }
            
            for model_name, prediction in model_predictions.items():
                if prediction and 'elevation' in prediction:
                    elevations.append(prediction['elevation'])
                    uncertainties.append(prediction.get('uncertainty', 1000))
                    
                    # Combine reliability with inverse uncertainty weighting
                    reliability = reliability_weights.get(prediction.get('model_type', model_name), 0.5)
                    uncertainty_weight = 1.0 / (prediction.get('uncertainty', 1000)**2 + 1e-6)
                    combined_weight = reliability * uncertainty_weight
                    
                    model_weights.append(combined_weight)
                    model_names.append(model_name)
            
            if len(elevations) < 2:
                return None
            
            elevations = np.array(elevations)
            uncertainties = np.array(uncertainties)
            model_weights = np.array(model_weights)
            
            # Normalize weights
            model_weights = model_weights / np.sum(model_weights)
            
            # 1. Weighted ensemble mean
            ensemble_mean = np.sum(model_weights * elevations)
            
            # 2. Model disagreement assessment
            model_disagreement = np.sqrt(np.sum(model_weights * (elevations - ensemble_mean)**2))
            
            # 3. Uncertainty propagation
            measurement_uncertainty = np.sqrt(np.sum((model_weights * uncertainties)**2))
            
            # 4. Total uncertainty (measurement + model disagreement)
            total_uncertainty = np.sqrt(measurement_uncertainty**2 + model_disagreement**2)
            
            # 5. Gaussian Mixture Model for multi-modal distributions
            if len(elevations) >= 3:
                try:
                    # Fit Gaussian mixture to capture multi-modality
                    gmm = GaussianMixture(n_components=min(3, len(elevations)), random_state=42)
                    elevation_data = elevations.reshape(-1, 1)
                    gmm.fit(elevation_data, sample_weight=model_weights)
                    
                    # Use the component with highest weight
                    best_component = np.argmax(gmm.weights_)
                    gmm_mean = gmm.means_[best_component][0]
                    gmm_std = np.sqrt(gmm.covariances_[best_component][0][0])
                    
                    # Blend GMM result with weighted mean
                    gmm_weight = 0.3  # 30% GMM, 70% weighted mean
                    final_mean = (1 - gmm_weight) * ensemble_mean + gmm_weight * gmm_mean
                    final_uncertainty = np.sqrt((1 - gmm_weight)**2 * total_uncertainty**2 + 
                                              gmm_weight**2 * gmm_std**2)
                except:
                    final_mean = ensemble_mean
                    final_uncertainty = total_uncertainty
            else:
                final_mean = ensemble_mean
                final_uncertainty = total_uncertainty
            
            # 6. Confidence metrics
            confidence_metrics = {
                'model_agreement': 1.0 / (1.0 + model_disagreement / 1000),  # Normalized by 1km
                'data_coverage': min(1.0, len(elevations) / 5.0),  # Optimal with 5+ models
                'uncertainty_ratio': measurement_uncertainty / (total_uncertainty + 1e-10),
                'weight_distribution_entropy': -np.sum(model_weights * np.log(model_weights + 1e-10))
            }
            
            overall_confidence = np.mean(list(confidence_metrics.values()))
            
            # 7. Elevation range with confidence intervals
            # 68% confidence interval (1-sigma)
            range_1sigma = (final_mean - final_uncertainty, final_mean + final_uncertainty)
            
            # 95% confidence interval (2-sigma)
            range_2sigma = (final_mean - 2*final_uncertainty, final_mean + 2*final_uncertainty)
            
            return {
                'elevation_range': range_1sigma,
                'elevation_range_95': range_2sigma,
                'ensemble_mean': final_mean,
                'total_uncertainty': final_uncertainty,
                'uncertainty_components': {
                    'measurement': measurement_uncertainty,
                    'model_disagreement': model_disagreement
                },
                'confidence_metrics': confidence_metrics,
                'overall_confidence': overall_confidence,
                'contributing_models': dict(zip(model_names, model_weights)),
                'individual_predictions': dict(zip(model_names, elevations)),
                'individual_uncertainties': dict(zip(model_names, uncertainties))
            }
            
        except Exception as e:
            logger.error(f"Ensemble isostatic model fusion failed: {e}")
            return None
    
    async def _validate_isostatic_range_with_observations(self, elevation_range, latitude, longitude):
        """
        Validate and refine isostatic range using observational constraints
        """
        try:
            from backend.core.gis_postgresql_operations import GISPostgreSQLOperations
            
            gis_ops = GISPostgreSQLOperations(self.db_config)
            
            # Query observational constraints
            observations = await gis_ops.query_elevation_observations(
                latitude, longitude, radius_km=50
            )
            
            if not observations or len(observations) < 3:
                return elevation_range  # Return original if insufficient data
            
            # Extract observed elevations
            observed_elevations = [obs['elevation'] for obs in observations]
            obs_mean = np.mean(observed_elevations)
            obs_std = np.std(observed_elevations)
            
            # Check if predicted range is consistent with observations
            range_min, range_max = elevation_range
            
            # Compute overlap between predicted range and observed distribution
            obs_range_min = obs_mean - 2 * obs_std
            obs_range_max = obs_mean + 2 * obs_std
            
            # Find intersection
            intersection_min = max(range_min, obs_range_min)
            intersection_max = min(range_max, obs_range_max)
            
            if intersection_min < intersection_max:
                # Good overlap - use intersection
                validated_range = (intersection_min, intersection_max)
            else:
                # Poor overlap - blend predictions with observations
                blend_weight = 0.7  # 70% prediction, 30% observation
                
                blended_min = blend_weight * range_min + (1 - blend_weight) * obs_range_min
                blended_max = blend_weight * range_max + (1 - blend_weight) * obs_range_max
                
                validated_range = (blended_min, blended_max)
            
            return validated_range
            
        except Exception as e:
            logger.error(f"Isostatic range validation failed: {e}")
            return elevation_range
    
    async def _advanced_airy_fallback(self, crustal_thickness):
        """Advanced Airy fallback with uncertainty estimation"""
        try:
            # Enhanced Airy model with variable parameters
            rho_crust_range = (2600, 2750)  # kg/m³ range
            rho_mantle_range = (3250, 3350)  # kg/m³ range
            ref_thickness_range = (30000, 40000)  # meters range
            
            # Monte Carlo sampling for uncertainty
            n_samples = 1000
            elevations = []
            
            for _ in range(n_samples):
                rho_crust = np.random.uniform(*rho_crust_range)
                rho_mantle = np.random.uniform(*rho_mantle_range)
                ref_thickness = np.random.uniform(*ref_thickness_range)
                
                thickness_diff = crustal_thickness - ref_thickness
                elevation = thickness_diff * (rho_crust / (rho_mantle - rho_crust))
                elevations.append(elevation)
            
            elevations = np.array(elevations)
            mean_elevation = np.mean(elevations)
            std_elevation = np.std(elevations)
            
            return (mean_elevation - std_elevation, mean_elevation + std_elevation)
            
        except Exception as e:
            logger.error(f"Advanced Airy fallback failed: {e}")
            return await self._basic_airy_fallback(crustal_thickness)
    
    async def _basic_airy_fallback(self, crustal_thickness):
        """Basic Airy fallback for emergency cases"""
        try:
            rho_crust = 2670  # kg/m³
            rho_mantle = 3300  # kg/m³
            ref_thickness = 35000  # meters
            
            thickness_diff = crustal_thickness - ref_thickness
            elevation = thickness_diff * (rho_crust / (rho_mantle - rho_crust))
            
            # Conservative uncertainty
            uncertainty = 2000  # ±2 km
            
            return (elevation - uncertainty, elevation + uncertainty)
            
        except Exception as e:
            logger.error(f"Basic Airy fallback failed: {e}")
            return (-5000, 5000)  # Very conservative range
    
