    async def _compute_ridge_thermal_structure(self, distance_to_ridge, spreading_rate, crustal_age):
        """Compute thermal structure at mid-ocean ridge"""
        try:
            # Thermal diffusivity
            kappa = 1e-6  # m²/s
            
            # Thermal boundary layer thickness
            thermal_thickness = 2.32 * np.sqrt(kappa * crustal_age * 1e6 * 365.25 * 24 * 3600)
            
            # Temperature at base of thermal boundary layer
            mantle_temp = 1350  # °C
            
            # Thermal subsidence
            thermal_subsidence = 350 * np.sqrt(crustal_age)  # Parsons & Sclater model
            
            return {
                'elevation': -2500 - thermal_subsidence,
                'uncertainty': 200 + crustal_age * 2,
                'thermal_thickness': thermal_thickness,
                'mantle_temperature': mantle_temp
            }
            
        except Exception as e:
            logger.error(f"Thermal structure computation failed: {e}")
            return {'elevation': 0, 'uncertainty': 500}
    
    async def _compute_lithospheric_flexure(self, latitude, longitude, distance_to_ridge, thermal_model):
        """Compute lithospheric flexure response"""
        try:
            # Flexural rigidity (depends on thermal structure)
            elastic_thickness = max(5000, thermal_model.get('thermal_thickness', 20000))
            flexural_rigidity = (70e9 * elastic_thickness**3) / (12 * (1 - 0.25**2))
            
            # Load from thermal structure
            thermal_load = thermal_model.get('mantle_temperature', 1350) * 2800 * 9.81 * 0.001
            
            # Flexural response
            flexural_wavelength = (4 * flexural_rigidity / (3300 * 9.81))**0.25
            deflection = thermal_load * np.exp(-distance_to_ridge / flexural_wavelength)
            
            return {
                'elevation': deflection / 1000,  # Convert to meters
                'uncertainty': abs(deflection) * 0.2 / 1000,
                'flexural_wavelength': flexural_wavelength
            }
            
        except Exception as e:
            logger.error(f"Flexural computation failed: {e}")
            return {'elevation': 0, 'uncertainty': 300}
    
    async def _apply_geological_corrections(self, latitude, longitude, geological_context, base_elevation):
        """Apply geological corrections to elevation"""
        try:
            correction = 0
            uncertainty_increase = 0
            confidence = 0.5
            
            if geological_context:
                for unit in geological_context:
                    # Age-based correction
                    age = unit.get('age_ma', 0)
                    if age > 0:
                        age_correction = np.log(age + 1) * 50
                        correction += age_correction
                    
                    # Lithology-based correction
                    lithology = unit.get('primary_lithology', '')
                    if 'basalt' in lithology.lower():
                        correction += 100
                    elif 'granite' in lithology.lower():
                        correction += 200
                    
                    uncertainty_increase += 50
                    confidence = max(confidence, unit.get('confidence_level', 0.5))
            
            return {
                'elevation_adjustment': correction,
                'uncertainty_increase': uncertainty_increase,
                'confidence': confidence
            }
            
        except Exception as e:
            logger.error(f"Geological correction failed: {e}")
            return {'elevation_adjustment': 0, 'uncertainty_increase': 100, 'confidence': 0.3}
    
    async def _fallback_ridge_elevation(self, latitude, longitude, tectonic_data):
        """Fallback method for ridge elevation"""
        distance_to_ridge = tectonic_data.get('distance_to_boundary', 0)
        spreading_rate = tectonic_data.get('spreading_rate_mm_yr', 20)
        
        # Simple Parsons & Sclater model
        ridge_depth = -2500 + 350 * np.sqrt(distance_to_ridge / 1000)
        spreading_factor = np.log(spreading_rate / 20 + 1) * 200
        
        return {
            'elevation': ridge_depth + spreading_factor,
            'uncertainty': 300 + distance_to_ridge * 0.1,
            'quality_score': 0.3,
            'model_components': {'fallback': True}
        }
    
