        extension_factor = np.log(extension_rate / 5 + 1) * 300
        elevation += extension_factor
        
        return {
            'elevation': elevation,
            'uncertainty': 300 + distance_to_rift * 0.005,
            'quality_score': 0.3,
            'model_components': {'fallback': True}
        }
    
