    async def _fetch_regional_geological_data(self, latitude, longitude):
        """Fetch regional geological survey data"""
        try:
            regional_data = {}
            
            # Determine region and fetch appropriate data
            if self._is_north_america(latitude, longitude):
                regional_data.update(await self._fetch_usgs_regional_data(latitude, longitude))
            elif self._is_europe(latitude, longitude):
                regional_data.update(await self._fetch_european_geological_data(latitude, longitude))
            elif self._is_asia_pacific(latitude, longitude):
                regional_data.update(await self._fetch_asia_pacific_data(latitude, longitude))
            
            return regional_data
            
        except Exception as e:
            logger.warning(f"Regional geological data fetch failed: {e}")
            return {}
    
    def _is_north_america(self, latitude, longitude):
        """Check if coordinates are in North America"""
        return (25 <= latitude <= 70) and (-170 <= longitude <= -50)
    
    def _is_europe(self, latitude, longitude):
        """Check if coordinates are in Europe"""
        return (35 <= latitude <= 75) and (-15 <= longitude <= 50)
    
    def _is_asia_pacific(self, latitude, longitude):
        """Check if coordinates are in Asia-Pacific region"""
        return ((-50 <= latitude <= 70) and (50 <= longitude <= 180)) or \
               ((-50 <= latitude <= 20) and (100 <= longitude <= 180))
    
