    async def _fetch_usgs_bathymetry(self, latitude, longitude):
        """Fetch bathymetry data from USGS"""
        try:
            import aiohttp
            
            # USGS Coastal and Marine Geology Program
            url = "https://coastalmap.marine.usgs.gov/cmgp/services/bathymetry/wms"
            params = {
                'service': 'WMS',
                'version': '1.3.0',
                'request': 'GetFeatureInfo',
                'layers': 'bathymetry',
                'query_layers': 'bathymetry',
                'i': 50,
                'j': 50,
                'width': 101,
                'height': 101,
                'crs': 'EPSG:4326',
                'bbox': f"{longitude-0.001},{latitude-0.001},{longitude+0.001},{latitude+0.001}",
                'info_format': 'application/json'
            }
            
            async with aiohttp.ClientSession() as session:
                async with session.get(url, params=params) as response:
                    if response.status == 200:
                        data = await response.json()
                        if 'features' in data and data['features']:
                            depth = data['features'][0].get('properties', {}).get('depth', 0)
                            return {'depth': abs(depth), 'source': 'USGS_Bathymetry'}
            
            return None
            
        except Exception as e:
            logger.warning(f"USGS bathymetry fetch failed: {e}")
