    async def _fetch_noaa_bathymetry(self, latitude, longitude):
        """Fetch bathymetry data from NOAA"""
        try:
            import aiohttp
            
            # NOAA National Centers for Environmental Information
            url = "https://maps.ngdc.noaa.gov/mapviewer-support/bathymetry/bathymetry_query.json"
            params = {
                'lat': latitude,
                'lon': longitude
            }
            
            async with aiohttp.ClientSession() as session:
                async with session.get(url, params=params) as response:
                    if response.status == 200:
                        data = await response.json()
                        depth = data.get('depth', 0)
                        
                        if depth > 200:
                            classification = 'oceanic'
                            confidence = 0.9
                        elif depth > 0:
                            classification = 'continental_shelf'
                            confidence = 0.7
                        else:
                            classification = 'continental'
                            confidence = 0.95
                        
                        return {
                            'classification': classification,
                            'confidence': confidence,
                            'depth': abs(depth),
                            'source': 'NOAA_Bathymetry'
                        }
            
            return None
            
        except Exception as e:
            logger.warning(f"NOAA bathymetry fetch failed: {e}")
            return None
    
