    async def _query_world_stress_map(self, latitude, longitude):
        """Query World Stress Map database for regional stress indicators"""
        try:
            # Query WSM database within 200km radius
            async with self.db_integrator.get_postgresql_session() as session:
                query = """
                SELECT 
                    shmax_azimuth,
                    stress_regime,
                    data_quality,
                    depth_km,
                    method,
                    ST_Distance(
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                        ST_Transform(location, 3857)
                    ) as distance_m
                FROM world_stress_map_data 
                WHERE ST_DWithin(
                    ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                    ST_Transform(location, 3857),
                    200000
                )
                AND data_quality IN ('A', 'B', 'C')
                ORDER BY 
                    CASE data_quality WHEN 'A' THEN 1 WHEN 'B' THEN 2 WHEN 'C' THEN 3 END,
                    distance_m
                LIMIT 50
                """
                
                result = await session.execute(query, (longitude, latitude, longitude, latitude))
                wsm_records = result.fetchall()
                
                if wsm_records:
                    # Distance-weighted interpolation of stress orientations
                    weights = []
                    azimuths = []
                    regimes = []
                    
                    for record in wsm_records:
                        # Weight by inverse distance and data quality
                        quality_weight = {'A': 1.0, 'B': 0.8, 'C': 0.6}.get(record.data_quality, 0.5)
                        distance_weight = 1.0 / (record.distance_m + 1000)  # +1km to avoid division by zero
                        combined_weight = quality_weight * distance_weight
                        
                        weights.append(combined_weight)
                        azimuths.append(record.shmax_azimuth)
                        regimes.append(record.stress_regime)
                    
                    # Calculate weighted average azimuth (handling circular data)
                    if azimuths and weights:
                        # Convert to unit vectors for circular averaging
                        x_components = [w * np.cos(np.radians(2 * az)) for w, az in zip(weights, azimuths)]
                        y_components = [w * np.sin(np.radians(2 * az)) for w, az in zip(weights, azimuths)]
                        
                        mean_x = sum(x_components) / sum(weights)
                        mean_y = sum(y_components) / sum(weights)
                        
                        # Convert back to azimuth
                        mean_azimuth = (np.degrees(np.arctan2(mean_y, mean_x)) / 2) % 180
                        
                        # Determine dominant stress regime
                        regime_counts = {}
                        for regime, weight in zip(regimes, weights):
                            regime_counts[regime] = regime_counts.get(regime, 0) + weight
                        
                        dominant_regime = max(regime_counts, key=regime_counts.get)
                        
                        # Calculate uncertainty based on data scatter
                        azimuth_deviations = [abs(az - mean_azimuth) for az in azimuths]
                        azimuth_uncertainty = np.sqrt(sum(w * dev**2 for w, dev in zip(weights, azimuth_deviations)) / sum(weights))
                        
                        return {
                            'shmax_azimuth': mean_azimuth,
                            'azimuth_uncertainty': azimuth_uncertainty,
                            'stress_regime': dominant_regime,
                            'regime_confidence': regime_counts[dominant_regime] / sum(regime_counts.values()),
                            'data_points': len(wsm_records),
                            'max_distance_km': max(r.distance_m for r in wsm_records) / 1000,
                            'average_quality': sum(weights) / len(weights),
                            'interpolation_method': 'circular_distance_weighted'
                        }
                
                return None
                
        except Exception as e:
            logger.warning(f"World Stress Map query failed: {e}")
            return None
    
    async def _query_focal_mechanisms(self, latitude, longitude):
        """Query earthquake focal mechanisms for stress field inversion"""
        try:
            # Query focal mechanism database within 100km and last 20 years
            async with self.db_integrator.get_postgresql_session() as session:
                query = """
                SELECT 
                    magnitude,
                    depth_km,
                    strike1, dip1, rake1,
                    strike2, dip2, rake2,
                    moment_tensor,
                    ST_Distance(
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                        ST_Transform(epicenter, 3857)
                    ) as distance_m
                FROM seismic_events 
                WHERE ST_DWithin(
                    ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                    ST_Transform(epicenter, 3857),
                    100000
                )
                AND magnitude >= 4.0
                AND origin_time >= NOW() - INTERVAL '20 years'
                AND (strike1 IS NOT NULL OR moment_tensor IS NOT NULL)
                ORDER BY magnitude DESC, distance_m ASC
                LIMIT 100
                """
                
                result = await session.execute(query, (longitude, latitude, longitude, latitude))
                focal_mechanisms = result.fetchall()
                
                return [
                    {
                        'magnitude': fm.magnitude,
                        'depth_km': fm.depth_km,
                        'distance_m': fm.distance_m,
                        'nodal_plane_1': {
                            'strike': fm.strike1,
                            'dip': fm.dip1,
                            'rake': fm.rake1
                        } if fm.strike1 else None,
                        'nodal_plane_2': {
                            'strike': fm.strike2,
                            'dip': fm.dip2,
                            'rake': fm.rake2
                        } if fm.strike2 else None,
                        'moment_tensor': fm.moment_tensor
                    }
                    for fm in focal_mechanisms
                ]
                
        except Exception as e:
            logger.warning(f"Focal mechanism query failed: {e}")
            return []
    
    async def _invert_stress_from_focal_mechanisms(self, focal_mechanisms):
        """
        Advanced stress tensor inversion from focal mechanism data using multiple algorithms
        
        Implements:
        1. Michael (1984) stress inversion with bootstrap uncertainty
        2. Gephart & Forsyth (1984) grid search method
        3. Lund & Slunga (1999) FMSI algorithm
        4. Bayesian stress inversion with MCMC sampling
        5. Machine learning enhanced stress prediction
        """
        try:
            if len(focal_mechanisms) < 6:  # Minimum for robust inversion
                logger.warning(f"Insufficient focal mechanisms for stress inversion: {len(focal_mechanisms)}")
                return None
            
            # Initialize database integration for enhanced data access
            from backend.core.database_integration import EnhancedDatabaseIntegrator
            db_integrator = EnhancedDatabaseIntegrator()
            await db_integrator.initialize()
            
            # Fetch additional geological context data
            geological_context = await self._fetch_geological_context(focal_mechanisms, db_integrator)
            
            # Preprocess and validate focal mechanism data
            processed_fms = await self._preprocess_focal_mechanisms(focal_mechanisms, geological_context)
            
            if len(processed_fms) < 6:
                return None
            
            # Multi-algorithm stress inversion ensemble
            inversion_results = {}
            
            # 1. Enhanced Michael (1984) method with bootstrap uncertainty
            michael_result = await self._michael_stress_inversion(processed_fms)
            if michael_result:
                inversion_results['michael1984'] = michael_result
            
            # 2. Gephart & Forsyth (1984) grid search method
            gephart_result = await self._gephart_forsyth_inversion(processed_fms)
            if gephart_result:
                inversion_results['gephart_forsyth'] = gephart_result
            
            # 3. FMSI (Lund & Slunga 1999) algorithm
            fmsi_result = await self._fmsi_stress_inversion(processed_fms)
            if fmsi_result:
                inversion_results['fmsi'] = fmsi_result
            
            # 4. Bayesian stress inversion with MCMC
            bayesian_result = await self._bayesian_stress_inversion(processed_fms, geological_context)
            if bayesian_result:
                inversion_results['bayesian_mcmc'] = bayesian_result
            
            # 5. Machine learning enhanced prediction
            ml_result = await self._ml_enhanced_stress_prediction(processed_fms, geological_context, db_integrator)
            if ml_result:
                inversion_results['ml_enhanced'] = ml_result
            
            # Ensemble analysis and uncertainty quantification
            ensemble_result = await self._ensemble_stress_analysis(inversion_results, processed_fms)
            
            # Store results in database for future analysis
            await self._store_stress_inversion_results(ensemble_result, processed_fms, db_integrator)
            
            await db_integrator.cleanup()
            
            return ensemble_result
            
        except Exception as e:
            logger.error(f"Advanced stress inversion failed: {e}")
            import traceback
            logger.error(traceback.format_exc())
            return None
    
    async def _fetch_geological_context(self, focal_mechanisms, db_integrator):
        """Fetch geological context data for enhanced stress inversion"""
        try:
            # Calculate bounding box for focal mechanisms
            lats = [fm['latitude'] for fm in focal_mechanisms]
            lons = [fm['longitude'] for fm in focal_mechanisms]
            depths = [fm['depth_km'] for fm in focal_mechanisms]
            
            min_lat, max_lat = min(lats) - 0.1, max(lats) + 0.1
            min_lon, max_lon = min(lons) - 0.1, max(lons) + 0.1
            min_depth, max_depth = min(depths) - 5, max(depths) + 5
            
            # Fetch geological units
            geological_units = await db_integrator.execute_unified_query(
                "geological_units",
                bbox=[min_lon, min_lat, max_lon, max_lat],
                depth_range=[min_depth, max_depth]
            )
            
            # Fetch regional stress indicators
            regional_stress = await db_integrator.execute_unified_query(
                "regional_stress_indicators",
                bbox=[min_lon, min_lat, max_lon, max_lat]
            )
            
            # Fetch tectonic setting information
            tectonic_setting = await self._determine_tectonic_setting(
                np.mean(lats), np.mean(lons), db_integrator
            )
            
            return {
                'geological_units': geological_units.data if geological_units.data else [],
                'regional_stress': regional_stress.data if regional_stress.data else [],
                'tectonic_setting': tectonic_setting,
                'spatial_bounds': {
                    'lat_range': [min_lat, max_lat],
                    'lon_range': [min_lon, max_lon],
                    'depth_range': [min_depth, max_depth]
                }
            }
            
        except Exception as e:
            logger.warning(f"Failed to fetch geological context: {e}")
            return {'geological_units': [], 'regional_stress': [], 'tectonic_setting': 'unknown'}
    
    async def _preprocess_focal_mechanisms(self, focal_mechanisms, geological_context):
        """Advanced preprocessing of focal mechanism data with quality assessment"""
        processed_fms = []
        
        for fm in focal_mechanisms:
            try:
                # Quality assessment based on multiple criteria
                quality_score = self._assess_focal_mechanism_quality(fm, geological_context)
                
                if quality_score < 0.3:  # Skip low-quality data
                    continue
                
                # Extract both nodal planes for ambiguity resolution
                planes = []
                
                for plane_key in ['nodal_plane_1', 'nodal_plane_2']:
                    if fm.get(plane_key):
                        plane = fm[plane_key]
                        
                        # Convert to radians
                        strike = np.radians(plane['strike'])
                        dip = np.radians(plane['dip'])
                        rake = np.radians(plane['rake'])
                        
                        # Calculate fault normal and slip vectors using proper transformations
                        fault_normal = np.array([
                            -np.sin(dip) * np.sin(strike),
                            np.sin(dip) * np.cos(strike),
                            -np.cos(dip)
                        ])
                        
                        slip_vector = np.array([
                            np.cos(rake) * np.cos(strike) + np.cos(dip) * np.sin(rake) * np.sin(strike),
                            np.cos(rake) * np.sin(strike) - np.cos(dip) * np.sin(rake) * np.cos(strike),
                            -np.sin(dip) * np.sin(rake)
                        ])
                        
                        # Normalize vectors
                        fault_normal = fault_normal / np.linalg.norm(fault_normal)
                        slip_vector = slip_vector / np.linalg.norm(slip_vector)
                        
                        planes.append({
                            'strike': plane['strike'],
                            'dip': plane['dip'],
                            'rake': plane['rake'],
                            'normal': fault_normal,
                            'slip': slip_vector
                        })
                
                if len(planes) >= 1:
                    # Calculate moment tensor components if available
                    moment_tensor = self._calculate_moment_tensor(planes[0]) if len(planes) > 0 else None
                    
                    # Enhanced weighting scheme
                    weight = self._calculate_focal_mechanism_weight(fm, quality_score, geological_context)
                    
                    processed_fm = {
                        'original_data': fm,
                        'planes': planes,
                        'moment_tensor': moment_tensor,
                        'quality_score': quality_score,
                        'weight': weight,
                        'location': np.array([fm['longitude'], fm['latitude'], fm['depth_km']]),
                        'magnitude': fm['magnitude'],
                        'timestamp': fm.get('timestamp', datetime.now())
                    }
                    
                    processed_fms.append(processed_fm)
                    
            except Exception as e:
                logger.warning(f"Failed to process focal mechanism: {e}")
                continue
        
        logger.info(f"Processed {len(processed_fms)} focal mechanisms from {len(focal_mechanisms)} input")
        return processed_fms
    
    def _assess_focal_mechanism_quality(self, fm, geological_context):
        """Assess focal mechanism quality using multiple criteria"""
        quality_factors = []
        
        # Magnitude-based quality (higher magnitude = better constraint)
        mag_quality = min(1.0, max(0.1, (fm['magnitude'] - 3.0) / 4.0))
        quality_factors.append(('magnitude', mag_quality, 0.3))
        
        # Depth constraint quality
        depth_quality = 1.0 if fm.get('depth_uncertainty_km', 10) < 5 else 0.5
        quality_factors.append(('depth', depth_quality, 0.2))
        
        # Station coverage (if available)
        station_count = fm.get('station_count', 10)
        station_quality = min(1.0, station_count / 20.0)
        quality_factors.append(('stations', station_quality, 0.2))
        
        # Azimuthal gap quality
        azimuthal_gap = fm.get('azimuthal_gap', 180)
        gap_quality = max(0.1, 1.0 - azimuthal_gap / 360.0)
        quality_factors.append(('azimuthal_gap', gap_quality, 0.15))
        
        # Temporal relevance (recent events weighted higher)
        if fm.get('timestamp'):
            age_days = (datetime.now() - fm['timestamp']).days
            temporal_quality = max(0.1, np.exp(-age_days / 365.0))  # Exponential decay over 1 year
        else:
            temporal_quality = 0.5
        quality_factors.append(('temporal', temporal_quality, 0.15))
        
        # Calculate weighted quality score
        total_weight = sum(weight for _, _, weight in quality_factors)
        quality_score = sum(score * weight for _, score, weight in quality_factors) / total_weight
        
        return quality_score
    
    def _calculate_moment_tensor(self, plane):
        """Calculate moment tensor from fault plane parameters"""
        try:
            # Convert to radians
            strike = np.radians(plane['strike'])
            dip = np.radians(plane['dip'])
            rake = np.radians(plane['rake'])
            
            # Direction cosines for fault normal
            n1 = -np.sin(dip) * np.sin(strike)
            n2 = np.sin(dip) * np.cos(strike)
            n3 = -np.cos(dip)
            
            # Direction cosines for slip vector
            s1 = np.cos(rake) * np.cos(strike) + np.cos(dip) * np.sin(rake) * np.sin(strike)
            s2 = np.cos(rake) * np.sin(strike) - np.cos(dip) * np.sin(rake) * np.cos(strike)
            s3 = -np.sin(dip) * np.sin(rake)
            
            # Moment tensor components (normalized)
            m11 = s1 * n1
            m22 = s2 * n2
            m33 = s3 * n3
            m12 = 0.5 * (s1 * n2 + s2 * n1)
            m13 = 0.5 * (s1 * n3 + s3 * n1)
            m23 = 0.5 * (s2 * n3 + s3 * n2)
            
            return np.array([
                [m11, m12, m13],
                [m12, m22, m23],
                [m13, m23, m33]
            ])
            
        except Exception as e:
            logger.warning(f"Moment tensor calculation failed: {e}")
            return None
    
    def _calculate_focal_mechanism_weight(self, fm, quality_score, geological_context):
        """Calculate sophisticated weighting for focal mechanism in stress inversion"""
        # Base weight from quality score
        base_weight = quality_score
        
        # Magnitude weighting (moment scales as 10^(1.5*M))
        magnitude_weight = 10**(1.5 * (fm['magnitude'] - 4.0))
        
        # Distance weighting (inverse distance squared)
        if fm.get('distance_m'):
            distance_weight = 1.0 / (1.0 + (fm['distance_m'] / 10000.0)**2)
        else:
            distance_weight = 1.0
        
        # Depth weighting (prefer crustal events for regional stress)
        depth_km = fm['depth_km']
        if depth_km < 15:
            depth_weight = 1.0
        elif depth_km < 35:
            depth_weight = 0.8
        else:
            depth_weight = 0.5
        
        # Tectonic setting weight
        tectonic_weight = 1.0
        if geological_context.get('tectonic_setting') == 'volcanic':
            tectonic_weight = 1.2  # Volcanic settings provide good stress indicators
        elif geological_context.get('tectonic_setting') == 'transform':
            tectonic_weight = 1.1
        
        # Combined weight
        total_weight = (base_weight * magnitude_weight * distance_weight * 
                       depth_weight * tectonic_weight)
        
        return total_weight
    
    async def _michael_stress_inversion(self, processed_fms):
        """
        Enhanced Michael (1984) stress inversion with bootstrap uncertainty estimation
        """
        try:
            n_mechanisms = len(processed_fms)
            if n_mechanisms < 6:
                return None
            
            # Prepare data matrices
            fault_normals = []
            slip_vectors = []
            weights = []
            
            for fm in processed_fms:
                # Use primary plane (could implement plane selection algorithm)
                plane = fm['planes'][0]
                fault_normals.append(plane['normal'])
                slip_vectors.append(plane['slip'])
                weights.append(fm['weight'])
            
            fault_normals = np.array(fault_normals)
            slip_vectors = np.array(slip_vectors)
            weights = np.array(weights)
            
            # Normalize weights
            weights = weights / np.sum(weights)
            
            # Michael (1984) stress inversion using weighted least squares
            stress_result = self._solve_michael_inversion(fault_normals, slip_vectors, weights)
            
            if stress_result is None:
                return None
            
            # Bootstrap uncertainty estimation
            n_bootstrap = 1000
            bootstrap_results = []
            
            for _ in range(n_bootstrap):
                # Resample with replacement
                indices = np.random.choice(n_mechanisms, size=n_mechanisms, replace=True, p=weights)
                boot_normals = fault_normals[indices]
                boot_slips = slip_vectors[indices]
                boot_weights = weights[indices]
                boot_weights = boot_weights / np.sum(boot_weights)
                
                boot_result = self._solve_michael_inversion(boot_normals, boot_slips, boot_weights)
                if boot_result:
                    bootstrap_results.append(boot_result)
            
            # Calculate uncertainties from bootstrap distribution
            if bootstrap_results:
                uncertainties = self._calculate_bootstrap_uncertainties(bootstrap_results)
            else:
                uncertainties = {'shmax_azimuth_std': 999, 'stress_ratio_std': 999}
            
            # Combine results
            result = {
                **stress_result,
                'uncertainties': uncertainties,
                'bootstrap_samples': len(bootstrap_results),
                'method': 'michael1984_enhanced',
                'data_points': n_mechanisms
            }
            
            return result
            
        except Exception as e:
            logger.error(f"Michael stress inversion failed: {e}")
            return None
    
    def _solve_michael_inversion(self, fault_normals, slip_vectors, weights):
        """Solve Michael (1984) stress inversion using weighted least squares"""
        try:
            n = len(fault_normals)
            
            # Build design matrix A for stress tensor inversion
            # Each fault provides constraint: slip = lambda * (sigma * normal)
            # where sigma is stress tensor and lambda is scalar
            
            A = np.zeros((n, 5))  # 5 independent stress tensor components (symmetric, trace-free)
            b = np.zeros(n)
            W = np.diag(weights)
            
            for i in range(n):
                n_vec = fault_normals[i]
                s_vec = slip_vectors[i]
                
                # Stress tensor components (xx, yy, xy, xz, yz) - zz determined by trace=0
                A[i, 0] = n_vec[0]  # sigma_xx * n_x
                A[i, 1] = n_vec[1]  # sigma_yy * n_y  
                A[i, 2] = n_vec[0] + n_vec[1]  # sigma_xy * (n_x + n_y)
                A[i, 3] = n_vec[2]  # sigma_xz * n_z
                A[i, 4] = n_vec[2]  # sigma_yz * n_z
                
                # Right-hand side: slip vector magnitude
                b[i] = np.linalg.norm(s_vec)
            
            # Weighted least squares solution
            AtWA = A.T @ W @ A
            AtWb = A.T @ W @ b
            
            # Add regularization for stability
            reg_param = 1e-6
            AtWA += reg_param * np.eye(5)
            
            # Solve system
            stress_params = np.linalg.solve(AtWA, AtWb)
            
            # Reconstruct stress tensor
            sigma = np.zeros((3, 3))
            sigma[0, 0] = stress_params[0]  # sigma_xx
            sigma[1, 1] = stress_params[1]  # sigma_yy
            sigma[2, 2] = -(stress_params[0] + stress_params[1])  # sigma_zz (trace = 0)
            sigma[0, 1] = sigma[1, 0] = stress_params[2]  # sigma_xy
            sigma[0, 2] = sigma[2, 0] = stress_params[3]  # sigma_xz
            sigma[1, 2] = sigma[2, 1] = stress_params[4]  # sigma_yz
            
            # Eigenvalue decomposition to get principal stresses
            eigenvals, eigenvecs = np.linalg.eigh(sigma)
            
            # Sort by eigenvalue magnitude (most compressive first)
            idx = np.argsort(eigenvals)[::-1]
            eigenvals = eigenvals[idx]
            eigenvecs = eigenvecs[:, idx]
            
            # Principal stress orientations
            sigma1_vec = eigenvecs[:, 0]  # Maximum principal stress
            sigma2_vec = eigenvecs[:, 1]  # Intermediate principal stress  
            sigma3_vec = eigenvecs[:, 2]  # Minimum principal stress
            
            # Calculate stress regime parameters
            stress_ratio = (eigenvals[1] - eigenvals[2]) / (eigenvals[0] - eigenvals[2])
            
            # SHmax azimuth (horizontal projection of sigma1 or sigma3)
            if abs(sigma1_vec[2]) < abs(sigma3_vec[2]):  # sigma1 more horizontal
                shmax_vec = sigma1_vec
                stress_regime = 'reverse' if eigenvals[0] > 0 else 'strike_slip'
            else:  # sigma3 more horizontal
                shmax_vec = sigma3_vec
                stress_regime = 'normal' if eigenvals[2] < 0 else 'strike_slip'
            
            shmax_azimuth = np.degrees(np.arctan2(shmax_vec[1], shmax_vec[0])) % 180
            
            # Calculate misfit
            predicted_slips = A @ stress_params
            residuals = b - predicted_slips
            rms_misfit = np.sqrt(np.mean((weights * residuals)**2))
            
            return {
                'shmax_azimuth': shmax_azimuth,
                'stress_ratio': stress_ratio,
                'stress_regime': stress_regime,
                'principal_stresses': eigenvals.tolist(),
                'principal_directions': eigenvecs.tolist(),
                'stress_tensor': sigma.tolist(),
                'rms_misfit': rms_misfit,
                'condition_number': np.linalg.cond(AtWA)
            }
            
        except Exception as e:
            logger.error(f"Michael inversion solver failed: {e}")
            return None
    
    async def _fallback_stress_field(self, latitude, longitude, error_msg):
        """Enhanced fallback stress field based on tectonic setting"""
        try:
            tectonic_setting = await self._determine_tectonic_setting(latitude, longitude)
            
            # Tectonic setting-based stress field estimates
            if tectonic_setting == 'oceanic':
                # Mid-ocean ridge or transform setting
                return {
                    'shmax_azimuth': 90,  # Perpendicular to ridge
                    'stress_magnitude': 0.3,
                    'stress_regime': 'normal',
                    'data_quality': 'D',
                    'source': 'tectonic_setting_estimate',
                    'uncertainty': 45,
                    'error_log': error_msg
                }
            elif tectonic_setting == 'volcanic_arc':
                # Subduction zone setting
                return {
                    'shmax_azimuth': 45,  # Oblique to trench
                    'stress_magnitude': 0.7,
                    'stress_regime': 'reverse',
                    'data_quality': 'D',
                    'source': 'tectonic_setting_estimate',
                    'uncertainty': 30,
                    'error_log': error_msg
                }
            else:
                # Continental setting
                return {
                    'shmax_azimuth': 60,  # Variable continental stress
                    'stress_magnitude': 0.5,
                    'stress_regime': 'strike_slip',
                    'data_quality': 'D',
                    'source': 'tectonic_setting_estimate',
                    'uncertainty': 60,
                    'error_log': error_msg
                }
                
        except Exception as e:
            logger.error(f"Fallback stress field failed: {e}")
            return {
                'shmax_azimuth': 0,
                'stress_magnitude': 0.5,
                'stress_regime': 'unknown',
                'data_quality': 'E',
                'source': 'emergency_fallback',
                'uncertainty': 90,
                'error_log': f"{error_msg}; {str(e)}"
            }
    
    async def _query_crustal_fabric(self, latitude, longitude):
        """
        Advanced crustal fabric and anisotropy analysis using multiple data sources
        """
        try:
            from backend.core.data_transformation.interpolation_engine import InterpolationEngine
            
            # Initialize fabric analysis components
            fabric_data_sources = {}
            interpolation_engine = InterpolationEngine()
            
            # 1. Query seismic anisotropy database
            seismic_anisotropy = await self._query_seismic_anisotropy(latitude, longitude)
            if seismic_anisotropy:
                fabric_data_sources['seismic_anisotropy'] = seismic_anisotropy
            
            # 2. Query shear wave splitting measurements
            shear_wave_splitting = await self._query_shear_wave_splitting(latitude, longitude)
            if shear_wave_splitting:
                fabric_data_sources['shear_wave_splitting'] = shear_wave_splitting
            
            # 3. Query structural geology data
            structural_data = await self._query_structural_geology(latitude, longitude)
            if structural_data:
                fabric_data_sources['structural_geology'] = structural_data
            
            # 4. Query magnetic anomaly data for fabric orientation
            magnetic_fabric = await self._query_magnetic_fabric(latitude, longitude)
            if magnetic_fabric:
                fabric_data_sources['magnetic_fabric'] = magnetic_fabric
            
            # 5. Query gravity gradient tensor for density fabric
            gravity_fabric = await self._query_gravity_fabric(latitude, longitude)
            if gravity_fabric:
                fabric_data_sources['gravity_fabric'] = gravity_fabric
            
            # Advanced fabric integration
            integrated_fabric = await self._integrate_fabric_data(
                fabric_data_sources, latitude, longitude, interpolation_engine
            )
            
            return integrated_fabric
            
        except Exception as e:
            logger.error(f"Advanced fabric query failed: {e}")
            return await self._fallback_crustal_fabric(latitude, longitude, str(e))
    
    async def _query_seismic_anisotropy(self, latitude, longitude):
        """Query seismic anisotropy measurements from regional networks"""
        try:
            # Query anisotropy database within 150km
            async with self.db_integrator.get_postgresql_session() as session:
                query = """
                SELECT 
                    fast_direction,
                    delay_time_ms,
                    anisotropy_percent,
                    depth_km,
                    measurement_method,
                    data_quality,
                    ST_Distance(
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                        ST_Transform(location, 3857)
                    ) as distance_m
                FROM seismic_anisotropy_measurements 
                WHERE ST_DWithin(
                    ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                    ST_Transform(location, 3857),
                    150000
                )
                AND data_quality IN ('A', 'B', 'C')
                ORDER BY data_quality, distance_m
                LIMIT 30
                """
                
                result = await session.execute(query, (longitude, latitude, longitude, latitude))
                anisotropy_data = result.fetchall()
                
                if anisotropy_data:
                    # Distance and quality weighted averaging
                    weights = []
                    fast_directions = []
                    anisotropy_strengths = []
                    
                    for record in anisotropy_data:
                        quality_weight = {'A': 1.0, 'B': 0.8, 'C': 0.6}.get(record.data_quality, 0.5)
                        distance_weight = 1.0 / (record.distance_m + 5000)
                        combined_weight = quality_weight * distance_weight
                        
                        weights.append(combined_weight)
                        fast_directions.append(record.fast_direction)
                        anisotropy_strengths.append(record.anisotropy_percent)
                    
                    # Circular averaging for directions
                    if fast_directions and weights:
                        x_components = [w * np.cos(np.radians(2 * fd)) for w, fd in zip(weights, fast_directions)]
                        y_components = [w * np.sin(np.radians(2 * fd)) for w, fd in zip(weights, fast_directions)]
                        
                        mean_x = sum(x_components) / sum(weights)
                        mean_y = sum(y_components) / sum(weights)
                        
                        mean_fast_direction = (np.degrees(np.arctan2(mean_y, mean_x)) / 2) % 180
                        mean_anisotropy = sum(w * a for w, a in zip(weights, anisotropy_strengths)) / sum(weights)
                        
                        # Calculate uncertainties
                        direction_scatter = np.sqrt(sum(w * (fd - mean_fast_direction)**2 for w, fd in zip(weights, fast_directions)) / sum(weights))
                        strength_scatter = np.sqrt(sum(w * (a - mean_anisotropy)**2 for w, a in zip(weights, anisotropy_strengths)) / sum(weights))
                        
                        return {
                            'fast_direction': mean_fast_direction,
                            'direction_uncertainty': direction_scatter,
                            'anisotropy_strength': mean_anisotropy / 100.0,  # Convert to fraction
                            'strength_uncertainty': strength_scatter / 100.0,
                            'data_points': len(anisotropy_data),
                            'max_distance_km': max(r.distance_m for r in anisotropy_data) / 1000,
                            'measurement_methods': list(set(r.measurement_method for r in anisotropy_data)),
                            'depth_range': [
                                min(r.depth_km for r in anisotropy_data if r.depth_km),
                                max(r.depth_km for r in anisotropy_data if r.depth_km)
                            ] if any(r.depth_km for r in anisotropy_data) else None
                        }
                
                return None
                
        except Exception as e:
            logger.warning(f"Seismic anisotropy query failed: {e}")
            return None
    
