    async def _analyze_strain_field(self, gps_velocities, latitude, longitude):
        """Analyze strain field from GPS velocities using advanced interpolation"""
        try:
            if not gps_velocities or len(gps_velocities['gps_velocities']) < 3:
                return None
            
            from scipy.spatial import Delaunay
            from scipy.interpolate import griddata
            
            velocities = gps_velocities['gps_velocities']
            
            # Extract coordinates and velocities
            coords = np.array([[v['location']['latitude'], v['location']['longitude']] for v in velocities])
            vel_east = np.array([v['velocity']['east'] for v in velocities])
            vel_north = np.array([v['velocity']['north'] for v in velocities])
            uncertainties = np.array([np.sqrt(v['uncertainty']['east']**2 + v['uncertainty']['north']**2) for v in velocities])
            
            # Create interpolation grid around target location
            grid_size = 0.1  # degrees
            lat_grid = np.linspace(latitude - grid_size, latitude + grid_size, 21)
            lon_grid = np.linspace(longitude - grid_size, longitude + grid_size, 21)
            lon_mesh, lat_mesh = np.meshgrid(lon_grid, lat_grid)
            
            # Interpolate velocity field using weighted interpolation
            weights = 1.0 / (uncertainties + 0.1)  # Inverse uncertainty weighting
            
            # Weighted griddata interpolation
            vel_east_interp = griddata(coords, vel_east * weights, (lat_mesh, lon_mesh), method='cubic', fill_value=0)
            vel_north_interp = griddata(coords, vel_north * weights, (lat_mesh, lon_mesh), method='cubic', fill_value=0)
            
            # Compute strain tensor components
            dlat = lat_grid[1] - lat_grid[0]
            dlon = lon_grid[1] - lon_grid[0]
            
            # Convert to meters (approximate)
            dlat_m = dlat * 111000  # degrees to meters
            dlon_m = dlon * 111000 * np.cos(np.radians(latitude))
            
            # Compute gradients
            dve_dlat, dve_dlon = np.gradient(vel_east_interp, dlat_m, dlon_m)
            dvn_dlat, dvn_dlon = np.gradient(vel_north_interp, dlat_m, dlon_m)
            
            # Strain tensor components (in nanostrain/year)
            exx = dve_dlon * 1e9  # East-West strain
            eyy = dvn_dlat * 1e9  # North-South strain
            exy = 0.5 * (dve_dlat + dvn_dlon) * 1e9  # Shear strain
            
            # Principal strain analysis
            principal_strains = []
            strain_orientations = []
            
            for i in range(exx.shape[0]):
                for j in range(exx.shape[1]):
                    strain_tensor = np.array([[exx[i,j], exy[i,j]], [exy[i,j], eyy[i,j]]])
                    eigenvals, eigenvecs = np.linalg.eigh(strain_tensor)
                    
                    principal_strains.append(eigenvals)
                    # Principal strain orientation (degrees from north)
                    orientation = np.degrees(np.arctan2(eigenvecs[1,0], eigenvecs[0,0]))
                    strain_orientations.append(orientation)
            
            principal_strains = np.array(principal_strains).reshape(exx.shape + (2,))
            strain_orientations = np.array(strain_orientations).reshape(exx.shape)
            
            # Strain rate magnitude and style
            strain_magnitude = np.sqrt(exx**2 + eyy**2 + 2*exy**2)
            dilatation = exx + eyy  # Volumetric strain
            max_shear = np.sqrt((exx - eyy)**2 + 4*exy**2) / 2
            
            # Classify strain regime
            strain_regime = np.where(
                np.abs(dilatation) > max_shear,
                np.where(dilatation > 0, 'extension', 'compression'),
                'shear'
            )
            
            # Extract values at target location
            center_idx = len(lat_grid) // 2
            target_strain = {
                'exx': float(exx[center_idx, center_idx]),
                'eyy': float(eyy[center_idx, center_idx]),
                'exy': float(exy[center_idx, center_idx]),
                'principal_strain_1': float(principal_strains[center_idx, center_idx, 1]),
                'principal_strain_2': float(principal_strains[center_idx, center_idx, 0]),
                'principal_orientation': float(strain_orientations[center_idx, center_idx]),
                'strain_magnitude': float(strain_magnitude[center_idx, center_idx]),
                'dilatation': float(dilatation[center_idx, center_idx]),
                'max_shear': float(max_shear[center_idx, center_idx]),
                'strain_regime': strain_regime[center_idx, center_idx]
            }
            
            return {
                'strain_tensor': target_strain,
                'strain_field_grid': {
                    'latitude': lat_grid,
                    'longitude': lon_grid,
                    'exx': exx,
                    'eyy': eyy,
                    'exy': exy,
                    'principal_strains': principal_strains,
                    'strain_orientations': strain_orientations
                },
                'analysis_method': 'gps_velocity_interpolation',
                'station_count': len(velocities),
                'interpolation_method': 'weighted_cubic',
                'grid_resolution_deg': grid_size / 10
            }
            
        except Exception as e:
            logger.error(f"Strain field analysis failed: {e}")
            return None
    
    async def _query_borehole_stress_indicators(self, latitude, longitude):
        """Query borehole breakout and drilling-induced fracture data from petroleum databases"""
        try:
            # Query borehole stress indicator database
            async with self.db_integrator.get_postgresql_session() as session:
                borehole_query = """
                SELECT 
                    well_id,
                    operator,
                    ST_X(location) as longitude,
                    ST_Y(location) as latitude,
                    total_depth_m,
                    breakout_azimuth,
                    breakout_width,
                    dif_azimuth,
                    stress_magnitude_estimate,
                    data_quality,
                    measurement_depth_m,
                    formation,
                    ST_Distance(
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                        ST_Transform(location, 3857)
                    ) as distance_m
                FROM borehole_stress_indicators 
                WHERE ST_DWithin(
                    ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                    ST_Transform(location, 3857),
                    200000
                )
                AND data_quality IN ('A', 'B', 'C')
                ORDER BY data_quality, distance_m
                LIMIT 30
                """
                
                result = await session.execute(borehole_query, (longitude, latitude, longitude, latitude))
                borehole_data = result.fetchall()
                
                if borehole_data:
                    # Process borehole stress indicators
                    stress_indicators = []
                    
                    for borehole in borehole_data:
                        # Calculate stress orientation from breakouts and DIFs
                        if borehole.breakout_azimuth is not None:
                            # Maximum horizontal stress is perpendicular to breakout
                            shmax_azimuth = (borehole.breakout_azimuth + 90) % 180
                            indicator_type = 'breakout'
                            confidence = self._assess_breakout_confidence(borehole.breakout_width)
                        elif borehole.dif_azimuth is not None:
                            # DIFs align with maximum horizontal stress
                            shmax_azimuth = borehole.dif_azimuth % 180
                            indicator_type = 'drilling_induced_fracture'
                            confidence = 0.8  # DIFs generally more reliable
                        else:
                            continue
                        
                        stress_indicator = {
                            'well_id': borehole.well_id,
                            'operator': borehole.operator,
                            'location': {
                                'latitude': borehole.latitude,
                                'longitude': borehole.longitude
                            },
                            'depth_m': borehole.measurement_depth_m or borehole.total_depth_m,
                            'shmax_azimuth': shmax_azimuth,
                            'indicator_type': indicator_type,
                            'confidence': confidence,
                            'stress_magnitude': borehole.stress_magnitude_estimate,
                            'formation': borehole.formation,
                            'distance_km': borehole.distance_m / 1000,
                            'data_quality': borehole.data_quality
                        }
                        
                        stress_indicators.append(stress_indicator)
                    
                    # Weighted average of stress orientations
                    if stress_indicators:
                        weights = [ind['confidence'] / (ind['distance_km'] + 1) for ind in stress_indicators]
                        azimuths = [ind['shmax_azimuth'] for ind in stress_indicators]
                        
                        # Circular averaging
                        x_sum = sum(w * np.cos(np.radians(2 * az)) for w, az in zip(weights, azimuths))
                        y_sum = sum(w * np.sin(np.radians(2 * az)) for w, az in zip(weights, azimuths))
                        
                        mean_azimuth = (np.degrees(np.arctan2(y_sum, x_sum)) / 2) % 180
                        
                        # Calculate uncertainty from scatter
                        azimuth_deviations = [abs(az - mean_azimuth) for az in azimuths]
                        weighted_std = np.sqrt(sum(w * dev**2 for w, dev in zip(weights, azimuth_deviations)) / sum(weights))
                        
                        return {
                            'shmax_azimuth': mean_azimuth,
                            'azimuth_uncertainty': weighted_std,
                            'stress_indicators': stress_indicators,
                            'indicator_count': len(stress_indicators),
                            'data_sources': ['borehole_breakouts', 'drilling_induced_fractures'],
                            'analysis_method': 'weighted_circular_averaging',
                            'confidence': np.mean([ind['confidence'] for ind in stress_indicators])
                        }
                
                return None
                
        except Exception as e:
            logger.error(f"Borehole stress indicator query failed: {e}")
            return None
    
    def _assess_breakout_confidence(self, breakout_width):
        """Assess confidence in breakout-derived stress orientation"""
        if breakout_width is None:
            return 0.5
        
        # Wider breakouts generally more reliable
        if breakout_width > 60:  # degrees
            return 0.9
        elif breakout_width > 30:
            return 0.7
        elif breakout_width > 15:
            return 0.5
        else:
            return 0.3
    
    async def _calculate_tectonic_loading(self, latitude, longitude):
        """Calculate tectonic loading stress field using plate motion models"""
        try:
            from backend.core.real_data_connectors.geological_survey_connector import GeologicalSurveyConnector
            
            # Query plate motion data
            plate_motion = await self._query_plate_motion_models(latitude, longitude)
            if not plate_motion:
                return None
            
            # Query nearby active faults
            active_faults = await self._query_active_faults(latitude, longitude)
            
            # Calculate stress field from plate motion
            plate_stress = await self._compute_plate_motion_stress(plate_motion, latitude, longitude)
            
            # Calculate stress from fault loading
            fault_stress = await self._compute_fault_loading_stress(active_faults, latitude, longitude)
            
            # Combine stress sources
            total_stress = await self._combine_stress_sources(plate_stress, fault_stress)
            
            return {
                'tectonic_stress': total_stress,
                'plate_motion_component': plate_stress,
                'fault_loading_component': fault_stress,
                'plate_boundary': plate_motion.get('plate_boundary'),
                'convergence_rate': plate_motion.get('convergence_rate'),
                'stress_regime': total_stress.get('regime'),
                'calculation_method': 'plate_motion_fault_loading'
            }
            
        except Exception as e:
            logger.error(f"Tectonic loading calculation failed: {e}")
            return None
    
    async def _query_plate_motion_models(self, latitude, longitude):
        """Query global plate motion models (MORVEL, NUVEL)"""
        try:
            # Query plate boundary database
            async with self.db_integrator.get_postgresql_session() as session:
                plate_query = """
                SELECT 
                    plate_name,
                    boundary_type,
                    convergence_rate_mm_yr,
                    convergence_azimuth,
                    transform_rate_mm_yr,
                    ST_Distance(
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                        ST_Transform(geometry, 3857)
                    ) as distance_m
                FROM plate_boundaries 
                WHERE ST_DWithin(
                    ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                    ST_Transform(geometry, 3857),
                    500000
                )
                ORDER BY distance_m
                LIMIT 5
                """
                
                result = await session.execute(plate_query, (longitude, latitude, longitude, latitude))
                plate_data = result.fetchall()
                
                if plate_data:
                    closest_boundary = plate_data[0]
                    return {
                        'plate_boundary': closest_boundary.boundary_type,
                        'convergence_rate': closest_boundary.convergence_rate_mm_yr,
                        'convergence_azimuth': closest_boundary.convergence_azimuth,
                        'transform_rate': closest_boundary.transform_rate_mm_yr,
                        'distance_to_boundary_km': closest_boundary.distance_m / 1000
                    }
                
                return None
                
        except Exception as e:
            logger.warning(f"Plate motion query failed: {e}")
            return None
    
