    async def _query_shear_wave_splitting(self, latitude, longitude):
        """Query shear wave splitting measurements from seismic networks"""
        try:
            # Query shear wave splitting database
            async with self.db_integrator.get_postgresql_session() as session:
                sws_query = """
                SELECT 
                    station_code,
                    network_code,
                    ST_X(location) as longitude,
                    ST_Y(location) as latitude,
                    fast_direction,
                    delay_time_ms,
                    measurement_depth_km,
                    frequency_band,
                    data_quality,
                    measurement_count,
                    ST_Distance(
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                        ST_Transform(location, 3857)
                    ) as distance_m
                FROM shear_wave_splitting_measurements 
                WHERE ST_DWithin(
                    ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                    ST_Transform(location, 3857),
                    200000
                )
                AND data_quality IN ('A', 'B', 'C')
                ORDER BY data_quality, distance_m
                LIMIT 25
                """
                
                result = await session.execute(sws_query, (longitude, latitude, longitude, latitude))
                sws_data = result.fetchall()
                
                if sws_data:
                    # Process shear wave splitting measurements
                    measurements = []
                    
                    for measurement in sws_data:
                        sws_record = {
                            'station_code': measurement.station_code,
                            'network': measurement.network_code,
                            'location': {
                                'latitude': measurement.latitude,
                                'longitude': measurement.longitude
                            },
                            'fast_direction': measurement.fast_direction,
                            'delay_time_ms': measurement.delay_time_ms,
                            'depth_km': measurement.measurement_depth_km,
                            'frequency_band': measurement.frequency_band,
                            'quality': measurement.data_quality,
                            'measurement_count': measurement.measurement_count,
                            'distance_km': measurement.distance_m / 1000
                        }
                        measurements.append(sws_record)
                    
                    # Calculate weighted average fast direction
                    weights = []
                    fast_directions = []
                    
                    for m in measurements:
                        # Weight by quality and inverse distance
                        quality_weight = {'A': 1.0, 'B': 0.8, 'C': 0.6}.get(m['quality'], 0.5)
                        distance_weight = 1.0 / (m['distance_km'] + 10)
                        measurement_weight = min(1.0, m['measurement_count'] / 10.0)
                        
                        combined_weight = quality_weight * distance_weight * measurement_weight
                        weights.append(combined_weight)
                        fast_directions.append(m['fast_direction'])
                    
                    # Circular averaging for fast directions
                    if fast_directions and weights:
                        x_sum = sum(w * np.cos(np.radians(2 * fd)) for w, fd in zip(weights, fast_directions))
                        y_sum = sum(w * np.sin(np.radians(2 * fd)) for w, fd in zip(weights, fast_directions))
                        
                        mean_fast_direction = (np.degrees(np.arctan2(y_sum, x_sum)) / 2) % 180
                        
                        # Calculate uncertainty from scatter
                        direction_scatter = np.sqrt(sum(w * (fd - mean_fast_direction)**2 for w, fd in zip(weights, fast_directions)) / sum(weights))
                        
                        return {
                            'fast_direction': mean_fast_direction,
                            'direction_uncertainty': direction_scatter,
                            'measurements': measurements,
                            'station_count': len(measurements),
                            'analysis_method': 'weighted_circular_averaging',
                            'data_quality': np.mean([{'A': 1.0, 'B': 0.8, 'C': 0.6}.get(m['quality'], 0.5) for m in measurements])
                        }
                
                return None
                
        except Exception as e:
            logger.error(f"Shear wave splitting query failed: {e}")
            return None
    
    async def _query_structural_geology(self, latitude, longitude):
        """Query structural geology data for fabric orientation from geological surveys"""
        try:
            from backend.core.real_data_connectors.geological_survey_connector import GeologicalSurveyConnector
            from backend.core.real_data_connectors.base_connector import DataSourceConfig
            
            # Initialize geological survey connector
            geo_config = DataSourceConfig(
                base_url="https://api.usgs.gov/geology",
                api_key=os.getenv('USGS_API_KEY'),
                rate_limit=5
            )
            
            geo_connector = GeologicalSurveyConnector(geo_config)
            
            # Query structural measurements database
            async with self.db_integrator.get_postgresql_session() as session:
                structural_query = """
                SELECT 
                    measurement_id,
                    measurement_type,
                    strike,
                    dip,
                    plunge,
                    trend,
                    fabric_type,
                    rock_type,
                    formation,
                    data_source,
                    ST_Distance(
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                        ST_Transform(location, 3857)
                    ) as distance_m
                FROM structural_measurements 
                WHERE ST_DWithin(
                    ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                    ST_Transform(location, 3857),
                    50000
                )
                AND measurement_type IN ('foliation', 'lineation', 'joint', 'fracture')
                ORDER BY distance_m
                LIMIT 100
                """
                
                result = await session.execute(structural_query, (longitude, latitude, longitude, latitude))
                structural_data = result.fetchall()
                
                if structural_data:
                    # Process structural measurements
                    fabric_orientations = []
                    
                    for measurement in structural_data:
                        if measurement.strike is not None:
                            fabric_orientations.append({
                                'measurement_type': measurement.measurement_type,
                                'strike': measurement.strike,
                                'dip': measurement.dip,
                                'fabric_type': measurement.fabric_type,
                                'rock_type': measurement.rock_type,
                                'distance_km': measurement.distance_m / 1000,
                                'data_source': measurement.data_source
                            })
                    
                    if fabric_orientations:
                        # Calculate dominant fabric orientation
                        strikes = [f['strike'] for f in fabric_orientations]
                        weights = [1.0 / (f['distance_km'] + 1) for f in fabric_orientations]
                        
                        # Circular averaging for strikes
                        x_sum = sum(w * np.cos(np.radians(2 * s)) for w, s in zip(weights, strikes))
                        y_sum = sum(w * np.sin(np.radians(2 * s)) for w, s in zip(weights, strikes))
                        
                        mean_strike = (np.degrees(np.arctan2(y_sum, x_sum)) / 2) % 180
                        
                        # Estimate fabric strength from measurement density
                        fabric_strength = min(0.2, len(fabric_orientations) / 50.0)
                        
                        return {
                            'fabric_orientation': mean_strike,
                            'fabric_strength': fabric_strength,
                            'fabric_type': 'structural_geology',
                            'measurements': fabric_orientations,
                            'measurement_count': len(fabric_orientations),
                            'dominant_fabric_types': list(set(f['fabric_type'] for f in fabric_orientations if f['fabric_type'])),
                            'data_sources': list(set(f['data_source'] for f in fabric_orientations if f['data_source']))
                        }
                
                return None
                
        except Exception as e:
            logger.error(f"Structural geology query failed: {e}")
            return None
    
    async def _query_magnetic_fabric(self, latitude, longitude):
        """Query magnetic anomaly data for fabric analysis using aeromagnetic surveys"""
        try:
            # Query aeromagnetic survey database
            async with self.db_integrator.get_postgresql_session() as session:
                magnetic_query = """
                SELECT 
                    survey_name,
                    flight_line_spacing_m,
                    flight_height_m,
                    total_magnetic_intensity,
                    magnetic_gradient_x,
                    magnetic_gradient_y,
                    magnetic_gradient_z,
                    data_quality,
                    ST_Distance(
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                        ST_Transform(location, 3857)
                    ) as distance_m
                FROM aeromagnetic_data 
                WHERE ST_DWithin(
                    ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                    ST_Transform(location, 3857),
                    25000
                )
                ORDER BY distance_m
                LIMIT 200
                """
                
                result = await session.execute(magnetic_query, (longitude, latitude, longitude, latitude))
                magnetic_data = result.fetchall()
                
                if magnetic_data and len(magnetic_data) > 10:
                    # Analyze magnetic fabric from gradient tensor
                    gradients = np.array([
                        [m.magnetic_gradient_x, m.magnetic_gradient_y, m.magnetic_gradient_z]
                        for m in magnetic_data
                        if all(g is not None for g in [m.magnetic_gradient_x, m.magnetic_gradient_y, m.magnetic_gradient_z])
                    ])
                    
                    if len(gradients) > 5:
                        # Principal component analysis of magnetic gradients
                        from sklearn.decomposition import PCA
                        
                        pca = PCA(n_components=3)
                        pca.fit(gradients)
                        
                        # Principal directions of magnetic fabric
                        principal_directions = pca.components_
                        explained_variance = pca.explained_variance_ratio_
                        
                        # Fabric orientation from first principal component
                        fabric_vector = principal_directions[0]
                        fabric_orientation = np.degrees(np.arctan2(fabric_vector[1], fabric_vector[0])) % 180
                        
                        # Fabric strength from anisotropy
                        fabric_strength = (explained_variance[0] - explained_variance[2]) / explained_variance[0]
                        
                        return {
                            'fabric_orientation': fabric_orientation,
                            'fabric_strength': fabric_strength,
                            'fabric_type': 'magnetic_anisotropy',
                            'principal_directions': principal_directions.tolist(),
                            'explained_variance': explained_variance.tolist(),
                            'data_points': len(gradients),
                            'analysis_method': 'magnetic_gradient_pca',
                            'survey_coverage': len(set(m.survey_name for m in magnetic_data))
                        }
                
                return None
                
        except Exception as e:
            logger.error(f"Magnetic fabric query failed: {e}")
            return None
    
    async def _query_gravity_fabric(self, latitude, longitude):
        """Query gravity gradient tensor for density fabric analysis"""
        try:
            # Query gravity gradient database
            async with self.db_integrator.get_postgresql_session() as session:
                gravity_query = """
                SELECT 
                    survey_name,
                    gravity_anomaly_mgal,
                    gradient_gxx,
                    gradient_gyy,
                    gradient_gzz,
                    gradient_gxy,
                    gradient_gxz,
                    gradient_gyz,
                    measurement_height_m,
                    data_quality,
                    ST_Distance(
                        ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                        ST_Transform(location, 3857)
                    ) as distance_m
                FROM gravity_gradient_data 
                WHERE ST_DWithin(
                    ST_Transform(ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3857),
                    ST_Transform(location, 3857),
                    30000
                )
                AND data_quality IN ('A', 'B')
                ORDER BY distance_m
                LIMIT 150
                """
                
                result = await session.execute(gravity_query, (longitude, latitude, longitude, latitude))
                gravity_data = result.fetchall()
                
                if gravity_data and len(gravity_data) > 8:
                    # Analyze density fabric from gravity gradient tensor
                    gradient_tensors = []
                    
                    for g in gravity_data:
                        if all(comp is not None for comp in [g.gradient_gxx, g.gradient_gyy, g.gradient_gzz, 
                                                           g.gradient_gxy, g.gradient_gxz, g.gradient_gyz]):
                            # Construct symmetric gradient tensor
                            tensor = np.array([
                                [g.gradient_gxx, g.gradient_gxy, g.gradient_gxz],
                                [g.gradient_gxy, g.gradient_gyy, g.gradient_gyz],
                                [g.gradient_gxz, g.gradient_gyz, g.gradient_gzz]
                            ])
                            gradient_tensors.append(tensor)
                    
                    if len(gradient_tensors) > 5:
                        # Average gradient tensor
                        mean_tensor = np.mean(gradient_tensors, axis=0)
                        
                        # Eigenvalue decomposition for principal axes
                        eigenvals, eigenvecs = np.linalg.eigh(mean_tensor)
                        
                        # Sort by eigenvalue magnitude
                        idx = np.argsort(np.abs(eigenvals))[::-1]
                        eigenvals = eigenvals[idx]
                        eigenvecs = eigenvecs[:, idx]
                        
                        # Fabric orientation from principal eigenvector
                        principal_vector = eigenvecs[:, 0]
                        fabric_orientation = np.degrees(np.arctan2(principal_vector[1], principal_vector[0])) % 180
                        
                        # Fabric strength from eigenvalue anisotropy
                        fabric_strength = abs(eigenvals[0] - eigenvals[2]) / abs(eigenvals[0]) if eigenvals[0] != 0 else 0
                        
                        return {
                            'fabric_orientation': fabric_orientation,
                            'fabric_strength': fabric_strength,
                            'fabric_type': 'density_anisotropy',
                            'eigenvalues': eigenvals.tolist(),
                            'eigenvectors': eigenvecs.tolist(),
                            'mean_gradient_tensor': mean_tensor.tolist(),
                            'data_points': len(gradient_tensors),
                            'analysis_method': 'gravity_gradient_tensor_analysis',
                            'survey_coverage': len(set(g.survey_name for g in gravity_data))
                        }
                
                return None
                
        except Exception as e:
            logger.error(f"Gravity fabric query failed: {e}")
            return None
    
    # Additional helper methods for real data processing
    
    async def _compute_plate_motion_stress(self, plate_motion, latitude, longitude):
        """Compute stress field from plate motion models"""
        try:
            if not plate_motion:
                return None
            
            convergence_rate = plate_motion.get('convergence_rate', 0)
            convergence_azimuth = plate_motion.get('convergence_azimuth', 0)
            boundary_type = plate_motion.get('plate_boundary', 'unknown')
            
            # Calculate stress magnitude from convergence rate
            # Empirical relationship: stress ~ convergence_rate^0.5
            stress_magnitude = min(1.0, np.sqrt(convergence_rate / 100.0))  # Normalized
            
            # Stress orientation based on boundary type
            if boundary_type == 'convergent':
                # Compressive stress perpendicular to boundary
                stress_azimuth = convergence_azimuth
                stress_regime = 'reverse'
            elif boundary_type == 'transform':
                # Shear stress parallel to boundary
                stress_azimuth = (convergence_azimuth + 90) % 180
                stress_regime = 'strike_slip'
            elif boundary_type == 'divergent':
                # Extensional stress perpendicular to boundary
                stress_azimuth = convergence_azimuth
                stress_regime = 'normal'
            else:
                # Default to regional stress
                stress_azimuth = convergence_azimuth
                stress_regime = 'unknown'
            
            return {
                'shmax_azimuth': stress_azimuth,
                'stress_magnitude': stress_magnitude,
                'stress_regime': stress_regime,
                'convergence_rate': convergence_rate,
                'boundary_type': boundary_type,
                'distance_to_boundary': plate_motion.get('distance_to_boundary_km', 0)
            }
            
        except Exception as e:
            logger.error(f"Plate motion stress calculation failed: {e}")
            return None
    
    async def _compute_fault_loading_stress(self, active_faults, latitude, longitude):
        """Compute stress field from fault loading"""
        try:
            if not active_faults:
                return None
            
            # Calculate stress contribution from each fault
            total_stress_x = 0
            total_stress_y = 0
            total_weight = 0
            
            for fault in active_faults:
                if fault.slip_rate_mm_yr and fault.strike is not None:
                    # Distance weighting (1/r^2)
                    distance_km = fault.distance_m / 1000
                    weight = 1.0 / (distance_km**2 + 1)  # +1 to avoid singularity
                    
                    # Stress magnitude from slip rate
                    stress_mag = min(1.0, fault.slip_rate_mm_yr / 10.0)  # Normalized
                    
                    # Stress orientation from fault geometry
                    fault_strike_rad = np.radians(fault.strike)
                    
                    # Stress components (simplified Coulomb stress)
                    stress_x = stress_mag * np.cos(fault_strike_rad) * weight
                    stress_y = stress_mag * np.sin(fault_strike_rad) * weight
                    
                    total_stress_x += stress_x
                    total_stress_y += stress_y
                    total_weight += weight
            
            if total_weight > 0:
                # Normalize by total weight
                avg_stress_x = total_stress_x / total_weight
                avg_stress_y = total_stress_y / total_weight
                
                # Calculate resultant stress orientation
                stress_azimuth = np.degrees(np.arctan2(avg_stress_y, avg_stress_x)) % 180
                stress_magnitude = np.sqrt(avg_stress_x**2 + avg_stress_y**2)
                
                # Determine stress regime from fault types
                fault_types = [f.fault_type for f in active_faults if f.fault_type]
                if 'reverse' in fault_types or 'thrust' in fault_types:
                    stress_regime = 'reverse'
                elif 'normal' in fault_types:
                    stress_regime = 'normal'
                elif 'strike_slip' in fault_types:
                    stress_regime = 'strike_slip'
                else:
                    stress_regime = 'mixed'
                
                return {
                    'shmax_azimuth': stress_azimuth,
                    'stress_magnitude': stress_magnitude,
                    'stress_regime': stress_regime,
                    'contributing_faults': len(active_faults),
                    'fault_types': list(set(fault_types))
                }
            
            return None
            
        except Exception as e:
            logger.error(f"Fault loading stress calculation failed: {e}")
            return None
    
    async def _combine_stress_sources(self, plate_stress, fault_stress):
        """Combine stress from multiple sources"""
        try:
            if not plate_stress and not fault_stress:
                return None
            
            if plate_stress and not fault_stress:
                return plate_stress
            
            if fault_stress and not plate_stress:
                return fault_stress
            
            # Combine both sources with weighting
            plate_weight = 0.6
            fault_weight = 0.4
            
            # Vector addition of stress orientations
            plate_az_rad = np.radians(2 * plate_stress['shmax_azimuth'])
            fault_az_rad = np.radians(2 * fault_stress['shmax_azimuth'])
            
            plate_mag = plate_stress['stress_magnitude']
            fault_mag = fault_stress['stress_magnitude']
            
            # Weighted vector sum
            x_component = (plate_weight * plate_mag * np.cos(plate_az_rad) + 
                          fault_weight * fault_mag * np.cos(fault_az_rad))
            y_component = (plate_weight * plate_mag * np.sin(plate_az_rad) + 
                          fault_weight * fault_mag * np.sin(fault_az_rad))
            
            # Resultant orientation and magnitude
            combined_azimuth = (np.degrees(np.arctan2(y_component, x_component)) / 2) % 180
            combined_magnitude = np.sqrt(x_component**2 + y_component**2)
            
            # Determine combined regime
            if plate_stress['stress_regime'] == fault_stress['stress_regime']:
                combined_regime = plate_stress['stress_regime']
            else:
                combined_regime = 'mixed'
            
            return {
                'shmax_azimuth': combined_azimuth,
                'stress_magnitude': combined_magnitude,
                'stress_regime': combined_regime,
                'plate_contribution': plate_weight,
                'fault_contribution': fault_weight,
                'combination_method': 'weighted_vector_sum'
            }
            
        except Exception as e:
            logger.error(f"Stress source combination failed: {e}")
            return plate_stress or fault_stress


    def _calculate_bootstrap_uncertainties(self, bootstrap_results):
        """Calculate uncertainties from bootstrap distribution"""
        try:
            azimuths = [r['shmax_azimuth'] for r in bootstrap_results]
            stress_ratios = [r['stress_ratio'] for r in bootstrap_results]
            
            # Handle circular statistics for azimuth
            azimuth_rad = np.radians(np.array(azimuths) * 2)  # Double angle for circular stats
            mean_azimuth_rad = np.arctan2(np.mean(np.sin(azimuth_rad)), np.mean(np.cos(azimuth_rad)))
            azimuth_std = np.degrees(np.sqrt(-2 * np.log(np.abs(
                np.mean(np.exp(1j * azimuth_rad))
            )))) / 2  # Convert back from double angle
            
            return {
                'shmax_azimuth_std': azimuth_std,
                'stress_ratio_std': np.std(stress_ratios),
                'azimuth_95_confidence': np.percentile(azimuths, [2.5, 97.5]).tolist(),
                'stress_ratio_95_confidence': np.percentile(stress_ratios, [2.5, 97.5]).tolist()
            }
            
        except Exception as e:
            logger.warning(f"Bootstrap uncertainty calculation failed: {e}")
            return {'shmax_azimuth_std': 999, 'stress_ratio_std': 999}
    
    async def _gephart_forsyth_inversion(self, processed_fms):
        """
        Gephart & Forsyth (1984) grid search stress inversion method
        """
        try:
            if len(processed_fms) < 6:
                return None
            
            # Grid search parameters
            azimuth_range = np.arange(0, 180, 5)  # SHmax azimuth
            plunge_range = np.arange(0, 90, 5)    # SHmax plunge
            ratio_range = np.arange(0.1, 1.0, 0.1)  # Stress ratio R = (S2-S3)/(S1-S3)
            
            best_misfit = float('inf')
            best_params = None
            misfit_grid = []
            
            # Prepare fault data
            fault_data = []
            for fm in processed_fms:
                plane = fm['planes'][0]  # Use primary plane
                fault_data.append({
                    'normal': plane['normal'],
                    'slip': plane['slip'],
                    'weight': fm['weight']
                })
            
            # Grid search over stress parameters
            for azimuth in azimuth_range:
                for plunge in plunge_range:
                    for ratio in ratio_range:
                        # Calculate stress tensor for this parameter set
                        stress_tensor = self._construct_stress_tensor(azimuth, plunge, ratio)
                        
                        # Calculate misfit for all focal mechanisms
                        misfit = self._calculate_stress_misfit(stress_tensor, fault_data)
                        
                        misfit_grid.append({
                            'azimuth': azimuth,
                            'plunge': plunge,
                            'ratio': ratio,
                            'misfit': misfit
                        })
                        
                        if misfit < best_misfit:
                            best_misfit = misfit
                            best_params = {
                                'shmax_azimuth': azimuth,
                                'shmax_plunge': plunge,
                                'stress_ratio': ratio,
                                'misfit': misfit
                            }
            
            if best_params is None:
                return None
            
            # Estimate uncertainties from misfit surface
            uncertainties = self._estimate_gephart_uncertainties(misfit_grid, best_misfit)
            
            # Determine stress regime
            stress_regime = self._classify_stress_regime(best_params['stress_ratio'], best_params['shmax_plunge'])
            
            result = {
                **best_params,
                'stress_regime': stress_regime,
                'uncertainties': uncertainties,
                'method': 'gephart_forsyth1984',
                'data_points': len(processed_fms),
                'grid_points_evaluated': len(misfit_grid)
            }
            
            return result
            
        except Exception as e:
            logger.error(f"Gephart-Forsyth inversion failed: {e}")
            return None
    
    def _construct_stress_tensor(self, azimuth_deg, plunge_deg, stress_ratio):
        """Construct stress tensor from orientation and ratio parameters"""
        try:
            # Convert to radians
            azimuth = np.radians(azimuth_deg)
            plunge = np.radians(plunge_deg)
            
            # Principal stress directions (assuming sigma1 > sigma2 > sigma3)
            # SHmax direction
            s1_dir = np.array([
                np.cos(plunge) * np.cos(azimuth),
                np.cos(plunge) * np.sin(azimuth),
                np.sin(plunge)
            ])
            
            # Vertical direction (approximate sigma2 or sigma3)
            vertical = np.array([0, 0, 1])
            
            # Third direction (perpendicular to both)
            s3_dir = np.cross(s1_dir, vertical)
            s3_dir = s3_dir / np.linalg.norm(s3_dir)
            
            # Second direction (completes orthogonal set)
            s2_dir = np.cross(s3_dir, s1_dir)
            s2_dir = s2_dir / np.linalg.norm(s2_dir)
            
            # Principal stress magnitudes (normalized)
            sigma1 = 1.0
            sigma2 = 1.0 - stress_ratio
            sigma3 = 0.0
            
            # Construct stress tensor
            stress_tensor = (sigma1 * np.outer(s1_dir, s1_dir) +
                           sigma2 * np.outer(s2_dir, s2_dir) +
                           sigma3 * np.outer(s3_dir, s3_dir))
            
            return stress_tensor
            
        except Exception as e:
            logger.warning(f"Stress tensor construction failed: {e}")
            return np.eye(3)
    
    def _calculate_stress_misfit(self, stress_tensor, fault_data):
        """Calculate misfit between predicted and observed slip directions"""
        try:
            total_misfit = 0.0
            total_weight = 0.0
            
            for fault in fault_data:
                normal = fault['normal']
                observed_slip = fault['slip']
                weight = fault['weight']
                
                # Calculate traction on fault plane
                traction = stress_tensor @ normal
                
                # Remove normal component to get shear traction
                normal_traction = np.dot(traction, normal)
                shear_traction = traction - normal_traction * normal
                
                # Normalize to get predicted slip direction
                if np.linalg.norm(shear_traction) > 1e-10:
                    predicted_slip = shear_traction / np.linalg.norm(shear_traction)
                else:
                    predicted_slip = np.array([1, 0, 0])  # Arbitrary direction for zero shear
                
                # Calculate angular misfit
                dot_product = np.clip(np.dot(observed_slip, predicted_slip), -1, 1)
                angular_misfit = np.arccos(abs(dot_product))  # Use absolute value for direction ambiguity
                
                total_misfit += weight * angular_misfit**2
                total_weight += weight
            
            return np.sqrt(total_misfit / total_weight) if total_weight > 0 else float('inf')
            
        except Exception as e:
            logger.warning(f"Misfit calculation failed: {e}")
            return float('inf')
    
    def _estimate_gephart_uncertainties(self, misfit_grid, best_misfit):
        """Estimate parameter uncertainties from misfit surface"""
        try:
            # Find points within 95% confidence interval (chi-square criterion)
            confidence_threshold = best_misfit * 1.1  # Approximate 95% confidence
            
            confident_points = [p for p in misfit_grid if p['misfit'] <= confidence_threshold]
            
            if len(confident_points) < 2:
                return {'azimuth_uncertainty': 999, 'ratio_uncertainty': 999}
            
            azimuths = [p['azimuth'] for p in confident_points]
            ratios = [p['ratio'] for p in confident_points]
            
            return {
                'azimuth_uncertainty': np.std(azimuths),
                'ratio_uncertainty': np.std(ratios),
                'azimuth_range': [min(azimuths), max(azimuths)],
                'ratio_range': [min(ratios), max(ratios)]
            }
            
        except Exception as e:
            logger.warning(f"Uncertainty estimation failed: {e}")
            return {'azimuth_uncertainty': 999, 'ratio_uncertainty': 999}
    
    def _classify_stress_regime(self, stress_ratio, shmax_plunge):
        """Classify stress regime based on stress ratio and principal stress orientations"""
        if shmax_plunge < 30:  # Horizontal maximum stress
            if stress_ratio > 0.7:
                return 'strike_slip'
            else:
                return 'reverse'
        elif shmax_plunge > 60:  # Vertical maximum stress
            return 'normal'
        else:
            return 'oblique'
    
    async def _fmsi_stress_inversion(self, processed_fms):
        """
        FMSI (Lund & Slunga 1999) stress inversion algorithm
        """
        try:
            if len(processed_fms) < 8:
                return None
            
            # FMSI uses iterative approach to find stress tensor
            # that minimizes angular misfits with automatic plane selection
            
            max_iterations = 100
            convergence_threshold = 1e-6
            
            # Initialize stress tensor (random)
            stress_tensor = np.random.rand(3, 3)
            stress_tensor = (stress_tensor + stress_tensor.T) / 2  # Make symmetric
            
            # Prepare fault data with both planes
            fault_pairs = []
            for fm in processed_fms:
                if len(fm['planes']) >= 2:
                    fault_pairs.append({
                        'plane1': fm['planes'][0],
                        'plane2': fm['planes'][1],
                        'weight': fm['weight'],
                        'selected_plane': 0  # Initially select first plane
                    })
            
            if len(fault_pairs) < 8:
                return None
            
            prev_misfit = float('inf')
            
            for iteration in range(max_iterations):
                # Step 1: Select optimal fault plane for each mechanism
                for fault_pair in fault_pairs:
                    misfit1 = self._calculate_single_fault_misfit(stress_tensor, fault_pair['plane1'])
                    misfit2 = self._calculate_single_fault_misfit(stress_tensor, fault_pair['plane2'])
                    
                    fault_pair['selected_plane'] = 0 if misfit1 < misfit2 else 1
                
                # Step 2: Update stress tensor using selected planes
                selected_faults = []
                for fault_pair in fault_pairs:
                    selected_plane = fault_pair['plane1'] if fault_pair['selected_plane'] == 0 else fault_pair['plane2']
                    selected_faults.append({
                        'normal': selected_plane['normal'],
                        'slip': selected_plane['slip'],
                        'weight': fault_pair['weight']
                    })
                
                # Solve for new stress tensor using weighted least squares
                new_stress_tensor = self._solve_stress_tensor_lsq(selected_faults)
                
                if new_stress_tensor is None:
                    break
                
                # Calculate total misfit
                current_misfit = sum(
                    self._calculate_single_fault_misfit(new_stress_tensor, 
                        fault_pair['plane1'] if fault_pair['selected_plane'] == 0 else fault_pair['plane2'])
                    * fault_pair['weight']
                    for fault_pair in fault_pairs
                )
                
                # Check convergence
                if abs(prev_misfit - current_misfit) < convergence_threshold:
                    break
                
                stress_tensor = new_stress_tensor
                prev_misfit = current_misfit
            
            # Extract principal stresses and orientations
            eigenvals, eigenvecs = np.linalg.eigh(stress_tensor)
            idx = np.argsort(eigenvals)[::-1]
            eigenvals = eigenvals[idx]
            eigenvecs = eigenvecs[:, idx]
            
            # Calculate stress parameters
            stress_ratio = (eigenvals[1] - eigenvals[2]) / (eigenvals[0] - eigenvals[2])
            
            # SHmax orientation
            sigma1_vec = eigenvecs[:, 0]
            shmax_azimuth = np.degrees(np.arctan2(sigma1_vec[1], sigma1_vec[0])) % 180
            shmax_plunge = np.degrees(np.arcsin(abs(sigma1_vec[2])))
            
            # Stress regime
            stress_regime = self._classify_stress_regime(stress_ratio, shmax_plunge)
            
            result = {
                'shmax_azimuth': shmax_azimuth,
                'shmax_plunge': shmax_plunge,
                'stress_ratio': stress_ratio,
                'stress_regime': stress_regime,
                'final_misfit': current_misfit,
                'iterations': iteration + 1,
                'converged': iteration < max_iterations - 1,
                'method': 'fmsi_lund_slunga1999',
                'data_points': len(processed_fms),
                'plane_selections': [fp['selected_plane'] for fp in fault_pairs]
            }
            
            return result
            
        except Exception as e:
            logger.error(f"FMSI stress inversion failed: {e}")
            return None
    
    def _calculate_single_fault_misfit(self, stress_tensor, plane):
        """Calculate misfit for a single fault plane"""
        try:
            normal = plane['normal']
            observed_slip = plane['slip']
            
            # Calculate traction
            traction = stress_tensor @ normal
            normal_traction = np.dot(traction, normal)
            shear_traction = traction - normal_traction * normal
            
            if np.linalg.norm(shear_traction) > 1e-10:
                predicted_slip = shear_traction / np.linalg.norm(shear_traction)
                dot_product = np.clip(np.dot(observed_slip, predicted_slip), -1, 1)
                return np.arccos(abs(dot_product))
            else:
                return np.pi / 2  # 90 degree misfit for zero shear
                
        except Exception as e:
            return np.pi / 2
    
    def _solve_stress_tensor_lsq(self, fault_data):
        """Solve for stress tensor using least squares"""
        try:
            n = len(fault_data)
            if n < 6:
                return None
            
            # Build system of equations for stress tensor components
            A = np.zeros((3 * n, 6))  # 6 independent components of symmetric tensor
            b = np.zeros(3 * n)
            
            for i, fault in enumerate(fault_data):
                normal = fault['normal']
                slip = fault['slip']
                weight = np.sqrt(fault['weight'])
                
                # Each fault contributes 3 equations (x, y, z components of traction)
                row_start = 3 * i
                
                # Traction = stress_tensor @ normal
                # stress_tensor = [[s11, s12, s13], [s12, s22, s23], [s13, s23, s33]]
                
                # X-component: s11*nx + s12*ny + s13*nz
                A[row_start, 0] = weight * normal[0]      # s11
                A[row_start, 1] = weight * normal[1]      # s12
                A[row_start, 2] = weight * normal[2]      # s13
                
                # Y-component: s12*nx + s22*ny + s23*nz
                A[row_start + 1, 1] = weight * normal[0]  # s12
                A[row_start + 1, 3] = weight * normal[1]  # s22
                A[row_start + 1, 4] = weight * normal[2]  # s23
                
                # Z-component: s13*nx + s23*ny + s33*nz
                A[row_start + 2, 2] = weight * normal[0]  # s13
                A[row_start + 2, 4] = weight * normal[1]  # s23
                A[row_start + 2, 5] = weight * normal[2]  # s33
                
                # Right-hand side: observed slip direction (normalized)
                slip_norm = slip / np.linalg.norm(slip)
                b[row_start:row_start + 3] = weight * slip_norm
            
            # Solve least squares with regularization
            AtA = A.T @ A
            Atb = A.T @ b
            
            # Add small regularization
            reg_param = 1e-8
            AtA += reg_param * np.eye(6)
            
            stress_components = np.linalg.solve(AtA, Atb)
            
            # Reconstruct symmetric stress tensor
            stress_tensor = np.array([
                [stress_components[0], stress_components[1], stress_components[2]],
                [stress_components[1], stress_components[3], stress_components[4]],
                [stress_components[2], stress_components[4], stress_components[5]]
            ])
            
            return stress_tensor
            
        except Exception as e:
            logger.warning(f"Stress tensor LSQ solution failed: {e}")
            return None
    
    async def _bayesian_stress_inversion(self, processed_fms, geological_context):
        """
        Bayesian stress inversion with MCMC sampling for uncertainty quantification
        """
        try:
            if len(processed_fms) < 10:
                return None
            
            # Import MCMC libraries
            try:
                import emcee
                import scipy.stats as stats
            except ImportError:
                logger.warning("MCMC libraries not available, skipping Bayesian inversion")
                return None
            
            # Define parameter space: [azimuth, plunge, stress_ratio, sigma_noise]
            n_params = 4
            n_walkers = 32
            n_steps = 2000
            n_burn = 500
            
            # Prepare data
            fault_data = []
            for fm in processed_fms:
                plane = fm['planes'][0]
                fault_data.append({
                    'normal': plane['normal'],
                    'slip': plane['slip'],
                    'weight': fm['weight']
                })
            
            # Define log-likelihood function
            def log_likelihood(params):
                azimuth, plunge, stress_ratio, log_sigma = params
                
                # Parameter bounds
                if not (0 <= azimuth <= 180 and 0 <= plunge <= 90 and 0.1 <= stress_ratio <= 1.0):
                    return -np.inf
                
                sigma_noise = np.exp(log_sigma)
                if sigma_noise > 1.0:  # Reasonable noise level
                    return -np.inf
                
                # Calculate stress tensor
                stress_tensor = self._construct_stress_tensor(azimuth, plunge, stress_ratio)
                
                # Calculate likelihood
                log_prob = 0.0
                for fault in fault_data:
                    predicted_misfit = self._calculate_single_fault_misfit(stress_tensor, fault)
                    
                    # Likelihood: misfit follows von Mises distribution (circular normal)
                    concentration = 1.0 / (sigma_noise**2)
                    log_prob += stats.vonmises.logpdf(predicted_misfit, concentration)
                
                return log_prob
            
            # Define log-prior function
            def log_prior(params):
                azimuth, plunge, stress_ratio, log_sigma = params
                
                # Uniform priors with geological constraints
                prior_prob = 0.0
                
                # Azimuth: uniform 0-180
                if not (0 <= azimuth <= 180):
                    return -np.inf
                
                # Plunge: prefer horizontal (geological prior)
                if geological_context.get('tectonic_setting') == 'volcanic':
                    # Volcanic settings: prefer horizontal stress
                    prior_prob += stats.norm.logpdf(plunge, 0, 20)
                else:
                    # General case: uniform
                    if not (0 <= plunge <= 90):
                        return -np.inf
                
                # Stress ratio: uniform
                if not (0.1 <= stress_ratio <= 1.0):
                    return -np.inf
                
                # Noise: log-normal prior
                prior_prob += stats.norm.logpdf(log_sigma, -2, 1)  # Prefer low noise
                
                return prior_prob
            
            # Combined log-posterior
            def log_posterior(params):
                lp = log_prior(params)
                if not np.isfinite(lp):
                    return -np.inf
                return lp + log_likelihood(params)
            
            # Initialize walkers
            initial_guess = [90, 10, 0.5, -2]  # [azimuth, plunge, ratio, log_sigma]
            pos = initial_guess + 1e-2 * np.random.randn(n_walkers, n_params)
            
            # Run MCMC
            sampler = emcee.EnsembleSampler(n_walkers, n_params, log_posterior)
            sampler.run_mcmc(pos, n_steps, progress=False)
            
            # Extract samples after burn-in
            samples = sampler.get_chain(discard=n_burn, flat=True)
            
            if len(samples) < 100:
                return None
            
            # Calculate statistics
            azimuth_samples = samples[:, 0]
            plunge_samples = samples[:, 1]
            ratio_samples = samples[:, 2]
            
            # Circular statistics for azimuth
            azimuth_rad = np.radians(azimuth_samples * 2)
            mean_azimuth = np.degrees(np.arctan2(np.mean(np.sin(azimuth_rad)), 
                                               np.mean(np.cos(azimuth_rad)))) / 2 % 180
            
            result = {
                'shmax_azimuth': mean_azimuth,
                'shmax_plunge': np.mean(plunge_samples),
                'stress_ratio': np.mean(ratio_samples),
                'uncertainties': {
                    'azimuth_std': np.std(azimuth_samples),
                    'plunge_std': np.std(plunge_samples),
                    'ratio_std': np.std(ratio_samples),
                    'azimuth_credible_interval': np.percentile(azimuth_samples, [2.5, 97.5]).tolist(),
                    'plunge_credible_interval': np.percentile(plunge_samples, [2.5, 97.5]).tolist(),
                    'ratio_credible_interval': np.percentile(ratio_samples, [2.5, 97.5]).tolist()
                },
                'mcmc_diagnostics': {
                    'n_samples': len(samples),
                    'acceptance_fraction': np.mean(sampler.acceptance_fraction),
                    'autocorr_time': sampler.get_autocorr_time(quiet=True).tolist() if hasattr(sampler, 'get_autocorr_time') else None
                },
                'method': 'bayesian_mcmc',
                'data_points': len(processed_fms)
            }
            
            # Classify stress regime
            result['stress_regime'] = self._classify_stress_regime(result['stress_ratio'], result['shmax_plunge'])
            
            return result
            
        except Exception as e:
            logger.error(f"Bayesian stress inversion failed: {e}")
            return None

    async def _ml_enhanced_stress_prediction(self, processed_fms, geological_context, db_integrator):
        """
        Machine learning enhanced stress prediction using trained models
        """
        try:
            # Import ML libraries
            try:
                from sklearn.ensemble import RandomForestRegressor, GradientBoostingRegressor
                from sklearn.neural_network import MLPRegressor
                from sklearn.preprocessing import StandardScaler
                from sklearn.model_selection import cross_val_score
                import joblib
            except ImportError:
                logger.warning("ML libraries not available, skipping ML prediction")
                return None
            
            # Feature engineering from focal mechanisms and geological context
            features = await self._extract_ml_features(processed_fms, geological_context, db_integrator)
            
            if features is None or len(features) < 10:
                return None
            
            # Try to load pre-trained models
            model_paths = {
                'azimuth_model': '/models/stress_inversion/azimuth_predictor.joblib',
                'ratio_model': '/models/stress_inversion/ratio_predictor.joblib',
                'regime_model': '/models/stress_inversion/regime_classifier.joblib'
            }
            
            models = {}
            for model_name, path in model_paths.items():
                try:
                    models[model_name] = joblib.load(path)
                except:
                    # Train new model if pre-trained not available
                    models[model_name] = await self._train_stress_model(model_name, features)
            
            if not models:
                return None
            
            # Prepare feature vector for prediction
            feature_vector = self._prepare_feature_vector(features)
            
            if feature_vector is None:
                return None
            
            # Make predictions
            predictions = {}
            uncertainties = {}
            
            # Azimuth prediction
            if 'azimuth_model' in models:
                azimuth_pred = models['azimuth_model'].predict([feature_vector])[0]
                
                # Estimate uncertainty using ensemble variance
                if hasattr(models['azimuth_model'], 'estimators_'):
                    tree_preds = [tree.predict([feature_vector])[0] for tree in models['azimuth_model'].estimators_]
                    azimuth_uncertainty = np.std(tree_preds)
                else:
                    azimuth_uncertainty = 15.0  # Default uncertainty
                
                predictions['shmax_azimuth'] = azimuth_pred % 180
                uncertainties['azimuth_uncertainty'] = azimuth_uncertainty
            
            # Stress ratio prediction
            if 'ratio_model' in models:
                ratio_pred = models['ratio_model'].predict([feature_vector])[0]
                ratio_pred = np.clip(ratio_pred, 0.1, 1.0)  # Ensure valid range
                
                if hasattr(models['ratio_model'], 'estimators_'):
                    tree_preds = [tree.predict([feature_vector])[0] for tree in models['ratio_model'].estimators_]
                    ratio_uncertainty = np.std(tree_preds)
                else:
                    ratio_uncertainty = 0.2
                
                predictions['stress_ratio'] = ratio_pred
                uncertainties['ratio_uncertainty'] = ratio_uncertainty
            
            # Stress regime classification
            if 'regime_model' in models:
                regime_pred = models['regime_model'].predict([feature_vector])[0]
                
                # Get prediction probabilities if available
                if hasattr(models['regime_model'], 'predict_proba'):
                    regime_probs = models['regime_model'].predict_proba([feature_vector])[0]
                    regime_confidence = np.max(regime_probs)
                else:
                    regime_confidence = 0.7
                
                predictions['stress_regime'] = regime_pred
                uncertainties['regime_confidence'] = regime_confidence
            
            # Feature importance analysis
            feature_importance = {}
            for model_name, model in models.items():
                if hasattr(model, 'feature_importances_'):
                    feature_importance[model_name] = model.feature_importances_.tolist()
            
            result = {
                **predictions,
                'uncertainties': uncertainties,
                'feature_importance': feature_importance,
                'method': 'ml_enhanced_prediction',
                'data_points': len(processed_fms),
                'feature_count': len(feature_vector),
                'models_used': list(models.keys())
            }
            
            return result
            
        except Exception as e:
            logger.error(f"ML enhanced stress prediction failed: {e}")
            return None
    
    async def _extract_ml_features(self, processed_fms, geological_context, db_integrator):
        """Extract comprehensive features for ML stress prediction"""
        try:
            features = {}
            
            # Spatial features
            lats = [fm['location'][1] for fm in processed_fms]
            lons = [fm['location'][0] for fm in processed_fms]
            depths = [fm['location'][2] for fm in processed_fms]
            
            features.update({
                'centroid_lat': np.mean(lats),
                'centroid_lon': np.mean(lons),
                'centroid_depth': np.mean(depths),
                'spatial_extent_lat': np.max(lats) - np.min(lats),
                'spatial_extent_lon': np.max(lons) - np.min(lons),
                'depth_range': np.max(depths) - np.min(depths),
                'event_density': len(processed_fms) / ((np.max(lats) - np.min(lats)) * (np.max(lons) - np.min(lons)) + 1e-6)
            })
            
            # Magnitude features
            magnitudes = [fm['magnitude'] for fm in processed_fms]
            features.update({
                'mean_magnitude': np.mean(magnitudes),
                'max_magnitude': np.max(magnitudes),
                'magnitude_std': np.std(magnitudes),
                'b_value': self._calculate_b_value(magnitudes)
            })
            
            # Focal mechanism features
            strikes = []
            dips = []
            rakes = []
            
            for fm in processed_fms:
                plane = fm['planes'][0]
                strikes.append(plane['strike'])
                dips.append(plane['dip'])
                rakes.append(plane['rake'])
            
            features.update({
                'mean_strike': np.mean(strikes),
                'strike_std': np.std(strikes),
                'mean_dip': np.mean(dips),
                'dip_std': np.std(dips),
                'mean_rake': np.mean(rakes),
                'rake_std': np.std(rakes)
            })
            
            # Temporal features
            timestamps = [fm['timestamp'] for fm in processed_fms if fm.get('timestamp')]
            if timestamps:
                time_span = (max(timestamps) - min(timestamps)).total_seconds() / 86400  # days
                features['temporal_span_days'] = time_span
                features['event_rate_per_day'] = len(timestamps) / max(time_span, 1)
            else:
                features['temporal_span_days'] = 0
                features['event_rate_per_day'] = 0
            
            # Geological context features
            tectonic_setting = geological_context.get('tectonic_setting', 'unknown')
            tectonic_encoding = {
                'volcanic': 1, 'transform': 2, 'extensional': 3, 
                'compressional': 4, 'strike_slip': 5, 'unknown': 0
            }
            features['tectonic_setting_encoded'] = tectonic_encoding.get(tectonic_setting, 0)
            
            # Regional stress indicators
            regional_stress = geological_context.get('regional_stress', [])
            if regional_stress:
                regional_azimuths = [rs.get('shmax_azimuth', 0) for rs in regional_stress]
                features['regional_stress_azimuth'] = np.mean(regional_azimuths) if regional_azimuths else 0
                features['regional_stress_consistency'] = 1.0 / (np.std(regional_azimuths) + 1) if regional_azimuths else 0
            else:
                features['regional_stress_azimuth'] = 0
                features['regional_stress_consistency'] = 0
            
            # Fetch additional geophysical data
            try:
                # Gravity anomaly data
                gravity_data = await db_integrator.execute_unified_query(
                    "gravity_anomalies",
                    bbox=[min(lons) - 0.1, min(lats) - 0.1, max(lons) + 0.1, max(lats) + 0.1]
                )
                
                if gravity_data.data:
                    gravity_values = [g.get('bouguer_anomaly', 0) for g in gravity_data.data]
                    features['mean_gravity_anomaly'] = np.mean(gravity_values)
                    features['gravity_gradient'] = np.std(gravity_values)
                else:
                    features['mean_gravity_anomaly'] = 0
                    features['gravity_gradient'] = 0
                
                # Magnetic anomaly data
                magnetic_data = await db_integrator.execute_unified_query(
                    "magnetic_anomalies",
                    bbox=[min(lons) - 0.1, min(lats) - 0.1, max(lons) + 0.1, max(lats) + 0.1]
                )
                
                if magnetic_data.data:
                    magnetic_values = [m.get('total_field_anomaly', 0) for m in magnetic_data.data]
                    features['mean_magnetic_anomaly'] = np.mean(magnetic_values)
                    features['magnetic_gradient'] = np.std(magnetic_values)
                else:
                    features['mean_magnetic_anomaly'] = 0
                    features['magnetic_gradient'] = 0
                    
            except Exception as e:
                logger.warning(f"Failed to fetch geophysical data: {e}")
                features.update({
                    'mean_gravity_anomaly': 0, 'gravity_gradient': 0,
                    'mean_magnetic_anomaly': 0, 'magnetic_gradient': 0
                })
            
            # Stress tensor invariants from preliminary analysis
            try:
                # Quick Michael inversion for tensor invariants
                fault_normals = np.array([fm['planes'][0]['normal'] for fm in processed_fms])
                slip_vectors = np.array([fm['planes'][0]['slip'] for fm in processed_fms])
                weights = np.array([fm['weight'] for fm in processed_fms])
                
                preliminary_result = self._solve_michael_inversion(fault_normals, slip_vectors, weights)
                
                if preliminary_result:
                    features['preliminary_stress_ratio'] = preliminary_result['stress_ratio']
                    features['preliminary_misfit'] = preliminary_result['rms_misfit']
                    features['condition_number'] = preliminary_result['condition_number']
                else:
                    features.update({
                        'preliminary_stress_ratio': 0.5,
                        'preliminary_misfit': 1.0,
                        'condition_number': 100
                    })
                    
            except Exception as e:
                logger.warning(f"Preliminary stress analysis failed: {e}")
                features.update({
                    'preliminary_stress_ratio': 0.5,
                    'preliminary_misfit': 1.0,
                    'condition_number': 100
                })
            
            return features
            
        except Exception as e:
            logger.error(f"Feature extraction failed: {e}")
            return None
    
    def _calculate_b_value(self, magnitudes):
        """Calculate Gutenberg-Richter b-value"""
        try:
            if len(magnitudes) < 10:
                return 1.0  # Default b-value
            
            # Use maximum likelihood estimation
            min_mag = min(magnitudes)
            mean_mag = np.mean(magnitudes)
            
            b_value = 1.0 / (np.log(10) * (mean_mag - min_mag))
            
            return np.clip(b_value, 0.5, 2.0)  # Reasonable range
            
        except Exception:
            return 1.0
    
    def _prepare_feature_vector(self, features):
        """Prepare feature vector for ML prediction"""
        try:
            # Define expected feature order (should match training data)
            expected_features = [
                'centroid_lat', 'centroid_lon', 'centroid_depth',
                'spatial_extent_lat', 'spatial_extent_lon', 'depth_range',
                'event_density', 'mean_magnitude', 'max_magnitude',
                'magnitude_std', 'b_value', 'mean_strike', 'strike_std',
                'mean_dip', 'dip_std', 'mean_rake', 'rake_std',
                'temporal_span_days', 'event_rate_per_day',
                'tectonic_setting_encoded', 'regional_stress_azimuth',
                'regional_stress_consistency', 'mean_gravity_anomaly',
                'gravity_gradient', 'mean_magnetic_anomaly',
                'magnetic_gradient', 'preliminary_stress_ratio',
                'preliminary_misfit', 'condition_number'
            ]
            
            # Extract features in correct order
            feature_vector = []
            for feature_name in expected_features:
                value = features.get(feature_name, 0.0)
                # Handle NaN values
                if np.isnan(value) or np.isinf(value):
                    value = 0.0
                feature_vector.append(value)
            
            return np.array(feature_vector)
            
        except Exception as e:
            logger.error(f"Feature vector preparation failed: {e}")
            return None
    
