    async def _ensemble_stress_analysis(self, inversion_results, processed_fms):
        """
        Ensemble analysis combining results from multiple stress inversion methods
        """
        try:
            if not inversion_results:
                return None
            
            # Extract results from different methods
            methods = list(inversion_results.keys())
            
            # Collect azimuth estimates
            azimuths = []
            azimuth_weights = []
            
            # Collect stress ratio estimates
            ratios = []
            ratio_weights = []
            
            # Collect stress regime classifications
            regimes = []
            regime_weights = []
            
            for method, result in inversion_results.items():
                if result and isinstance(result, dict):
                    # Weight based on method reliability and data fit
                    method_weight = self._calculate_method_weight(method, result, processed_fms)
                    
                    if 'shmax_azimuth' in result:
                        azimuths.append(result['shmax_azimuth'])
                        azimuth_weights.append(method_weight)
                    
                    if 'stress_ratio' in result:
                        ratios.append(result['stress_ratio'])
                        ratio_weights.append(method_weight)
                    
                    if 'stress_regime' in result:
                        regimes.append(result['stress_regime'])
                        regime_weights.append(method_weight)
            
            if not azimuths:
                return None
            
            # Ensemble azimuth calculation (circular statistics)
            azimuth_weights = np.array(azimuth_weights)
            azimuth_weights = azimuth_weights / np.sum(azimuth_weights)
            
            # Convert to complex numbers for circular averaging
            azimuth_complex = np.sum(azimuth_weights * np.exp(2j * np.radians(azimuths)))
            ensemble_azimuth = np.degrees(np.angle(azimuth_complex)) / 2 % 180
            
            # Azimuth uncertainty from circular variance
            azimuth_variance = 1 - np.abs(azimuth_complex)
            azimuth_uncertainty = np.degrees(np.sqrt(azimuth_variance)) / 2
            
            # Ensemble stress ratio
            if ratios:
                ratio_weights = np.array(ratio_weights)
                ratio_weights = ratio_weights / np.sum(ratio_weights)
                ensemble_ratio = np.sum(ratio_weights * ratios)
                ratio_uncertainty = np.sqrt(np.sum(ratio_weights * (ratios - ensemble_ratio)**2))
            else:
                ensemble_ratio = 0.5
                ratio_uncertainty = 0.3
            
            # Ensemble stress regime (weighted voting)
            if regimes:
                regime_counts = {}
                for regime, weight in zip(regimes, regime_weights):
                    regime_counts[regime] = regime_counts.get(regime, 0) + weight
                
                ensemble_regime = max(regime_counts, key=regime_counts.get)
                regime_confidence = regime_counts[ensemble_regime] / sum(regime_counts.values())
            else:
                ensemble_regime = 'unknown'
                regime_confidence = 0.0
            
            # Calculate ensemble quality metrics
            method_agreement = self._calculate_method_agreement(inversion_results)
            data_quality = self._assess_ensemble_data_quality(processed_fms)
            
            # Overall confidence score
            confidence_score = (
                (1 - azimuth_uncertainty / 90) * 0.4 +  # Azimuth precision
                (1 - ratio_uncertainty) * 0.3 +         # Ratio precision
                regime_confidence * 0.2 +               # Regime confidence
                method_agreement * 0.1                  # Method agreement
            )
            
            # Compile ensemble result
            ensemble_result = {
                'shmax_azimuth': ensemble_azimuth,
                'stress_ratio': ensemble_ratio,
                'stress_regime': ensemble_regime,
                'uncertainties': {
                    'azimuth_uncertainty': azimuth_uncertainty,
                    'ratio_uncertainty': ratio_uncertainty,
                    'regime_confidence': regime_confidence,
                    'overall_confidence': confidence_score
                },
                'ensemble_statistics': {
                    'methods_used': methods,
                    'method_agreement': method_agreement,
                    'data_quality_score': data_quality,
                    'azimuth_range': [min(azimuths), max(azimuths)] if len(azimuths) > 1 else [ensemble_azimuth, ensemble_azimuth],
                    'ratio_range': [min(ratios), max(ratios)] if len(ratios) > 1 else [ensemble_ratio, ensemble_ratio]
                },
                'individual_results': inversion_results,
                'method': 'ensemble_analysis',
                'data_points': len(processed_fms),
                'analysis_timestamp': datetime.now().isoformat()
            }
            
            return ensemble_result
            
        except Exception as e:
            logger.error(f"Ensemble analysis failed: {e}")
            return None
    
    def _calculate_method_weight(self, method, result, processed_fms):
        """Calculate weight for each inversion method based on reliability"""
        base_weights = {
            'michael1984': 0.8,
            'gephart_forsyth': 0.7,
            'fmsi': 0.9,
            'bayesian_mcmc': 1.0,
            'ml_enhanced': 0.6
        }
        
        base_weight = base_weights.get(method, 0.5)
        
        # Adjust based on result quality
        quality_factor = 1.0
        
        # Penalize high misfit
        if 'misfit' in result or 'rms_misfit' in result:
            misfit = result.get('misfit', result.get('rms_misfit', 0))
            quality_factor *= np.exp(-misfit)  # Exponential penalty for high misfit
        
        # Reward good convergence
        if 'converged' in result and result['converged']:
            quality_factor *= 1.2
        
        # Penalize poor condition numbers
        if 'condition_number' in result:
            cond_num = result['condition_number']
            if cond_num > 100:
                quality_factor *= 0.8
        
        # Reward large datasets
        data_points = result.get('data_points', len(processed_fms))
        if data_points > 20:
            quality_factor *= 1.1
        elif data_points < 10:
            quality_factor *= 0.8
        
        return base_weight * quality_factor
    
    def _calculate_method_agreement(self, inversion_results):
        """Calculate agreement between different inversion methods"""
        try:
            azimuths = []
            ratios = []
            
            for result in inversion_results.values():
                if result and isinstance(result, dict):
                    if 'shmax_azimuth' in result:
                        azimuths.append(result['shmax_azimuth'])
                    if 'stress_ratio' in result:
                        ratios.append(result['stress_ratio'])
            
            agreement_score = 0.0
            
            # Azimuth agreement (circular statistics)
            if len(azimuths) > 1:
                azimuth_rad = np.radians(np.array(azimuths) * 2)  # Double angle
                circular_variance = 1 - np.abs(np.mean(np.exp(1j * azimuth_rad)))
                azimuth_agreement = 1 - circular_variance
                agreement_score += azimuth_agreement * 0.6
            
            # Ratio agreement
            if len(ratios) > 1:
                ratio_std = np.std(ratios)
                ratio_agreement = np.exp(-ratio_std * 2)  # Exponential decay with std
                agreement_score += ratio_agreement * 0.4
            
            return np.clip(agreement_score, 0, 1)
            
        except Exception as e:
            logger.warning(f"Method agreement calculation failed: {e}")
            return 0.5
    
    def _assess_ensemble_data_quality(self, processed_fms):
        """Assess overall data quality for ensemble analysis"""
        try:
            quality_factors = []
            
            # Number of focal mechanisms
            n_fms = len(processed_fms)
            count_quality = min(1.0, n_fms / 20.0)  # Optimal around 20+ mechanisms
            quality_factors.append(count_quality)
            
            # Average quality score
            quality_scores = [fm['quality_score'] for fm in processed_fms]
            avg_quality = np.mean(quality_scores)
            quality_factors.append(avg_quality)
            
            # Spatial distribution
            locations = np.array([fm['location'] for fm in processed_fms])
            if len(locations) > 3:
                # Calculate spatial spread
                centroid = np.mean(locations, axis=0)
                distances = np.linalg.norm(locations - centroid, axis=1)
                spatial_spread = np.std(distances)
                spatial_quality = min(1.0, spatial_spread / 10.0)  # Normalize by ~10 km
                quality_factors.append(spatial_quality)
            
            # Magnitude distribution
            magnitudes = [fm['magnitude'] for fm in processed_fms]
            mag_range = max(magnitudes) - min(magnitudes)
            mag_quality = min(1.0, mag_range / 2.0)  # Good range is 2+ magnitude units
            quality_factors.append(mag_quality)
            
            return np.mean(quality_factors)
            
        except Exception as e:
            logger.warning(f"Data quality assessment failed: {e}")
            return 0.5
    
    async def _store_stress_inversion_results(self, ensemble_result, processed_fms, db_integrator):
        """Store stress inversion results in database for future analysis"""
        try:
            if not ensemble_result:
                return
            
            # Prepare data for storage
            result_data = {
                'analysis_id': f"stress_inversion_{datetime.now().strftime('%Y%m%d_%H%M%S')}",
                'timestamp': datetime.now(),
                'location': {
                    'centroid_lat': np.mean([fm['location'][1] for fm in processed_fms]),
                    'centroid_lon': np.mean([fm['location'][0] for fm in processed_fms]),
                    'centroid_depth': np.mean([fm['location'][2] for fm in processed_fms])
                },
                'shmax_azimuth': ensemble_result['shmax_azimuth'],
                'stress_ratio': ensemble_result['stress_ratio'],
                'stress_regime': ensemble_result['stress_regime'],
                'confidence_score': ensemble_result['uncertainties']['overall_confidence'],
                'data_points': len(processed_fms),
                'methods_used': ensemble_result['ensemble_statistics']['methods_used'],
                'analysis_metadata': ensemble_result
            }
            
            # Store in PostgreSQL
            await db_integrator.store_analysis_result('stress_inversion', result_data)
            
            # Store in time-series database for monitoring
            await db_integrator.store_time_series_data(
                measurement='stress_analysis',
                tags={
                    'analysis_type': 'stress_inversion',
                    'stress_regime': ensemble_result['stress_regime'],
                    'region': f"{result_data['location']['centroid_lat']:.2f}_{result_data['location']['centroid_lon']:.2f}"
                },
                fields={
                    'shmax_azimuth': ensemble_result['shmax_azimuth'],
                    'stress_ratio': ensemble_result['stress_ratio'],
                    'confidence_score': ensemble_result['uncertainties']['overall_confidence'],
                    'data_points': len(processed_fms)
                },
                timestamp=datetime.now()
            )
            
            logger.info(f"Stored stress inversion results for {len(processed_fms)} focal mechanisms")
            
        except Exception as e:
            logger.warning(f"Failed to store stress inversion results: {e}")
    
    async def _determine_tectonic_setting(self, lat, lon, db_integrator):
        """Determine tectonic setting from geological databases"""
        try:
            # Query tectonic plates database
            tectonic_query = await db_integrator.execute_unified_query(
                "tectonic_plates",
                point=[lon, lat]
            )
            
            if tectonic_query.data:
                plate_data = tectonic_query.data[0]
                plate_type = plate_data.get('plate_boundary_type', 'unknown')
                
                # Map plate boundary types to tectonic settings
                setting_map = {
                    'divergent': 'extensional',
                    'convergent': 'compressional',
                    'transform': 'transform',
                    'volcanic_arc': 'volcanic',
                    'back_arc': 'volcanic',
                    'intraplate': 'intraplate'
                }
                
                return setting_map.get(plate_type, 'unknown')
            
            # Fallback: check for nearby volcanoes
            volcano_query = await db_integrator.execute_unified_query(
                "volcanoes",
                bbox=[lon - 0.5, lat - 0.5, lon + 0.5, lat + 0.5]
            )
            
            if volcano_query.data and len(volcano_query.data) > 0:
                return 'volcanic'
            
            return 'unknown'
            
        except Exception as e:
            logger.warning(f"Tectonic setting determination failed: {e}")
            return 'unknown'
            
        except Exception as e:
            logger.error(f"Error determining tectonic setting: {e}")
            return {'tectonic_setting': 'unknown', 'plate_name': 'unknown', 'boundary_distance': 0}

