    async def _fuse_multi_source_dem(self, dem_sources, latitude, longitude):
        """Fuse multiple DEM sources with uncertainty quantification"""
        try:
            import numpy as np
            from scipy import interpolate
            
            if not dem_sources:
                return None
            
            # Create unified coordinate grid based on highest resolution source
            best_resolution = min(
                source.get('resolution', 1000) for source in dem_sources.values()
            )
            
            # Define fusion grid
            grid_extent = 0.1  # degrees
            grid_spacing = best_resolution / 111320  # Convert meters to degrees
            
            lon_grid = np.arange(
                longitude - grid_extent/2, 
                longitude + grid_extent/2, 
                grid_spacing
            )
            lat_grid = np.arange(
                latitude - grid_extent/2, 
                latitude + grid_extent/2, 
                grid_spacing
            )
            
            LON, LAT = np.meshgrid(lon_grid, lat_grid)
            
            # Interpolate each DEM source to common grid
            interpolated_dems = {}
            weights = {}
            
            for source_name, dem_data in dem_sources.items():
                if 'points' in dem_data:
                    # Point data from database
                    points = dem_data['points']
                    if points:
                        coords = np.array([[p['longitude'], p['latitude']] for p in points])
                        elevations = np.array([p['elevation'] for p in points])
                        uncertainties = np.array([p['uncertainty'] for p in points])
                        
                        # Interpolate to grid
                        interp_func = interpolate.griddata(
                            coords, elevations, (LON, LAT), method='linear'
                        )
                        
                        interpolated_dems[source_name] = interp_func
                        weights[source_name] = 1.0 / (uncertainties.mean() + 1e-6)
                
                elif 'elevation_grid' in dem_data:
                    # Grid data from external sources
                    elevation_grid = dem_data['elevation_grid']
                    coordinates = dem_data['coordinates']
                    uncertainty = dem_data.get('uncertainty', 10.0)
                    
                    # Interpolate grid to common coordinates
                    if coordinates and elevation_grid is not None:
                        # This would require proper coordinate handling
                        # For now, use a simplified approach
                        interpolated_dems[source_name] = elevation_grid
                        weights[source_name] = 1.0 / (uncertainty + 1e-6)
            
            # Weighted fusion of DEMs
            if interpolated_dems:
                fused_elevation = np.zeros_like(LON)
                total_weight = np.zeros_like(LON)
                
                for source_name, dem_grid in interpolated_dems.items():
                    if dem_grid is not None:
                        weight = weights[source_name]
                        valid_mask = np.isfinite(dem_grid)
                        
                        fused_elevation[valid_mask] += weight * dem_grid[valid_mask]
                        total_weight[valid_mask] += weight
                
                # Normalize by total weight
                valid_fusion = total_weight > 0
                fused_elevation[valid_fusion] /= total_weight[valid_fusion]
                
                # Estimate fusion uncertainty
                fusion_uncertainty = np.zeros_like(LON)
                if len(interpolated_dems) > 1:
                    # Compute standard deviation across sources
                    dem_stack = []
                    for dem_grid in interpolated_dems.values():
                        if dem_grid is not None:
                            dem_stack.append(dem_grid)
                    
                    if len(dem_stack) > 1:
                        dem_array = np.stack(dem_stack, axis=0)
                        fusion_uncertainty = np.nanstd(dem_array, axis=0)
                
                return {
                    'elevation_grids': {
                        'fused': {
                            'elevation_grid': fused_elevation,
                            'coordinates': {'longitude': LON, 'latitude': LAT},
                            'resolution': best_resolution,
                            'source': 'multi_source_fusion',
                            'uncertainty': fusion_uncertainty,
                            'metadata': {
                                'sources_used': list(dem_sources.keys()),
                                'fusion_method': 'weighted_average',
                                'grid_size': fused_elevation.shape
                            }
                        }
                    },
                    'source_data': dem_sources,
                    'fusion_statistics': {
                        'sources_count': len(dem_sources),
                        'best_resolution': best_resolution,
                        'coverage_area': np.sum(valid_fusion),
                        'mean_uncertainty': np.nanmean(fusion_uncertainty)
                    }
                }
            
            return None
            
        except Exception as e:
            logger.error(f"Multi-source DEM fusion failed: {e}")
            return None
    
    async def _convert_to_local_projection(self, coords, center_lat, center_lon):
        """Convert geographic coordinates to local projection"""
        try:
            from backend.core.data_transformation.coordinate_transformer import CoordinateTransformer
            
            transformer = CoordinateTransformer()
            
            # Use UTM projection centered on the analysis point
            utm_zone = int((center_lon + 180) / 6) + 1
            utm_crs = f"EPSG:{32600 + utm_zone}"  # Northern hemisphere UTM
            
            if center_lat < 0:
                utm_crs = f"EPSG:{32700 + utm_zone}"  # Southern hemisphere UTM
            
            # Transform coordinates
            local_coords = await transformer.transform_coordinates(
                coords, source_crs="EPSG:4326", target_crs=utm_crs
            )
            
            return local_coords
            
        except Exception as e:
            logger.error(f"Coordinate transformation failed: {e}")
            return coords  # Return original coordinates as fallback
    
    async def _define_adaptive_compartments(self, coords, elevation_grid, obs_elevation, resolution):
        """Define adaptive compartments based on topographic complexity"""
        try:
            import numpy as np
            
            # Compute topographic gradients
            grad_y, grad_x = np.gradient(elevation_grid)
            gradient_magnitude = np.sqrt(grad_x**2 + grad_y**2)
            
            # Define compartment sizes based on gradient
            base_size = resolution * 2  # Base compartment size
            adaptive_sizes = base_size / (1 + gradient_magnitude / np.nanmean(gradient_magnitude))
            
            compartments = []
            ny, nx = elevation_grid.shape
            
            for i in range(0, ny, 5):  # Sample every 5th point for efficiency
                for j in range(0, nx, 5):
                    if np.isfinite(elevation_grid[i, j]):
                        compartment_size = adaptive_sizes[i, j]
                        
                        compartment = {
                            'center': (coords[i, j, 0], coords[i, j, 1]),
                            'elevation': elevation_grid[i, j],
                            'size': compartment_size,
                            'gradient': gradient_magnitude[i, j],
                            'distance_to_obs': np.sqrt(
                                (coords[i, j, 0] - coords[ny//2, nx//2, 0])**2 +
                                (coords[i, j, 1] - coords[ny//2, nx//2, 1])**2
                            )
                        }
                        compartments.append(compartment)
            
            return compartments
            
        except Exception as e:
            logger.error(f"Adaptive compartment definition failed: {e}")
            return []
    
    async def _estimate_compartment_density(self, compartment, latitude, longitude):
        """Estimate rock density for compartment based on geological data"""
        try:
            # Query geological database for rock types in the area
            geology_query = f"""
            SELECT lithology, density_kg_m3
            FROM geological_structures
            WHERE ST_DWithin(
                location,
                ST_SetSRID(ST_MakePoint({longitude}, {latitude}), 4326),
                0.01
            )
            ORDER BY ST_Distance(
                location,
                ST_SetSRID(ST_MakePoint({longitude}, {latitude}), 4326)
            )
            LIMIT 1
            """
            
            # Simplified density estimation
            # In a real implementation, this would query the geological database
            
            # Default densities by elevation (simplified model)
            elevation = compartment['elevation']
            
            if elevation < -2000:  # Deep ocean
                return 2300  # Sediments
            elif elevation < 0:  # Shallow marine
                return 2500  # Marine sediments/basalt
            elif elevation < 1000:  # Low elevation terrestrial
                return 2600  # Sedimentary rocks
            elif elevation < 3000:  # Moderate elevation
                return 2700  # Metamorphic/igneous rocks
            else:  # High elevation
                return 2800  # Dense igneous rocks
            
        except Exception as e:
            logger.error(f"Compartment density estimation failed: {e}")
            return 2670  # Average crustal density
    
    async def _compute_compartment_correction(self, compartment, obs_elevation, density, G):
        """Compute gravitational correction for a compartment"""
        try:
            import numpy as np
            
            # Compartment parameters
            center_x, center_y = compartment['center']
            comp_elevation = compartment['elevation']
            size = compartment['size']
            
            # Height difference
            height_diff = comp_elevation - obs_elevation
            
            if abs(height_diff) < 1e-6:  # Negligible height difference
                return 0.0
            
            # Horizontal distance
            horizontal_dist = compartment['distance_to_obs']
            
            if horizontal_dist < 1e-6:  # At observation point
                return 0.0
            
            # Compartment volume (simplified as rectangular prism)
            volume = size * size * abs(height_diff)
            
            # Mass of compartment
            mass = density * volume
            
            # Gravitational attraction (simplified point mass approximation)
            total_distance = np.sqrt(horizontal_dist**2 + height_diff**2)
            
            # Gravitational acceleration
            g_correction = G * mass / (total_distance**2)
            
            # Vertical component
            vertical_component = g_correction * abs(height_diff) / total_distance
            
            # Sign convention: positive for mass above, negative for mass below
            if comp_elevation > obs_elevation:
                return vertical_component
            else:
                return -vertical_component
            
        except Exception as e:
            logger.error(f"Compartment correction computation failed: {e}")
            return 0.0
    
    async def _apply_field_corrections(self, base_correction, elevation_grid, obs_elevation, resolution):
        """Apply near-field and far-field corrections"""
        try:
            import numpy as np
            
            # Near-field correction for high-frequency effects
            local_relief = np.nanstd(elevation_grid)
            near_field_factor = 1.0 + 0.1 * (local_relief / 1000.0)  # 10% per km of relief
            
            # Far-field correction for regional topography
            regional_elevation = np.nanmean(elevation_grid)
            elevation_anomaly = obs_elevation - regional_elevation
            far_field_correction = 0.0001 * elevation_anomaly  # Small regional effect
            
            corrected_value = base_correction * near_field_factor + far_field_correction
            
            return corrected_value
            
        except Exception as e:
            logger.error(f"Field corrections failed: {e}")
            return base_correction
    
    async def _create_adaptive_prism_grid(self, coords, elevation_grid, obs_elevation, resolution):
        """Create adaptive prism grid for Nagy correction"""
        try:
            import numpy as np
            
            prisms = []
            ny, nx = elevation_grid.shape
            
            # Create prisms with adaptive sizing
            for i in range(0, ny-1, 2):  # Sample every 2nd point
                for j in range(0, nx-1, 2):
                    if (np.isfinite(elevation_grid[i, j]) and 
                        np.isfinite(elevation_grid[i+1, j+1])):
                        
                        # Prism corners
                        x1, y1 = coords[i, j, 0], coords[i, j, 1]
                        x2, y2 = coords[i+1, j+1, 0], coords[i+1, j+1, 1]
                        
                        # Prism elevations
                        z1 = min(elevation_grid[i, j], obs_elevation)
                        z2 = max(elevation_grid[i, j], obs_elevation)
                        
                        if abs(z2 - z1) > 1e-6:  # Non-zero thickness
                            prism = {
                                'x1': x1, 'x2': x2,
                                'y1': y1, 'y2': y2,
                                'z1': z1, 'z2': z2,
                                'center_x': (x1 + x2) / 2,
                                'center_y': (y1 + y2) / 2,
                                'thickness': abs(z2 - z1)
                            }
                            prisms.append(prism)
            
            return prisms
            
        except Exception as e:
            logger.error(f"Adaptive prism grid creation failed: {e}")
            return []
    
    async def _estimate_prism_density(self, prism, latitude, longitude):
        """Estimate density for prism based on geological context"""
        try:
            # Use center of prism for density estimation
            center_elevation = (prism['z1'] + prism['z2']) / 2
            
            # Simplified density model based on elevation and geological context
            if center_elevation < -1000:  # Deep marine
                return 2400  # Marine sediments
            elif center_elevation < 0:  # Shallow marine/coastal
                return 2550  # Mixed sediments/volcanics
            elif center_elevation < 500:  # Low terrestrial
                return 2650  # Sedimentary rocks
            elif center_elevation < 2000:  # Moderate elevation
                return 2700  # Mixed rocks
            else:  # High elevation
                return 2750  # Dense igneous/metamorphic
            
        except Exception as e:
            logger.error(f"Prism density estimation failed: {e}")
            return 2670  # Default crustal density
    
    async def _compute_nagy_prism_attraction(self, prism, obs_elevation, density, G):
        """Compute Nagy analytical solution for rectangular prism"""
        try:
            import numpy as np
            
            # Prism dimensions
            x1, x2 = prism['x1'], prism['x2']
            y1, y2 = prism['y1'], prism['y2']
            z1, z2 = prism['z1'], prism['z2']
            
            # Observation point (at origin of local coordinate system)
            x0, y0, z0 = 0.0, 0.0, obs_elevation
            
            # Nagy's analytical solution for rectangular prism
            # This is a simplified version - full implementation would include all terms
            
            # Distance calculations
            dx1, dx2 = x1 - x0, x2 - x0
            dy1, dy2 = y1 - y0, y2 - y0
            dz1, dz2 = z1 - z0, z2 - z0
            
            # Avoid singularities
            eps = 1e-10
            dx1 = dx1 if abs(dx1) > eps else eps
            dx2 = dx2 if abs(dx2) > eps else eps
            dy1 = dy1 if abs(dy1) > eps else eps
            dy2 = dy2 if abs(dy2) > eps else eps
            dz1 = dz1 if abs(dz1) > eps else eps
            dz2 = dz2 if abs(dz2) > eps else eps
            
            # Nagy formula terms (simplified)
            r111 = np.sqrt(dx1**2 + dy1**2 + dz1**2)
            r112 = np.sqrt(dx1**2 + dy1**2 + dz2**2)
            r121 = np.sqrt(dx1**2 + dy2**2 + dz1**2)
            r122 = np.sqrt(dx1**2 + dy2**2 + dz2**2)
            r211 = np.sqrt(dx2**2 + dy1**2 + dz1**2)
            r212 = np.sqrt(dx2**2 + dy1**2 + dz2**2)
            r221 = np.sqrt(dx2**2 + dy2**2 + dz1**2)
            r222 = np.sqrt(dx2**2 + dy2**2 + dz2**2)
            
            # Gravitational potential (simplified)
            potential = (
                dx1 * dy1 * np.log(dz1 + r111) - dx1 * dy1 * np.log(dz2 + r112) -
                dx1 * dy2 * np.log(dz1 + r121) + dx1 * dy2 * np.log(dz2 + r122) -
                dx2 * dy1 * np.log(dz1 + r211) + dx2 * dy1 * np.log(dz2 + r212) +
                dx2 * dy2 * np.log(dz1 + r221) - dx2 * dy2 * np.log(dz2 + r222)
            )
            
            # Gravitational acceleration (vertical component)
            g_z = G * density * potential
            
            return g_z
            
        except Exception as e:
            logger.error(f"Nagy prism attraction computation failed: {e}")
            return 0.0
    
    async def _extract_topographic_features(self, latitude, longitude, elevation, dem_data):
        """Extract topographic features for ML model"""
        try:
            import numpy as np
            
            best_dem = self._select_best_resolution_dem(dem_data['elevation_grids'])
            if not best_dem:
                return None
            
            elevation_grid = best_dem['elevation_grid']
            
            # Compute topographic features
            features = {}
            
            # Basic statistics
            features['mean_elevation'] = np.nanmean(elevation_grid)
            features['std_elevation'] = np.nanstd(elevation_grid)
            features['min_elevation'] = np.nanmin(elevation_grid)
            features['max_elevation'] = np.nanmax(elevation_grid)
            features['elevation_range'] = features['max_elevation'] - features['min_elevation']
            
            # Gradients and slopes
            grad_y, grad_x = np.gradient(elevation_grid)
            slope = np.sqrt(grad_x**2 + grad_y**2)
            features['mean_slope'] = np.nanmean(slope)
            features['max_slope'] = np.nanmax(slope)
            features['slope_std'] = np.nanstd(slope)
            
            # Curvature
            grad_yy, grad_yx = np.gradient(grad_y)
            grad_xy, grad_xx = np.gradient(grad_x)
            curvature = grad_xx + grad_yy
            features['mean_curvature'] = np.nanmean(curvature)
            features['curvature_std'] = np.nanstd(curvature)
            
            # Roughness index
            features['roughness_index'] = np.nanstd(elevation_grid) / np.nanmean(elevation_grid)
            
            # Observation point characteristics
            features['obs_elevation'] = elevation
            features['elevation_percentile'] = np.sum(elevation_grid < elevation) / np.sum(np.isfinite(elevation_grid))
            
            return features
            
        except Exception as e:
            logger.error(f"Topographic feature extraction failed: {e}")
            return None
    
