    async def _compute_aerosol_transmission(self, aod_550nm, air_mass, elevation_deg):
        """Compute aerosol transmission using Angstrom turbidity model"""
        try:
            # Angstrom exponent (typical value for continental aerosols)
            alpha = 1.3
            
            # Wavelength-dependent AOD (assuming solar spectrum ~500nm)
            wavelength_ratio = 550.0 / 500.0
            aod_500nm = aod_550nm * (wavelength_ratio ** alpha)
            
            # Aerosol transmission
            transmission = np.exp(-aod_500nm * air_mass)
            
            return transmission
            
        except Exception as e:
            logger.error(f"Aerosol transmission computation failed: {e}")
            return 0.9  # Default clear sky value
    
    async def _compute_water_vapor_transmission(self, water_vapor_cm, air_mass, elevation_deg):
        """Compute water vapor transmission using MODTRAN-based model"""
        try:
            # Water vapor absorption coefficients (simplified MODTRAN model)
            # These are wavelength-dependent; using broadband solar values
            k_wv = 0.031  # Absorption coefficient for water vapor (cm⁻¹)
            
            # Water vapor transmission
            transmission = np.exp(-k_wv * water_vapor_cm * air_mass)
            
            return transmission
            
        except Exception as e:
            logger.error(f"Water vapor transmission computation failed: {e}")
            return 0.95  # Default value
    
    async def _compute_ozone_transmission(self, ozone_column_du, air_mass, elevation_deg):
        """Compute ozone transmission"""
        try:
            # Ozone absorption coefficient (Dobson units to optical depth)
            k_ozone = 0.0001  # Simplified coefficient for solar spectrum
            
            # Convert Dobson units to optical depth
            ozone_optical_depth = k_ozone * ozone_column_du
            
            # Ozone transmission
            transmission = np.exp(-ozone_optical_depth * air_mass)
            
            return transmission
            
        except Exception as e:
            logger.error(f"Ozone transmission computation failed: {e}")
            return 0.98  # Default value
    
    async def _compute_rayleigh_transmission(self, pressure_hpa, air_mass, elevation_deg, site_elevation_m):
        """Compute Rayleigh scattering transmission"""
        try:
            # Rayleigh optical depth at sea level for 500nm
            tau_r_0 = 0.008735  # At 500nm wavelength
            
            # Pressure correction for altitude
            pressure_ratio = pressure_hpa / 1013.25
            
            # Rayleigh optical depth
            tau_rayleigh = tau_r_0 * pressure_ratio
            
            # Rayleigh transmission
            transmission = np.exp(-tau_rayleigh * air_mass)
            
            return transmission
            
        except Exception as e:
            logger.error(f"Rayleigh transmission computation failed: {e}")
            return 0.92  # Default value
    
    async def _compute_mixed_gas_transmission(self, atmospheric_data, air_mass, elevation_deg):
        """Compute mixed gas absorption (CO2, O2, etc.)"""
        try:
            # Simplified mixed gas absorption
            # CO2 absorption (relatively constant)
            tau_co2 = 0.0016
            
            # O2 absorption
            tau_o2 = 0.0019
            
            # Total mixed gas optical depth
            tau_mixed = tau_co2 + tau_o2
            
            # Mixed gas transmission
            transmission = np.exp(-tau_mixed * air_mass)
            
            return transmission
            
        except Exception as e:
            logger.error(f"Mixed gas transmission computation failed: {e}")
            return 0.99  # Default value
    
    async def _compute_precise_solar_azimuth(self, latitude, longitude, timestamp):
        """Compute precise solar azimuth using astronomical algorithms"""
        try:
            from datetime import datetime
            import math
            
            # Convert timestamp to Julian day
            julian_day = await self._datetime_to_julian_day(timestamp)
            
            # Compute solar position using high-precision algorithms
            solar_position = await self._compute_solar_position_spa(
                julian_day, latitude, longitude
            )
            
            return solar_position['azimuth']
            
        except Exception as e:
            logger.error(f"Precise solar azimuth computation failed: {e}")
            # Fallback to approximate calculation
            return await self._compute_approximate_solar_azimuth(latitude, longitude, timestamp)
    
    async def _compute_solar_position_spa(self, julian_day, latitude, longitude):
        """
        Solar Position Algorithm (SPA) for high-precision solar position
        Based on NREL SPA algorithm
        """
        try:
            import math
            
            # Julian centuries since J2000.0
            jc = (julian_day - 2451545.0) / 36525.0
            
            # Heliocentric longitude (degrees)
            L0 = self._compute_earth_heliocentric_longitude(jc)
            
            # Heliocentric latitude (degrees)
            B0 = self._compute_earth_heliocentric_latitude(jc)
            
            # Earth radius vector (AU)
            R = self._compute_earth_radius_vector(jc)
            
            # Geocentric longitude and latitude
            theta = L0 + 180.0
            beta = -B0
            
            # Nutation and aberration corrections
            delta_psi, delta_epsilon = self._compute_nutation(jc)
            delta_tau = -20.4898 / (3600.0 * R)  # Aberration correction
            
            # Apparent geocentric longitude
            lambda_app = theta + delta_psi + delta_tau
            
            # True obliquity of the ecliptic
            epsilon = self._compute_obliquity_ecliptic(jc) + delta_epsilon
            
            # Geocentric sun right ascension and declination
            alpha, delta = self._ecliptic_to_equatorial(lambda_app, beta, epsilon)
            
            # Local hour angle
            nu = self._compute_greenwich_sidereal_time(julian_day) + longitude - alpha
            
            # Topocentric sun coordinates
            elevation, azimuth = self._equatorial_to_horizontal(nu, delta, latitude)
            
            return {
                'elevation': elevation,
                'azimuth': azimuth,
                'right_ascension': alpha,
                'declination': delta
            }
            
        except Exception as e:
            logger.error(f"SPA solar position computation failed: {e}")
            return {'elevation': 45.0, 'azimuth': 180.0}
    
    async def _query_historical_atmospheric_corrections(self, latitude, longitude, start_date, end_date, gis_integrator):
        """Query historical atmospheric corrections from database"""
        try:
            # Query atmospheric correction data from deformation measurements
            query = f"""
            SELECT 
                measurement_timestamp,
                atmospheric_correction,
                processing_parameters,
                data_quality,
                ST_X(ST_Transform(ST_SetSRID(ST_MakePoint(location_lon, location_lat), 4326), 4326)) as longitude,
                ST_Y(ST_Transform(ST_SetSRID(ST_MakePoint(location_lon, location_lat), 4326), 4326)) as latitude
            FROM high_res_deformation_measurements
            WHERE measurement_type = 'InSAR'
            AND measurement_timestamp BETWEEN '{start_date.isoformat()}' AND '{end_date.isoformat()}'
            AND ST_DWithin(
                ST_SetSRID(ST_MakePoint(location_lon, location_lat), 4326),
                ST_SetSRID(ST_MakePoint({longitude}, {latitude}), 4326),
                0.5  -- 0.5 degree radius
            )
            AND atmospheric_correction IS NOT NULL
            ORDER BY measurement_timestamp
            """
            
            result = await gis_integrator.enhanced_db.execute_query(query)
            
            corrections = []
            if result and result.data:
                for row in result.data:
                    correction_data = {
                        'timestamp': row[0],
                        'atmospheric_correction': row[1],
                        'processing_parameters': row[2] or {},
                        'data_quality': row[3],
                        'longitude': row[4],
                        'latitude': row[5]
                    }
                    corrections.append(correction_data)
            
            logger.info(f"Retrieved {len(corrections)} historical atmospheric corrections")
            return corrections
            
        except Exception as e:
            logger.error(f"Historical atmospheric corrections query failed: {e}")
            return []
    
