    async def _synchronize_atmospheric_datasets(self, corrections, era5_data, modis_data, weather_data, radiosonde_data):
        """Synchronize and merge atmospheric datasets"""
        try:
            from datetime import timedelta
            import pandas as pd
            
            synchronized_records = []
            
            # Use atmospheric corrections as the primary timeline
            for correction in corrections:
                timestamp = correction['timestamp']
                
                # Create synchronized record
                record = {
                    'timestamp': timestamp,
                    'atmospheric_correction': correction['atmospheric_correction'],
                    'latitude': correction['latitude'],
                    'longitude': correction['longitude']
                }
                
                # Find nearest ERA5 data (within 6 hours)
                era5_match = self._find_nearest_temporal_match(
                    era5_data, timestamp, timedelta(hours=6)
                )
                if era5_match:
                    record.update({
                        'era5_water_vapor': era5_match.get('total_column_water_vapour', 0),
                        'era5_pressure': era5_match.get('surface_pressure', 0),
                        'era5_temperature': era5_match.get('2m_temperature', 0),
                        'era5_humidity': era5_match.get('2m_relative_humidity', 0),
                        'era5_cloud_cover': era5_match.get('total_cloud_cover', 0)
                    })
                
                # Find nearest MODIS data (within 1 day)
                modis_match = self._find_nearest_temporal_match(
                    modis_data, timestamp, timedelta(days=1)
                )
                if modis_match:
                    record.update({
                        'modis_aod': modis_match.get('Aerosol_Optical_Depth_Land_Ocean_Mean', 0),
                        'modis_water_vapor': modis_match.get('Water_Vapor_Infrared_Mean', 0),
                        'modis_cloud_fraction': modis_match.get('Cloud_Fraction_Mean', 0)
                    })
                
                # Find nearest weather station data (within 3 hours)
                weather_match = self._find_nearest_temporal_match(
                    weather_data, timestamp, timedelta(hours=3)
                )
                if weather_match:
                    record.update({
                        'station_temperature': weather_match.get('temperature_c', 0),
                        'station_pressure': weather_match.get('pressure_hpa', 0),
                        'station_humidity': weather_match.get('humidity_percent', 0),
                        'station_wind_speed': weather_match.get('wind_speed_ms', 0),
                        'station_wind_direction': weather_match.get('wind_direction_deg', 0)
                    })
                
                synchronized_records.append(record)
            
            logger.info(f"Synchronized {len(synchronized_records)} atmospheric records")
            return synchronized_records
            
        except Exception as e:
            logger.error(f"Atmospheric dataset synchronization failed: {e}")
            return []
    
    def _find_nearest_temporal_match(self, data_list, target_timestamp, max_delta):
        """Find nearest temporal match within maximum time delta"""
        try:
            best_match = None
            min_delta = max_delta
            
            for record in data_list:
                record_timestamp = record.get('timestamp') or record.get('measurement_time')
                if record_timestamp:
                    delta = abs(record_timestamp - target_timestamp)
                    if delta < min_delta:
                        min_delta = delta
                        best_match = record
            
            return best_match
            
        except Exception as e:
            logger.error(f"Temporal matching failed: {e}")
            return None
    
    async def _extract_atmospheric_feature_vector(self, record):
        """Extract feature vector for ML training"""
        try:
            features = []
            
            # Temporal features
            timestamp = record.get('timestamp')
            if timestamp:
                features.extend([
                    timestamp.hour,  # Hour of day
                    timestamp.day,   # Day of month
                    timestamp.month, # Month
                    np.sin(2 * np.pi * timestamp.hour / 24),  # Diurnal cycle
                    np.cos(2 * np.pi * timestamp.hour / 24),
                    np.sin(2 * np.pi * timestamp.day / 365.25),  # Annual cycle
                    np.cos(2 * np.pi * timestamp.day / 365.25)
                ])
            else:
                features.extend([0] * 7)
            
            # Spatial features
            features.extend([
                record.get('latitude', 0),
                record.get('longitude', 0)
            ])
            
            # ERA5 features
            features.extend([
                record.get('era5_water_vapor', 0),
                record.get('era5_pressure', 0),
                record.get('era5_temperature', 0),
                record.get('era5_humidity', 0),
                record.get('era5_cloud_cover', 0)
            ])
            
            # MODIS features
            features.extend([
                record.get('modis_aod', 0),
                record.get('modis_water_vapor', 0),
                record.get('modis_cloud_fraction', 0)
            ])
            
            # Weather station features
            features.extend([
                record.get('station_temperature', 0),
                record.get('station_pressure', 0),
                record.get('station_humidity', 0),
                record.get('station_wind_speed', 0),
                record.get('station_wind_direction', 0)
            ])
            
            # Derived features
            # Atmospheric stability indicators
            temp_gradient = record.get('era5_temperature', 288) - 288.15  # Temperature anomaly
            pressure_anomaly = record.get('era5_pressure', 101325) - 101325  # Pressure anomaly
            
            features.extend([
                temp_gradient,
                pressure_anomaly,
                temp_gradient * pressure_anomaly,  # Interaction term
                record.get('era5_water_vapor', 0) * record.get('era5_temperature', 288),  # WV-temp interaction
                record.get('modis_aod', 0) * record.get('era5_humidity', 50)  # Aerosol-humidity interaction
            ])
            
            # Pad to ensure consistent feature count (50 features)
            while len(features) < 50:
                features.append(0.0)
            
            return np.array(features[:50])  # Ensure exactly 50 features
            
        except Exception as e:
            logger.error(f"Feature vector extraction failed: {e}")
            return None
    
    async def _condition_dem_for_analysis(self, dem):
        """Condition DEM data for robust analysis"""
        try:
            from scipy import ndimage
            
            # Remove outliers using median filter
            dem_filtered = ndimage.median_filter(dem, size=3)
            
            # Fill NaN values using interpolation
            mask = np.isfinite(dem_filtered)
            if not np.all(mask):
                from scipy.interpolate import griddata
                
                y, x = np.mgrid[0:dem.shape[0], 0:dem.shape[1]]
                valid_points = np.column_stack([y[mask], x[mask]])
                valid_values = dem_filtered[mask]
                
                if len(valid_values) > 0:
                    interpolated = griddata(
                        valid_points, valid_values, (y, x), method='linear', fill_value=np.nanmean(valid_values)
                    )
                    dem_filtered = np.where(mask, dem_filtered, interpolated)
            
            return dem_filtered
            
        except Exception as e:
            logger.error(f"DEM conditioning failed: {e}")
            return dem
    
    async def _compute_basic_topographic_derivatives(self, dem, resolution):
        """Fallback basic topographic derivatives"""
        try:
            # Simple gradient computation
            gy, gx = np.gradient(dem)
            slope = np.degrees(np.arctan(np.sqrt(gx**2 + gy**2)))
            aspect = np.degrees(np.arctan2(-gx, gy)) % 360
            
            return {
                'slope': slope,
                'aspect': aspect,
                'curvatures': {'mean_curvature': np.zeros_like(dem)},
                'roughness_metrics': {'surface_roughness_3x3': np.std(dem) * np.ones_like(dem)},
                'geomorphometry': {},
                'terrain_classes': np.zeros_like(dem)
            }
            
        except Exception as e:
            logger.error(f"Basic topographic derivatives failed: {e}")
            return {
                'slope': np.zeros_like(dem),
                'aspect': np.zeros_like(dem),
                'curvatures': {'mean_curvature': np.zeros_like(dem)},
                'roughness_metrics': {'surface_roughness_3x3': np.zeros_like(dem)},
                'geomorphometry': {},
                'terrain_classes': np.zeros_like(dem)
            }
    
