    async def _analyze_spatial_coherence(self, original_phases, corrected_phases):
        """Analyze spatial coherence improvements from atmospheric correction"""
        from scipy import ndimage
        from skimage.measure import compare_ssim
        
        coherence_metrics = {}
        
        try:
            # Compute spatial gradients
            original_gradients = []
            corrected_gradients = []
            
            for i in range(original_phases.shape[0]):
                # Original gradients
                grad_x_orig = np.gradient(original_phases[i], axis=1)
                grad_y_orig = np.gradient(original_phases[i], axis=0)
                grad_mag_orig = np.sqrt(grad_x_orig**2 + grad_y_orig**2)
                original_gradients.append(grad_mag_orig)
                
                # Corrected gradients
                grad_x_corr = np.gradient(corrected_phases[i], axis=1)
                grad_y_corr = np.gradient(corrected_phases[i], axis=0)
                grad_mag_corr = np.sqrt(grad_x_corr**2 + grad_y_corr**2)
                corrected_gradients.append(grad_mag_corr)
            
            # Gradient smoothness improvement
            original_gradient_std = np.mean([np.nanstd(grad) for grad in original_gradients])
            corrected_gradient_std = np.mean([np.nanstd(grad) for grad in corrected_gradients])
            
            coherence_metrics['gradient_smoothness_improvement'] = (
                original_gradient_std - corrected_gradient_std
            ) / original_gradient_std
            
            # Structural similarity improvement
            ssim_scores = []
            for i in range(len(original_phases) - 1):
                for j in range(i + 1, len(original_phases)):
                    # Ensure data is in valid range for SSIM
                    orig_i = (original_phases[i] - np.nanmin(original_phases[i])) / (np.nanmax(original_phases[i]) - np.nanmin(original_phases[i]) + 1e-8)
                    orig_j = (original_phases[j] - np.nanmin(original_phases[j])) / (np.nanmax(original_phases[j]) - np.nanmin(original_phases[j]) + 1e-8)
                    corr_i = (corrected_phases[i] - np.nanmin(corrected_phases[i])) / (np.nanmax(corrected_phases[i]) - np.nanmin(corrected_phases[i]) + 1e-8)
                    corr_j = (corrected_phases[j] - np.nanmin(corrected_phases[j])) / (np.nanmax(corrected_phases[j]) - np.nanmin(corrected_phases[j]) + 1e-8)
                    
                    # Handle NaN values
                    valid_mask = ~(np.isnan(orig_i) | np.isnan(orig_j) | np.isnan(corr_i) | np.isnan(corr_j))
                    if np.sum(valid_mask) > 100:
                        try:
                            ssim_orig = compare_ssim(orig_i[valid_mask].reshape(int(np.sqrt(np.sum(valid_mask))), -1), 
                                                   orig_j[valid_mask].reshape(int(np.sqrt(np.sum(valid_mask))), -1))
                            ssim_corr = compare_ssim(corr_i[valid_mask].reshape(int(np.sqrt(np.sum(valid_mask))), -1), 
                                                   corr_j[valid_mask].reshape(int(np.sqrt(np.sum(valid_mask))), -1))
                            ssim_scores.append((ssim_orig, ssim_corr))
                        except:
                            continue
            
            if ssim_scores:
                ssim_improvement = np.mean([corr - orig for orig, corr in ssim_scores])
                coherence_metrics['ssim_improvement'] = ssim_improvement
            
            # Overall spatial coherence score
            coherence_metrics['overall_score'] = np.mean([
                coherence_metrics.get('gradient_smoothness_improvement', 0),
                coherence_metrics.get('ssim_improvement', 0)
            ])
            
        except Exception as e:
            logger.warning(f"Spatial coherence analysis failed: {e}")
            coherence_metrics['overall_score'] = 0.0
        
        return coherence_metrics
    
    async def _analyze_temporal_consistency(self, original_phases, corrected_phases):
        """Analyze temporal consistency improvements"""
        consistency_metrics = {}
        
        try:
            # Temporal variance reduction
            original_temporal_var = np.var(original_phases, axis=0)
            corrected_temporal_var = np.var(corrected_phases, axis=0)
            
            var_reduction = np.nanmean(
                (original_temporal_var - corrected_temporal_var) / (original_temporal_var + 1e-8)
            )
            consistency_metrics['variance_reduction'] = var_reduction
            
            # Temporal autocorrelation improvement
            original_autocorr = []
            corrected_autocorr = []
            
            for i in range(original_phases.shape[1]):
                for j in range(original_phases.shape[2]):
                    orig_ts = original_phases[:, i, j]
                    corr_ts = corrected_phases[:, i, j]
                    
                    if not np.any(np.isnan(orig_ts)) and not np.any(np.isnan(corr_ts)):
                        if len(orig_ts) > 2:
                            orig_ac = np.corrcoef(orig_ts[:-1], orig_ts[1:])[0, 1]
                            corr_ac = np.corrcoef(corr_ts[:-1], corr_ts[1:])[0, 1]
                            
                            if not np.isnan(orig_ac) and not np.isnan(corr_ac):
                                original_autocorr.append(orig_ac)
                                corrected_autocorr.append(corr_ac)
            
            if original_autocorr and corrected_autocorr:
                autocorr_improvement = np.mean(corrected_autocorr) - np.mean(original_autocorr)
                consistency_metrics['autocorr_improvement'] = autocorr_improvement
            
            # Overall temporal consistency score
            consistency_metrics['overall_score'] = np.mean([
                consistency_metrics.get('variance_reduction', 0),
                consistency_metrics.get('autocorr_improvement', 0)
            ])
            
        except Exception as e:
            logger.warning(f"Temporal consistency analysis failed: {e}")
            consistency_metrics['overall_score'] = 0.0
        
        return consistency_metrics
    
    async def _analyze_correction_spectrum(self, original_phases, corrections):
        """Analyze spectral characteristics of atmospheric corrections"""
        from scipy.fft import fft2, fftfreq
        
        spectral_analysis = {}
        
        try:
            # Compute 2D FFT for spatial frequency analysis
            correction_spectra = []
            original_spectra = []
            
            for i in range(original_phases.shape[0]):
                # Original spectrum
                orig_fft = fft2(original_phases[i])
                orig_power = np.abs(orig_fft)**2
                original_spectra.append(orig_power)
                
                # Correction spectrum
                corr_fft = fft2(corrections[i])
                corr_power = np.abs(corr_fft)**2
                correction_spectra.append(corr_power)
            
            # Average power spectra
            avg_orig_spectrum = np.mean(original_spectra, axis=0)
            avg_corr_spectrum = np.mean(correction_spectra, axis=0)
            
            # Spectral characteristics
            spectral_analysis['correction_power_ratio'] = np.sum(avg_corr_spectrum) / np.sum(avg_orig_spectrum)
            
            # Dominant spatial frequencies in corrections
            freqs_x = fftfreq(corrections.shape[2])
            freqs_y = fftfreq(corrections.shape[1])
            
            # Find peak frequencies
            peak_idx = np.unravel_index(np.argmax(avg_corr_spectrum), avg_corr_spectrum.shape)
            dominant_freq_x = freqs_x[peak_idx[1]]
            dominant_freq_y = freqs_y[peak_idx[0]]
            
            spectral_analysis['dominant_spatial_frequency'] = {
                'freq_x': dominant_freq_x,
                'freq_y': dominant_freq_y,
                'wavelength_x': 1.0 / (abs(dominant_freq_x) + 1e-8),
                'wavelength_y': 1.0 / (abs(dominant_freq_y) + 1e-8)
            }
            
        except Exception as e:
            logger.warning(f"Spectral analysis failed: {e}")
            spectral_analysis = {'correction_power_ratio': 0.0}
        
        return spectral_analysis
    
    async def _assess_correction_physics(self, original_phases, corrections):
        """Assess physical plausibility of atmospheric corrections"""
        physics_metrics = {}
        
        try:
            # Check correction magnitudes
            correction_magnitudes = np.abs(corrections)
            max_correction = np.nanmax(correction_magnitudes)
            mean_correction = np.nanmean(correction_magnitudes)
            
            # Typical atmospheric delays: 0-20 cm in extreme cases
            if max_correction > 200:  # > 20 cm
                magnitude_plausibility = 0.1
            elif max_correction > 100:  # > 10 cm
                magnitude_plausibility = 0.5
            elif max_correction < 1:  # < 1 mm
                magnitude_plausibility = 0.3
            else:
                magnitude_plausibility = 0.9
            
            physics_metrics['magnitude_plausibility'] = magnitude_plausibility
            
            # Spatial smoothness (atmospheric effects should be smooth)
            smoothness_scores = []
            for i in range(corrections.shape[0]):
                laplacian = ndimage.laplace(corrections[i])
                roughness = np.nanstd(laplacian)
                smoothness = 1.0 / (1.0 + roughness)
                smoothness_scores.append(smoothness)
            
            physics_metrics['spatial_smoothness'] = np.mean(smoothness_scores)
            
            # Temporal smoothness
            if corrections.shape[0] > 1:
                temporal_diff = np.diff(corrections, axis=0)
                temporal_roughness = np.nanstd(temporal_diff)
                temporal_smoothness = 1.0 / (1.0 + temporal_roughness)
                physics_metrics['temporal_smoothness'] = temporal_smoothness
            
            # Overall plausibility score
            physics_metrics['plausibility_score'] = np.mean([
                physics_metrics['magnitude_plausibility'],
                physics_metrics['spatial_smoothness'],
                physics_metrics.get('temporal_smoothness', 0.8)
            ])
            
        except Exception as e:
            logger.warning(f"Physics assessment failed: {e}")
            physics_metrics['plausibility_score'] = 0.5
        
        return physics_metrics
    
    async def _validate_atmospheric_corrections(self, corrections):
        """Validate corrections against external atmospheric data"""
        validation_metrics = {}
        
        try:
            # Fetch independent atmospheric data for validation
            atmospheric_data = await self._fetch_independent_atmospheric_data()
            
            if atmospheric_data:
                # Compare correction patterns with atmospheric model predictions
                model_predictions = atmospheric_data.get('zenith_delay_predictions', [])
                
                if model_predictions and len(model_predictions) == corrections.shape[0]:
                    # Compute correlation between corrections and atmospheric predictions
                    correlations = []
                    for i in range(corrections.shape[0]):
                        corr_flat = corrections[i].flatten()
                        pred_flat = np.full_like(corr_flat, model_predictions[i])
                        
                        valid_mask = ~np.isnan(corr_flat)
                        if np.sum(valid_mask) > 100:
                            corr_coef = np.corrcoef(corr_flat[valid_mask], pred_flat[valid_mask])[0, 1]
                            if not np.isnan(corr_coef):
                                correlations.append(abs(corr_coef))
                    
                    if correlations:
                        validation_metrics['atmospheric_correlation'] = np.mean(correlations)
                    else:
                        validation_metrics['atmospheric_correlation'] = 0.0
                else:
                    validation_metrics['atmospheric_correlation'] = 0.0
            else:
                validation_metrics['atmospheric_correlation'] = 0.0
            
            # Validation score
            validation_metrics['validation_score'] = validation_metrics['atmospheric_correlation']
            
        except Exception as e:
            logger.warning(f"Atmospheric validation failed: {e}")
            validation_metrics['validation_score'] = 0.0
        
        return validation_metrics
    
    async def _quantify_correction_uncertainty(self, corrections):
        """Quantify uncertainty in atmospheric corrections"""
        uncertainty_metrics = {}
        
        try:
            # Spatial uncertainty
            spatial_std = np.nanstd(corrections, axis=(1, 2))
            uncertainty_metrics['spatial_uncertainty'] = np.mean(spatial_std)
            
            # Temporal uncertainty
            if corrections.shape[0] > 1:
                temporal_std = np.nanstd(corrections, axis=0)
                uncertainty_metrics['temporal_uncertainty'] = np.nanmean(temporal_std)
            
            # Bootstrap uncertainty estimation
            n_bootstrap = 20
            bootstrap_corrections = []
            
            for _ in range(n_bootstrap):
                # Resample corrections with replacement
                indices = np.random.choice(corrections.shape[0], size=corrections.shape[0], replace=True)
                bootstrap_sample = corrections[indices]
                bootstrap_mean = np.nanmean(bootstrap_sample, axis=0)
                bootstrap_corrections.append(bootstrap_mean)
            
            bootstrap_std = np.nanstd(bootstrap_corrections, axis=0)
            uncertainty_metrics['bootstrap_uncertainty'] = np.nanmean(bootstrap_std)
            
            # Overall uncertainty
            uncertainty_metrics['overall_uncertainty'] = np.mean([
                uncertainty_metrics['spatial_uncertainty'],
                uncertainty_metrics.get('temporal_uncertainty', 0),
                uncertainty_metrics['bootstrap_uncertainty']
            ])
            
        except Exception as e:
            logger.warning(f"Uncertainty quantification failed: {e}")
            uncertainty_metrics['overall_uncertainty'] = 0.0
        
        return uncertainty_metrics
    
    async def _cross_validate_corrections(self, original_phases, corrections):
        """Cross-validate atmospheric corrections"""
        cv_metrics = {}
        
        try:
            from sklearn.model_selection import KFold
            
            # Prepare data for cross-validation
            n_samples = original_phases.shape[0]
            if n_samples < 5:
                cv_metrics['cv_score'] = 0.5
                return cv_metrics
            
            kf = KFold(n_splits=min(5, n_samples), shuffle=True, random_state=42)
            cv_scores = []
            
            for train_idx, test_idx in kf.split(range(n_samples)):
                # Use training set to estimate correction model
                train_phases = original_phases[train_idx]
                train_corrections = corrections[train_idx]
                
                # Test on held-out set
                test_phases = original_phases[test_idx]
                test_corrections = corrections[test_idx]
                
                # Simple validation: check if corrections reduce variance
                original_var = np.nanvar(test_phases)
                corrected_var = np.nanvar(test_phases - test_corrections)
                
                if original_var > 0:
                    improvement = (original_var - corrected_var) / original_var
                    cv_scores.append(max(0, improvement))
            
            cv_metrics['cv_score'] = np.mean(cv_scores) if cv_scores else 0.0
            cv_metrics['cv_std'] = np.std(cv_scores) if cv_scores else 0.0
            
        except Exception as e:
            logger.warning(f"Cross-validation failed: {e}")
            cv_metrics['cv_score'] = 0.0
        
        return cv_metrics
    
    async def _analyze_correction_residuals(self, original_phases, corrections):
        """Analyze residuals after atmospheric correction"""
        residual_metrics = {}
        
        try:
            residuals = original_phases - corrections
            
            # Residual statistics
            residual_metrics['mean_residual'] = np.nanmean(residuals)
            residual_metrics['std_residual'] = np.nanstd(residuals)
            residual_metrics['max_residual'] = np.nanmax(np.abs(residuals))
            
            # Residual normality test (Shapiro-Wilk on sample)
            from scipy.stats import shapiro
            
            sample_size = min(5000, residuals.size)
            residual_sample = np.random.choice(residuals.flatten(), size=sample_size, replace=False)
            residual_sample = residual_sample[~np.isnan(residual_sample)]
            
            if len(residual_sample) > 10:
                shapiro_stat, shapiro_p = shapiro(residual_sample)
                residual_metrics['normality_p_value'] = shapiro_p
            
            # Spatial correlation in residuals (should be minimal)
            spatial_autocorr = []
            for i in range(residuals.shape[0]):
                residual_2d = residuals[i]
                if not np.all(np.isnan(residual_2d)):
                    # Compute spatial autocorrelation
                    shifted = np.roll(residual_2d, 1, axis=0)
                    valid_mask = ~(np.isnan(residual_2d) | np.isnan(shifted))
                    
                    if np.sum(valid_mask) > 100:
                        autocorr = np.corrcoef(residual_2d[valid_mask], shifted[valid_mask])[0, 1]
                        if not np.isnan(autocorr):
                            spatial_autocorr.append(abs(autocorr))
            
            residual_metrics['spatial_autocorr'] = np.mean(spatial_autocorr) if spatial_autocorr else 0.0
            
        except Exception as e:
            logger.warning(f"Residual analysis failed: {e}")
            residual_metrics = {'mean_residual': 0.0, 'std_residual': 1.0}
        
        return residual_metrics 
   
