    async def _estimate_component_period(self, component, acquisition_dates):
        """Estimate the period of a seasonal component"""
        from scipy.signal import find_peaks, periodogram
        
        try:
            # Remove trend
            detrended = signal.detrend(component)
            
            # Compute periodogram
            freqs, power = periodogram(detrended, fs=1.0)  # Assuming daily sampling
            
            # Find dominant frequency
            peak_idx = np.argmax(power[1:]) + 1  # Skip DC component
            dominant_freq = freqs[peak_idx]
            
            # Convert to period in days
            period_days = 1.0 / dominant_freq if dominant_freq > 0 else 365.25
            
            return period_days
            
        except Exception as e:
            logger.warning(f"Period estimation failed: {e}")
            return 365.25  # Default to annual
    
