    async def _ml_seasonal_extraction(self, time_series, acquisition_dates):
        """Machine learning-based seasonal extraction"""
        try:
            from sklearn.ensemble import RandomForestRegressor
            from sklearn.preprocessing import StandardScaler
            
            # Create features for ML model
            features = []
            for date in acquisition_dates:
                day_of_year = date.timetuple().tm_yday
                month = date.month
                
                # Cyclical encoding
                day_sin = np.sin(2 * np.pi * day_of_year / 365.25)
                day_cos = np.cos(2 * np.pi * day_of_year / 365.25)
                month_sin = np.sin(2 * np.pi * month / 12)
                month_cos = np.cos(2 * np.pi * month / 12)
                
                features.append([day_sin, day_cos, month_sin, month_cos])
            
            X = np.array(features)
            y = time_series.values
            
            # Train random forest to capture seasonal patterns
            rf = RandomForestRegressor(n_estimators=100, random_state=42)
            rf.fit(X, y)
            
            # Predict seasonal component
            seasonal_pred = rf.predict(X)
            
            return seasonal_pred
            
        except Exception as e:
            logger.warning(f"ML seasonal extraction failed: {e}")
            return None
    
    async def _assess_periodicity_strength(self, component, acquisition_dates):
        """Assess the strength of periodicity in a component"""
        try:
            from scipy.signal import periodogram
            
            # Compute power spectral density
            freqs, power = periodogram(component, fs=1.0)
            
            # Find peak power
            peak_power = np.max(power[1:])  # Exclude DC
            total_power = np.sum(power[1:])
            
            # Periodicity strength as ratio of peak to total power
            periodicity_strength = peak_power / total_power if total_power > 0 else 0
            
            return min(1.0, periodicity_strength * 10)  # Scale to 0-1
            
        except Exception as e:
            logger.warning(f"Periodicity assessment failed: {e}")
            return 0.5
    
    async def _assess_component_smoothness(self, component):
        """Assess smoothness of a seasonal component"""
        try:
            # Compute second derivative (curvature)
            second_deriv = np.diff(component, n=2)
            
            # Smoothness as inverse of curvature variance
            curvature_var = np.var(second_deriv)
            smoothness = 1.0 / (1.0 + curvature_var)
            
            return smoothness
            
        except Exception as e:
            logger.warning(f"Smoothness assessment failed: {e}")
            return 0.5
    
    async def _assess_physical_plausibility_seasonal(self, component):
        """Assess physical plausibility of seasonal component"""
        try:
            # Check amplitude (seasonal atmospheric effects typically < 5 cm)
            amplitude = np.max(component) - np.min(component)
            
            if amplitude > 100:  # > 10 cm
                amplitude_score = 0.2
            elif amplitude > 50:  # > 5 cm
                amplitude_score = 0.6
            elif amplitude < 1:  # < 1 mm
                amplitude_score = 0.3
            else:
                amplitude_score = 1.0
            
            # Check for reasonable seasonal pattern (should have ~1 cycle per year)
            # This is a simplified check
            zero_crossings = np.sum(np.diff(np.sign(component)) != 0)
            expected_crossings = 2  # For sinusoidal annual cycle
            
            crossing_score = 1.0 / (1.0 + abs(zero_crossings - expected_crossings))
            
            return 0.7 * amplitude_score + 0.3 * crossing_score
            
        except Exception as e:
            logger.warning(f"Physical plausibility assessment failed: {e}")
            return 0.5
    
