    async def _compute_shap_interactions(self, shap_values):
        """Compute SHAP interaction effects"""
        try:
            # Compute pairwise interactions
            n_features = shap_values.values.shape[1]
            interactions = np.zeros((n_features, n_features))
            
            for i in range(n_features):
                for j in range(i + 1, n_features):
                    # Interaction as correlation between SHAP values
                    interaction = np.corrcoef(shap_values.values[:, i], shap_values.values[:, j])[0, 1]
                    interactions[i, j] = abs(interaction) if not np.isnan(interaction) else 0
                    interactions[j, i] = interactions[i, j]
            
            return interactions.tolist()
            
        except Exception as e:
            logger.warning(f"SHAP interaction computation failed: {e}")
            return []
    
    async def _compute_stability_importance(self, model, X_train, y_train, feature_names):
        """Compute feature importance stability across bootstrap samples"""
        try:
            n_bootstrap = 20
            importance_samples = []
            
            for _ in range(n_bootstrap):
                # Bootstrap sample
                indices = np.random.choice(len(X_train), size=len(X_train), replace=True)
                X_boot = X_train[indices]
                y_boot = y_train[indices]
                
                # Train model
                model_copy = type(model)(**model.get_params())
                model_copy.fit(X_boot, y_boot)
                
                # Get importance
                if hasattr(model_copy, 'feature_importances_'):
                    importance_samples.append(model_copy.feature_importances_)
                elif hasattr(model_copy, 'coef_'):
                    importance_samples.append(np.abs(model_copy.coef_))
            
            if importance_samples:
                importance_matrix = np.array(importance_samples)
                
                return {
                    'mean_importance': np.mean(importance_matrix, axis=0).tolist(),
                    'std_importance': np.std(importance_matrix, axis=0).tolist(),
                    'stability_score': 1.0 / (1.0 + np.mean(np.std(importance_matrix, axis=0)))
                }
            else:
                return {'stability_score': 0.0}
                
        except Exception as e:
            logger.warning(f"Stability importance computation failed: {e}")
            return {'stability_score': 0.0}
    
    async def _score_physical_relevance(self, feature_names):
        """Score physical relevance of features for atmospheric correction"""
        try:
            # Define physical relevance scores for common atmospheric features
            relevance_map = {
                'pressure': 0.9,
                'temperature': 0.8,
                'humidity': 0.9,
                'precipitable_water': 0.95,
                'wind_speed': 0.6,
                'elevation': 0.7,
                'latitude': 0.5,
                'longitude': 0.3,
                'time_of_day': 0.4,
                'season': 0.8,
                'topography': 0.6
            }
            
            scores = []
            for name in feature_names:
                # Match feature name to relevance categories
                score = 0.5  # Default relevance
                
                for key, relevance in relevance_map.items():
                    if key.lower() in name.lower():
                        score = relevance
                        break
                
                scores.append(score)
            
            return scores
            
        except Exception as e:
            logger.warning(f"Physical relevance scoring failed: {e}")
            return [0.5] * len(feature_names)
    
    async def _combine_importance_scores(self, importance_dict, feature_names):
        """Combine multiple importance scores into unified ranking"""
        try:
            n_features = len(feature_names)
            combined_scores = np.zeros(n_features)
            
            # Weight different importance methods
            weights = {
                'tree_importance': 0.2,
                'permutation_importance': 0.25,
                'shap_values': 0.3,
                'mutual_information': 0.15,
                'stability_importance': 0.1
            }
            
            total_weight = 0
            
            for method, weight in weights.items():
                if method in importance_dict:
                    if method == 'permutation_importance':
                        scores = importance_dict[method]['importances_mean']
                    elif method == 'shap_values':
                        scores = importance_dict[method]['mean_abs_shap']
                    elif method == 'stability_importance':
                        scores = importance_dict[method]['mean_importance']
                    else:
                        scores = importance_dict[method]
                    
                    if len(scores) == n_features:
                        # Normalize scores to 0-1
                        scores = np.array(scores)
                        if np.max(scores) > np.min(scores):
                            scores = (scores - np.min(scores)) / (np.max(scores) - np.min(scores))
                        
                        combined_scores += weight * scores
                        total_weight += weight
            
            # Normalize by total weight
            if total_weight > 0:
                combined_scores /= total_weight
            
            return {
                'unified_scores': combined_scores.tolist(),
                'feature_ranking': np.argsort(combined_scores)[::-1].tolist(),
                'top_features': [feature_names[i] for i in np.argsort(combined_scores)[::-1][:10]]
            }
            
        except Exception as e:
            logger.warning(f"Importance combination failed: {e}")
            return {'unified_scores': [0.5] * len(feature_names)}
    
    async def _define_correlation_regions(self, phases):
        """Define regions for regional correlation analysis"""
        try:
            height, width = phases.shape[1], phases.shape[2]
            
            regions = {}
            
            # Quadrant regions
            mid_h, mid_w = height // 2, width // 2
            
            regions['northwest'] = np.zeros((height, width), dtype=bool)
            regions['northwest'][:mid_h, :mid_w] = True
            
            regions['northeast'] = np.zeros((height, width), dtype=bool)
            regions['northeast'][:mid_h, mid_w:] = True
            
            regions['southwest'] = np.zeros((height, width), dtype=bool)
            regions['southwest'][mid_h:, :mid_w] = True
            
            regions['southeast'] = np.zeros((height, width), dtype=bool)
            regions['southeast'][mid_h:, mid_w:] = True
            
            # Central region
            quarter_h, quarter_w = height // 4, width // 4
            regions['center'] = np.zeros((height, width), dtype=bool)
            regions['center'][quarter_h:3*quarter_h, quarter_w:3*quarter_w] = True
            
            return regions
            
        except Exception as e:
            logger.warning(f"Region definition failed: {e}")
            return {'full': np.ones((phases.shape[1], phases.shape[2]), dtype=bool)}
    
    async def _compute_mutual_information_matrix(self, phases):
        """Compute mutual information matrix for nonlinear dependencies"""
        try:
            from sklearn.feature_selection import mutual_info_regression
            from sklearn.preprocessing import KBinsDiscretizer
            
            n_ifg = phases.shape[0]
            mi_matrix = np.zeros((n_ifg, n_ifg))
            
            # Discretize data for mutual information
            discretizer = KBinsDiscretizer(n_bins=20, encode='ordinal', strategy='uniform')
            
            for i in range(n_ifg):
                phase_i = phases[i].flatten()
                valid_i = ~np.isnan(phase_i)
                
                if np.sum(valid_i) < 100:
                    continue
                
                phase_i_clean = phase_i[valid_i].reshape(-1, 1)
                phase_i_discrete = discretizer.fit_transform(phase_i_clean).flatten()
                
                for j in range(i, n_ifg):
                    if i == j:
                        mi_matrix[i, j] = 1.0
                        continue
                    
                    phase_j = phases[j].flatten()
                    valid_j = ~np.isnan(phase_j)
                    
                    # Use intersection of valid pixels
                    valid_both = valid_i & valid_j
                    
                    if np.sum(valid_both) < 100:
                        continue
                    
                    phase_j_clean = phase_j[valid_both].reshape(-1, 1)
                    phase_j_discrete = discretizer.fit_transform(phase_j_clean).flatten()
                    phase_i_both = phase_i_discrete[:len(phase_j_discrete)]
                    
                    # Compute mutual information
                    mi_score = mutual_info_score(phase_i_both, phase_j_discrete)
                    
                    mi_matrix[i, j] = mi_score
                    mi_matrix[j, i] = mi_score
            
            return mi_matrix
            
        except Exception as e:
            logger.warning(f"Mutual information computation failed: {e}")
            return np.eye(phases.shape[0])
    
    async def _analyze_spatial_correlation_patterns(self, phases, correlation_matrix):
        """Analyze spatial patterns in temporal correlations"""
        try:
            patterns = {}
            
            # Correlation distance decay
            distances = []
            correlations = []
            
            n_ifg = phases.shape[0]
            for i in range(n_ifg):
                for j in range(i + 1, n_ifg):
                    time_distance = abs(j - i)  # Temporal distance
                    correlation = correlation_matrix[i, j]
                    
                    distances.append(time_distance)
                    correlations.append(correlation)
            
            if distances and correlations:
                # Fit exponential decay model
                from scipy.optimize import curve_fit
                
                def exp_decay(x, a, b):
                    return a * np.exp(-b * x)
                
                try:
                    popt, _ = curve_fit(exp_decay, distances, correlations, 
                                      bounds=([0, 0], [2, 1]), maxfev=1000)
                    patterns['decay_amplitude'] = popt[0]
                    patterns['decay_rate'] = popt[1]
                    patterns['correlation_length'] = 1.0 / popt[1] if popt[1] > 0 else np.inf
                except:
                    patterns['decay_rate'] = 0.1
                    patterns['correlation_length'] = 10.0
            
            # Correlation clustering
            from sklearn.cluster import KMeans
            
            if correlation_matrix.shape[0] > 3:
                kmeans = KMeans(n_clusters=min(3, correlation_matrix.shape[0]), random_state=42)
                clusters = kmeans.fit_predict(correlation_matrix)
                patterns['temporal_clusters'] = clusters.tolist()
            
            return patterns
            
        except Exception as e:
            logger.warning(f"Spatial correlation pattern analysis failed: {e}")
            return {}
    
    async def _assess_correlation_stability(self, phases, correlation_matrices):
        """Assess stability of correlation patterns"""
        try:
            stability_metrics = {}
            
            # Compute stability across different regions
            if len(correlation_matrices) > 1:
                # Compare correlation matrices from different regions
                matrix_list = list(correlation_matrices.values())
                
                # Compute pairwise matrix correlations
                matrix_correlations = []
                for i in range(len(matrix_list)):
                    for j in range(i + 1, len(matrix_list)):
                        mat_i = matrix_list[i].flatten()
                        mat_j = matrix_list[j].flatten()
                        
                        valid_mask = ~(np.isnan(mat_i) | np.isnan(mat_j))
                        if np.sum(valid_mask) > 10:
                            corr = np.corrcoef(mat_i[valid_mask], mat_j[valid_mask])[0, 1]
                            if not np.isnan(corr):
                                matrix_correlations.append(abs(corr))
                
                stability_metrics['inter_region_stability'] = np.mean(matrix_correlations) if matrix_correlations else 0.0
            
            # Temporal stability (if enough data)
            if phases.shape[0] > 10:
                # Split into temporal windows and compare correlations
                window_size = phases.shape[0] // 3
                
                window_correlations = []
                for start in range(0, phases.shape[0] - window_size, window_size // 2):
                    end = start + window_size
                    window_phases = phases[start:end]
                    
                    # Compute correlation matrix for this window
                    window_corr = np.corrcoef([phase.flatten() for phase in window_phases])
                    window_correlations.append(window_corr)
                
                if len(window_correlations) > 1:
                    # Compare correlation matrices across windows
                    window_stability = []
                    for i in range(len(window_correlations) - 1):
                        corr_i = window_correlations[i].flatten()
                        corr_j = window_correlations[i + 1].flatten()
                        
                        valid_mask = ~(np.isnan(corr_i) | np.isnan(corr_j))
                        if np.sum(valid_mask) > 10:
                            stability = np.corrcoef(corr_i[valid_mask], corr_j[valid_mask])[0, 1]
                            if not np.isnan(stability):
                                window_stability.append(abs(stability))
                    
                    stability_metrics['temporal_stability'] = np.mean(window_stability) if window_stability else 0.0
            
            return stability_metrics
            
        except Exception as e:
            logger.warning(f"Correlation stability assessment failed: {e}")
            return {}
    
    async def _interpret_correlation_physics(self, correlation_results, phases):
        """Provide physical interpretation of correlation patterns"""
        try:
            interpretation = {}
            
            # Interpret correlation decay rate
            if 'correlation_patterns' in correlation_results and 'spatial_patterns' in correlation_results['correlation_patterns']:
                decay_rate = correlation_results['correlation_patterns']['spatial_patterns'].get('decay_rate', 0.1)
                
                if decay_rate > 0.5:
                    interpretation['temporal_coherence'] = 'short'
                    interpretation['physical_meaning'] = 'Rapid decorrelation suggests strong atmospheric turbulence or measurement noise'
                elif decay_rate > 0.1:
                    interpretation['temporal_coherence'] = 'moderate'
                    interpretation['physical_meaning'] = 'Moderate decorrelation typical of atmospheric effects'
                else:
                    interpretation['temporal_coherence'] = 'long'
                    interpretation['physical_meaning'] = 'Slow decorrelation suggests persistent atmospheric patterns or systematic effects'
            
            # Interpret network properties
            if 'temporal_networks' in correlation_results:
                for threshold, network_metrics in correlation_results['temporal_networks'].items():
                    clustering = network_metrics.get('clustering_coefficient', 0)
                    
                    if clustering > 0.7:
                        interpretation[f'network_{threshold}'] = 'Highly clustered - suggests coherent atmospheric patterns'
                    elif clustering > 0.3:
                        interpretation[f'network_{threshold}'] = 'Moderately clustered - mixed atmospheric effects'
                    else:
                        interpretation[f'network_{threshold}'] = 'Low clustering - random or uncorrelated effects'
            
            return interpretation
            
        except Exception as e:
            logger.warning(f"Correlation physics interpretation failed: {e}")
            return {}
    
