    async def _compute_correlation_decay_rate(self, lag_correlations):
        """Compute correlation decay rate from lag analysis"""
        try:
            if not lag_correlations:
                return 0.1
            
            lags = list(lag_correlations.keys())
            correlations = [lag_correlations[lag]['mean'] for lag in lags]
            
            # Fit exponential decay
            from scipy.optimize import curve_fit
            
            def exp_decay(x, a, b):
                return a * np.exp(-b * x)
            
            try:
                popt, _ = curve_fit(exp_decay, lags, correlations, bounds=([0, 0], [2, 1]))
                return popt[1]  # Decay rate
            except:
                # Fallback: compute simple decay rate
                if len(correlations) > 1:
                    return -np.log(correlations[-1] / correlations[0]) / lags[-1]
                else:
                    return 0.1
                    
        except Exception as e:
            logger.warning(f"Correlation decay rate computation failed: {e}")
            return 0.1
    
    async def _find_dominant_correlation_scale(self, correlation_results):
        """Find dominant correlation scale from analysis results"""
        try:
            # Look for the scale with highest correlation strength
            scales = []
            
            if 'correlation_patterns' in correlation_results:
                patterns = correlation_results['correlation_patterns']
                
                # Check sliding window results
                for key, values in patterns.items():
                    if 'sliding_window' in key and values:
                        window_size = int(key.split('_')[-1])
                        mean_corr = np.mean([v['mean_correlation'] for v in values])
                        scales.append((window_size, mean_corr))
            
            if scales:
                # Find scale with maximum correlation
                best_scale = max(scales, key=lambda x: x[1])
                return best_scale[0]
            else:
                return 5  # Default scale
                
        except Exception as e:
            logger.warning(f"Dominant scale finding failed: {e}")
            return 5
    
    async def _compute_correlation_anisotropy(self, spatial_patterns):
        """Compute correlation anisotropy from spatial patterns"""
        try:
            # Simple anisotropy measure based on directional correlations
            # This would be more sophisticated in practice
            return spatial_patterns.get('anisotropy_ratio', 1.0) if spatial_patterns else 1.0
            
        except Exception as e:
            logger.warning(f"Correlation anisotropy computation failed: {e}")
            return 1.0
    
    async def _estimate_coherence_length(self, correlation_results):
        """Estimate temporal coherence length"""
        try:
            # Use correlation decay rate to estimate coherence length
            if 'summary' in correlation_results:
                decay_rate = correlation_results['summary'].get('correlation_decay_rate', 0.1)
                coherence_length = 1.0 / decay_rate if decay_rate > 0 else 10.0
                return min(coherence_length, 100.0)  # Cap at reasonable value
            else:
                return 10.0  # Default coherence length
                
        except Exception as e:
            logger.warning(f"Coherence length estimation failed: {e}")
            return 10.0

