    async def _process_copernicus_atmospheric_data(self, source_data, connector_factory):
        """Process Copernicus Sentinel-5P atmospheric composition data"""
        try:
            from backend.core.real_data_connectors.copernicus_connector import CopernicusConnector
            from backend.core.data_transformation.unit_converter import UnitConverter
            
            unit_converter = UnitConverter()
            processed_data = {
                'timestamps': [],
                'pressure': [],
                'temperature': [],
                'humidity': [],
                'wind_speed': [],
                'precipitable_water': [],
                'atmospheric_composition': [],
                'quality_metrics': []
            }
            
            for obs in source_data:
                if hasattr(obs, 'value') and isinstance(obs.value, dict):
                    # Extract atmospheric parameters from Sentinel-5P data
                    if obs.observation_type == 'atmospheric_so2':
                        # Process SO2 column density for volcanic monitoring
                        so2_column = obs.value.get('so2_column_density_mol_m2')
                        if so2_column is not None:
                            processed_data['atmospheric_composition'].append({
                                'so2_column_density': so2_column,
                                'measurement_type': 'tropomi_so2'
                            })
                    
                    # Extract meteorological parameters if available
                    if 'surface_pressure_pa' in obs.value:
                        pressure_hpa = unit_converter.convert_pressure(
                            obs.value['surface_pressure_pa'], 'Pa', 'hPa'
                        )
                        processed_data['pressure'].append(pressure_hpa)
                    
                    if 'surface_temperature_k' in obs.value:
                        temp_celsius = unit_converter.convert_temperature(
                            obs.value['surface_temperature_k'], 'K', 'C'
                        )
                        processed_data['temperature'].append(temp_celsius)
                    
                    if 'precipitable_water_kg_m2' in obs.value:
                        processed_data['precipitable_water'].append(
                            obs.value['precipitable_water_kg_m2']
                        )
                    
                    processed_data['timestamps'].append(obs.timestamp)
                    
                    # Calculate quality metrics based on Copernicus quality flags
                    quality_score = self._calculate_copernicus_quality_score(obs)
                    processed_data['quality_metrics'].append(quality_score)
            
            return processed_data
            
        except Exception as e:
            logger.error(f"Copernicus atmospheric data processing failed: {e}")
            return None
    
    async def _process_nasa_atmospheric_data(self, source_data, connector_factory):
        """Process NASA MODIS/VIIRS atmospheric products"""
        try:
            from backend.core.real_data_connectors.nasa_connector import NASAEarthDataConnector
            from backend.core.data_transformation.interpolation_engine import InterpolationEngine
            
            interpolation_engine = InterpolationEngine()
            processed_data = {
                'timestamps': [],
                'pressure': [],
                'temperature': [],
                'humidity': [],
                'wind_speed': [],
                'precipitable_water': [],
                'aerosol_optical_depth': [],
                'cloud_properties': []
            }
            
            for obs in source_data:
                if hasattr(obs, 'value') and isinstance(obs.value, dict):
                    # Process MODIS atmospheric products
                    if obs.observation_type == 'atmospheric_profile':
                        # Extract atmospheric profile data
                        if 'pressure_levels_hpa' in obs.value:
                            pressure_profile = obs.value['pressure_levels_hpa']
                            temp_profile = obs.value.get('temperature_profile_k', [])
                            humidity_profile = obs.value.get('humidity_profile_percent', [])
                            
                            # Interpolate to surface level
                            if pressure_profile and temp_profile:
                                surface_temp = interpolation_engine.interpolate_to_surface(
                                    pressure_profile, temp_profile, method='linear'
                                )
                                processed_data['temperature'].append(surface_temp - 273.15)  # K to C
                            
                            if pressure_profile and humidity_profile:
                                surface_humidity = interpolation_engine.interpolate_to_surface(
                                    pressure_profile, humidity_profile, method='linear'
                                )
                                processed_data['humidity'].append(surface_humidity)
                            
                            # Use lowest pressure level as surface pressure
                            if pressure_profile:
                                processed_data['pressure'].append(max(pressure_profile))
                    
                    # Process precipitable water
                    if 'precipitable_water_cm' in obs.value:
                        # Convert cm to kg/m²
                        pw_kg_m2 = obs.value['precipitable_water_cm'] * 10.0
                        processed_data['precipitable_water'].append(pw_kg_m2)
                    
                    # Process aerosol optical depth
                    if 'aerosol_optical_depth_550nm' in obs.value:
                        processed_data['aerosol_optical_depth'].append(
                            obs.value['aerosol_optical_depth_550nm']
                        )
                    
                    # Process cloud properties
                    if 'cloud_fraction' in obs.value:
                        cloud_props = {
                            'cloud_fraction': obs.value['cloud_fraction'],
                            'cloud_top_pressure_hpa': obs.value.get('cloud_top_pressure_hpa'),
                            'cloud_top_temperature_k': obs.value.get('cloud_top_temperature_k')
                        }
                        processed_data['cloud_properties'].append(cloud_props)
                    
                    processed_data['timestamps'].append(obs.timestamp)
            
            return processed_data
            
        except Exception as e:
            logger.error(f"NASA atmospheric data processing failed: {e}")
            return None
    
