    def _apply_thermodynamic_consistency(self, data):
        """Apply thermodynamic consistency checks"""
        try:
            # Check for thermodynamic consistency between temperature and humidity
            if 'temperature' in data and 'humidity' in data:
                temp = np.array(data['temperature'])
                humidity = np.array(data['humidity'])
                
                # Calculate dew point and check for consistency
                for i in range(len(temp)):
                    if not np.isnan(temp[i]) and not np.isnan(humidity[i]):
                        dew_point = self._calculate_dew_point(temp[i], humidity[i])
                        
                        # Dew point should not exceed temperature
                        if dew_point > temp[i] + 0.5:  # Allow small tolerance
                            # Flag as potentially inconsistent
                            data.setdefault('quality_flags', []).append(f'thermodynamic_inconsistency_at_{i}')
            
            data['validation_flags'] = data.get('validation_flags', [])
            data['validation_flags'].append('thermodynamic_consistency_checked')
            
            return data
            
        except Exception as e:
            logger.warning(f"Thermodynamic consistency check failed: {e}")
            return data
    
    def _calculate_dew_point(self, temperature_c, relative_humidity):
        """Calculate dew point temperature"""
        try:
            # Magnus formula approximation
            a = 17.27
            b = 237.7
            
            alpha = ((a * temperature_c) / (b + temperature_c)) + np.log(relative_humidity / 100.0)
            dew_point = (b * alpha) / (a - alpha)
            
            return dew_point
            
        except Exception as e:
            logger.warning(f"Dew point calculation failed: {e}")
            return np.nan
    
    def _calculate_atmospheric_stability(self, data):
        """Calculate atmospheric stability indices"""
        try:
            # Add atmospheric stability metrics
            data['stability_indices'] = {}
            
            if 'temperature' in data and 'pressure' in data:
                temp = np.array(data['temperature'])
                pressure = np.array(data['pressure'])
                
                # Calculate potential temperature (simplified)
                potential_temp = temp + 273.15  # Convert to Kelvin
                # θ = T * (1000/P)^(R/cp) - simplified version
                potential_temp = potential_temp * ((1000.0 / pressure) ** 0.286)
                
                data['stability_indices']['potential_temperature'] = potential_temp.tolist()
            
            return data
            
        except Exception as e:
            logger.warning(f"Atmospheric stability calculation failed: {e}")
            return data
    
    def _apply_temporal_consistency(self, data):
        """Apply temporal consistency checks"""
        try:
            # Check for unrealistic temporal changes
            for param in ['pressure', 'temperature', 'humidity', 'wind_speed']:
                if param in data:
                    values = np.array(data[param])
                    
                    # Calculate temporal gradients
                    gradients = np.diff(values)
                    
                    # Define reasonable change limits per hour
                    limits = {
                        'pressure': 10.0,  # hPa/hour
                        'temperature': 5.0,  # °C/hour
                        'humidity': 20.0,  # %/hour
                        'wind_speed': 15.0  # m/s/hour
                    }
                    
                    limit = limits.get(param, 10.0)
                    
                    # Flag excessive changes
                    excessive_changes = np.abs(gradients) > limit
                    if np.any(excessive_changes):
                        change_indices = np.where(excessive_changes)[0]
                        for idx in change_indices:
                            data.setdefault('quality_flags', []).append(
                                f'excessive_temporal_change_{param}_at_{idx}'
                            )
            
            data['validation_flags'] = data.get('validation_flags', [])
            data['validation_flags'].append('temporal_consistency_checked')
            
            return data
            
        except Exception as e:
            logger.warning(f"Temporal consistency check failed: {e}")
            return data
    
