    def _calculate_autocorrelation(self, values):
        """Calculate autocorrelation function"""
        try:
            from scipy.signal import correlate
            
            # Normalize values
            values_norm = (values - np.mean(values)) / np.std(values)
            
            # Calculate full autocorrelation
            autocorr = correlate(values_norm, values_norm, mode='full')
            autocorr = autocorr[autocorr.size // 2:]
            
            # Normalize by zero-lag value
            autocorr = autocorr / autocorr[0]
            
            return autocorr
            
        except Exception as e:
            logger.warning(f"Autocorrelation calculation failed: {e}")
            return np.array([1.0])
    
    def _find_decorrelation_time(self, autocorr):
        """Find decorrelation time (e-folding time)"""
        try:
            # Find where autocorrelation drops to 1/e
            e_fold_threshold = 1.0 / np.e
            
            # Find first crossing of threshold
            crossing_indices = np.where(autocorr < e_fold_threshold)[0]
            
            if len(crossing_indices) > 0:
                return float(crossing_indices[0])
            else:
                # If no crossing found, use half-length as estimate
                return float(len(autocorr) // 2)
                
        except Exception as e:
            logger.warning(f"Decorrelation time calculation failed: {e}")
            return 10.0  # Default value
    
    def _calculate_persistence_strength(self, values):
        """Calculate persistence strength using Hurst exponent"""
        try:
            # Calculate Hurst exponent using R/S analysis
            def hurst_rs(ts):
                """Calculate Hurst exponent using rescaled range analysis"""
                n = len(ts)
                if n < 20:
                    return 0.5
                
                # Calculate mean
                mean_ts = np.mean(ts)
                
                # Calculate cumulative deviations
                y = np.cumsum(ts - mean_ts)
                
                # Calculate range
                R = np.max(y) - np.min(y)
                
                # Calculate standard deviation
                S = np.std(ts)
                
                if S == 0:
                    return 0.5
                
                # R/S ratio
                rs = R / S
                
                # Hurst exponent approximation
                if rs > 0:
                    return np.log(rs) / np.log(n)
                else:
                    return 0.5
            
            hurst = hurst_rs(values)
            
            # Convert Hurst exponent to persistence strength
            # H > 0.5: persistent, H < 0.5: anti-persistent, H = 0.5: random
            if hurst > 0.5:
                persistence = 2 * (hurst - 0.5)  # Scale to 0-1
            else:
                persistence = 0.0
            
            return float(np.clip(persistence, 0.0, 1.0))
            
        except Exception as e:
            logger.warning(f"Persistence strength calculation failed: {e}")
            return 0.5
    
    def _perform_spectral_analysis(self, values, timestamps):
        """Perform spectral analysis to identify periodic components"""
        try:
            from scipy import signal
            
            # Calculate sampling frequency (assuming regular intervals)
            if len(timestamps) < 2:
                return {'frequencies': [], 'power_spectrum': [], 'dominant_periods': []}
            
            dt_seconds = np.mean(np.diff([(ts - timestamps[0]).total_seconds() for ts in timestamps]))
            fs = 1.0 / dt_seconds if dt_seconds > 0 else 1.0
            
            # Calculate power spectral density
            frequencies, psd = signal.periodogram(values, fs=fs)
            
            # Find dominant frequencies (peaks in PSD)
            peaks, _ = signal.find_peaks(psd, height=np.max(psd) * 0.1)
            
            dominant_frequencies = frequencies[peaks]
            dominant_periods = [1.0 / f if f > 0 else np.inf for f in dominant_frequencies]
            
            return {
                'frequencies': frequencies.tolist(),
                'power_spectrum': psd.tolist(),
                'dominant_periods': dominant_periods
            }
            
        except Exception as e:
            logger.warning(f"Spectral analysis failed: {e}")
            return {'frequencies': [], 'power_spectrum': [], 'dominant_periods': []}
    
    def _identify_dominant_timescales(self, spectral_analysis):
        """Identify dominant timescales from spectral analysis"""
        try:
            dominant_periods = spectral_analysis.get('dominant_periods', [])
            
            if not dominant_periods:
                return {'diurnal': False, 'synoptic': False, 'seasonal': False}
            
            # Convert periods to hours
            periods_hours = [p / 3600.0 for p in dominant_periods if np.isfinite(p)]
            
            # Identify characteristic timescales
            timescales = {
                'diurnal': any(20 <= p <= 28 for p in periods_hours),  # ~24 hours
                'synoptic': any(3*24 <= p <= 10*24 for p in periods_hours),  # 3-10 days
                'seasonal': any(80*24 <= p <= 120*24 for p in periods_hours),  # ~3-4 months
                'dominant_periods_hours': periods_hours[:5]  # Top 5 periods
            }
            
            return timescales
            
        except Exception as e:
            logger.warning(f"Dominant timescale identification failed: {e}")
            return {'diurnal': False, 'synoptic': False, 'seasonal': False}
    
    def _calculate_memory_confidence(self, values, total_length):
        """Calculate confidence in memory analysis"""
        try:
            # Base confidence on data length and quality
            length_factor = min(1.0, len(values) / 1000.0)  # Prefer 1000+ points
            
            # Quality factor based on data completeness
            completeness = len(values) / total_length if total_length > 0 else 0
            
            # Variability factor (too little or too much variability reduces confidence)
            if len(values) > 1:
                cv = np.std(values) / np.abs(np.mean(values)) if np.mean(values) != 0 else 0
                variability_factor = np.exp(-((cv - 0.2) ** 2) / 0.1)  # Optimal CV around 0.2
            else:
                variability_factor = 0.1
            
            confidence = length_factor * completeness * variability_factor
            
            return float(np.clip(confidence, 0.0, 1.0))
            
        except Exception as e:
            logger.warning(f"Memory confidence calculation failed: {e}")
            return 0.3
    
    def _get_parameter_weights(self, param_names):
        """Get weights for different atmospheric parameters"""
        weight_map = {
            'pressure': 0.3,
            'temperature': 0.25,
            'humidity': 0.2,
            'wind_speed': 0.15,
            'precipitable_water': 0.1
        }
        
        weights = [weight_map.get(param, 0.1) for param in param_names]
        total_weight = sum(weights)
        
        return [w / total_weight for w in weights] if total_weight > 0 else [1.0 / len(param_names)] * len(param_names)
    
    def _identify_memory_patterns(self, persistence_metrics):
        """Identify patterns in atmospheric memory using clustering"""
        try:
            from sklearn.cluster import KMeans
            
            if not persistence_metrics:
                return {'pattern_type': 'unknown', 'characteristics': {}}
            
            # Extract features for clustering
            features = []
            param_names = []
            
            for param, metrics in persistence_metrics.items():
                features.append([
                    metrics['decorrelation_time'],
                    metrics['persistence_strength']
                ])
                param_names.append(param)
            
            if len(features) < 2:
                return {'pattern_type': 'insufficient_data', 'characteristics': {}}
            
            features = np.array(features)
            
            # Perform clustering (2 clusters: high vs low memory)
            kmeans = KMeans(n_clusters=min(2, len(features)), random_state=42)
            cluster_labels = kmeans.fit_predict(features)
            
            # Analyze clusters
            cluster_centers = kmeans.cluster_centers_
            
            # Identify pattern type based on cluster characteristics
            if len(cluster_centers) >= 2:
                high_memory_cluster = np.argmax(cluster_centers[:, 1])  # Higher persistence
                low_memory_cluster = 1 - high_memory_cluster
                
                high_memory_params = [param_names[i] for i, label in enumerate(cluster_labels) 
                                    if label == high_memory_cluster]
                low_memory_params = [param_names[i] for i, label in enumerate(cluster_labels) 
                                   if label == low_memory_cluster]
                
                pattern_type = 'mixed_memory'
                if len(high_memory_params) > len(low_memory_params):
                    pattern_type = 'high_memory_dominant'
                elif len(low_memory_params) > len(high_memory_params):
                    pattern_type = 'low_memory_dominant'
            else:
                pattern_type = 'uniform_memory'
                high_memory_params = param_names
                low_memory_params = []
            
            return {
                'pattern_type': pattern_type,
                'characteristics': {
                    'high_memory_parameters': high_memory_params,
                    'low_memory_parameters': low_memory_params,
                    'cluster_centers': cluster_centers.tolist()
                }
            }
            
        except Exception as e:
            logger.warning(f"Memory pattern identification failed: {e}")
            return {'pattern_type': 'analysis_failed', 'characteristics': {}}
    
