    async def _assess_atmospheric_data_quality(self, atmospheric_data):
        """Assess quality of atmospheric data"""
        try:
            quality_metrics = {}
            
            if not atmospheric_data or not atmospheric_data.get('timestamps'):
                return {'overall_score': 0.0, 'completeness': 0.0}
            
            # Completeness assessment
            total_expected = len(atmospheric_data['timestamps'])
            variables = ['pressure', 'temperature', 'humidity', 'wind_speed', 'precipitable_water']
            
            completeness_scores = []
            for var in variables:
                if var in atmospheric_data:
                    valid_count = np.sum(~np.isnan(atmospheric_data[var]))
                    completeness = valid_count / total_expected if total_expected > 0 else 0
                    completeness_scores.append(completeness)
            
            overall_completeness = np.mean(completeness_scores) if completeness_scores else 0
            quality_metrics['completeness'] = overall_completeness
            
            # Temporal consistency
            if len(atmospheric_data['timestamps']) > 1:
                time_diffs = np.diff([t.timestamp() for t in atmospheric_data['timestamps']])
                expected_interval = np.median(time_diffs)
                
                # Check for regular intervals
                interval_consistency = np.sum(np.abs(time_diffs - expected_interval) < expected_interval * 0.1) / len(time_diffs)
                quality_metrics['temporal_consistency'] = interval_consistency
            else:
                quality_metrics['temporal_consistency'] = 0.0
            
            # Data range plausibility
            plausibility_scores = []
            
            # Pressure: typical range 950-1050 hPa
            if 'pressure' in atmospheric_data:
                pressure_data = atmospheric_data['pressure'][~np.isnan(atmospheric_data['pressure'])]
                if len(pressure_data) > 0:
                    in_range = np.sum((pressure_data >= 900) & (pressure_data <= 1100)) / len(pressure_data)
                    plausibility_scores.append(in_range)
            
            # Temperature: typical range -50 to +50°C
            if 'temperature' in atmospheric_data:
                temp_data = atmospheric_data['temperature'][~np.isnan(atmospheric_data['temperature'])]
                if len(temp_data) > 0:
                    in_range = np.sum((temp_data >= -60) & (temp_data <= 60)) / len(temp_data)
                    plausibility_scores.append(in_range)
            
            quality_metrics['plausibility'] = np.mean(plausibility_scores) if plausibility_scores else 0.5
            
            # Overall quality score
            quality_metrics['overall_score'] = np.mean([
                quality_metrics['completeness'],
                quality_metrics['temporal_consistency'],
                quality_metrics['plausibility']
            ])
            
            return quality_metrics
            
        except Exception as e:
            logger.warning(f"Atmospheric data quality assessment failed: {e}")
            return {'overall_score': 0.5}
    
