    def _generate_synthetic_topography(self, spatial_shape):
        """Generate synthetic topography for testing purposes"""
        height, width = spatial_shape
        
        # Create realistic volcanic topography
        x = np.linspace(-10, 10, width)
        y = np.linspace(-10, 10, height)
        X, Y = np.meshgrid(x, y)
        
        # Volcanic cone with some noise
        R = np.sqrt(X**2 + Y**2)
        elevation = 2000 * np.exp(-R**2 / 25) + 100 * np.random.randn(height, width)
        
        return {
            'elevation': elevation,
            'slope': np.gradient(elevation),
            'aspect': np.arctan2(*np.gradient(elevation))
        }
    
