    async def _fallback_los_conversion(self, insar_data: Dict[str, Any]) -> Dict[str, Any]:
        """Fallback LOS conversion method"""
        try:
            los_displacements = np.array(insar_data.get('los_displacement', []))
            incidence_angles = np.array(insar_data.get('incidence_angle', [35.0]))
            
            if len(los_displacements) == 0:
                return {'east': [], 'north': [], 'up': []}
            
            # Simple vertical assumption
            inc_rad = np.radians(np.mean(incidence_angles))
            vertical_displacement = los_displacements / np.cos(inc_rad)
            
            return {
                'east': np.zeros_like(vertical_displacement),
                'north': np.zeros_like(vertical_displacement),
                'up': vertical_displacement,
                'method': 'simple_vertical_fallback'
            }
            
        except Exception as e:
            logger.error(f"Error in fallback LOS conversion: {e}")
            return {'east': [], 'north': [], 'up': [], 'error': str(e)}
    
    async def _fallback_interpolation(
        self, 
        insar_3d: Dict[str, Any], 
        gps_coords: np.ndarray
    ) -> Dict[str, Any]:
        """Fallback interpolation method"""
        try:
            from scipy.interpolate import griddata
            
            # Extract data
            insar_east = np.array(insar_3d.get('east', []))
            insar_north = np.array(insar_3d.get('north', []))
            insar_up = np.array(insar_3d.get('up', []))
            
            if len(insar_east) == 0:
                return {
                    'interpolated_east': np.zeros(len(gps_coords)),
                    'interpolated_north': np.zeros(len(gps_coords)),
                    'interpolated_up': np.zeros(len(gps_coords)),
                    'method': 'zero_fallback'
                }
            
            # Create simple grid
            n_points = len(insar_east)
            grid_size = int(np.sqrt(n_points))
            
            if grid_size > 1:
                x_coords = np.linspace(gps_coords[:, 0].min(), gps_coords[:, 0].max(), grid_size)
                y_coords = np.linspace(gps_coords[:, 1].min(), gps_coords[:, 1].max(), grid_size)
                
                xx, yy = np.meshgrid(x_coords, y_coords)
                insar_coords = np.column_stack([xx.ravel()[:n_points], yy.ravel()[:n_points]])
                
                gps_xy = gps_coords[:, :2]
                
                interpolated_east = griddata(insar_coords, insar_east, gps_xy, method='linear', fill_value=0)
                interpolated_north = griddata(insar_coords, insar_north, gps_xy, method='linear', fill_value=0)
                interpolated_up = griddata(insar_coords, insar_up, gps_xy, method='linear', fill_value=0)
                
                return {
                    'interpolated_east': interpolated_east,
                    'interpolated_north': interpolated_north,
                    'interpolated_up': interpolated_up,
                    'interpolation_method': 'linear_fallback',
                    'insar_points_used': n_points
                }
            else:
                # Use mean values
                return {
                    'interpolated_east': np.full(len(gps_coords), np.mean(insar_east)),
                    'interpolated_north': np.full(len(gps_coords), np.mean(insar_north)),
                    'interpolated_up': np.full(len(gps_coords), np.mean(insar_up)),
                    'method': 'mean_fallback'
                }
                
        except Exception as e:
            logger.error(f"Error in fallback interpolation: {e}")
            return {
                'interpolated_east': np.zeros(len(gps_coords)),
                'interpolated_north': np.zeros(len(gps_coords)),
                'interpolated_up': np.zeros(len(gps_coords)),
                'error': str(e)
            }
    
