    async def _process_era5_atmospheric_data(self, era5_data, parameters):
        """Process ERA5 atmospheric data for PINN training"""
        try:
            if era5_data is None:
                raise ValueError("No ERA5 data provided")
            
            # Extract atmospheric variables
            pressure_levels = era5_data.level.values
            temperatures = era5_data.t.values  # Temperature
            humidity = era5_data.r.values if 'r' in era5_data else era5_data.q.values  # Relative or specific humidity
            geopotential = era5_data.z.values  # Geopotential height
            
            # Calculate atmospheric delays using ERA5 data
            atmospheric_delays = self._calculate_era5_atmospheric_delays(
                pressure_levels, temperatures, humidity, geopotential
            )
            
            # Extract spatial and temporal coordinates
            lons, lats = np.meshgrid(era5_data.longitude.values, era5_data.latitude.values)
            times = era5_data.time.values
            
            # Prepare processed data structure
            processed_data = {
                'pressure_levels': pressure_levels,
                'temperature_profiles': temperatures,
                'humidity_profiles': humidity,
                'geopotential_profiles': geopotential,
                'atmospheric_delays': atmospheric_delays,
                'coordinates': {
                    'longitude': lons,
                    'latitude': lats,
                    'time': times
                },
                'metadata': {
                    'source': 'ERA5_reanalysis',
                    'spatial_resolution': '0.25_degree',
                    'temporal_resolution': '6_hourly',
                    'pressure_levels': len(pressure_levels)
                }
            }
            
            logger.info(f"Processed ERA5 data: {len(pressure_levels)} pressure levels, {len(times)} time steps")
            
            return processed_data
            
        except Exception as e:
            logger.error(f"ERA5 data processing failed: {e}")
            return await self._generate_era5_climatology_data(parameters)
    
    def _calculate_era5_atmospheric_delays(self, pressure_levels, temperatures, humidity, geopotential):
        """Calculate atmospheric delays from ERA5 meteorological data"""
        # Constants for atmospheric delay calculation
        k1 = 77.6  # K/hPa
        k2 = 70.4  # K/hPa
        k3 = 3.739e5  # K²/hPa
        
        # Calculate refractivity for each pressure level
        refractivity = np.zeros_like(temperatures)
        
        for i, p_level in enumerate(pressure_levels):
            T = temperatures[:, i, :, :]  # Temperature at pressure level
            
            if len(humidity.shape) == 4:  # Relative humidity
                RH = humidity[:, i, :, :]
                # Convert to water vapor pressure
                e = RH * 6.112 * np.exp(17.67 * (T - 273.15) / (T - 29.65)) / 100.0
            else:  # Specific humidity
                q = humidity[:, i, :, :]
                # Convert to water vapor pressure
                e = q * p_level / (0.622 + 0.378 * q)
            
            # Calculate refractivity
            refractivity[:, i, :, :] = k1 * (p_level / T) + k2 * (e / T) + k3 * (e / T**2)
        
        # Integrate refractivity to get total atmospheric delay
        # This is a simplified integration - in practice would use more sophisticated methods
        height_differences = np.diff(geopotential / 9.81, axis=1)  # Convert geopotential to height
        
        # Zenith delay calculation
        zenith_delays = np.zeros((refractivity.shape[0], refractivity.shape[2], refractivity.shape[3]))
        
        for t in range(refractivity.shape[0]):
            for lat in range(refractivity.shape[2]):
                for lon in range(refractivity.shape[3]):
                    # Integrate refractivity over height
                    ref_profile = refractivity[t, :, lat, lon]
                    height_diffs = height_differences[t, :, lat, lon] if height_differences.shape[0] > t else height_differences[0, :, lat, lon]
                    
                    # Trapezoidal integration
                    zenith_delays[t, lat, lon] = 1e-6 * np.trapz(ref_profile[:-1], height_diffs)
        
        return zenith_delays
    
    async def _generate_era5_climatology_data(self, parameters):
        """Generate ERA5-like climatological atmospheric data"""
        # Standard pressure levels (hPa)
        pressure_levels = np.array([1000, 975, 950, 925, 900, 875, 850, 825, 800, 775, 750, 700, 650, 600, 550, 500, 450, 400, 350, 300, 250, 200, 150, 100])
        
        # Generate climatological profiles
        n_levels = len(pressure_levels)
        n_time = 120  # 5 days of 6-hourly data
        n_lat, n_lon = 20, 20  # Spatial grid
        
        # Temperature profiles (K) - standard atmosphere with variations
        base_temp = 288.15  # Surface temperature
        lapse_rate = -0.0065  # K/m
        
        temperatures = np.zeros((n_time, n_levels, n_lat, n_lon))
        for i, p in enumerate(pressure_levels):
            height = 44330 * (1 - (p / 1013.25)**0.1903)  # Approximate height
            temp_at_level = base_temp + lapse_rate * height
            
            # Add temporal and spatial variations
            for t in range(n_time):
                for lat in range(n_lat):
                    for lon in range(n_lon):
                        # Diurnal variation
                        diurnal = 5 * np.sin(2 * np.pi * t / 4)  # 6-hourly cycle
                        
                        # Spatial variation
                        lat_variation = -20 * (lat - n_lat/2) / (n_lat/2)
                        
                        # Random variation
                        random_variation = np.random.normal(0, 2)
                        
                        temperatures[t, i, lat, lon] = temp_at_level + diurnal + lat_variation + random_variation
        
        # Humidity profiles (relative humidity %)
        humidity = np.zeros((n_time, n_levels, n_lat, n_lon))
        for i, p in enumerate(pressure_levels):
            base_humidity = 80 * np.exp(-p / 500)  # Decreasing with altitude
            
            for t in range(n_time):
                for lat in range(n_lat):
                    for lon in range(n_lon):
                        # Temporal variation
                        temporal_var = 20 * np.sin(2 * np.pi * t / 24)  # Daily cycle
                        
                        # Spatial variation
                        spatial_var = 30 * np.exp(-abs(lat - n_lat/2) / 5)
                        
                        humidity[t, i, lat, lon] = np.clip(base_humidity + temporal_var + spatial_var + np.random.normal(0, 10), 5, 95)
        
        # Geopotential heights (m²/s²)
        geopotential = np.zeros((n_time, n_levels, n_lat, n_lon))
        for i, p in enumerate(pressure_levels):
            height = 44330 * (1 - (p / 1013.25)**0.1903)
            geopotential[:, i, :, :] = height * 9.81  # Convert to geopotential
        
        return {
            'pressure_levels': pressure_levels,
            'temperature_profiles': temperatures,
            'humidity_profiles': humidity,
            'geopotential_profiles': geopotential,
            'metadata': {
                'source': 'ERA5_climatology',
                'note': 'Synthetic climatological data based on ERA5 patterns'
            }
        }
    
    async def _query_gacos_service(self, gacos_base_url, spatial_bounds, temporal_bounds, parameters):
        """Query GACOS service for atmospheric correction data"""
        try:
            import requests
            
            # Construct GACOS query
            query_params = {
                'north': spatial_bounds['north'],
                'south': spatial_bounds['south'],
                'east': spatial_bounds['east'],
                'west': spatial_bounds['west'],
                'start_date': temporal_bounds['start_date'].strftime('%Y-%m-%d'),
                'end_date': temporal_bounds['end_date'].strftime('%Y-%m-%d'),
                'format': 'netcdf'
            }
            
            # Query GACOS service
            response = requests.get(f"{gacos_base_url}/query", params=query_params, timeout=30)
            
            if response.status_code == 200:
                # Parse GACOS response
                gacos_data = response.json()
                
                # Download correction files
                correction_data = []
                for file_info in gacos_data.get('files', []):
                    file_response = requests.get(file_info['download_url'], timeout=60)
                    if file_response.status_code == 200:
                        correction_data.append({
                            'data': file_response.content,
                            'metadata': file_info
                        })
                
                return correction_data
            else:
                logger.warning(f"GACOS service returned status {response.status_code}")
                return None
                
        except Exception as e:
            logger.error(f"GACOS service query failed: {e}")
            return None
    
    async def _process_gacos_corrections(self, gacos_data, parameters):
        """Process GACOS atmospheric correction data"""
        try:
            import xarray as xr
            from io import BytesIO
            
            correction_maps = []
            uncertainty_maps = []
            
            for data_item in gacos_data:
                # Load NetCDF data
                dataset = xr.open_dataset(BytesIO(data_item['data']))
                
                # Extract correction and uncertainty maps
                if 'ztd' in dataset:  # Zenith Total Delay
                    correction_maps.append(dataset.ztd.values)
                
                if 'ztd_uncertainty' in dataset:
                    uncertainty_maps.append(dataset.ztd_uncertainty.values)
                elif 'std' in dataset:
                    uncertainty_maps.append(dataset.std.values)
            
            # Stack maps into arrays
            correction_maps = np.stack(correction_maps) if correction_maps else np.array([])
            uncertainty_maps = np.stack(uncertainty_maps) if uncertainty_maps else np.array([])
            
            return {
                'correction_maps': correction_maps,
                'uncertainty_maps': uncertainty_maps,
                'metadata': {
                    'source': 'GACOS',
                    'n_maps': len(correction_maps),
                    'processing_date': datetime.now().isoformat()
                }
            }
            
        except Exception as e:
            logger.error(f"GACOS data processing failed: {e}")
            return await self._generate_synthetic_gacos_corrections(parameters)
    
    async def _generate_synthetic_gacos_corrections(self, parameters):
        """Generate synthetic GACOS-like atmospheric corrections"""
        # Generate realistic atmospheric correction patterns
        n_time = 30  # 30 time steps
        n_lat, n_lon = 100, 100  # Spatial grid
        
        # Create spatial coordinates
        lats = np.linspace(-90, 90, n_lat)
        lons = np.linspace(-180, 180, n_lon)
        lat_grid, lon_grid = np.meshgrid(lats, lons, indexing='ij')
        
        # Generate correction maps with realistic patterns
        correction_maps = np.zeros((n_time, n_lat, n_lon))
        uncertainty_maps = np.zeros((n_time, n_lat, n_lon))
        
        for t in range(n_time):
            # Base atmospheric delay pattern
            base_delay = 0.1 * np.sin(np.pi * lat_grid / 90) * np.cos(2 * np.pi * lon_grid / 360)
            
            # Temporal variation
            temporal_factor = 1 + 0.3 * np.sin(2 * np.pi * t / 30)
            
            # Add turbulent atmospheric patterns
            turbulence = self._generate_atmospheric_turbulence(n_lat, n_lon)
            
            # Combine patterns
            correction_maps[t] = base_delay * temporal_factor + 0.02 * turbulence
            
            # Generate uncertainty maps
            base_uncertainty = 0.005 + 0.01 * np.abs(base_delay)
            uncertainty_maps[t] = base_uncertainty + 0.002 * np.random.random((n_lat, n_lon))
        
        return {
            'correction_maps': correction_maps,
            'uncertainty_maps': uncertainty_maps,
            'metadata': {
                'source': 'synthetic_GACOS',
                'note': 'Physics-based synthetic atmospheric corrections'
            }
        }
    
    def _generate_atmospheric_turbulence(self, n_lat, n_lon):
        """Generate realistic atmospheric turbulence patterns"""
        # Use Fourier synthesis to create realistic turbulence
        kx = np.fft.fftfreq(n_lat)
        ky = np.fft.fftfreq(n_lon)
        kx_grid, ky_grid = np.meshgrid(kx, ky, indexing='ij')
        
        # Power spectrum (Kolmogorov-like)
        k_magnitude = np.sqrt(kx_grid**2 + ky_grid**2)
        k_magnitude[0, 0] = 1e-10  # Avoid division by zero
        
        power_spectrum = k_magnitude**(-11/3)  # Kolmogorov spectrum
        
        # Generate random phases
        phases = 2 * np.pi * np.random.random((n_lat, n_lon))
        
        # Create Fourier coefficients
        fourier_coeffs = np.sqrt(power_spectrum) * np.exp(1j * phases)
        
        # Inverse FFT to get spatial pattern
        turbulence = np.real(np.fft.ifft2(fourier_coeffs))
        
        # Normalize
        turbulence = (turbulence - np.mean(turbulence)) / np.std(turbulence)
        
        return turbulence
    
