    async def _generate_volcanic_observatory_weather(self, spatial_bounds, temporal_bounds):
        """Generate synthetic volcanic observatory weather data"""
        # Generate weather stations near volcanic areas
        n_stations = 5
        
        # Random station locations within bounds
        station_lats = np.random.uniform(spatial_bounds['south'], spatial_bounds['north'], n_stations)
        station_lons = np.random.uniform(spatial_bounds['west'], spatial_bounds['east'], n_stations)
        
        # Generate time series
        time_range = (temporal_bounds['end_date'] - temporal_bounds['start_date']).days
        n_time_steps = time_range * 24  # Hourly data
        
        # Generate realistic volcanic area weather
        temperature_series = np.zeros((n_stations, n_time_steps))
        pressure_series = np.zeros((n_stations, n_time_steps))
        humidity_series = np.zeros((n_stations, n_time_steps))
        
        for i in range(n_stations):
            # Base conditions (volcanic areas tend to be warmer)
            base_temp = 288.15 + np.random.normal(5, 2)  # Slightly warmer
            base_pressure = 101325 * np.exp(-1000 / 8400)  # Assume 1km elevation
            base_humidity = 70 + np.random.normal(0, 10)
            
            for t in range(n_time_steps):
                # Diurnal cycles
                hour = t % 24
                diurnal_temp = 8 * np.sin(2 * np.pi * (hour - 6) / 24)
                diurnal_humidity = -15 * np.sin(2 * np.pi * (hour - 12) / 24)
                
                # Seasonal variation
                day_of_year = (t // 24) % 365
                seasonal_temp = 10 * np.sin(2 * np.pi * day_of_year / 365)
                
                # Volcanic influence (random thermal anomalies)
                volcanic_temp = 2 * np.random.exponential(0.1) if np.random.random() < 0.05 else 0
                
                # Store values
                temperature_series[i, t] = base_temp + diurnal_temp + seasonal_temp + volcanic_temp + np.random.normal(0, 1)
                pressure_series[i, t] = base_pressure + np.random.normal(0, 100)
                humidity_series[i, t] = np.clip(base_humidity + diurnal_humidity + np.random.normal(0, 5), 10, 95)
        
        return {
            'station_locations': np.column_stack([station_lons, station_lats]),
            'temperature_time_series': temperature_series,
            'pressure_time_series': pressure_series,
            'humidity_time_series': humidity_series,
            'metadata': {
                'source': 'volcanic_observatory_synthetic',
                'n_stations': n_stations,
                'temporal_resolution': 'hourly'
            }
        }
    
    def _merge_weather_station_data(self, existing_data, new_data):
        """Merge weather station data from multiple sources"""
        if not existing_data:
            return new_data
        
        if not new_data:
            return existing_data
        
        # Merge station locations
        existing_locations = existing_data.get('station_locations', np.array([]).reshape(0, 2))
        new_locations = new_data.get('station_locations', np.array([]).reshape(0, 2))
        
        if existing_locations.size > 0 and new_locations.size > 0:
            merged_locations = np.vstack([existing_locations, new_locations])
        elif new_locations.size > 0:
            merged_locations = new_locations
        else:
            merged_locations = existing_locations
        
        # Merge time series data
        merged_data = {
            'station_locations': merged_locations
        }
        
        # Merge temperature data
        existing_temp = existing_data.get('temperature_time_series', np.array([]))
        new_temp = new_data.get('temperature_time_series', np.array([]))
        
        if existing_temp.size > 0 and new_temp.size > 0:
            merged_data['temperature_time_series'] = np.vstack([existing_temp, new_temp])
        elif new_temp.size > 0:
            merged_data['temperature_time_series'] = new_temp
        elif existing_temp.size > 0:
            merged_data['temperature_time_series'] = existing_temp
        
        # Similar merging for other variables
        for var in ['pressure_time_series', 'humidity_time_series']:
            existing_var = existing_data.get(var, np.array([]))
            new_var = new_data.get(var, np.array([]))
            
            if existing_var.size > 0 and new_var.size > 0:
                merged_data[var] = np.vstack([existing_var, new_var])
            elif new_var.size > 0:
                merged_data[var] = new_var
            elif existing_var.size > 0:
                merged_data[var] = existing_var
        
        return merged_data
    
    async def _process_weather_station_data(self, weather_data, parameters):
        """Process and quality control weather station data"""
        if not weather_data:
            return {}
        
        processed_data = weather_data.copy()
        
        # Quality control checks
        if 'temperature_time_series' in processed_data:
            temp_data = processed_data['temperature_time_series']
            
            # Remove unrealistic temperatures
            valid_temp_mask = (temp_data > 200) & (temp_data < 350)  # Kelvin range
            temp_data[~valid_temp_mask] = np.nan
            
            # Interpolate missing values
            for i in range(temp_data.shape[0]):
                station_temps = temp_data[i, :]
                valid_indices = ~np.isnan(station_temps)
                if np.sum(valid_indices) > 2:
                    # Linear interpolation
                    station_temps[~valid_indices] = np.interp(
                        np.where(~valid_indices)[0],
                        np.where(valid_indices)[0],
                        station_temps[valid_indices]
                    )
            
            processed_data['temperature_time_series'] = temp_data
        
        # Similar processing for pressure and humidity
        for var_name, (min_val, max_val) in [
            ('pressure_time_series', (50000, 110000)),  # Pa
            ('humidity_time_series', (0, 100))  # %
        ]:
            if var_name in processed_data:
                var_data = processed_data[var_name]
                valid_mask = (var_data >= min_val) & (var_data <= max_val)
                var_data[~valid_mask] = np.nan
                
                # Interpolate missing values
                for i in range(var_data.shape[0]):
                    station_data = var_data[i, :]
                    valid_indices = ~np.isnan(station_data)
                    if np.sum(valid_indices) > 2:
                        station_data[~valid_indices] = np.interp(
                            np.where(~valid_indices)[0],
                            np.where(valid_indices)[0],
                            station_data[valid_indices]
                        )
                
                processed_data[var_name] = var_data
        
        return processed_data
    
    async def _cache_weather_station_data(self, db_integrator, weather_data, parameters):
        """Cache processed weather station data in database"""
        try:
            # Store in Redis cache for quick access
            cache_key = f"weather_stations:{parameters.get('region', 'global')}:{datetime.now().strftime('%Y%m%d')}"
            await db_integrator.cache_set(cache_key, weather_data, ttl=86400)  # 24 hour cache
            
            # Store metadata in PostgreSQL
            if 'station_locations' in weather_data:
                n_stations = len(weather_data['station_locations'])
                
                metadata = {
                    'cache_key': cache_key,
                    'n_stations': n_stations,
                    'data_sources': weather_data.get('metadata', {}).get('sources', []),
                    'temporal_coverage': parameters.get('temporal_bounds', {}),
                    'spatial_coverage': parameters.get('spatial_bounds', {}),
                    'cached_at': datetime.now()
                }
                
                # This would store in a weather_data_cache table
                logger.info(f"Cached weather station data: {n_stations} stations")
            
        except Exception as e:
            logger.warning(f"Failed to cache weather station data: {e}")
    
    async def _generate_climatological_weather_data(self, parameters):
        """Generate climatological weather data as fallback"""
        # Generate realistic climatological weather patterns
        spatial_bounds = parameters.get('spatial_bounds', {
            'north': 90, 'south': -90, 'east': 180, 'west': -180
        })
        
        # Generate station network
        n_stations = 20
        station_lats = np.random.uniform(spatial_bounds['south'], spatial_bounds['north'], n_stations)
        station_lons = np.random.uniform(spatial_bounds['west'], spatial_bounds['east'], n_stations)
        
        # Generate climatological time series (1 year of daily data)
        n_days = 365
        
        temperature_series = np.zeros((n_stations, n_days))
        pressure_series = np.zeros((n_stations, n_days))
        humidity_series = np.zeros((n_stations, n_days))
        
        for i in range(n_stations):
            lat = station_lats[i]
            
            # Climatological base values
            base_temp = 288.15 - 0.5 * abs(lat)  # Colder at higher latitudes
            base_pressure = 101325.0
            base_humidity = 60 + 20 * np.exp(-abs(lat) / 30)
            
            for day in range(n_days):
                # Seasonal variation
                seasonal_temp = 15 * np.sin(2 * np.pi * (day - 80) / 365)  # Peak in summer
                seasonal_humidity = -10 * np.sin(2 * np.pi * (day - 80) / 365)  # Opposite phase
                
                # Random weather variations
                temp_noise = np.random.normal(0, 3)
                pressure_noise = np.random.normal(0, 500)
                humidity_noise = np.random.normal(0, 10)
                
                temperature_series[i, day] = base_temp + seasonal_temp + temp_noise
                pressure_series[i, day] = base_pressure + pressure_noise
                humidity_series[i, day] = np.clip(base_humidity + seasonal_humidity + humidity_noise, 10, 95)
        
        return {
            'station_locations': np.column_stack([station_lons, station_lats]),
            'temperature_time_series': temperature_series,
            'pressure_time_series': pressure_series,
            'humidity_time_series': humidity_series,
            'metadata': {
                'source': 'climatological_synthetic',
                'note': 'Fallback climatological weather data'
            }
        }
    
    def _process_usgs_weather_observations(self, observations):
        """Process USGS weather observations into station format"""
        if not observations:
            return {}
        
        # Group observations by station
        stations = {}
        for obs in observations:
            station_id = obs.metadata.get('station_id', f"usgs_{obs.observation_id}")
            
            if station_id not in stations:
                stations[station_id] = {
                    'location': [obs.longitude, obs.latitude],
                    'temperature': [],
                    'pressure': [],
                    'humidity': [],
                    'timestamps': []
                }
            
            # Extract meteorological data
            if obs.observation_type == 'temperature':
                stations[station_id]['temperature'].append(obs.value)
            elif obs.observation_type == 'pressure':
                stations[station_id]['pressure'].append(obs.value)
            elif obs.observation_type == 'humidity':
                stations[station_id]['humidity'].append(obs.value)
            
            stations[station_id]['timestamps'].append(obs.timestamp)
        
        # Convert to arrays
        station_locations = []
        temperature_series = []
        pressure_series = []
        humidity_series = []
        
        for station_id, station_data in stations.items():
            station_locations.append(station_data['location'])
            
            # Pad series to same length
            max_length = max(len(station_data['temperature']), len(station_data['pressure']), len(station_data['humidity']))
            
            temp_series = station_data['temperature'] + [np.nan] * (max_length - len(station_data['temperature']))
            press_series = station_data['pressure'] + [np.nan] * (max_length - len(station_data['pressure']))
            humid_series = station_data['humidity'] + [np.nan] * (max_length - len(station_data['humidity']))
            
            temperature_series.append(temp_series)
            pressure_series.append(press_series)
            humidity_series.append(humid_series)
        
        return {
            'station_locations': np.array(station_locations),
            'temperature_time_series': np.array(temperature_series),
            'pressure_time_series': np.array(pressure_series),
            'humidity_time_series': np.array(humidity_series),
            'metadata': {
                'source': 'USGS',
                'n_stations': len(stations)
            }
        }
    
