    # Additional helper methods for training metrics storage
    
    def _calculate_convergence_rate(self, loss_history):
        """Calculate convergence rate from loss history"""
        if len(loss_history) < 10:
            return 0.0
        
        # Fit exponential decay to recent loss history
        recent_losses = loss_history[-20:]
        x = np.arange(len(recent_losses))
        
        try:
            # Log-linear fit
            log_losses = np.log(np.maximum(recent_losses, 1e-10))
            slope, _ = np.polyfit(x, log_losses, 1)
            return -slope  # Negative slope indicates convergence
        except:
            return 0.0
    
