    async def _mosaic_dem_granules(self, granule_list, bbox):
        """Mosaic multiple DEM granules into single dataset"""
        try:
            if len(granule_list) == 1:
                return granule_list[0]
            
            # Find common resolution and extent
            min_resolution = min(g['resolution'] for g in granule_list)
            
            # Create target grid
            x_min, y_min, x_max, y_max = bbox
            x_coords = np.arange(x_min, x_max, min_resolution / 111000)  # Convert to degrees
            y_coords = np.arange(y_max, y_min, -min_resolution / 111000)
            
            # Initialize output array
            output_elevations = np.full((len(y_coords), len(x_coords)), np.nan)
            weight_sum = np.zeros_like(output_elevations)
            
            # Mosaic granules with distance-based weighting
            for granule in granule_list:
                # Interpolate granule to target grid
                granule_x, granule_y = np.meshgrid(granule['x_coords'], granule['y_coords'])
                target_x, target_y = np.meshgrid(x_coords, y_coords)
                
                # Flatten for interpolation
                valid_mask = ~np.isnan(granule['elevations'])
                if not np.any(valid_mask):
                    continue
                
                points = np.column_stack([
                    granule_x[valid_mask].ravel(),
                    granule_y[valid_mask].ravel()
                ])
                values = granule['elevations'][valid_mask].ravel()
                
                # Interpolate to target grid
                interpolated = griddata(
                    points, values,
                    (target_x, target_y),
                    method='linear',
                    fill_value=np.nan
                )
                
                # Calculate weights (inverse distance from granule center)
                center_x = np.mean(granule['x_coords'])
                center_y = np.mean(granule['y_coords'])
                distances = np.sqrt((target_x - center_x)**2 + (target_y - center_y)**2)
                weights = 1.0 / (distances + 1e-6)
                
                # Add to weighted sum
                valid_interp = ~np.isnan(interpolated)
                output_elevations[valid_interp] = np.nansum([
                    output_elevations[valid_interp] * weight_sum[valid_interp],
                    interpolated[valid_interp] * weights[valid_interp]
                ], axis=0) / (weight_sum[valid_interp] + weights[valid_interp])
                
                weight_sum[valid_interp] += weights[valid_interp]
            
            return {
                'elevations': output_elevations,
                'x_coords': x_coords,
                'y_coords': y_coords,
                'resolution': min_resolution,
                'source': 'mosaicked'
            }
            
        except Exception as e:
            logger.error(f"Error mosaicking DEM granules: {e}")
            return granule_list[0]  # Return first granule as fallback
    
    def _calculate_adaptive_weight(self, quality_metrics, source_name):
        """Calculate adaptive weight for DEM fusion based on quality metrics"""
        try:
            base_weights = {
                'srtm': 1.0,
                'aster': 0.8,
                'alos': 0.9,
                'tandem': 0.7
            }
            
            base_weight = base_weights.get(source_name, 0.5)
            
            # Adjust based on quality metrics
            completeness_factor = quality_metrics.get('completeness', 0.5)
            spatial_consistency_factor = quality_metrics.get('spatial_consistency', 0.5)
            edge_quality_factor = quality_metrics.get('edge_quality', 0.5)
            
            adaptive_weight = base_weight * (
                0.4 * completeness_factor +
                0.3 * spatial_consistency_factor +
                0.3 * edge_quality_factor
            )
            
            return max(0.1, min(1.0, adaptive_weight))
            
        except Exception as e:
            logger.error(f"Error calculating adaptive weight: {e}")
            return 0.5
    
    async def _resample_dem_to_grid(self, dem_data, reference_grid):
        """Resample DEM to match reference grid"""
        try:
            from scipy.interpolate import RegularGridInterpolator
            
            # Create interpolator for source DEM
            interpolator = RegularGridInterpolator(
                (dem_data['y_coords'], dem_data['x_coords']),
                dem_data['elevations'],
                method='linear',
                bounds_error=False,
                fill_value=np.nan
            )
            
            # Create target grid
            target_x, target_y = np.meshgrid(reference_grid['x_coords'], reference_grid['y_coords'])
            target_points = np.column_stack([target_y.ravel(), target_x.ravel()])
            
            # Interpolate
            resampled_elevations = interpolator(target_points).reshape(target_x.shape)
            
            return {
                'elevations': resampled_elevations,
                'x_coords': reference_grid['x_coords'],
                'y_coords': reference_grid['y_coords'],
                'resolution': reference_grid['resolution'],
                'source': f"resampled_{dem_data['source']}"
            }
            
        except Exception as e:
            logger.error(f"Error resampling DEM: {e}")
            return dem_data
    
    async def _ml_dem_fusion(self, dem_arrays, weights, reference_grid):
        """Machine learning-based DEM fusion using Random Forest"""
        try:
            # Prepare training data
            valid_mask = ~np.isnan(dem_arrays).any(axis=0)
            if not np.any(valid_mask):
                return np.nanmean(dem_arrays, axis=0)
            
            # Features: elevation values from different sources + spatial coordinates
            y_grid, x_grid = np.meshgrid(reference_grid['y_coords'], reference_grid['x_coords'], indexing='ij')
            
            features = []
            for i, dem_array in enumerate(dem_arrays):
                features.append(dem_array[valid_mask])
            
            # Add spatial features
            features.extend([
                x_grid[valid_mask],
                y_grid[valid_mask],
                np.sqrt(x_grid[valid_mask]**2 + y_grid[valid_mask]**2)  # Distance from origin
            ])
            
            X = np.column_stack(features)
            
            # Target: weighted average as initial estimate
            y = np.average(dem_arrays[:, valid_mask], axis=0, weights=weights)
            
            # Train Random Forest
            rf = RandomForestRegressor(
                n_estimators=100,
                max_depth=10,
                random_state=42,
                n_jobs=-1
            )
            rf.fit(X, y)
            
            # Predict for all pixels
            all_features = []
            for dem_array in dem_arrays:
                all_features.append(dem_array.ravel())
            
            all_features.extend([
                x_grid.ravel(),
                y_grid.ravel(),
                np.sqrt(x_grid.ravel()**2 + y_grid.ravel()**2)
            ])
            
            X_all = np.column_stack(all_features)
            
            # Handle NaN values
            nan_mask = np.isnan(X_all).any(axis=1)
            predictions = np.full(X_all.shape[0], np.nan)
            
            if not np.all(nan_mask):
                predictions[~nan_mask] = rf.predict(X_all[~nan_mask])
            
            return predictions.reshape(dem_arrays[0].shape)
            
        except Exception as e:
            logger.error(f"Error in ML DEM fusion: {e}")
            return np.nanmean(dem_arrays, axis=0)
    
    async def _gaussian_process_fusion(self, dem_arrays, weights, reference_grid):
        """Gaussian Process fusion for uncertainty quantification"""
        try:
            # Subsample for computational efficiency
            subsample_factor = max(1, dem_arrays[0].size // 10000)
            
            if subsample_factor > 1:
                subsampled_arrays = dem_arrays[:, ::subsample_factor, ::subsample_factor]
                y_sub = reference_grid['y_coords'][::subsample_factor]
                x_sub = reference_grid['x_coords'][::subsample_factor]
            else:
                subsampled_arrays = dem_arrays
                y_sub = reference_grid['y_coords']
                x_sub = reference_grid['x_coords']
            
            # Prepare data
            valid_mask = ~np.isnan(subsampled_arrays).any(axis=0)
            if not np.any(valid_mask):
                return np.nanmean(dem_arrays, axis=0), np.ones_like(dem_arrays[0]) * 100
            
            y_grid_sub, x_grid_sub = np.meshgrid(y_sub, x_sub, indexing='ij')
            
            # Features and targets
            X_train = np.column_stack([
                x_grid_sub[valid_mask],
                y_grid_sub[valid_mask]
            ])
            y_train = np.average(subsampled_arrays[:, valid_mask], axis=0, weights=weights)
            
            # Gaussian Process with RBF kernel
            kernel = RBF(length_scale=0.01) + WhiteKernel(noise_level=1.0)
            gp = GaussianProcessRegressor(
                kernel=kernel,
                alpha=1e-6,
                normalize_y=True,
                n_restarts_optimizer=2
            )
            
            gp.fit(X_train, y_train)
            
            # Predict for full grid
            y_grid_full, x_grid_full = np.meshgrid(reference_grid['y_coords'], reference_grid['x_coords'], indexing='ij')
            X_pred = np.column_stack([
                x_grid_full.ravel(),
                y_grid_full.ravel()
            ])
            
            mean_pred, std_pred = gp.predict(X_pred, return_std=True)
            
            return mean_pred.reshape(dem_arrays[0].shape), std_pred.reshape(dem_arrays[0].shape)
            
        except Exception as e:
            logger.error(f"Error in Gaussian Process fusion: {e}")
            return np.nanmean(dem_arrays, axis=0), np.ones_like(dem_arrays[0]) * 50
    
    async def _adaptive_fusion_blending(self, weighted_avg, ml_fused, gp_fused, uncertainty_map, quality_metrics):
        """Adaptive blending of different fusion methods"""
        try:
            # Calculate blending weights based on uncertainty and quality
            uncertainty_normalized = uncertainty_map / np.nanmax(uncertainty_map)
            
            # High uncertainty areas: favor ML fusion
            # Low uncertainty areas: favor weighted average
            # Medium uncertainty: favor GP fusion
            
            ml_weight = uncertainty_normalized
            wa_weight = 1 - uncertainty_normalized
            gp_weight = 1 - np.abs(uncertainty_normalized - 0.5) * 2
            
            # Normalize weights
            total_weight = ml_weight + wa_weight + gp_weight
            ml_weight /= total_weight
            wa_weight /= total_weight
            gp_weight /= total_weight
            
            # Blend methods
            blended = (
                weighted_avg * wa_weight +
                ml_fused * ml_weight +
                gp_fused * gp_weight
            )
            
            return blended
            
        except Exception as e:
            logger.error(f"Error in adaptive fusion blending: {e}")
            return weighted_avg
    
    async def _simple_weighted_fusion(self, dem_sources, quality_metrics):
        """Simple weighted fusion fallback"""
        try:
            if not dem_sources:
                return None
            
            # Get reference grid from best source
            best_source = max(quality_metrics.items(), key=lambda x: x[1]['overall_score'])[0]
            reference = dem_sources[best_source]
            
            # Simple weighted average
            total_weight = 0
            weighted_sum = np.zeros_like(reference['elevations'])
            
            for source_name, dem_data in dem_sources.items():
                weight = quality_metrics[source_name]['overall_score']
                
                # Resample to reference grid if needed
                if not np.array_equal(dem_data['x_coords'], reference['x_coords']):
                    dem_data = await self._resample_dem_to_grid(dem_data, reference)
                
                valid_mask = ~np.isnan(dem_data['elevations'])
                weighted_sum[valid_mask] += dem_data['elevations'][valid_mask] * weight
                total_weight += weight
            
            final_elevations = weighted_sum / total_weight
            
            return {
                'elevations': final_elevations,
                'x_coords': reference['x_coords'],
                'y_coords': reference['y_coords'],
                'resolution': reference['resolution'],
                'source': 'simple_weighted_fusion',
                'quality_score': np.mean([q['overall_score'] for q in quality_metrics.values()])
            }
            
        except Exception as e:
            logger.error(f"Error in simple weighted fusion: {e}")
            return list(dem_sources.values())[0]
    
    async def _calculate_spatial_consistency(self, elevations):
        """Calculate spatial consistency metric for DEM quality assessment"""
        try:
            # Calculate local standard deviation using sliding window
            from scipy.ndimage import uniform_filter
            
            # Local mean and variance
            local_mean = uniform_filter(elevations, size=5, mode='constant', cval=np.nan)
            local_var = uniform_filter(elevations**2, size=5, mode='constant', cval=np.nan) - local_mean**2
            local_std = np.sqrt(np.maximum(local_var, 0))
            
            # Spatial consistency is inverse of normalized local variation
            mean_local_std = np.nanmean(local_std)
            elevation_range = np.nanmax(elevations) - np.nanmin(elevations)
            
            if elevation_range == 0:
                return 1.0
            
            consistency = 1.0 - min(1.0, mean_local_std / (elevation_range * 0.1))
            return max(0.0, consistency)
            
        except Exception as e:
            logger.error(f"Error calculating spatial consistency: {e}")
            return 0.5
    
    async def _assess_edge_quality(self, elevations):
        """Assess quality of DEM edges"""
        try:
            # Check for edge artifacts (sudden elevation changes at boundaries)
            edge_pixels = 5
            
            # Top and bottom edges
            top_edge = elevations[:edge_pixels, :]
            bottom_edge = elevations[-edge_pixels:, :]
            
            # Left and right edges
            left_edge = elevations[:, :edge_pixels]
            right_edge = elevations[:, -edge_pixels:]
            
            # Calculate edge gradients
            edges = [top_edge, bottom_edge, left_edge, right_edge]
            edge_quality_scores = []
            
            for edge in edges:
                if edge.size == 0:
                    continue
                
                # Calculate gradient magnitude
                grad_y, grad_x = np.gradient(edge)
                grad_magnitude = np.sqrt(grad_x**2 + grad_y**2)
                
                # Edge quality is inverse of mean gradient (lower gradients = better)
                mean_gradient = np.nanmean(grad_magnitude)
                max_reasonable_gradient = 100  # meters per pixel
                
                quality = 1.0 - min(1.0, mean_gradient / max_reasonable_gradient)
                edge_quality_scores.append(max(0.0, quality))
            
            return np.mean(edge_quality_scores) if edge_quality_scores else 0.5
            
        except Exception as e:
            logger.error(f"Error assessing edge quality: {e}")
            return 0.5
    
    async def _comprehensive_quality_assessment(self, enhanced_dem, dem_sources, quality_metrics):
        """Comprehensive quality assessment of fused DEM"""
        try:
            elevations = enhanced_dem['elevations']
            
            # 1. Data completeness
            completeness = np.sum(~np.isnan(elevations)) / elevations.size
            
            # 2. Elevation statistics
            elevation_stats = {
                'mean': np.nanmean(elevations),
                'std': np.nanstd(elevations),
                'range': np.nanmax(elevations) - np.nanmin(elevations),
                'percentiles': np.nanpercentile(elevations, [5, 25, 50, 75, 95])
            }
            
            # 3. Spatial coherence
            spatial_coherence = await self._calculate_spatial_consistency(elevations)
            
            # 4. Multi-source agreement
            source_agreement = await self._calculate_source_agreement(dem_sources, enhanced_dem)
            
            # 5. Topographic realism
            topo_realism = await self._assess_topographic_realism(elevations)
            
            # 6. Uncertainty quantification
            uncertainty_map = await self._calculate_uncertainty_map(enhanced_dem, dem_sources, quality_metrics)
            
            # 7. Confidence intervals
            confidence_intervals = await self._calculate_confidence_intervals(elevations, uncertainty_map)
            
            # Overall quality score
            overall_score = (
                completeness * 0.25 +
                spatial_coherence * 0.25 +
                source_agreement * 0.20 +
                topo_realism * 0.20 +
                (1.0 - np.nanmean(uncertainty_map) / 100.0) * 0.10
            )
            
            return {
                'overall_score': max(0.0, min(1.0, overall_score)),
                'completeness': completeness,
                'spatial_coherence': spatial_coherence,
                'source_agreement': source_agreement,
                'topographic_realism': topo_realism,
                'elevation_statistics': elevation_stats,
                'uncertainty_map': uncertainty_map,
                'confidence_intervals': confidence_intervals,
                'assessment_timestamp': datetime.now().isoformat()
            }
            
        except Exception as e:
            logger.error(f"Error in comprehensive quality assessment: {e}")
            return {
                'overall_score': 0.5,
                'uncertainty_map': np.ones_like(enhanced_dem['elevations']) * 50,
                'confidence_intervals': {'lower': enhanced_dem['elevations'] - 50, 'upper': enhanced_dem['elevations'] + 50}
            }
    
    async def _calculate_source_agreement(self, dem_sources, fused_dem):
        """Calculate agreement between different DEM sources"""
        try:
            if len(dem_sources) < 2:
                return 1.0
            
            agreements = []
            fused_elevations = fused_dem['elevations']
            
            for source_name, dem_data in dem_sources.items():
                # Resample to fused grid if needed
                if not np.array_equal(dem_data['x_coords'], fused_dem['x_coords']):
                    dem_data = await self._resample_dem_to_grid(dem_data, fused_dem)
                
                # Calculate RMSE between source and fused DEM
                valid_mask = ~np.isnan(dem_data['elevations']) & ~np.isnan(fused_elevations)
                if np.sum(valid_mask) == 0:
                    continue
                
                rmse = np.sqrt(np.mean((dem_data['elevations'][valid_mask] - fused_elevations[valid_mask])**2))
                
                # Convert RMSE to agreement score (0-1)
                max_reasonable_rmse = 100  # meters
                agreement = 1.0 - min(1.0, rmse / max_reasonable_rmse)
                agreements.append(max(0.0, agreement))
            
            return np.mean(agreements) if agreements else 0.5
            
        except Exception as e:
            logger.error(f"Error calculating source agreement: {e}")
            return 0.5
    
    async def _assess_topographic_realism(self, elevations):
        """Assess topographic realism of DEM"""
        try:
            # Calculate slope and aspect
            grad_y, grad_x = np.gradient(elevations)
            slope = np.sqrt(grad_x**2 + grad_y**2)
            
            # Check for unrealistic slopes (>45 degrees is unusual for most terrain)
            max_reasonable_slope = np.tan(np.radians(45))  # 100% grade
            unrealistic_slope_fraction = np.sum(slope > max_reasonable_slope) / slope.size
            
            # Check for elevation spikes (isolated high/low values)
            from scipy.ndimage import median_filter
            median_filtered = median_filter(elevations, size=3)
            elevation_diff = np.abs(elevations - median_filtered)
            spike_threshold = 3 * np.nanstd(elevation_diff)
            spike_fraction = np.sum(elevation_diff > spike_threshold) / elevations.size
            
            # Topographic realism score
            realism_score = 1.0 - (unrealistic_slope_fraction * 0.6 + spike_fraction * 0.4)
            
            return max(0.0, min(1.0, realism_score))
            
        except Exception as e:
            logger.error(f"Error assessing topographic realism: {e}")
            return 0.5
    
    async def _calculate_uncertainty_map(self, enhanced_dem, dem_sources, quality_metrics):
        """Calculate pixel-wise uncertainty map"""
        try:
            elevations = enhanced_dem['elevations']
            uncertainty_map = np.full_like(elevations, 50.0)  # Default 50m uncertainty
            
            if len(dem_sources) > 1:
                # Calculate uncertainty based on source disagreement
                source_elevations = []
                
                for source_name, dem_data in dem_sources.items():
                    if not np.array_equal(dem_data['x_coords'], enhanced_dem['x_coords']):
                        dem_data = await self._resample_dem_to_grid(dem_data, enhanced_dem)
                    source_elevations.append(dem_data['elevations'])
                
                source_elevations = np.array(source_elevations)
                
                # Standard deviation across sources as uncertainty measure
                source_std = np.nanstd(source_elevations, axis=0)
                
                # Combine with quality-based uncertainty
                mean_quality = np.mean([q['overall_score'] for q in quality_metrics.values()])
                quality_uncertainty = (1.0 - mean_quality) * 100
                
                uncertainty_map = np.sqrt(source_std**2 + quality_uncertainty**2)
            
            return uncertainty_map
            
        except Exception as e:
            logger.error(f"Error calculating uncertainty map: {e}")
            return np.full_like(enhanced_dem['elevations'], 50.0)
    
    async def _calculate_confidence_intervals(self, elevations, uncertainty_map):
        """Calculate confidence intervals for elevations"""
        try:
            # 95% confidence intervals (±1.96 * uncertainty)
            confidence_factor = 1.96
            
            lower_bound = elevations - confidence_factor * uncertainty_map
            upper_bound = elevations + confidence_factor * uncertainty_map
            
            return {
                'lower': lower_bound,
                'upper': upper_bound,
                'confidence_level': 0.95
            }
            
        except Exception as e:
            logger.error(f"Error calculating confidence intervals: {e}")
            return {
                'lower': elevations - 50,
                'upper': elevations + 50,
                'confidence_level': 0.95
            }
    
    def _calculate_tectonic_elevation(self, lat_grid, lon_grid):
        """Calculate elevation based on tectonic setting"""
        try:
            # Simplified tectonic elevation model
            # Higher elevations near plate boundaries and mountain ranges
            
            # Distance from major tectonic features (simplified)
            # This would be replaced with actual tectonic database queries
            
            # Mid-ocean ridges (low elevation)
            ridge_factor = np.sin(lat_grid * np.pi / 30) * np.cos(lon_grid * np.pi / 60)
            
            # Continental margins (variable elevation)
            margin_factor = np.cos(lat_grid * np.pi / 45) * np.sin(lon_grid * np.pi / 90)
            
            # Mountain belts (high elevation)
            mountain_factor = np.abs(np.sin(lat_grid * np.pi / 20)) * np.abs(np.cos(lon_grid * np.pi / 40))
            
            tectonic_elevation = (
                ridge_factor * 500 +
                margin_factor * 1000 +
                mountain_factor * 2000
            )
            
            return np.maximum(tectonic_elevation, 0)
            
        except Exception as e:
            logger.error(f"Error calculating tectonic elevation: {e}")
            return np.zeros_like(lat_grid)
    
    def _calculate_volcanic_elevation(self, lat_grid, lon_grid, center_lat, center_lon):
        """Calculate volcanic elevation contribution"""
        try:
            # Distance from volcanic center
            distance = np.sqrt((lat_grid - center_lat)**2 + (lon_grid - center_lon)**2)
            
            # Volcanic edifice model (Gaussian-like)
            volcanic_height = 1500 * np.exp(-distance**2 / 0.01)  # Peak height 1500m
            
            # Add volcanic field effects
            field_effect = 200 * np.exp(-distance**2 / 0.1)
            
            return volcanic_height + field_effect
            
        except Exception as e:
            logger.error(f"Error calculating volcanic elevation: {e}")
            return np.zeros_like(lat_grid)
    
    def _calculate_erosional_patterns(self, lat_grid, lon_grid):
        """Calculate erosional modification factor"""
        try:
            # Climate-based erosion (higher erosion in tropical/temperate regions)
            climate_factor = 1.0 - 0.3 * np.abs(np.sin(lat_grid * np.pi / 180))
            
            # Drainage network effects (simplified)
            drainage_factor = 0.8 + 0.2 * np.sin(lon_grid * np.pi / 30) * np.cos(lat_grid * np.pi / 45)
            
            return climate_factor * drainage_factor
            
        except Exception as e:
            logger.error(f"Error calculating erosional patterns: {e}")
            return np.ones_like(lat_grid) 
   
    # Advanced helper methods for thermal and topographic loading calculations
    
    async def _collect_ground_thermal_measurements(self, latitude, longitude):
        """Collect ground-based thermal measurements from database"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                thermal_query = """
                SELECT 
                    gs.properties->>'temperature_c' as temperature,
                    gs.properties->>'depth_m' as depth,
                    gs.properties->>'measurement_type' as measurement_type,
                    ST_Distance(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) * 111.0 as distance_km
                FROM geological_structures gs
                WHERE gs.structure_type IN ('temperature_probe', 'thermal_well', 'geothermal_measurement')
                AND ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 0.5)
                ORDER BY distance_km ASC
                LIMIT 20
                """
                
                result = await session.execute(thermal_query, (longitude, latitude, longitude, latitude))
                measurements = result.fetchall()
                
                ground_thermal = {
                    'measurements': [],
                    'average_temperature': None,
                    'temperature_gradient': None
                }
                
                for measurement in measurements:
                    try:
                        temp = float(measurement.temperature) if measurement.temperature else None
                        depth = float(measurement.depth) if measurement.depth else None
                        
                        if temp is not None:
                            ground_thermal['measurements'].append({
                                'temperature_c': temp,
                                'depth_m': depth,
                                'measurement_type': measurement.measurement_type,
                                'distance_km': measurement.distance_km
                            })
                    except (ValueError, TypeError):
                        continue
                
                # Calculate average temperature and gradient
                if ground_thermal['measurements']:
                    temps = [m['temperature_c'] for m in ground_thermal['measurements']]
                    ground_thermal['average_temperature'] = np.mean(temps)
                    
                    # Calculate temperature gradient if depth data available
                    depth_temp_pairs = [(m['depth_m'], m['temperature_c']) 
                                       for m in ground_thermal['measurements'] 
                                       if m['depth_m'] is not None]
                    
                    if len(depth_temp_pairs) >= 2:
                        depths, temps = zip(*depth_temp_pairs)
                        gradient = np.polyfit(depths, temps, 1)[0]  # °C/m
                        ground_thermal['temperature_gradient'] = gradient * 1000  # °C/km
                
                return ground_thermal
                
        except Exception as e:
            logger.error(f"Error collecting ground thermal measurements: {e}")
            return {'measurements': [], 'error': str(e)}
    
    async def _collect_geothermal_gradient_data(self, latitude, longitude):
        """Collect geothermal gradient data from regional studies"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                gradient_query = """
                SELECT 
                    CAST(gs.properties->>'geothermal_gradient_c_km' AS FLOAT) as gradient,
                    CAST(gs.properties->>'heat_flow_mw_m2' AS FLOAT) as heat_flow,
                    gs.properties->>'data_source' as source,
                    ST_Distance(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) * 111.0 as distance_km
                FROM geological_structures gs
                WHERE gs.properties ? 'geothermal_gradient_c_km'
                AND ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 2.0)
                ORDER BY distance_km ASC
                LIMIT 10
                """
                
                result = await session.execute(gradient_query, (longitude, latitude, longitude, latitude))
                gradient_data = result.fetchall()
                
                geothermal = {
                    'gradient_c_km': 25.0,  # Default global average
                    'heat_flow_mw_m2': 60.0,  # Default global average
                    'data_sources': [],
                    'confidence': 'low'
                }
                
                if gradient_data:
                    gradients = [row.gradient for row in gradient_data if row.gradient is not None]
                    heat_flows = [row.heat_flow for row in gradient_data if row.heat_flow is not None]
                    
                    if gradients:
                        geothermal['gradient_c_km'] = np.mean(gradients)
                        geothermal['confidence'] = 'high' if len(gradients) >= 3 else 'medium'
                    
                    if heat_flows:
                        geothermal['heat_flow_mw_m2'] = np.mean(heat_flows)
                    
                    geothermal['data_sources'] = [row.source for row in gradient_data if row.source]
                
                return geothermal
                
        except Exception as e:
            logger.error(f"Error collecting geothermal gradient data: {e}")
            return {'gradient_c_km': 25.0, 'heat_flow_mw_m2': 60.0, 'error': str(e)}
    
    async def _collect_volcanic_thermal_signatures(self, latitude, longitude):
        """Collect volcanic thermal signatures from monitoring data"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                volcanic_thermal_query = """
                SELECT 
                    vm.ground_temperature_celsius,
                    vm.thermal_anomaly_count,
                    vm.timestamp,
                    v.volcano_name,
                    ST_Distance(v.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) * 111.0 as distance_km
                FROM volcanic_monitoring vm
                JOIN volcanoes v ON vm.volcano_id = v.volcano_id
                WHERE ST_DWithin(v.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1.0)
                AND vm.timestamp > NOW() - INTERVAL '30 days'
                AND (vm.ground_temperature_celsius IS NOT NULL OR vm.thermal_anomaly_count > 0)
                ORDER BY vm.timestamp DESC
                LIMIT 50
                """
                
                result = await session.execute(volcanic_thermal_query, (longitude, latitude, longitude, latitude))
                thermal_monitoring = result.fetchall()
                
                volcanic_thermal = {
                    'recent_temperatures': [],
                    'thermal_anomalies': [],
                    'average_temperature': None,
                    'anomaly_frequency': 0.0,
                    'volcanoes': set()
                }
                
                for record in thermal_monitoring:
                    volcanic_thermal['volcanoes'].add(record.volcano_name)
                    
                    if record.ground_temperature_celsius:
                        volcanic_thermal['recent_temperatures'].append({
                            'temperature_c': record.ground_temperature_celsius,
                            'timestamp': record.timestamp,
                            'distance_km': record.distance_km
                        })
                    
                    if record.thermal_anomaly_count and record.thermal_anomaly_count > 0:
                        volcanic_thermal['thermal_anomalies'].append({
                            'anomaly_count': record.thermal_anomaly_count,
                            'timestamp': record.timestamp,
                            'distance_km': record.distance_km
                        })
                
                # Calculate statistics
                if volcanic_thermal['recent_temperatures']:
                    temps = [t['temperature_c'] for t in volcanic_thermal['recent_temperatures']]
                    volcanic_thermal['average_temperature'] = np.mean(temps)
                
                if volcanic_thermal['thermal_anomalies']:
                    total_anomalies = sum(a['anomaly_count'] for a in volcanic_thermal['thermal_anomalies'])
                    days_monitored = 30  # Last 30 days
                    volcanic_thermal['anomaly_frequency'] = total_anomalies / days_monitored
                
                volcanic_thermal['volcanoes'] = list(volcanic_thermal['volcanoes'])
                
                return volcanic_thermal
                
        except Exception as e:
            logger.error(f"Error collecting volcanic thermal signatures: {e}")
            return {'recent_temperatures': [], 'thermal_anomalies': [], 'error': str(e)}
    
    def _get_observation_time_range(self, observations):
        """Get time range from list of observations"""
        if not observations:
            return None
        
        timestamps = [obs.timestamp for obs in observations]
        return {
            'start': min(timestamps),
            'end': max(timestamps),
            'duration_hours': (max(timestamps) - min(timestamps)).total_seconds() / 3600
        }
    
    async def _extract_surface_temperature(self, thermal_data):
        """Extract representative surface temperature from thermal data"""
        try:
            temperatures = []
            
            # From satellite data
            if 'satellite_thermal' in thermal_data:
                for obs in thermal_data['satellite_thermal'].get('observations', []):
                    if 'brightness_temperature_k' in obs.value:
                        temp_c = obs.value['brightness_temperature_k'] - 273.15
                        temperatures.append(temp_c)
            
            # From ground measurements
            if 'ground_thermal' in thermal_data:
                if thermal_data['ground_thermal'].get('average_temperature'):
                    temperatures.append(thermal_data['ground_thermal']['average_temperature'])
            
            # From volcanic monitoring
            if 'volcanic_thermal' in thermal_data:
                if thermal_data['volcanic_thermal'].get('average_temperature'):
                    temperatures.append(thermal_data['volcanic_thermal']['average_temperature'])
            
            if temperatures:
                return np.mean(temperatures)
            else:
                return 15.0  # Default surface temperature
                
        except Exception as e:
            logger.error(f"Error extracting surface temperature: {e}")
            return 15.0
    
    async def _extract_geothermal_gradient(self, thermal_data):
        """Extract geothermal gradient from thermal data"""
        try:
            # From geothermal data
            if 'geothermal' in thermal_data:
                return thermal_data['geothermal'].get('gradient_c_km', 25.0)
            
            # From ground measurements
            if 'ground_thermal' in thermal_data:
                gradient = thermal_data['ground_thermal'].get('temperature_gradient')
                if gradient:
                    return gradient
            
            return 25.0  # Default geothermal gradient
            
        except Exception as e:
            logger.error(f"Error extracting geothermal gradient: {e}")
            return 25.0
    
    async def _get_thermal_conductivity(self, latitude, longitude):
        """Get thermal conductivity from rock properties"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                conductivity_query = """
                SELECT 
                    AVG(rmp.thermal_conductivity_w_m_k) as avg_conductivity
                FROM rock_mechanical_properties rmp
                JOIN geological_structures gs ON gs.structure_id = rmp.formation_id
                WHERE ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 1.0)
                AND rmp.thermal_conductivity_w_m_k IS NOT NULL
                """
                
                result = await session.execute(conductivity_query, (longitude, latitude))
                row = result.fetchone()
                
                if row and row.avg_conductivity:
                    return row.avg_conductivity
                else:
                    return 2.5  # Default thermal conductivity for crustal rocks
                    
        except Exception as e:
            logger.error(f"Error getting thermal conductivity: {e}")
            return 2.5
    
    async def _create_3d_temperature_field(self, surface_temp, gradient, conductivity, depth, resolution, latitude, longitude):
        """Create 3D temperature field using heat conduction modeling"""
        try:
            # Create depth grid
            z_coords = np.arange(0, depth, resolution)
            
            # Simple 1D conductive temperature profile
            temperature_profile = surface_temp + gradient * z_coords / 1000.0  # Convert gradient to °C/m
            
            # Add lateral variations based on geological structures
            lateral_variation = await self._get_lateral_thermal_variation(latitude, longitude)
            
            # Create 3D field (simplified as 1D profile with lateral variations)
            temperature_field = temperature_profile * lateral_variation
            
            return temperature_field
            
        except Exception as e:
            logger.error(f"Error creating 3D temperature field: {e}")
            return np.array([surface_temp])
    
    async def _get_thermal_expansion_coefficients(self, latitude, longitude):
        """Get thermal expansion coefficients for different rock types"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                expansion_query = """
                SELECT 
                    gs.lithology,
                    AVG(CAST(rmp.thermal_expansion_per_k AS FLOAT)) as avg_expansion
                FROM geological_structures gs
                JOIN rock_mechanical_properties rmp ON gs.structure_id = rmp.formation_id
                WHERE ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 2.0)
                AND rmp.thermal_expansion_per_k IS NOT NULL
                GROUP BY gs.lithology
                """
                
                result = await session.execute(expansion_query, (longitude, latitude))
                expansion_data = result.fetchall()
                
                coefficients = {}
                for row in expansion_data:
                    if row.lithology and row.avg_expansion:
                        coefficients[row.lithology] = row.avg_expansion
                
                # Add default values for common rock types
                default_coefficients = {
                    'granite': 8e-6,
                    'basalt': 6e-6,
                    'andesite': 7e-6,
                    'limestone': 5e-6,
                    'sandstone': 12e-6,
                    'shale': 10e-6
                }
                
                for rock_type, coeff in default_coefficients.items():
                    if rock_type not in coefficients:
                        coefficients[rock_type] = coeff
                
                return coefficients
                
        except Exception as e:
            logger.error(f"Error getting thermal expansion coefficients: {e}")
            return {'default': 8e-6}
    
