    async def _estimate_erosion_rate(self, elevations, x_coords, y_coords, latitude, longitude):
        """Estimate erosion rate from topographic analysis"""
        try:
            # Calculate slope
            grad_y, grad_x = np.gradient(elevations)
            slope = np.sqrt(grad_x**2 + grad_y**2)
            mean_slope = np.nanmean(slope)
            
            # Calculate drainage density (simplified)
            elevation_range = np.nanmax(elevations) - np.nanmin(elevations)
            
            # Empirical erosion rate model
            # Based on slope, elevation range, and climate
            base_erosion_rate = 1e-5  # m/year base rate
            
            # Slope factor
            slope_factor = 1 + mean_slope * 10
            
            # Relief factor
            relief_factor = 1 + elevation_range / 1000.0
            
            # Climate factor (simplified)
            climate_factor = 1.5  # Assume moderate climate
            
            erosion_rate = base_erosion_rate * slope_factor * relief_factor * climate_factor
            
            return erosion_rate
            
        except Exception as e:
            logger.error(f"Error estimating erosion rate: {e}")
            return 0.0
    
    async def _get_tectonic_setting(self, latitude, longitude):
        """Get tectonic setting for the location"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                tectonic_query = """
                SELECT 
                    tf.feature_type,
                    MIN(ST_Distance(tf.geometry, ST_SetSRID(ST_MakePoint(%s, %s), 4326))) as min_distance
                FROM tectonic_features tf
                WHERE ST_DWithin(tf.geometry, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 10.0)
                GROUP BY tf.feature_type
                ORDER BY min_distance ASC
                LIMIT 1
                """
                
                result = await session.execute(tectonic_query, (longitude, latitude, longitude, latitude))
                row = result.fetchone()
                
                if row:
                    feature_type = row.feature_type
                    
                    # Map feature types to tectonic settings
                    setting_map = {
                        'active_fault': 'active_margin',
                        'inactive_fault': 'stable_craton',
                        'rift': 'rift_zone',
                        'fold': 'continental',
                        'volcanic_arc': 'arc'
                    }
                    
                    return setting_map.get(feature_type, 'continental')
                else:
                    return 'continental'  # Default
                    
        except Exception as e:
            logger.error(f"Error getting tectonic setting: {e}")
            return 'continental'
    
