    async def _collect_seismic_crustal_structure_data(self, latitude, longitude):
        """Collect seismic data for crustal structure analysis"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                seismic_query = """
                SELECT 
                    se.magnitude,
                    se.depth,
                    se.focal_mechanism,
                    se.moment_tensor,
                    ST_Distance(se.epicenter, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) * 111.0 as distance_km
                FROM seismic_events se
                WHERE ST_DWithin(se.epicenter, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 2.0)
                AND se.origin_time > NOW() - INTERVAL '5 years'
                ORDER BY distance_km ASC
                LIMIT 100
                """
                
                result = await session.execute(seismic_query, (longitude, latitude, longitude, latitude))
                seismic_records = result.fetchall()
                
                return {
                    'earthquake_data': [
                        {
                            'magnitude': record.magnitude,
                            'depth': record.depth,
                            'distance_km': record.distance_km,
                            'focal_mechanism': record.focal_mechanism,
                            'moment_tensor': record.moment_tensor
                        }
                        for record in seismic_records
                    ],
                    'data_count': len(seismic_records)
                }
                
        except Exception as e:
            logger.error(f"Error collecting seismic crustal structure data: {e}")
            return {'earthquake_data': [], 'data_count': 0}
    
