    async def _collect_geological_density_data(self, latitude, longitude):
        """Collect geological data relevant to density variations"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                geological_query = """
                SELECT 
                    gs.lithology,
                    gs.structure_type,
                    gs.age,
                    gs.properties,
                    ST_Distance(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) * 111.0 as distance_km
                FROM geological_structures gs
                WHERE ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 3.0)
                ORDER BY distance_km ASC
                LIMIT 50
                """
                
                result = await session.execute(geological_query, (longitude, latitude, longitude, latitude))
                geological_records = result.fetchall()
                
                return {
                    'geological_units': [
                        {
                            'lithology': record.lithology,
                            'structure_type': record.structure_type,
                            'age': record.age,
                            'distance_km': record.distance_km,
                            'properties': record.properties
                        }
                        for record in geological_records
                    ],
                    'data_count': len(geological_records)
                }
                
        except Exception as e:
            logger.error(f"Error collecting geological density data: {e}")
            return {'geological_units': [], 'data_count': 0}
    
    async def _collect_structural_density_data(self, latitude, longitude):
        """Collect structural deformation data affecting density"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                structural_query = """
                SELECT 
                    tf.feature_type,
                    tf.activity_status,
                    tf.properties,
                    ST_Distance(tf.geometry, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) * 111.0 as distance_km
                FROM tectonic_features tf
                WHERE ST_DWithin(tf.geometry, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 5.0)
                ORDER BY distance_km ASC
                LIMIT 30
                """
                
                result = await session.execute(structural_query, (longitude, latitude, longitude, latitude))
                structural_records = result.fetchall()
                
                # Calculate fracture density and deformation intensity
                fracture_density = 0.0
                deformation_intensity = 0.0
                
                for record in structural_records:
                    distance_km = record.distance_km
                    weight = np.exp(-distance_km / 10.0)
                    
                    if record.feature_type in ['fault', 'fracture']:
                        fracture_density += weight
                    
                    if record.activity_status == 'active':
                        deformation_intensity += weight * 2.0
                    else:
                        deformation_intensity += weight
                
                return {
                    'fracture_density': fracture_density,
                    'deformation_intensity': deformation_intensity,
                    'structural_features': len(structural_records)
                }
                
        except Exception as e:
            logger.error(f"Error collecting structural density data: {e}")
            return {'fracture_density': 0.0, 'deformation_intensity': 0.0}
    
    async def _collect_alteration_density_data(self, latitude, longitude):
        """Collect alteration and weathering data affecting density"""
        try:
            async with self.db_integrator.get_postgresql_session() as session:
                alteration_query = """
                SELECT 
                    gs.properties->>'alteration_type' as alteration_type,
                    gs.properties->>'alteration_intensity' as alteration_intensity,
                    gs.properties->>'weathering_grade' as weathering_grade,
                    ST_Distance(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326)) * 111.0 as distance_km
                FROM geological_structures gs
                WHERE ST_DWithin(gs.location, ST_SetSRID(ST_MakePoint(%s, %s), 4326), 2.0)
                AND (gs.properties ? 'alteration_type' OR gs.properties ? 'weathering_grade')
                ORDER BY distance_km ASC
                LIMIT 20
                """
                
                result = await session.execute(alteration_query, (longitude, latitude, longitude, latitude))
                alteration_records = result.fetchall()
                
                # Analyze alteration data
                alteration_types = []
                alteration_intensities = []
                
                for record in alteration_records:
                    if record.alteration_type:
                        alteration_types.append(record.alteration_type)
                    
                    if record.alteration_intensity:
                        try:
                            intensity = float(record.alteration_intensity)
                            alteration_intensities.append(intensity)
                        except (ValueError, TypeError):
                            pass
                
                # Determine dominant alteration type and average intensity
                dominant_alteration = 'none'
                if alteration_types:
                    from collections import Counter
                    alteration_counts = Counter(alteration_types)
                    dominant_alteration = alteration_counts.most_common(1)[0][0]
                
                average_intensity = 0.0
                if alteration_intensities:
                    average_intensity = np.mean(alteration_intensities)
                
                return {
                    'alteration_type': dominant_alteration,
                    'alteration_intensity': average_intensity,
                    'data_count': len(alteration_records)
                }
                
        except Exception as e:
            logger.error(f"Error collecting alteration density data: {e}")
            return {'alteration_type': 'none', 'alteration_intensity': 0.0}